;---------------------------------------------------------------------------
; LevelBounds - per level: x0, x1, y1, y0 (in 256-pixel map cells)
;  L0 x0-13 row 0     L1 x14-27 rows 0-1   L2 x0-13 rows 2-5   L3 x14-25 row 2
;  L4 x26-28 rows 2-6 L5 x29-30 rows 6-10  L6 x31 row 10
;---------------------------------------------------------------------------
LevelBounds:
	dc.b	0,13,0,0	; level 0: cells x 0-13, y 0-0
	dc.b	14,27,1,0	; level 1: cells x 14-27, y 0-1
	dc.b	0,13,5,2	; level 2: cells x 0-13, y 2-5
	dc.b	14,25,2,2	; level 3: cells x 14-25, y 2-2
	dc.b	26,28,6,2	; level 4: cells x 26-28, y 2-6
	dc.b	29,30,10,6	; level 5: cells x 29-30, y 6-10
	dc.b	31,31,10,10	; level 6: cells x 31-31, y 10-10

;---------------------------------------------------------------------------
; Level time limit (BCD mm:ss word) per level
;---------------------------------------------------------------------------
LevelTimeStart:
	dc.w	$0200,$0130,$0230,$0230,$0340,$0340,$0200	; BCD m:ss: 2:00 1:30 2:30 2:30 3:40 3:40 2:00

;---------------------------------------------------------------------------
; Level time limit after the half-way checkpoint
;---------------------------------------------------------------------------
LevelTimeCheckpoint:
	dc.w	$0200,$0230,$0230,$0230,$0340,$0340,$0200	; BCD m:ss: 2:00 2:30 2:30 2:30 3:40 3:40 2:00

;---------------------------------------------------------------------------
; Arthur start X,Y per level (bytes)
;---------------------------------------------------------------------------
LevelStartPos:
	dc.b	$60,$40,$50,$70,$50,$40,$30,$40,$50,$50,$30,$50,$58,$40	; (x, y) per level

;---------------------------------------------------------------------------
; Arthur restart X,Y after the checkpoint
;---------------------------------------------------------------------------
LevelCheckpointPos:
	dc.b	$80,$40,$80,$50,$80,$40,$80,$40,$50,$50,$30,$50,$58,$40	; (x, y) per level

;---------------------------------------------------------------------------
; LevelMapTable - per level, a word offset FROM THE TABLE START ($44BA) to the
; level's map origin cell (bottom-left) inside WorldMap. Rows go up in steps
; of +32. Origins (row,col): L0 0,0  L1 0,14  L2 2,0  L3 2,14  L4 2,26
; L5 6,30  L6 = WorldMap+352 (cell $63, the throne room).
; Note L5/L6 origins are one cell right of their LevelBounds x0.
;---------------------------------------------------------------------------
LevelMapTable:
	dc.w	WorldMap+0-LevelMapTable,WorldMap+14-LevelMapTable,WorldMap+64-LevelMapTable,WorldMap+78-LevelMapTable,WorldMap+90-LevelMapTable,WorldMap+222-LevelMapTable,WorldMap+352-LevelMapTable	; levels 0-6: origin cell, from the table start
	dc.w	$0015,$0020,$0052,$0061,$0068,$00EC,$016E	; not read by any code found

;---------------------------------------------------------------------------
; WorldMap - ONE map shared by all levels: 32 cells x 11 rows plus one extra
; byte (cell $63, level 6's throne room), one byte per 256x256-pixel cell,
; bottom row first. Cell $67 = tile 0 in every position.
; Each level's origin comes from LevelMapTable; its size from LevelBounds.
; Each cell byte indexes CellTiles.
;---------------------------------------------------------------------------
WorldMap:
	dc.b	$00,$01,$02,$23,$24,$01,$25,$65,$03,$04,$05,$06,$07,$08,$09,$0B,$0D,$0F,$10,$11,$12,$14,$16,$18,$1A,$1C,$1E,$1F,$67,$67,$67,$67	; row 0 - levels 0, 1
	dc.b	$67,$67,$67,$67,$67,$67,$67,$67,$67,$67,$67,$67,$67,$67,$0A,$0C,$0E,$67,$67,$67,$13,$15,$17,$19,$1B,$1D,$67,$67,$67,$67,$67,$67	; row 1 - level 1
	dc.b	$20,$21,$22,$26,$27,$28,$2A,$2D,$2C,$2C,$37,$3B,$3F,$40,$41,$42,$64,$66,$43,$44,$45,$46,$47,$47,$48,$49,$4A,$4F,$54,$20,$20,$20	; row 2 - levels 2, 3, 4
	dc.b	$20,$67,$67,$67,$2C,$29,$2B,$2E,$31,$34,$38,$3C,$2C,$67,$67,$67,$67,$67,$67,$67,$67,$67,$67,$67,$67,$67,$4B,$50,$55,$67,$67,$20	; row 3 - levels 2, 4
	dc.b	$67,$67,$67,$67,$67,$67,$2C,$2F,$32,$35,$39,$3D,$2C,$67,$67,$67,$67,$67,$67,$67,$67,$67,$67,$67,$67,$67,$4C,$51,$56,$67,$67,$20	; row 4 - levels 2, 4
	dc.b	$67,$67,$67,$67,$67,$67,$2C,$30,$33,$36,$3A,$3E,$2C,$67,$67,$67,$67,$67,$67,$67,$67,$67,$67,$67,$67,$67,$4D,$52,$57,$67,$67,$67	; row 5 - levels 2, 4
	dc.b	$67,$67,$67,$67,$67,$67,$67,$67,$67,$67,$67,$67,$67,$67,$67,$67,$67,$67,$67,$67,$67,$67,$67,$67,$67,$67,$4E,$53,$58,$00,$59,$5E	; row 6 - levels 4, 5
	dc.b	$67,$67,$67,$67,$67,$67,$67,$67,$67,$67,$67,$67,$67,$67,$67,$67,$67,$67,$67,$67,$67,$67,$67,$67,$67,$67,$67,$67,$67,$67,$5A,$5F	; row 7 - level 5
	dc.b	$67,$67,$67,$67,$67,$67,$67,$67,$67,$67,$67,$67,$67,$67,$67,$67,$67,$67,$67,$67,$67,$67,$67,$67,$67,$67,$67,$67,$67,$67,$5B,$60	; row 8 - level 5
	dc.b	$67,$67,$67,$67,$67,$67,$67,$67,$67,$67,$67,$67,$67,$67,$67,$67,$67,$67,$67,$67,$67,$67,$67,$67,$67,$67,$67,$67,$67,$67,$5C,$61	; row 9 - level 5
