;---------------------------------------------------------------------------
; MapTileAt - collision lookup for a world position
; In:  d6 = X, d7 = Y (level-relative pixels, Y increasing upwards)
; cell  = WorldMap byte at g_MapPtr + (X>>8) + (Y>>8)*32
; tile  = BlockTiles[cell*64 + ((X>>5)&7)*8 + ((Y>>5)&7)]   (8x8 grid of 32px tiles,
;         column-major, rows counted from the bottom of the cell)
; rec   = TileAttr + (MapBlockIndex[cell]<<8) + tile*8
; Out: a1 = rec + (X bit4 ? 2 : 0) + (Y bit4 ? 1 : 0)   (the 16x16 quadrant)
;      (a1)  = profile (SIGN-EXTENDED when indexing the tables below)
;              FloorProfile[p] = floor height 1-16 within the quadrant (0 = none)
;              WallProfileR/L[p] = wall offsets; p = $40-$7D = ladder
;      4(a1) = flags: bits 6-7 set = background / not solid (decorations, water)
;---------------------------------------------------------------------------
MapTileAt:
        movea.l g_MapPtr(a6),a1                 ; 05A7C
        move.w  d6,d0                           ; 05A80
        lsr.w   #$8,d0                          ; 05A82
        adda.w  d0,a1                           ; 05A84
        move.w  d7,d0                           ; 05A86
        clr.b   d0                              ; 05A88
        lsr.w   #$3,d0                          ; 05A8A
        adda.w  d0,a1                           ; 05A8C
        move.b  (a1),d0                         ; 05A8E
        ext.w   d0                              ; 05A90
        lea.l   MapBlockIndex(pc),a1            ; 05A92
        adda.w  d0,a1                           ; 05A96
        swap    d0                              ; 05A98
        move.b  (a1),d0                         ; 05A9A
        lsl.w   #$8,d0                          ; 05A9C
        lea.l   TileAttr(pc),a1                 ; 05A9E
        pea.l   (a1,d0.w)                       ; 05AA2
        swap    d0                              ; 05AA6
        lsl.w   #$6,d0                          ; 05AA8
        lea.l   BlockTiles(pc),a1               ; 05AAA
        adda.w  d0,a1                           ; 05AAE
        move.w  d6,d0                           ; 05AB0
        lsr.w   #$5,d0                          ; 05AB2
        andi.w  #$7,d0                          ; 05AB4
        lsl.w   #$3,d0                          ; 05AB8
        adda.w  d0,a1                           ; 05ABA
        move.w  d7,d0                           ; 05ABC
        lsr.w   #$5,d0                          ; 05ABE
        andi.w  #$7,d0                          ; 05AC0
        adda.w  d0,a1                           ; 05AC4
        clr.w   d0                              ; 05AC6
        move.b  (a1),d0                         ; 05AC8
        lsl.w   #$3,d0                          ; 05ACA
        movea.l (a7)+,a1                        ; 05ACC
        adda.w  d0,a1                           ; 05ACE
        btst    #$4,d6                          ; 05AD0
        beq.b   l_05AD8                         ; 05AD4
        addq.l  #$2,a1                          ; 05AD6
l_05AD8:
        btst    #$4,d7                          ; 05AD8
        beq.b   l_05AE0                         ; 05ADC
        addq.l  #$1,a1                          ; 05ADE
l_05AE0:
        rts                                     ; 05AE0

;---------------------------------------------------------------------------
; CrashReset - target of every CPU exception vector ($8-$2C, $3C).
; Writes RESET / JMP $0.L ($4E70 $4EF9 0000) to address 0 and jumps there:
; any bus error, illegal instruction, trace etc. reboots the machine.
; This doubles as an anti-tamper / anti-debug measure.
;---------------------------------------------------------------------------
CrashReset:
        move.l  #$4e704ef9,(RESET_STUB).w       ; 05AE2
        jmp     (RESET_STUB).w                  ; 05AEA

;---------------------------------------------------------------------------
; ==================================================================
; Start - one-time initialisation
;  - point all exception vectors at CrashReset, autovectors at it too
;  - a6 = GLOBALS, USP = GLOBALS (user mode stack lives below it)
;  - load file $7F9C (tracks 33-36): Arthur sprite graphics, interleave
;    and convert into the 8 sprite planes at $1DE34-$26E34
;  - build HUD sprite data, load the remaining common files
;  - initialise hi-score table, copper lists, screen buffers
;  - install interrupts (InitHardware), show the FAST copyright
;    warning screen for 10 s, then drop
;    to user mode and spin: the whole game runs in interrupts.
; ==================================================================
;---------------------------------------------------------------------------
Start:
        lea.l   $8.w,a1                         ; 05AEE  CPU exceptions $08-$24 (bus error ... trace) -> CrashReset
        lea.l   CrashReset(pc),a0               ; 05AF2
        move.l  a0,(a1)+                        ; 05AF6
        move.l  a0,(a1)+                        ; 05AF8
        move.l  a0,(a1)+                        ; 05AFA
        move.l  a0,(a1)+                        ; 05AFC
        move.l  a0,(a1)+                        ; 05AFE
        move.l  a0,(a1)+                        ; 05B00
        move.l  a0,(a1)+                        ; 05B02
        move.l  a0,(a1)+                        ; 05B04
        move.l  a0,(VEC_UNINIT).w               ; 05B06  Line-A/Line-F slots ($28/$2C) left free: the loader uses them as variables
        move.l  a0,d0                           ; 05B0A
        move.l  a0,d1                           ; 05B0C
        move.l  a0,d2                           ; 05B0E
        move.l  (VEC_LEVEL3).w,d3               ; 05B10  autovectors $60-$7C -> CrashReset, except level 3 (kept for now)
        move.l  a0,d4                           ; 05B14
        move.l  a0,d5                           ; 05B16
        move.l  a0,d6                           ; 05B18
        move.l  a0,d7                           ; 05B1A
        lea.l   (VEC_SPURIOUS).w,a0             ; 05B1C
        movem.l d0-d7,(a0)                      ; 05B20
        lea.l   (GLOBALS).l,a6                  ; 05B24
        move    a6,usp                          ; 05B2A  USP = globals block (user-mode stack grows down from here)
        lea.l   FileTable(pc),a1                ; 05B2C
        bsr.w   LoadFile                        ; 05B30  load Arthur sprite file (tracks 33-36) to $37468

;---------------------------------------------------------------------------
; Arthur's sprite graphics (file tracks 33-36, 42 frames of 32x32, 4 planes).
; Source rows are 8 words: [L-p0 R-p0 L-p1 R-p1 L-p2 R-p2 L-p3 R-p3].
; They are split into four sprite banks $2900 apart: sprites 0+1 = left 16
; pixels (attached pair, 16 colours from COLOR16), sprites 2+3 = right half.
; Frames: 0-14 armoured poses, 15 frog, 16-31 the same poses without armour (+$10),
; 32-36 skeleton (death), 37-39 frog, 40 sitting in his underwear (opening scene),
; 41 arms raised (end of level, ending). The second loop builds mirrored copies
; (bit-reversed, halves swapped) of frames 0-39 only - 40 and 41 always face right.
;---------------------------------------------------------------------------
        lea.l   FileTable(pc),a5                ; 05B34
        movea.l (a5),a5                         ; 05B38
        lea.l   (ARTHUR_SPR_GFX).l,a1           ; 05B3A
        lea.l   (SPR_GFX_A1).l,a2               ; 05B40
        lea.l   (SPR_GFX_A2).l,a3               ; 05B46
        lea.l   (SPR_GFX_A3).l,a4               ; 05B4C
