;---------------------------------------------------------------------------
; RedrawEntry - the VBL handler patches the return PC to here when a
; full redraw is pending (g_RedrawPending). Runs in user mode, outside the interrupt:
;   bsr.w RedrawScreen / clr.b g_SkipLogic(a6) (lets the logic run again) / bra *
; (kept as bytes: the code is only reached through the patched return address)
;---------------------------------------------------------------------------
RedrawEntry:
	dc.b	$61,$00,$61,$30,$42,$2E,$00,$1E,$60,$FE

;---------------------------------------------------------------------------
; ==================================================================
; Level1Logic - LEVEL 1 (SOFTINT) handler = the game's main loop
; The VBL handler raises SOFTINT each frame unless the previous frame's
; logic is still running, so this runs at most once per frame at IPL 1,
; letting the VBL/keyboard interrupts pre-empt it.
; Dispatches on g_GameState:
;    0 -> InGame        1 -> AttractTitle      2 -> AttractHiScores
; ==================================================================
;---------------------------------------------------------------------------
Level1Logic:
        move.w  #INTF_SOFTINT,CUSTOM+INTREQ     ; 05EB6
        movem.l d0-d7/a0-a5,-(a7)               ; 05EBE
        move.b  g_GameState(a6),d0              ; 05EC2
        ext.w   d0                              ; 05EC6
        add.w   d0,d0                           ; 05EC8
        add.w   d0,d0                           ; 05ECA
        jmp     GameStateTable(pc,d0.w)         ; 05ECC
GameStateTable:
        bra.w   InGame                          ; 05ED0
        bra.w   AttractTitle                    ; 05ED4
        bra.w   AttractHiScores                 ; 05ED8

;---------------------------------------------------------------------------
; Attract state 1: credits/title text, 400 frames
;---------------------------------------------------------------------------
AttractTitle:
        tst.b   g_SubState(a6)                  ; 05EDC
        bne.b   l_05F16                         ; 05EE0
        tst.b   g_RedrawDone(a6)                ; 05EE2
        beq.b   l_05F2C                         ; 05EE6
        clr.w   g_RawKey(a6)                    ; 05EE8
        bsr.w   SwapScreens                     ; 05EEC
        bsr.w   DrawCreditsScreen               ; 05EF0
        clr.b   g_ArthurVisible(a6)             ; 05EF4
        clr.b   g_Spr47Visible(a6)              ; 05EF8
        bsr.w   ArthurSpritePos                 ; 05EFC
        bsr.w   SetBitplanePtrs                 ; 05F00
        bsr.w   ShowBackBuffer                  ; 05F04
        st.b    g_RedrawPending(a6)             ; 05F08
        move.w  g_VblCount(a6),g_FrameStamp(a6) ; 05F0C
        addq.b  #SS_PLAYLEVEL,g_SubState(a6)    ; 05F12
l_05F16:
        move.w  g_VblCount(a6),d0               ; 05F16
        sub.w   g_FrameStamp(a6),d0             ; 05F1A
        cmp.w   #$190,d0                        ; 05F1E
        bcs.b   l_05F2C                         ; 05F22
        addq.b  #GS_TITLE,g_GameState(a6)       ; 05F24
        clr.b   g_SubState(a6)                  ; 05F28
l_05F2C:
        bra.b   CheckGameStart                  ; 05F2C

;---------------------------------------------------------------------------
; Attract state 2: high-score table, 200 frames
;---------------------------------------------------------------------------
AttractHiScores:
        tst.b   g_SubState(a6)                  ; 05F2E
        bne.b   l_05F5C                         ; 05F32
        tst.b   g_RedrawDone(a6)                ; 05F34
        beq.b   CheckGameStart                  ; 05F38
        bsr.w   SwapScreens                     ; 05F3A
        bsr.w   DrawHiScoreTable                ; 05F3E
        bsr.w   ArthurSpritePos                 ; 05F42
        bsr.w   SetBitplanePtrs                 ; 05F46
        bsr.w   ShowBackBuffer                  ; 05F4A
        st.b    g_RedrawPending(a6)             ; 05F4E
        move.w  g_VblCount(a6),g_FrameStamp(a6) ; 05F52
        addq.b  #SS_PLAYLEVEL,g_SubState(a6)    ; 05F58
l_05F5C:
        move.w  g_VblCount(a6),d0               ; 05F5C
        sub.w   g_FrameStamp(a6),d0             ; 05F60
        cmp.w   #$c8,d0                         ; 05F64
        bcs.b   CheckGameStart                  ; 05F68
        move.b  #GS_TITLE,g_GameState(a6)       ; 05F6A
        clr.b   g_SubState(a6)                  ; 05F70

;---------------------------------------------------------------------------
; Start a game: fire (CIA-A PRA bit 7) starts with the current mode,
; F1 = one player, F2 = two players.  Resets both player blocks
; (level 0, weapon 1 = lance, 7 lives, intro cut-scene pending).
;---------------------------------------------------------------------------
CheckGameStart:
        btst    #$7,$bfe001.l                   ; 05F74
        beq.b   l_05F9A                         ; 05F7C
        cmpi.b  #$50,g_RawKey(a6)               ; 05F7E  F1 pressed?
        bne.b   l_05F8C                         ; 05F84
        clr.b   g_TwoPlayer(a6)                 ; 05F86
        bra.b   l_05F9A                         ; 05F8A
l_05F8C:
        cmpi.b  #$51,g_RawKey(a6)               ; 05F8C  F2 pressed?
        bne.w   LogicExit                       ; 05F92
        st.b    g_TwoPlayer(a6)                 ; 05F96
l_05F9A:
        clr.w   g_RawKey(a6)                    ; 05F9A
        clr.b   g_Paused(a6)                    ; 05F9E
        clr.b   g_GameState(a6)                 ; 05FA2
        clr.b   g_SubState(a6)                  ; 05FA6
        clr.b   g_SubState2(a6)                 ; 05FAA
        clr.b   g_SubState3(a6)                 ; 05FAE
        clr.b   g_CurPlayer(a6)                 ; 05FB2
        move.b  #$7,g_Lives(a6)                 ; 05FB6  lives = 7
        move.w  #$1,g_Weapon(a6)                ; 05FBC  weapon = 1 (lance)
        clr.w   g_Level(a6)                     ; 05FC2
        clr.l   g_Score(a6)                     ; 05FC6
        clr.b   g_ExtraLives(a6)                ; 05FCA
        st.b    g_ShowIntro(a6)                 ; 05FCE  play opening cut-scene
        clr.b   g_Checkpoint(a6)                ; 05FD2
        clr.b   g_PlayerDied(a6)                ; 05FD6
        tst.b   g_TwoPlayer(a6)                 ; 05FDA
        beq.b   StartGame                       ; 05FDE
        lea.l   (GLOBALS_P2).l,a0               ; 05FE0
        move.b  #$7,$a6(a0)                     ; 05FE6
        move.w  #INTF_TBE,$9c(a0)               ; 05FEC
        clr.w   $9a(a0)                         ; 05FF2
        clr.l   $9e(a0)                         ; 05FF6
        clr.b   $a8(a0)                         ; 05FFA
        st.b    $a9(a0)                         ; 05FFE
        clr.b   $a7(a0)                         ; 06002
StartGame:
        bsr.w   ClearHudArea                    ; 06006
        move.b  #$1f,g_TextShadow(a6)           ; 0600A
        move.b  #$1b,g_TextInk(a6)              ; 06010
        move.b  #$5,g_TextPaper(a6)             ; 06016
        lea.l   TxtPlayer(pc),a3                ; 0601C
        moveq   #$1,d1                          ; 06020
        moveq   #$0,d2                          ; 06022
        bsr.w   PrintString                     ; 06024
        move.b  #$31,d0                         ; 06028
        bsr.w   PrintChar                       ; 0602C
        moveq   #$1,d1                          ; 06030
        moveq   #$8,d2                          ; 06032
        moveq   #$0,d6                          ; 06034
        bsr.w   PrintBCD                        ; 06036
        tst.b   g_TwoPlayer(a6)                 ; 0603A
        beq.b   l_06070                         ; 0603E
        move.b  #$1f,g_TextShadow(a6)           ; 06040
        move.b  #$1b,g_TextInk(a6)              ; 06046
        move.b  #$5,g_TextPaper(a6)             ; 0604C
        lea.l   TxtPlayer(pc),a3                ; 06052
        moveq   #$17,d1                         ; 06056
        moveq   #$0,d2                          ; 06058
        bsr.w   PrintString                     ; 0605A
