        move.w  g_Joy(a6),d0                    ; 0614A
        and.w   g_JoyPrev(a6),d0                ; 0614E
        btst    #$1,d0                          ; 06152  right
        bne.w   l_0623E                         ; 06156
        btst    #$9,d0                          ; 0615A  left
        bne.w   l_0624E                         ; 0615E
        btst    #$0,d0                          ; 06162  down
        bne.w   l_0625C                         ; 06166
        btst    #$8,d0                          ; 0616A  up
        bne.w   l_0626C                         ; 0616E
        btst    #$f,d0                          ; 06172  fire
        beq.w   l_0621C                         ; 06176
        move.w  g_ArthurY(a6),d5                ; 0617A  cell = row * 13 + column
        mulu.w  #$d,d5                          ; 0617E
        add.w   g_ArthurX(a6),d5                ; 06182
        cmp.w   #$40,d5                         ; 06186  END
        beq.b   l_061BC                         ; 0618A
        cmp.w   #$3f,d5                         ; 0618C  rub out
        beq.w   l_0621E                         ; 06190
        cmp.w   #$3e,d5                         ; 06194  space
        beq.w   l_06238                         ; 06198
        lea.l   NameGridLetters(pc),a0          ; 0619C
        move.b  (a0,d5.w),d0                    ; 061A0
l_061A4:
