;---------------------------------------------------------------------------
; ==================================================================
; InGame - dispatch on g_SubState:
;   0 LoadLevel     load the level's files            -> 1
;   1 PlayLevel     g_SubState2: 0 progress map, 1 SetupLevel, 2 start music -> 2
;   2 InPlay        PlayFrame every frame; after a death or a finished level decides
;                   what comes next
;   3 GameOver      'GAME OVER', high-score insertion and name entry
;   4 LevelComplete walk off, bonus                   -> 2 (g_LevelDone) -> 0
;   5 IntroCutscene once per game, before the first level
;   6 Ending        after Astaroth
;   7 WeaponUseless Astaroth's guard beaten without the cross
; ==================================================================
;---------------------------------------------------------------------------
InGame:
        move.b  g_SubState(a6),d0               ; 0645E
        add.w   d0,d0                           ; 06462
        add.w   d0,d0                           ; 06464
        jmp     InGameStateTable(pc,d0.w)       ; 06466
InGameStateTable:
        bra.w   LoadLevel                       ; 0646A
        bra.w   PlayLevel                       ; 0646E
        bra.w   InPlay                          ; 06472
        bra.w   GameOver                        ; 06476
        bra.w   LevelComplete                   ; 0647A
        bra.w   IntroCutscene                   ; 0647E
        bra.w   Ending                          ; 06482
        bra.w   WeaponUseless                   ; 06486

;---------------------------------------------------------------------------
; LevelComplete - sub state 4 (after taking the key). Steps (g_SubState2):
;  0 Arthur stands just past the right edge facing right
;  1 walks right for 32 frames,
;  2 raises his arms (frame 41) for 64 frames while 'BONUS' and the amount are shown
;    (5000 for levels 0-1, 10000 for 2-3, 15000 for 4-5); then the bonus is added and
;    his armour is restored
;  3 walks on for 70 frames; then g_Level + 1 (wrapping after 6), g_LevelDone, and
;    sub state 2 -> InPlay loads the next level.
;---------------------------------------------------------------------------
LevelComplete:
        move.b  g_SubState2(a6),d0              ; 0648A
        ext.w   d0                              ; 0648E
        add.w   d0,d0                           ; 06490
        add.w   d0,d0                           ; 06492
        jmp     LevelComplete_Jumps(pc,d0.w)    ; 06494
LevelComplete_Jumps:
        bra.w   Bonus_Setup                     ; 06498
        bra.w   Bonus_Walk                      ; 0649C
        bra.w   Bonus_Show                      ; 064A0
        bra.w   Bonus_WalkOff                   ; 064A4
Bonus_Setup:
        clr.b   g_Jumping(a6)                   ; 064A8
        clr.b   g_Crouching(a6)                 ; 064AC
        clr.b   g_ArthurState(a6)               ; 064B0
        move.b  #$1,g_ArthurFacing(a6)          ; 064B4
        move.b  #$1,g_ArthurDir(a6)             ; 064BA
        moveq   #$25,d0                         ; 064C0  37 px past the right edge
        add.w   g_LevelWidth(a6),d0             ; 064C2
        move.w  d0,g_ArthurX(a6)                ; 064C6
        lea.l   ArthurAnims(pc),a1              ; 064CA
        bsr.w   ArthurSetAnim                   ; 064CE
        move.b  #$20,g_StateTimer(a6)           ; 064D2
        addq.b  #$1,g_SubState2(a6)             ; 064D8
        bra.w   l_06DA0                         ; 064DC
Bonus_Walk:
        subq.b  #$1,g_StateTimer(a6)            ; 064E0
        beq.b   l_064F6                         ; 064E4
        addi.l  #$12000,g_ArthurX(a6)           ; 064E6
        bsr.w   ArthurAnimate                   ; 064EE
        bra.w   l_06DA0                         ; 064F2
l_064F6:
        move.b  #$29,g_ArthurFrame(a6)          ; 064F6  arms raised
        clr.b   g_ArthurAnimTimer(a6)           ; 064FC
        move.b  #$40,g_StateTimer(a6)           ; 06500
        addq.b  #$1,g_SubState2(a6)             ; 06506
        bra.w   l_06DA0                         ; 0650A
Bonus_Show:
