        moveq   #$18,d1                         ; 0652A
        move.w  #$b8,d2                         ; 0652C  lower on levels 4-6
        cmpi.w  #$4,g_Level(a6)                 ; 06530
        bcs.b   l_0653C                         ; 06536
        move.w  #$80,d2                         ; 06538
l_0653C:
        bsr.w   PrintString                     ; 0653C
        move.w  g_Level(a6),d0                  ; 06540
        mulu.w  #$6,d0                          ; 06544
        lea.l   TxtBonusAmounts(pc,d0.w),a3     ; 06548
        moveq   #$18,d1                         ; 0654C
        addq.w  #$8,d2                          ; 0654E
        bsr.w   PrintString                     ; 06550
        bra.w   l_06DA0                         ; 06554
l_06558:
