        bsr.w   ArthurSetAnim                   ; 0656C
        move.b  #$46,g_StateTimer(a6)           ; 06570
        addq.b  #$1,g_SubState2(a6)             ; 06576
        bra.w   l_06DA0                         ; 0657A

;---------------------------------------------------------------------------
