	dc.b	$30,$00,$31,$30,$30,$30,$30,$00,$31,$35,$30,$30,$30,$00,$31,$35
	dc.b	$30,$30,$30,$00
Bonus_WalkOff:
        subq.b  #$1,g_StateTimer(a6)            ; 065AE
        beq.b   l_065C4                         ; 065B2
        addi.l  #$12000,g_ArthurX(a6)           ; 065B4
        bsr.w   ArthurAnimate                   ; 065BC
