;---------------------------------------------------------------------------
; GameOver - sub state 3. Steps (g_SubState2 / g_SubState3):
;  0     'GAME OVER PLAYER ONE' (or TWO) for 200 frames
;  1/0   not in the top 10 -> step 2. Otherwise insert the score and three blank initials
;        (the lower entries move down), redraw the screen where the camera was and show
;        the letter grid; the 1MB build plays tune 3 (1 for a new top score)
;  1/1   NameEntry
;  1/2   200 frames, then
;  2     back to InPlay (g_GameState 0, sub state 2), which switches to the other player
;        or returns to the attract screens.
; Name entry borrows Arthur's variables: g_ArthurX/Y = cursor column (0-12) / row (0-4),
; g_ArthurAux = letters entered, g_Crouching/g_Jumping/g_Falling = the three initials,
; g_ShownScore = pointer to the name's slot in g_HiNames.
;---------------------------------------------------------------------------
GameOver:
        cmpi.b  #$1,g_SubState2(a6)             ; 065EE
        beq.b   l_06648                         ; 065F4
        bhi.w   l_06736                         ; 065F6
        move.b  #$c8,g_StateTimer(a6)           ; 065FA  200 frames
        move.b  #$1f,g_TextShadow(a6)           ; 06600
        move.b  #$1b,g_TextInk(a6)              ; 06606
        move.b  #$5,g_TextPaper(a6)             ; 0660C
        moveq   #$6,d1                          ; 06612
        move.w  #$88,d2                         ; 06614
        lea.l   TxtGameOver(pc),a3              ; 06618
        bsr.w   PrintString                     ; 0661C
        tst.b   g_CurPlayer(a6)                 ; 06620
        bne.b   l_0662C                         ; 06624
        lea.l   TxtOne(pc),a3                   ; 06626
        bra.b   l_06630                         ; 0662A
l_0662C:
        lea.l   TxtTwo(pc),a3                   ; 0662C
l_06630:
        bsr.w   PrintString                     ; 06630
        bsr.w   ArthurSpritePos                 ; 06634
        bsr.w   SetBitplanePtrs                 ; 06638
        bsr.w   ShowBackBuffer                  ; 0663C
        addq.b  #$1,g_SubState2(a6)             ; 06640
        bra.w   LogicExit                       ; 06644
l_06648:
        cmpi.b  #$1,g_SubState3(a6)             ; 06648
        beq.w   NameEntry                       ; 0664E
        bhi.w   l_06726                         ; 06652
        subq.b  #$1,g_StateTimer(a6)            ; 06656  wait
        bne.w   LogicExit                       ; 0665A
        move.w  g_ScrollFineX(a6),d0            ; 0665E  redraw origin = where the camera is
        asr.w   #$4,d0                          ; 06662
        add.w   g_ScrollTileX(a6),d0            ; 06664
        move.w  d0,g_NewTileX(a6)               ; 06668
        clr.w   g_ScrollFineX(a6)               ; 0666C
        move.w  g_ScrollFineY(a6),d0            ; 06670
        asr.w   #$4,d0                          ; 06674
        add.w   g_ScrollTileY(a6),d0            ; 06676
        move.w  d0,g_NewTileY(a6)               ; 0667A
        clr.w   g_ScrollFineY(a6)               ; 0667E
        clr.b   g_ArthurVisible(a6)             ; 06682
        clr.b   g_Spr47Visible(a6)              ; 06686
        lea.l   g_HiScores(a6),a0               ; 0668A  rank: first entry the score beats
        moveq   #$0,d7                          ; 0668E
        move.l  g_Score(a6),d0                  ; 06690
l_06694:
        cmp.l   (a0)+,d0                        ; 06694
        bhi.b   l_066A4                         ; 06696
        addq.w  #$1,d7                          ; 06698
        cmp.w   #$a,d7                          ; 0669A
        bne.b   l_06694                         ; 0669E
        bra.w   l_06736                         ; 066A0
l_066A4:
        lea.l   g_HiScores+36(a6),a0            ; 066A4  shift the lower scores down and insert
        move.w  d7,d6                           ; 066A8
l_066AA:
        addq.w  #$1,d7                          ; 066AA
        cmp.w   #$a,d7                          ; 066AC
        beq.b   l_066B8                         ; 066B0
        move.l  -(a0),$4(a0)                    ; 066B2
        bra.b   l_066AA                         ; 066B6
l_066B8:
        move.l  d0,(a0)                         ; 066B8
        lea.l   g_HiNames+27(a6),a0             ; 066BA  and the names (3 bytes each)
l_066BE:
        addq.w  #$1,d6                          ; 066BE
        cmp.w   #$a,d6                          ; 066C0
        beq.b   l_066D4                         ; 066C4
        move.b  -(a0),$3(a0)                    ; 066C6
        move.b  -(a0),$3(a0)                    ; 066CA
        move.b  -(a0),$3(a0)                    ; 066CE
        bra.b   l_066BE                         ; 066D2
l_066D4:
        move.l  a0,g_ShownScore(a6)             ; 066D4  remember where the initials go
        moveq   #$3,d0                          ; 066D8  1MB build: tune 3, or 1 for a new top score
        move.l  g_Score(a6),d1                  ; 066DA
        cmp.l   g_HiScores(a6),d1               ; 066DE
        bne.b   l_066E6                         ; 066E2
        moveq   #TUNE_HISCORE_TOP,d0            ; 066E4
l_066E6:
        clr.b   g_RedrawPending(a6)             ; 066E6  [1MB build: BSR PlayMusic here - d0 is tune no.; call removed in 512K]
        bsr.w   RedrawScreen                    ; 066EA
        bsr.w   SwapScreens                     ; 066EE
        clr.w   g_ArthurAux(a6)                 ; 066F2  no letters yet; initials = spaces
        moveq   #$20,d0                         ; 066F6
        move.b  d0,g_Crouching(a6)              ; 066F8
        move.b  d0,g_Jumping(a6)                ; 066FC
        move.b  d0,g_Falling(a6)                ; 06700
        move.w  #$c,g_ArthurX(a6)               ; 06704  cursor on END
        move.w  #$4,g_ArthurY(a6)               ; 0670A
        moveq   #$40,d5                         ; 06710
        bsr.w   DrawNameGrid                    ; 06712
        bsr.w   SetBitplanePtrs                 ; 06716
        bsr.w   ShowBackBuffer                  ; 0671A
        addq.b  #$1,g_SubState3(a6)             ; 0671E
        bra.w   LogicExit                       ; 06722
l_06726:
        subq.b  #$1,g_StateTimer(a6)            ; 06726  200 frames after the name
        bne.w   LogicExit                       ; 0672A
        addq.b  #$1,g_SubState2(a6)             ; 0672E
        bra.w   LogicExit                       ; 06732
l_06736:
        clr.b   g_GameState(a6)                 ; 06736  -> InPlay: next player or attract mode
        move.b  #SS_INPLAY,g_SubState(a6)       ; 0673A
        clr.b   g_SubState2(a6)                 ; 06740
        clr.b   g_SubState3(a6)                 ; 06744
        bra.w   LogicExit                       ; 06748

;---------------------------------------------------------------------------
; Sub state 2 - the normal 'playing' state. Each frame:
;   no death and no finished level -> PlayFrame
;   level finished (g_LevelDone)   -> sub state 0, load the next level
;   Arthur died (g_PlayerDied):
;     two players and the other one still has lives -> SwapPlayers; reload the level
;       if the other player is on a different one, else straight to sub state 1
;     else lives left -> sub state 1 (progress map, set-up) on the same level
;     else -> attract mode (g_GameState 1)
;---------------------------------------------------------------------------
InPlay:
        tst.b   g_PlayerDied(a6)                ; 0674C
        beq.b   l_067B0                         ; 06750
        tst.b   g_TwoPlayer(a6)                 ; 06752  2 players: does the other player have lives left?
        beq.b   l_06764                         ; 06756
        lea.l   (GLOBALS_P2).l,a0               ; 06758
        tst.b   $a6(a0)                         ; 0675E
        bne.b   l_06784                         ; 06762
l_06764:
        tst.b   g_Lives(a6)                     ; 06764  no lives: back to the attract screens
        bne.b   l_0679E                         ; 06768
        move.b  #GS_TITLE,g_GameState(a6)       ; 0676A
        clr.b   g_SubState(a6)                  ; 06770
        clr.b   g_SubState2(a6)                 ; 06774
        clr.b   g_SubState3(a6)                 ; 06778
        st.b    g_RedrawPending(a6)             ; 0677C
        bra.w   LogicExit                       ; 06780
l_06784:
        bsr.w   SwapPlayers                     ; 06784  switch to the other player
        clr.b   g_SubState(a6)                  ; 06788
        lea.l   (GLOBALS_P2).l,a0               ; 0678C
        move.w  $9a(a0),d0                      ; 06792  same level as before? (then no need to reload)
        cmp.w   g_Level(a6),d0                  ; 06796
        bne.w   LogicExit                       ; 0679A
l_0679E:
        move.b  #SS_PLAYLEVEL,g_SubState(a6)    ; 0679E  progress map and level set-up
        clr.b   g_SubState2(a6)                 ; 067A4
        clr.b   g_SubState3(a6)                 ; 067A8
        bra.w   LogicExit                       ; 067AC
l_067B0:
        tst.b   g_LevelDone(a6)                 ; 067B0  normal frame: no level change pending
        beq.w   PlayFrame                       ; 067B4
        clr.b   g_LevelDone(a6)                 ; 067B8  level finished: load the next one (g_Level already advanced)
        clr.b   g_SubState(a6)                  ; 067BC
        bra.w   LogicExit                       ; 067C0

;---------------------------------------------------------------------------
; 21 words: byte size of each BOB graphics set (see BobSetOffsets)
;---------------------------------------------------------------------------
BobSetSizes:
	dc.b	$10,$E0,$08,$98,$11,$80,$04,$60,$10,$D6,$3F,$C0,$2F,$3A,$0B,$E0
	dc.b	$3B,$88,$06,$D6,$20,$58,$15,$2C,$13,$92,$50,$00,$08,$52,$07,$94
	dc.b	$00,$00,$0B,$68,$0D,$C0,$08,$20,$08,$98
SmallBobSetSizes:
	dc.b	$00,$82,$00,$96,$01,$40,$01,$40,$01,$90,$01,$90,$01,$90,$01,$A4
	dc.b	$01,$A4,$01,$90

;---------------------------------------------------------------------------
; Per-level long bitmask of the BOB sets LoadLevel copies out of the big
; graphics file (only the enemies used on that level are kept in memory).
;---------------------------------------------------------------------------
LevelBobSetMask:
	dc.b	$00,$02,$89,$EB,$00,$12,$05,$36,$00,$0C,$18,$B1,$00,$00,$50,$24
	dc.b	$00,$08,$06,$65,$00,$00,$17,$61,$00,$00,$A0,$00
LevelSmallBobMask:
	dc.b	$00,$EB,$02,$07,$00,$13,$01,$03,$01,$01,$00,$02,$00,$01

;---------------------------------------------------------------------------
; Sub state 0: load the level.
;  - file $7FA6 (track 37)      -> BOB_GFX_A ($311E8)
;  - file $7FB0 (tracks 38-56)  -> SCREEN_0 area (enemy graphics)
;  - level file via index $7F8E -> LEVEL_FILE ($65548)
; then builds frame pointer tables with BuildFrameTable.
;---------------------------------------------------------------------------
LoadLevel:
        lea.l   FileSmallBobs(pc),a1            ; 0682C
        bsr.w   LoadFile                        ; 06830
        move.w  #DMAF_RASTER,$96(a0)            ; 06834  disable copper DMA while loading
        lea.l   FileEnemyBobs(pc),a1            ; 0683A
        bsr.w   LoadFile                        ; 0683E
        lea.l   LevelFileIndex(pc),a1           ; 06842
        move.w  g_Level(a6),d0                  ; 06846
        add.w   d0,d0                           ; 0684A
        adda.w  d0,a1                           ; 0684C
        adda.w  (a1),a1                         ; 0684E
        bsr.w   LoadFile                        ; 06850  load per-level file (tracks 84-109)
        move.l  a5,g_LevelFileEnd(a6)           ; 06854
        move.w  g_Level(a6),d0                  ; 06858
        lsl.w   #$2,d0                          ; 0685C
        move.l  LevelBobSetMask(pc,d0.w),d0     ; 0685E
        lea.l   g_BobSets(a6),a0                ; 06862
        movea.l g_LevelFileEnd(a6),a2           ; 06866
        lea.l   BobSetSizes(pc),a3              ; 0686A
        lea.l   BobSetOffsets(pc),a4            ; 0686E
        lea.l   (SCREEN_0).l,a5                 ; 06872
        moveq   #$14,d7                         ; 06878
        bsr.w   BuildFrameTable                 ; 0687A
        move.w  g_Level(a6),d0                  ; 0687E
        add.w   d0,d0                           ; 06882
        move.w  LevelSmallBobMask(pc,d0.w),d0   ; 06884
        lea.l   g_SmallBobSets(a6),a0           ; 06888
        lea.l   SmallBobSetSizes(pc),a3         ; 0688C
        lea.l   SmallBobSetOffsets(pc),a4       ; 06890
        lea.l   (BOB_GFX_A).l,a5                ; 06894
        moveq   #$9,d7                          ; 0689A
        bsr.w   BuildFrameTable                 ; 0689C
        clr.b   g_LevelDone(a6)                 ; 068A0
        addq.b  #SS_PLAYLEVEL,g_SubState(a6)    ; 068A4
        clr.b   g_SubState2(a6)                 ; 068A8
        clr.b   g_SubState3(a6)                 ; 068AC
        tst.b   g_ShowIntro(a6)                 ; 068B0  first level of a game: skip the progress map (the opening scene comes instead)
        beq.w   LogicExit                       ; 068B4
        addq.b  #$1,g_SubState2(a6)             ; 068B8
        bra.w   LogicExit                       ; 068BC

;---------------------------------------------------------------------------
; Sub state 1: in-level play. $2B: 0 = progress map, 1 = set up level, 2 = play
;---------------------------------------------------------------------------
PlayLevel:
        tst.b   g_RedrawDone(a6)                ; 068C0  wait for any redraw in progress
        beq.w   LogicExit                       ; 068C4
        clr.b   g_PlayerDied(a6)                ; 068C8
        cmpi.b  #$1,g_SubState2(a6)             ; 068CC
        bcs.w   ProgressMap                     ; 068D2
        bhi.w   l_06C0E                         ; 068D6

;---------------------------------------------------------------------------
; SetupLevel - PlayLevel step 1: start (or restart) the level.
;  - map pointer, boss countdown, bonus-carrier and weapon-drop state
;  - start or checkpoint position and time (LevelStartPos / LevelCheckpointPos,
;    LevelTimeStart / LevelTimeCheckpoint); at the checkpoint the screen starts
;    LevelCheckpointX further right
;  - level bounds from LevelBounds (4 bytes, each x 256: origin X, end X, height,
;    origin Y); scroll limits reset
;  - every Arthur variable cleared: armour on, no frog, no key
;  - spawn quotas, then all shot / special / enemy-shot / spawner / item / enemy slots freed
;  - first game frame: go to the opening scene instead (sub state 5), which comes back here
;  - fill g_Items from LevelItemLists (type, param, x, y; shootable scenery gets 15 hits)
;    and g_Enemies from LevelEnemyLists (the placed enemies: type, param, x, y)
;  - draw both screen buffers, the HUD (lives, timer, weapon), show Arthur -> step 2
;---------------------------------------------------------------------------
SetupLevel:
        lea.l   LevelMapTable(pc),a1            ; 068DA
        lea.l   LevelBossCountdown(pc),a2       ; 068DE
        move.w  g_Level(a6),d0                  ; 068E2
        adda.w  d0,a2                           ; 068E6
        add.w   d0,d0                           ; 068E8
        adda.w  (a1,d0.w),a1                    ; 068EA
        move.l  a1,g_MapPtr(a6)                 ; 068EE  level map
        move.b  (a2),g_BossCountdown(a6)        ; 068F2  boss hits before the key / ending (BossKilled)
        clr.b   g_BigEnemyCount(a6)             ; 068F6
        move.b  #$6,g_BonusEvery(a6)            ; 068FA  every 6th spawn carries a bonus prize
        clr.b   g_BonusCycle(a6)                ; 06900
        clr.b   g_BonusRoll(a6)                 ; 06904
        clr.b   g_WeaponOdds(a6)                ; 06908
        clr.b   g_WeaponOdds+1(a6)              ; 0690C
        clr.b   g_WeaponOdds+2(a6)              ; 06910
        clr.b   g_WeaponOdds+3(a6)              ; 06914
        clr.b   g_WeaponOdds+4(a6)              ; 06918
        lea.l   LevelStartPos(pc),a1            ; 0691C  start of the level ...
        lea.l   LevelTimeStart(pc),a2           ; 06920
        tst.b   g_Checkpoint(a6)                ; 06924
        beq.b   l_06932                         ; 06928
        lea.l   LevelCheckpointPos(pc),a1       ; 0692A  ... or the checkpoint
        lea.l   LevelTimeCheckpoint(pc),a2      ; 0692E
l_06932:
        move.w  g_Level(a6),d0                  ; 06932
        add.w   d0,d0                           ; 06936
        adda.w  d0,a1                           ; 06938
        adda.w  d0,a2                           ; 0693A
        move.w  (a2),g_TimeLeft(a6)             ; 0693C
        clr.w   d0                              ; 06940
        move.b  (a1)+,d0                        ; 06942
        move.w  d0,g_ArthurX(a6)                ; 06944
        move.b  (a1)+,d0                        ; 06948
        move.w  d0,g_ArthurY(a6)                ; 0694A
        lea.l   LevelBounds(pc),a1              ; 0694E  level bounds, in units of 256 px
        move.w  g_Level(a6),d0                  ; 06952
        lsl.w   #$2,d0                          ; 06956
        adda.w  d0,a1                           ; 06958
        move.b  (a1)+,d0                        ; 0695A
        lsl.w   #$8,d0                          ; 0695C
        move.w  d0,g_LevelOriginX(a6)           ; 0695E
        move.b  (a1)+,d0                        ; 06962
        lsl.w   #$8,d0                          ; 06964
        sub.w   g_LevelOriginX(a6),d0           ; 06966
        move.w  d0,g_LevelWidth(a6)             ; 0696A
        move.b  (a1)+,d0                        ; 0696E
        lsl.w   #$8,d0                          ; 06970
        move.w  d0,g_LevelHeight(a6)            ; 06972
        move.b  (a1)+,d0                        ; 06976
        lsl.w   #$8,d0                          ; 06978
        move.w  d0,g_LevelOriginY(a6)           ; 0697A
        sub.w   d0,g_LevelHeight(a6)            ; 0697E
        clr.w   g_ScrollTileX(a6)               ; 06982
        clr.w   g_ScrollTileY(a6)               ; 06986
        tst.b   g_Checkpoint(a6)                ; 0698A  checkpoint: start that far into the level
        beq.b   l_069A8                         ; 0698E
        lea.l   LevelCheckpointX(pc),a0         ; 06990
        move.w  g_Level(a6),d0                  ; 06994
        add.w   d0,d0                           ; 06998
        adda.w  d0,a0                           ; 0699A
        move.w  (a0),d0                         ; 0699C
        add.w   d0,g_ArthurX(a6)                ; 0699E
        lsr.w   #$4,d0                          ; 069A2
        move.w  d0,g_ScrollTileX(a6)            ; 069A4
l_069A8:
        clr.w   g_CamMinX(a6)                   ; 069A8
        clr.w   g_CamMinY(a6)                   ; 069AC
        clr.w   g_CameraX(a6)                   ; 069B0
        clr.w   g_CameraY(a6)                   ; 069B4
        clr.w   g_ScrollFineX(a6)               ; 069B8
        clr.w   g_ScrollFineY(a6)               ; 069BC
        move.w  g_ScrollTileX(a6),g_NewTileX(a6); 069C0
        move.w  g_ScrollTileY(a6),g_NewTileY(a6); 069C6
        st.b    g_MaxMapZone(a6)                ; 069CC  force UpdateMapZone to start the first zone
        st.b    g_MapZone(a6)                   ; 069D0
        clr.b   g_ArthurState(a6)               ; 069D4
        clr.b   g_NoArmour(a6)                  ; 069D8
        clr.b   g_ArthurFlash(a6)               ; 069DC
        clr.b   g_FrogTimer(a6)                 ; 069E0
        clr.b   g_KeyState(a6)                  ; 069E4
        clr.l   g_ArthurAnim(a6)                ; 069E8
        clr.b   g_ArthurAnimTimer(a6)           ; 069EC
        clr.b   g_ArthurDir(a6)                 ; 069F0
        clr.b   g_LadderDir(a6)                 ; 069F4
        clr.b   g_ArthurFacing(a6)              ; 069F8
        clr.b   g_Crouching(a6)                 ; 069FC
        clr.b   g_Jumping(a6)                   ; 06A00
        clr.b   g_Falling(a6)                   ; 06A04
        clr.b   g_FireCooldown(a6)              ; 06A08
        clr.b   g_OnPlatform(a6)                ; 06A0C
        clr.b   g_OnLadder(a6)                  ; 06A10
        clr.b   g_StateTimer(a6)                ; 06A14
        clr.l   g_ArthurVelX(a6)                ; 06A18
        clr.l   g_ArthurVelY(a6)                ; 06A1C
        clr.l   g_ArthurPlatform(a6)            ; 06A20
        tst.w   g_Level(a6)                     ; 06A24  colour 19 (sprite palette): $070 on level 0, $079 on the others
        beq.b   l_06A2E                         ; 06A28
        moveq   #$79,d1                         ; 06A2A
        bra.b   l_06A30                         ; 06A2C
l_06A2E:
        moveq   #$70,d1                         ; 06A2E
l_06A30:
        lea.l   CUSTOM,a0                       ; 06A30
        move.w  d1,COLOR19(a0)                  ; 06A36
        lea.l   LevelSpawnQuota(pc),a0          ; 06A3A  16 spawn quotas for this level
        lea.l   g_SpawnQuota(a6),a1             ; 06A3E
