        move.w  g_Level(a6),d0                  ; 06D6E
        add.w   d0,d0                           ; 06D72
        adda.w  d0,a0                           ; 06D74
        move.w  g_ScrollTileX(a6),d0            ; 06D76
        lsl.w   #$4,d0                          ; 06D7A
        add.w   g_ScrollFineX(a6),d0            ; 06D7C
        cmp.w   (a0),d0                         ; 06D80  past the half-way point? -> checkpoint
        sge.b   g_Checkpoint(a6)                ; 06D82
