        asl.w   #$4,d1                          ; 06E0E
        move.w  d0,d2                           ; 06E10
        sub.w   d1,d2                           ; 06E12
        move.w  d2,g_PendFineX(a6)              ; 06E14
        move.w  g_ScrollTileX(a6),d1            ; 06E18  and to the current origin
        asl.w   #$4,d1                          ; 06E1C
        sub.w   d1,d0                           ; 06E1E
        move.w  d0,g_CamDeltaX(a6)              ; 06E20
        cmpi.w  #$20,g_ArthurY(a6)              ; 06E24  Arthur below the bottom of the map -> fell to death
        bhi.b   l_06E64                         ; 06E2A
