;---------------------------------------------------------------------------
; ==================================================================
; IntroCutscene - sub state 5, the opening scene (shown once per game: g_ShowIntro).
; Objects: the princess in g_Enemy1 (type 15), the demon in g_Enemies slot 0 (type 6, the
; Satan graphics and animations), and Arthur's armour on the ground in special object 0.
; Steps (g_SubState3):
;   0 Arthur sits with the princess in his underwear (frame 40) at X $60; his armour
;     lies at X $50. Draw both screens; wait 60 frames. (1MB build: tune 14.)
;   1 the demon appears top right ($C5,$A0), the princess changes to frame 0; wait 20 frames.
;   2 the demon flaps for 64 frames,
;   3 then turns to dive (the 1MB build stops the music: tune 0).
;   4 it dives down-left at (-0.33, -6) px/frame until it reaches the floor; it grabs the
;     princess and Arthur is hit (ArthurState 1, pushed left).
;   5 Arthur is knocked back by the normal ArthurUpdate (g_NoArmour is clear, so it takes
;     the 'armour flies off' path; the pieces are never drawn here) while the demon carries the princess up and
;     right at (+1.125, +4.19) until Y $A0, where the princess is removed.
;   6-7 32 frames, then the demon is removed.
;   8 Arthur walks to his armour at X $50 and puts it on (g_NoArmour cleared),
;   9 walks on to X $60, stands (frame 4) for 30 frames,
;  10 and the game starts: sub state 1, progress map skipped (g_SubState2 = 1).
; ===================================================================
;---------------------------------------------------------------------------
IntroCutscene:
        lea.l   g_Enemies(a6),a5                ; 07402
        move.b  g_SubState3(a6),d0              ; 07406
        ext.w   d0                              ; 0740A
        add.w   d0,d0                           ; 0740C
        add.w   d0,d0                           ; 0740E
        jmp     IntroCutscene_Jumps(pc,d0.w)    ; 07410
IntroCutscene_Jumps:
        bra.w   Intro_Setup                     ; 07414
        bra.w   Intro_DemonAppears              ; 07418
        bra.w   Intro_DemonWait                 ; 0741C
        bra.w   Intro_DemonHover                ; 07420
        bra.w   Intro_DemonSwoop                ; 07424
        bra.w   Intro_Abduction                 ; 07428
        bra.w   Intro_Pause                     ; 0742C
        bra.w   Intro_DemonGone                 ; 07430
        bra.w   Intro_WalkToArmour              ; 07434
        bra.w   Intro_WalkOn                    ; 07438
        bra.w   Intro_Finish                    ; 0743C
Intro_Setup:
        moveq   #TUNE_INTRO,d0                  ; 07440
        clr.b   g_NoArmour(a6)                  ; 07442  [1MB build: BSR PlayMusic here - d0 is tune no.; call removed in 512K]
        move.w  #$60,g_ArthurX(a6)              ; 07446  Arthur at ($60,$40), sitting (frame 40), facing right
        move.w  #$40,g_ArthurY(a6)              ; 0744C
        move.b  #$28,g_ArthurFrame(a6)          ; 07452
        move.b  #$1,g_ArthurDir(a6)             ; 07458
        move.b  #$1,g_ArthurFacing(a6)          ; 0745E
        clr.b   g_OnLadder(a6)                  ; 07464
        clr.b   g_OnPlatform(a6)                ; 07468
        st.b    g_ArthurVisible(a6)             ; 0746C
        clr.b   g_Spr47Visible(a6)              ; 07470
        move.b  #$3c,g_StateTimer(a6)           ; 07474  60 frames
        clr.b   (a5)                            ; 0747A  demon slot free for now
        lea.l   $3c(a5),a5                      ; 0747C
        move.b  #$1,(a5)                        ; 07480  g_Enemy1 = princess: active, on screen, state 1, size 1, type 15, at ($70,$40)
        move.b  #$1,O_OnScreen(a5)              ; 07484
        move.b  #ST_ACTIVE,O_State(a5)          ; 0748A
        move.b  #$1,O_Size(a5)                  ; 07490
        move.b  #E_PRINCESS,O_Type(a5)          ; 07496
        move.w  #$70,O_X(a5)                    ; 0749C
        move.w  #$40,O_Y(a5)                    ; 074A2
        lea.l   Princess_AnimSit(pc),a0         ; 074A8
        bsr.w   SetAnim                         ; 074AC
        lea.l   g_SpecialObjs(a6),a5            ; 074B0  special object 0 = the armour on the ground: at ($50,$38), frame 2
        move.b  #$1,(a5)                        ; 074B4
        move.b  #$1,O_OnScreen(a5)              ; 074B8
        clr.b   O_Size(a5)                      ; 074BE
        move.w  #$50,O_X(a5)                    ; 074C2
        move.w  #$38,O_Y(a5)                    ; 074C8
        move.b  #$2,O_Frame(a5)                 ; 074CE
        clr.b   g_RedrawPending(a6)             ; 074D4  draw and show both screen buffers before the scene starts
        bsr.w   RedrawScreen                    ; 074D8
        bsr.w   SwapScreens                     ; 074DC
        bsr.w   ArthurSpritePos                 ; 074E0
        bsr.w   SetBitplanePtrs                 ; 074E4
        bsr.w   ShowBackBuffer                  ; 074E8
        move.w  #DMAF_SETCLR|DMAF_RASTER,CUSTOM+DMACON; 074EC  bitplane DMA on
        clr.b   g_RedrawPending(a6)             ; 074F4
        bsr.w   RedrawScreen                    ; 074F8
        bsr.w   SwapScreens                     ; 074FC
        bsr.w   ArthurSpritePos                 ; 07500
        bsr.w   SetBitplanePtrs                 ; 07504
        bsr.w   ShowBackBuffer                  ; 07508
        addq.b  #$1,g_SubState3(a6)             ; 0750C
        bra.w   Intro_Draw                      ; 07510

