        addi.l  #$fffa0000,O_Y(a5)              ; 075B2
        bsr.w   Animate                         ; 075BA
        bsr.w   ObjectMapCollide                ; 075BE  Z set = reached the floor
        bne.w   Intro_Draw                      ; 075C2
        lea.l   Satan_AnimFlap(pc),a0           ; 075C6
        bsr.w   SetAnim                         ; 075CA
        lea.l   $3c(a5),a5                      ; 075CE
        lea.l   Princess_AnimCarried(pc),a0     ; 075D2  the princess is grabbed
        bsr.w   SetAnim                         ; 075D6
        move.b  #AS_HIT,g_ArthurState(a6)       ; 075DA  Arthur hit, pushed to the left
        move.b  #$ff,g_ArthurDir(a6)            ; 075E0
        addq.b  #$1,g_SubState3(a6)             ; 075E6
        bra.w   Intro_Draw                      ; 075EA
Intro_Abduction:
        bsr.w   ArthurUpdate                    ; 075EE  Arthur: knockback flight until he lands
        tst.b   g_ArthurState(a6)               ; 075F2
