        bcc.w   Intro_Draw                      ; 07618
        addi.l  #$12000,O_X(a5)                 ; 0761C
        addi.l  #$43000,O_Y(a5)                 ; 07624
        bsr.w   Animate                         ; 0762C
        lea.l   $3c(a5),a5                      ; 07630
        addi.l  #$12000,O_X(a5)                 ; 07634
        addi.l  #$43000,O_Y(a5)                 ; 0763C
        lea.l   -$3c(a5),a5                     ; 07644
