;---------------------------------------------------------------------------
; ==================================================================
; ProgressMap - sub state 1 / g_SubState2 0, before each level (and after a life lost).
;  0 load FileProgressMap and unpack it into the spare screen: 80 lines x 5 planes,
;    each plane line RLE-packed to $2C bytes (n >= 0: copy n+1 bytes; n < 0: repeat the
;    next byte -n+1 times; -128: nothing), with blank borders. Point the map copper list
;    ($1A250) at it, and place a flashing Arthur marker from ProgressMapMarkers.
;  1 scroll the map 144 px to the left, one pixel a frame; the marker stops flashing.
;  2 hold for 100 frames, then on to level set-up (g_SubState2 = 1).
; The 1MB build stops the music and unpacks the copy kept at PROGRESS_MAP_CACHE instead
; of loading the file.
; ===================================================================
;---------------------------------------------------------------------------
ProgressMap:
        cmpi.b  #$1,g_SubState3(a6)             ; 07736
        beq.w   ProgressMap_Scroll              ; 0773C
        bhi.w   ProgressMap_Wait                ; 07740
        lea.l   FileProgressMap(pc),a1          ; 07744  load the packed map picture
        bsr.w   LoadFile                        ; 07748
        moveq   #$0,d0                          ; 0774C
        lea.l   FileProgressMap(pc),a0          ; 0774E
        movea.l (a0),a0                         ; 07752
        movea.l g_ScreenSpare1(a6),a1           ; 07754  unpack into the lower of the two spare screens
        movea.l g_ScreenSpare2(a6),a2           ; 07758
        cmpa.l  a1,a2                           ; 0775C
        bhi.b   l_07762                         ; 0775E
        movea.l a2,a1                           ; 07760
l_07762:
        move.l  a1,g_ArthurAnim(a6)             ; 07762
        move.w  #$1f3f,d7                       ; 07766  clear $7D00 bytes
l_0776A:
        clr.l   (a1)+                           ; 0776A
        dbra    d7,l_0776A                      ; 0776C
        moveq   #$2c,d5                         ; 07770  $2C bytes per plane line; 80 lines
        moveq   #$4f,d7                         ; 07772
l_07774:
        moveq   #$4,d6                          ; 07774  5 planes
l_07776:
        clr.w   d4                              ; 07776
        clr.l   (a1)+                           ; 07778  4 blank bytes at the left
l_0777A:
        clr.w   d0                              ; 0777A
        move.b  (a0)+,d0                        ; 0777C
        bmi.b   l_0778A                         ; 0777E  n < 0: run
l_07780:
        move.b  (a0)+,(a1)+                     ; 07780  n >= 0: n+1 literal bytes
        addq.w  #$1,d4                          ; 07782
        dbra    d0,l_07780                      ; 07784
        bra.b   l_07798                         ; 07788
l_0778A:
        neg.b   d0                              ; 0778A  -n+1 copies of the next byte (-128: none)
        bvs.b   l_07798                         ; 0778C
        move.b  (a0)+,d1                        ; 0778E
l_07790:
        move.b  d1,(a1)+                        ; 07790
        addq.w  #$1,d4                          ; 07792
        dbra    d0,l_07790                      ; 07794
l_07798:
        cmp.w   d5,d4                           ; 07798
        bcs.b   l_0777A                         ; 0779A
        clr.w   (a1)+                           ; 0779C  2 blank bytes at the right (line = $32 bytes)
        dbra    d6,l_07776                      ; 0779E
        dbra    d7,l_07774                      ; 077A2
        move.w  #$3e7,d7                        ; 077A6  blank area below the picture
l_077AA:
        clr.l   (a1)+                           ; 077AA
        dbra    d7,l_077AA                      ; 077AC
        bsr.w   SetMapBitplanePtrs              ; 077B0
        lea.l   CUSTOM,a0                       ; 077B4
        move.l  #$1a250,COP2LCH(a0)             ; 077BA  map copper list
        bsr.w   SwapScreens                     ; 077C2
        move.w  g_Level(a6),d0                  ; 077C6  marker = ProgressMapMarkers[level][checkpoint]
        lsl.w   #$3,d0                          ; 077CA
        tst.b   g_Checkpoint(a6)                ; 077CC
        beq.b   l_077D4                         ; 077D0
        addq.w  #$4,d0                          ; 077D2
l_077D4:
        lea.l   ProgressMapMarkers(pc,d0.w),a1  ; 077D4
        move.w  (a1)+,g_ArthurX(a6)             ; 077D8
        move.w  (a1)+,g_ArthurY(a6)             ; 077DC
        addq.w  #$8,g_ArthurX(a6)               ; 077E0
        subq.w  #$8,g_ArthurY(a6)               ; 077E4
        st.b    g_ArthurVisible(a6)             ; 077E8
        clr.b   g_Spr47Visible(a6)              ; 077EC
        clr.b   g_ArthurFrame(a6)               ; 077F0
        clr.w   g_ScrollFineX(a6)               ; 077F4
        clr.w   g_ScrollFineY(a6)               ; 077F8
        clr.w   g_ScrollTileX(a6)               ; 077FC
        clr.w   g_ScrollTileY(a6)               ; 07800
        st.b    g_ArthurFlash(a6)               ; 07804  marker flashes while the map scrolls
        addq.b  #$1,g_SubState3(a6)             ; 07808
        bra.w   LogicExit                       ; 0780C

;---------------------------------------------------------------------------
; ProgressMapMarkers - per level, two (x.w, y.w) points on the map: level start and
; checkpoint (used when g_Checkpoint is set). The marker is drawn 8 px right and 8 px
; higher. Levels 4-6 use the same point for both.
;---------------------------------------------------------------------------
ProgressMapMarkers:
	dc.b	$00,$18,$00,$40,$00,$45,$00,$40,$00,$56,$00,$40,$00,$6E,$00,$40
	dc.b	$00,$9F,$00,$40,$00,$B5,$00,$40,$00,$D1,$00,$40,$00,$EC,$00,$40
	dc.b	$01,$19,$00,$40,$01,$19,$00,$40,$01,$35,$00,$50,$01,$35,$00,$50
	dc.b	$01,$35,$00,$63,$01,$35,$00,$63
ProgressMap_Scroll:
        bsr.w   SetMapBitplanePtrs              ; 07848
        bsr.w   ArthurSpritePos                 ; 0784C
        move.w  #DMAF_SETCLR|DMAF_RASTER,CUSTOM+DMACON; 07850
        addq.w  #$1,g_GameFrame(a6)             ; 07858  drives the marker flash
        addq.w  #$1,g_ScrollFineX(a6)           ; 0785C  scroll 1 px a frame up to 144 px
        cmpi.w  #$90,g_ScrollFineX(a6)          ; 07860
        bne.w   LogicExit                       ; 07866
        clr.b   g_ArthurFlash(a6)               ; 0786A
        bsr.w   SetMapBitplanePtrs              ; 0786E
        bsr.w   ArthurSpritePos                 ; 07872
        move.b  #$64,g_StateTimer(a6)           ; 07876  then hold for 100 frames
        addq.b  #$1,g_SubState3(a6)             ; 0787C
ProgressMap_Wait:
        subq.b  #$1,g_StateTimer(a6)            ; 07880
        bne.w   LogicExit                       ; 07884
        clr.w   g_ScrollFineX(a6)               ; 07888
        clr.b   g_SubState3(a6)                 ; 0788C
        move.b  #$1,g_SubState2(a6)             ; 07890
        bra.w   LogicExit                       ; 07896

;---------------------------------------------------------------------------
; Write bitplane pointers + BPLCON1 fine scroll into the back copper list
;---------------------------------------------------------------------------
SetBitplanePtrs:
        move.l  g_ScreenFront(a6),d2            ; 0789A  front screen
        move.w  g_ScrollFineX(a6),d0            ; 0789E  + the scroll in words
        subq.w  #$1,d0                          ; 078A2
        asr.w   #$4,d0                          ; 078A4
        add.w   d0,d0                           ; 078A6
        addq.w  #$2,d0                          ; 078A8
        ext.l   d0                              ; 078AA
        add.l   d0,d2                           ; 078AC
        moveq   #$10,d0                         ; 078AE  + (16 - fine Y) lines of 180 bytes
        sub.w   g_ScrollFineY(a6),d0            ; 078B0
        mulu.w  #$b4,d0                         ; 078B4
        add.l   d0,d2                           ; 078B8
        movea.l g_CopperBack(a6),a1             ; 078BA
        moveq   #$24,d0                         ; 078BE  5 planes, 36 bytes apart (line-interleaved)
        addq.l  #$2,a1                          ; 078C0
        swap    d2                              ; 078C2
        move.w  d2,(a1)+                        ; 078C4
        addq.l  #$2,a1                          ; 078C6
        swap    d2                              ; 078C8
        move.w  d2,(a1)+                        ; 078CA
        add.l   d0,d2                           ; 078CC
        addq.l  #$2,a1                          ; 078CE
        swap    d2                              ; 078D0
        move.w  d2,(a1)+                        ; 078D2
        addq.l  #$2,a1                          ; 078D4
        swap    d2                              ; 078D6
        move.w  d2,(a1)+                        ; 078D8
        add.l   d0,d2                           ; 078DA
        addq.l  #$2,a1                          ; 078DC
        swap    d2                              ; 078DE
        move.w  d2,(a1)+                        ; 078E0
        addq.l  #$2,a1                          ; 078E2
        swap    d2                              ; 078E4
        move.w  d2,(a1)+                        ; 078E6
        add.l   d0,d2                           ; 078E8
        addq.l  #$2,a1                          ; 078EA
        swap    d2                              ; 078EC
        move.w  d2,(a1)+                        ; 078EE
        addq.l  #$2,a1                          ; 078F0
        swap    d2                              ; 078F2
        move.w  d2,(a1)+                        ; 078F4
        add.l   d0,d2                           ; 078F6
        addq.l  #$2,a1                          ; 078F8
        swap    d2                              ; 078FA
        move.w  d2,(a1)+                        ; 078FC
        addq.l  #$2,a1                          ; 078FE
        swap    d2                              ; 07900
        move.w  d2,(a1)+                        ; 07902
        moveq   #$f,d1                          ; 07904
        and.w   g_ScrollFineX(a6),d1            ; 07906
        beq.b   l_07918                         ; 0790A
        moveq   #$10,d0                         ; 0790C
        sub.w   d1,d0                           ; 0790E
        move.w  d0,d1                           ; 07910
        lsl.w   #$4,d1                          ; 07912
        or.w    d1,d0                           ; 07914
        bra.b   l_0791A                         ; 07916
l_07918:
        clr.w   d0                              ; 07918
l_0791A:
        addq.l  #$2,a1                          ; 0791A
        move.w  d0,(a1)+                        ; 0791C
        rts                                     ; 0791E

;---------------------------------------------------------------------------
; Same for the progress-map copper list
;---------------------------------------------------------------------------
SetMapBitplanePtrs:
        move.l  g_ArthurAnim(a6),d2             ; 07920  the unpacked map picture (address kept in g_ArthurAnim)
        move.w  g_ScrollFineX(a6),d0            ; 07924  + the scroll in words
        subq.w  #$1,d0                          ; 07928
        asr.w   #$4,d0                          ; 0792A
        add.w   d0,d0                           ; 0792C
        ext.l   d0                              ; 0792E
        add.l   d0,d2                           ; 07930
        lea.l   (COPPER_MAP).l,a1               ; 07932
        moveq   #$32,d0                         ; 07938  5 planes, $32 bytes apart (one map line is $32 x 5 bytes)
        addq.l  #$2,a1                          ; 0793A
        swap    d2                              ; 0793C
        move.w  d2,(a1)+                        ; 0793E
        addq.l  #$2,a1                          ; 07940
        swap    d2                              ; 07942
        move.w  d2,(a1)+                        ; 07944
        add.l   d0,d2                           ; 07946
        addq.l  #$2,a1                          ; 07948
        swap    d2                              ; 0794A
        move.w  d2,(a1)+                        ; 0794C
        addq.l  #$2,a1                          ; 0794E
        swap    d2                              ; 07950
        move.w  d2,(a1)+                        ; 07952
        add.l   d0,d2                           ; 07954
        addq.l  #$2,a1                          ; 07956
        swap    d2                              ; 07958
        move.w  d2,(a1)+                        ; 0795A
        addq.l  #$2,a1                          ; 0795C
        swap    d2                              ; 0795E
        move.w  d2,(a1)+                        ; 07960
        add.l   d0,d2                           ; 07962
        addq.l  #$2,a1                          ; 07964
        swap    d2                              ; 07966
        move.w  d2,(a1)+                        ; 07968
        addq.l  #$2,a1                          ; 0796A
        swap    d2                              ; 0796C
        move.w  d2,(a1)+                        ; 0796E
        add.l   d0,d2                           ; 07970
        addq.l  #$2,a1                          ; 07972
        swap    d2                              ; 07974
        move.w  d2,(a1)+                        ; 07976
        addq.l  #$2,a1                          ; 07978
        swap    d2                              ; 0797A
        move.w  d2,(a1)+                        ; 0797C
        moveq   #$f,d1                          ; 0797E
        and.w   g_ScrollFineX(a6),d1            ; 07980
        beq.b   l_07992                         ; 07984
        moveq   #$10,d0                         ; 07986
        sub.w   d1,d0                           ; 07988
        move.w  d0,d1                           ; 0798A
        lsl.w   #$4,d1                          ; 0798C
        or.w    d1,d0                           ; 0798E
        bra.b   l_07994                         ; 07990
l_07992:
        clr.w   d0                              ; 07992
l_07994:
        addq.l  #$2,a1                          ; 07994
        move.w  d0,(a1)+                        ; 07996
        rts                                     ; 07998
TxtTakeKey:
	dc.b	'TAKE A KEY FOR COMING IN !'
	dc.b	$00,$00

;---------------------------------------------------------------------------
; The key that drops when the boss is beaten (after 'TAKE A KEY FOR COMING IN !').
; Runs instead of the enemies and shots, so everything else on screen freezes. Steps
; (g_SubState2, the key is special object 0):
;  0 wait until Arthur reaches the end of the level (levels 0-3: within 48 px of the
;    right edge; 4-6: above the top), then place the key 37 px past the right edge at
;    KeyDropY[level]; the 1MB build plays tune 5
;  1 30 frames spinning in the air
;  2 fall at 1.24 px/frame until it reaches the floor
;  3 when Arthur is within 8 px: sound 28, 1000 points, sub state 4 (LevelComplete)
;---------------------------------------------------------------------------
EndOfLevelKey:
        lea.l   g_SpecialObjs(a6),a5            ; 079B6
        move.b  g_SubState2(a6),d0              ; 079BA
        ext.w   d0                              ; 079BE
        add.w   d0,d0                           ; 079C0
        add.w   d0,d0                           ; 079C2
        jsr     EndOfLevelKey_Jumps(pc,d0.w)    ; 079C4
        tst.b   O_OnScreen(a5)                  ; 079C8
        bne.w   QueueObjectDraw                 ; 079CC
        rts                                     ; 079D0
EndOfLevelKey_Jumps:
        bra.w   Key_Wait                        ; 079D2
        bra.w   Key_Spin                        ; 079D6
        bra.w   Key_Fall                        ; 079DA
        bra.w   Key_Take                        ; 079DE
Key_Wait:
        moveq   #$5,d0                          ; 079E2
        move.b  #$1,(a5)                        ; 079E4  active, not yet on screen
        clr.b   O_OnScreen(a5)                  ; 079E8
        clr.b   O_State(a5)                     ; 079EC
        clr.b   O_Step(a5)                      ; 079F0
        clr.b   O_Size(a5)                      ; 079F4
        move.b  #$1e,Key_Timer(a5)              ; 079F8  spin for 30 frames
        cmpi.w  #$4,g_Level(a6)                 ; 079FE  levels 4-6 end at the top
        bcc.b   l_07A40                         ; 07A04
        moveq   #-48,d0                         ; 07A06  within 48 px of the right edge?
        add.w   g_LevelWidth(a6),d0             ; 07A08
        cmp.w   g_ArthurX(a6),d0                ; 07A0C
        bhi.b   l_07A3E                         ; 07A10
l_07A12:
        moveq   #$25,d0                         ; 07A12  key: 37 px right of the edge, at KeyDropY
        add.w   g_LevelWidth(a6),d0             ; 07A14
        move.w  d0,O_X(a5)                      ; 07A18
        move.w  g_Level(a6),d0                  ; 07A1C
        add.w   d0,d0                           ; 07A20
        move.w  KeyDropY(pc,d0.w),d0            ; 07A22
        sub.w   g_LevelOriginY(a6),d0           ; 07A26
        move.w  d0,O_Y(a5)                      ; 07A2A
        lea.l   Key_AnimSpin(pc),a0             ; 07A2E
        bsr.w   SetAnim                         ; 07A32
        bsr.w   CheckOnScreen                   ; 07A36
        addq.b  #$1,g_SubState2(a6)             ; 07A3A
l_07A3E:
        rts                                     ; 07A3E
l_07A40:
        moveq   #$20,d0                         ; 07A40  above the top?
        add.w   g_LevelHeight(a6),d0            ; 07A42
        cmp.w   g_ArthurY(a6),d0                ; 07A46
        bhi.b   l_07A3E                         ; 07A4A
        bra.b   l_07A12                         ; 07A4C

;---------------------------------------------------------------------------
; Per level (0-5): height the key appears at (level coordinates, before g_LevelOriginY)
;---------------------------------------------------------------------------
KeyDropY:
	dc.b	$00,$B0,$00,$B0,$02,$B0,$02,$B0,$06,$90,$0A,$A0
Key_Spin:
        subq.b  #$1,Key_Timer(a5)               ; 07A5A
        beq.b   l_07A68                         ; 07A5E
        bsr.w   Animate                         ; 07A60
        bra.w   CheckOnScreen                   ; 07A64
l_07A68:
        lea.l   Key_AnimFall(pc),a0             ; 07A68
        bsr.w   SetAnim                         ; 07A6C
        bsr.w   CheckOnScreen                   ; 07A70
        addq.b  #$1,g_SubState2(a6)             ; 07A74
        rts                                     ; 07A78
Key_Fall:
        addi.l  #$fffec300,O_Y(a5)              ; 07A7A  fall 1.24 px/frame
        bsr.w   Animate                         ; 07A82
        bsr.w   ObjectMapCollide                ; 07A86  Z set = landed
        bne.b   l_07A90                         ; 07A8A
        addq.b  #$1,g_SubState2(a6)             ; 07A8C
l_07A90:
        bra.w   CheckOnScreen                   ; 07A90
Key_Take:
        move.w  g_ArthurX(a6),d0                ; 07A94  Arthur within 8 px?
        sub.w   O_X(a5),d0                      ; 07A98
        addq.w  #$8,d0                          ; 07A9C
        cmp.w   #$10,d0                         ; 07A9E
        bhi.b   l_07AD8                         ; 07AA2
        move.w  g_ArthurY(a6),d0                ; 07AA4
        sub.w   O_Y(a5),d0                      ; 07AA8
        addq.w  #$8,d0                          ; 07AAC
        cmp.w   #$10,d0                         ; 07AAE
        bhi.b   l_07AD8                         ; 07AB2
        clr.b   (a5)                            ; 07AB4
        clr.b   O_OnScreen(a5)                  ; 07AB6
        moveq   #SFX_PICKUP,d0                  ; 07ABA
        bsr.w   PlaySfx                         ; 07ABC
        moveq   #PTS_1000,d0                    ; 07AC0
        bsr.w   AddScore                        ; 07AC2
        move.b  #SS_LEVELCOMPLETE,g_SubState(a6); 07AC6  -> LevelComplete
        clr.b   g_SubState2(a6)                 ; 07ACC
        clr.b   g_SubState3(a6)                 ; 07AD0
        clr.b   g_KeyState(a6)                  ; 07AD4
l_07AD8:
        rts                                     ; 07AD8

;---------------------------------------------------------------------------
; Key spinning: frames 16, 17, 18, 17
;---------------------------------------------------------------------------
Key_AnimSpin:
	AF	$10,3
	AF	$11,3
	AF	$12,3
	AL	$11,3,Key_AnimSpin

;---------------------------------------------------------------------------
; Key falling: frame 19
;---------------------------------------------------------------------------
Key_AnimFall:
	AF	$13,1
	AF	$13,1
	AL	$13,1,Key_AnimFall

;---------------------------------------------------------------------------
; Look up the map zone of the cell under the camera (g_ScrollTileX/Y >> 4, in MapZoneTable). On a change, stop the spawners
; (except those flagged to keep running) and start the zone's list from ZoneSpawners:
; count.b, then per spawner two bytes: hi nibble of byte 1 = enemy type (= spawner slot),
; lo nibble of byte 1 / lo nibble of byte 2 = script number, hi nibble of byte 2 = flags
; (bit 0 world coordinates, bit 1 run once). Types with ZoneFlags = 0 only spawn in a zone
; further on than any reached before (no respawns when walking back).
;---------------------------------------------------------------------------
UpdateMapZone:
        move.w  g_ScrollTileX(a6),d0            ; 07AEC  map cell under the camera: column ...
        asr.w   #$4,d0                          ; 07AF0
        bpl.b   l_07AF6                         ; 07AF2
        clr.w   d0                              ; 07AF4
l_07AF6:
        move.w  g_ScrollTileY(a6),d1            ; 07AF6  ... and row (32 cells a row)
        asr.w   #$4,d1                          ; 07AFA
        asl.w   #$5,d1                          ; 07AFC
        bpl.b   l_07B02                         ; 07AFE
        clr.w   d1                              ; 07B00
l_07B02:
        add.w   d0,d1                           ; 07B02  -> offset into WorldMap -> zone from MapZoneTable
        add.l   g_MapPtr(a6),d1                 ; 07B04
        lea.l   WorldMap(pc),a1                 ; 07B08
        sub.l   a1,d1                           ; 07B0C
        lea.l   MapZoneTable(pc),a1             ; 07B0E
        move.b  (a1,d1.w),d0                    ; 07B12
        cmp.b   g_MapZone(a6),d0                ; 07B16  same zone as last frame: nothing to do
        beq.w   l_07BC6                         ; 07B1A
        move.b  d0,g_MapZone(a6)                ; 07B1E
        lea.l   g_Spawners(a6),a5               ; 07B22  zone changed: stop every spawner not flagged to keep running
        moveq   #$f,d7                          ; 07B26
l_07B28:
        btst    #$2,Spn_Flags(a5)               ; 07B28
        bne.b   l_07B32                         ; 07B2E
        clr.b   (a5)                            ; 07B30
l_07B32:
        lea.l   $c(a5),a5                       ; 07B32
        dbra    d7,l_07B28                      ; 07B36
        lea.l   ZoneSpawners(pc),a2             ; 07B3A  the zone's spawner list (ZoneSpawners: byte offset to count + entries)
        ext.w   d0                              ; 07B3E
        adda.w  d0,a2                           ; 07B40
        move.b  (a2),d0                         ; 07B42
        adda.w  d0,a2                           ; 07B44
        move.b  (a2)+,d7                        ; 07B46
        ext.w   d7                              ; 07B48
        subq.w  #$1,d7                          ; 07B4A
        bmi.b   l_07BB8                         ; 07B4C
l_07B4E:
        clr.w   d1                              ; 07B4E  entry: type (high nibble of byte 1), script number, flags (high nibble of byte 2)
        move.b  (a2)+,d1                        ; 07B50
        move.b  (a2)+,d2                        ; 07B52
        move.w  d1,d0                           ; 07B54
        lsr.w   #$4,d0                          ; 07B56
        lsl.b   #$4,d1                          ; 07B58
        moveq   #$f,d3                          ; 07B5A
        and.b   d2,d3                           ; 07B5C
        or.b    d3,d1                           ; 07B5E
        lea.l   SpawnScripts(pc),a1             ; 07B60  SpawnScripts: per type a byte offset to a word-offset table of scripts
        adda.w  d0,a1                           ; 07B64
        move.b  (a1),d3                         ; 07B66
        adda.w  d3,a1                           ; 07B68
        add.w   d1,d1                           ; 07B6A
        adda.w  d1,a1                           ; 07B6C
        adda.w  (a1),a1                         ; 07B6E
        move.w  (a1),d6                         ; 07B70  empty script: skip
        beq.b   l_07BB4                         ; 07B72
        move.w  d0,d1                           ; 07B74  start the spawner of this type: active, first spawn in 10 frames,
        mulu.w  #$c,d1                          ; 07B76
        lea.l   g_Spawners(a6),a0               ; 07B7A
        adda.w  d1,a0                           ; 07B7E
        st.b    (a0)                            ; 07B80
        move.b  #$a,$a(a0)                      ; 07B82
        move.l  a1,$6(a0)                       ; 07B88  script start and position, entries left, flags
        addq.l  #$2,a1                          ; 07B8C
        move.l  a1,$2(a0)                       ; 07B8E
        move.b  d6,$1(a0)                       ; 07B92
        lsr.b   #$4,d2                          ; 07B96
        move.b  d2,$b(a0)                       ; 07B98
        lea.l   ZoneFlags(pc,d0.w),a1           ; 07B9C  types with ZoneFlags = 0 (bosses, Red Arremer, Big Man) keep running and only
        tst.b   (a1)                            ; 07BA0
        bne.b   l_07BB4                         ; 07BA2
        bset    #$2,$b(a0)                      ; 07BA4  start in a zone beyond any reached before
        move.b  g_MapZone(a6),d0                ; 07BAA
        cmp.b   g_MaxMapZone(a6),d0             ; 07BAE
        sgt.b   (a0)                            ; 07BB2
l_07BB4:
        dbra    d7,l_07B4E                      ; 07BB4
l_07BB8:
        move.b  g_MapZone(a6),d0                ; 07BB8
        cmp.b   g_MaxMapZone(a6),d0             ; 07BBC
        ble.b   l_07BC6                         ; 07BC0
        move.b  d0,g_MaxMapZone(a6)             ; 07BC2
l_07BC6:
        rts                                     ; 07BC6
ZoneFlags:
	dc.b	$01,$01,$01,$01,$01,$00,$00,$01,$00,$01,$00,$01,$00,$00,$01,$01

;---------------------------------------------------------------------------
; 256-byte bit-reversal table used to build Arthur's mirrored sprite frames
;---------------------------------------------------------------------------
BitReverseTable:
