ClearHudArea:
        lea.l   (CLEAR_AREA).l,a0               ; 07CD8
        move.w  #$2cf,d7                        ; 07CDE
l_07CE2:
        clr.l   (a0)+                           ; 07CE2
        dbra    d7,l_07CE2                      ; 07CE4
        rts                                     ; 07CE8

;---------------------------------------------------------------------------
; Display, audio and interrupt set-up:
;  BPLCON0 $5200 (5 planes), DDF $40-$C0, DIW $34A1-$24A1, modulos $92
;  all audio channels silent, vector $60 = MUSIC_PLAYER
;  CIA-A: serial (keyboard) interrupt only
;  vectors: $64 L1 = Level1Logic, $68 L2 = KeyboardIRQ, $6C L3 = VblIRQ
;  INTENA = SOFTINT|PORTS|VERTB, waits for line $12C before returning
;---------------------------------------------------------------------------
InitHardware:
        lea.l   CUSTOM,a0                       ; 07CEA
        move.w  #DMAF_MASTER,DMACON(a0)         ; 07CF0  bitplane DMA off while setting up
        move.w  #$5200,BPLCON0(a0)              ; 07CF6  5 bitplanes, lores
        move.w  #$0,BPLCON1(a0)                 ; 07CFC
        move.w  #$24,BPLCON2(a0)                ; 07D02
        move.w  #$92,BPL1MOD(a0)                ; 07D08  modulo 146: 180-byte interleaved lines, 34 bytes fetched
        move.w  #$92,BPL2MOD(a0)                ; 07D0E
        move.w  #$40,DDFSTRT(a0)                ; 07D14  fetch 17 words (272 px: one more than shown, for the scroll)
        move.w  #$c0,DDFSTOP(a0)                ; 07D1A
        move.w  #$34a1,DIWSTRT(a0)              ; 07D20  display window: 240 lines from line 52, 256 px wide
        move.w  #$24a1,DIWSTOP(a0)              ; 07D26
        moveq   #$7f,d0                         ; 07D2C  audio: silent, period 1
        move.w  d0,AUD0LEN(a0)                  ; 07D2E
        move.w  d0,AUD1LEN(a0)                  ; 07D32
        move.w  d0,AUD2LEN(a0)                  ; 07D36
        move.w  d0,AUD3LEN(a0)                  ; 07D3A
        moveq   #$1,d0                          ; 07D3E
        move.w  d0,AUD0PER(a0)                  ; 07D40
        move.w  d0,AUD1PER(a0)                  ; 07D44
        move.w  d0,AUD2PER(a0)                  ; 07D48
        move.w  d0,AUD3PER(a0)                  ; 07D4C
        moveq   #$0,d0                          ; 07D50
        move.w  d0,AUD0VOL(a0)                  ; 07D52
        move.w  d0,AUD1VOL(a0)                  ; 07D56
        move.w  d0,AUD2VOL(a0)                  ; 07D5A
        move.w  d0,AUD3VOL(a0)                  ; 07D5E
        lea.l   (MUSIC_PLAYER).l,a1             ; 07D62
        move.l  a1,(VEC_SPURIOUS).w             ; 07D68  vector $60 = music player (called through it by VblIRQ and PlaySfx)
        move.w  #$ff,ADKCON(a0)                 ; 07D6C
        move.w  #DMAF_SETCLR|DMAF_AUD3|DMAF_AUD2|DMAF_AUD1|DMAF_AUD0,DMACON(a0); 07D72
        lea.l   $bfe001.l,a1                    ; 07D78
        move.b  #$7f,$d00(a1)                   ; 07D7E  CIA-A: all interrupts off, then the keyboard (SP) on
        move.b  #$88,$d00(a1)                   ; 07D84
        andi.b  #$80,$e00(a1)                   ; 07D8A  CIA-A CRA: keep only bit 7
        move.w  #$aaaa,g_RandSeed(a6)           ; 07D90
        clr.w   g_FrameStamp(a6)                ; 07D96
        clr.w   g_VblCount(a6)                  ; 07D9A
        clr.w   g_GameFrame(a6)                 ; 07D9E
        clr.b   g_ArthurVisible(a6)             ; 07DA2
        clr.b   g_Spr47Visible(a6)              ; 07DA6
        clr.b   g_RedrawPending(a6)             ; 07DAA
        st.b    g_SkipLogic(a6)                 ; 07DAE
        move.l  g_CopperFront(a6),COP2LCH(a0)   ; 07DB2  copper: COP1 = the init list at COPPER_INIT, COP2 = the front list
        move.l  #$1a118,COP1LCH(a0)             ; 07DB8
        move.w  COPJMP1(a0),d0                  ; 07DC0
        move.w  #INTF_INTEN|INTF_EXTER|INTF_DSKSYNC|INTF_RBF|INTF_AUD3|INTF_AUD2|INTF_AUD1|INTF_AUD0|INTF_BLIT|INTF_VERTB|INTF_COPER|INTF_PORTS|INTF_SOFTINT|INTF_DSKBLK|INTF_TBE,INTENA(a0); 07DC4  all interrupts off before installing the vectors
        lea.l   Level1Logic(pc),a1              ; 07DCA  level 1 autovector
        move.l  a1,(VEC_LEVEL1).w               ; 07DCE
        lea.l   KeyboardIRQ(pc),a1              ; 07DD2  level 2 autovector
        move.l  a1,(VEC_LEVEL2).w               ; 07DD6
        lea.l   VblIRQ(pc),a1                   ; 07DDA  level 3 autovector
        move.l  a1,(VEC_LEVEL3).w               ; 07DDE
        clr.l   $1a114.l                        ; 07DE2  clear the long before COPPER_INIT
        move.w  #DMAF_SETCLR|DMAF_BLITHOG|DMAF_MASTER|DMAF_RASTER|DMAF_COPPER|DMAF_BLITTER|DMAF_SPRITE|DMAF_DISK,DMACON(a0); 07DE8  DMA on: blitter priority, master, bitplanes, copper, blitter, sprites, disk
        move.w  #INTF_INTEN|INTF_EXTER|INTF_DSKSYNC|INTF_RBF|INTF_AUD3|INTF_AUD2|INTF_AUD1|INTF_AUD0|INTF_BLIT|INTF_VERTB|INTF_COPER|INTF_PORTS|INTF_SOFTINT|INTF_DSKBLK|INTF_TBE,INTREQ(a0); 07DEE
        move.w  #INTF_SETCLR|INTF_INTEN|INTF_VERTB|INTF_PORTS|INTF_SOFTINT,INTENA(a0); 07DF4  INTENA = SET|INTEN|VERTB|PORTS|SOFTINT
l_07DFA:
        move.l  VPOSR(a0),d0                    ; 07DFA  wait for raster line 300
        andi.l  #$1ffff,d0                      ; 07DFE
        cmp.l   #$12c00,d0                      ; 07E04
        bcs.b   l_07DFA                         ; 07E0A
        rts                                     ; 07E0C

;---------------------------------------------------------------------------
; CopperTemplate - $180 bytes copied to COPPER_INIT at start-up. First the COP1 list: the
; 16 lines above line $44 from $64468, the eight sprite pointers, then at line $44 the copper
; interrupt and a jump to COP2. Then the four playfield lists that COP2 rotates through
; (g_CopperFront / g_CopperBack / spares; their plane pointers are rewritten for the scroll) and
; the progress-map list. Bitplanes are line-interleaved: 5 planes of 36 bytes per 180-byte line.
;---------------------------------------------------------------------------
; COPPER_INIT (COP1): before line $44 the 16-line strip at $64468, all eight sprites,
; then the copper interrupt and a jump to COP2 (the front list)
CopperTemplate:
	dc.w	BPLCON1,$0000	; no fine scroll
	dc.w	BPL1PTH,$0006,BPL1PTL,$4468	; BPL1PT = $64468
	dc.w	BPL2PTH,$0006,BPL2PTL,$448C	; BPL2PT = $6448C
	dc.w	BPL3PTH,$0006,BPL3PTL,$44B0	; BPL3PT = $644B0
	dc.w	BPL4PTH,$0006,BPL4PTL,$44D4	; BPL4PT = $644D4
	dc.w	BPL5PTH,$0006,BPL5PTL,$44F8	; BPL5PT = $644F8
	dc.w	SPR0PTH,$0003,SPR0PTL,$0EB8	; SPR0PT = $30EB8
	dc.w	SPR1PTH,$0003,SPR1PTL,$0F84	; SPR1PT = $30F84
	dc.w	SPR2PTH,$0003,SPR2PTL,$1050	; SPR2PT = $31050
	dc.w	SPR3PTH,$0003,SPR3PTL,$111C	; SPR3PT = $3111C
	dc.w	SPR4PTH,$0003,SPR4PTL,$0BB8	; SPR4PT = $30BB8
	dc.w	SPR5PTH,$0003,SPR5PTL,$0C78	; SPR5PT = $30C78
	dc.w	SPR6PTH,$0003,SPR6PTL,$0D38	; SPR6PT = $30D38
	dc.w	SPR7PTH,$0003,SPR7PTL,$0DF8	; SPR7PT = $30DF8
	dc.w	$4401,$FF00	; WAIT line $44
	dc.w	INTREQ,$8010	; set COPER: the copper interrupt (level 3)
	dc.w	COPJMP2,$0000	; jump to COP2LC (the front list)
; COPPER_A1: playfield planes in SCREEN_0 (one of the four lists COP2 points at)
	dc.w	BPL1PTH,$0003,BPL1PTL,$746A	; BPL1PT = $3746A
	dc.w	BPL2PTH,$0003,BPL2PTL,$748E	; BPL2PT = $3748E
	dc.w	BPL3PTH,$0003,BPL3PTL,$74B2	; BPL3PT = $374B2
	dc.w	BPL4PTH,$0003,BPL4PTL,$74D6	; BPL4PT = $374D6
	dc.w	BPL5PTH,$0003,BPL5PTL,$74FA	; BPL5PT = $374FA
	dc.w	BPLCON1,$0000	; no fine scroll
	dc.w	$FFFF,$FFFE	; end of list
; COPPER_A2: SCREEN_1
	dc.w	BPL1PTH,$0004,BPL1PTL,$286A	; BPL1PT = $4286A
	dc.w	BPL2PTH,$0004,BPL2PTL,$288E	; BPL2PT = $4288E
	dc.w	BPL3PTH,$0004,BPL3PTL,$28B2	; BPL3PT = $428B2
	dc.w	BPL4PTH,$0004,BPL4PTL,$28D6	; BPL4PT = $428D6
	dc.w	BPL5PTH,$0004,BPL5PTL,$28FA	; BPL5PT = $428FA
	dc.w	BPLCON1,$0000	; no fine scroll
	dc.w	$FFFF,$FFFE	; end of list
; COPPER_B1: SCREEN_2
	dc.w	BPL1PTH,$0004,BPL1PTL,$DC6A	; BPL1PT = $4DC6A
	dc.w	BPL2PTH,$0004,BPL2PTL,$DC8E	; BPL2PT = $4DC8E
	dc.w	BPL3PTH,$0004,BPL3PTL,$DCB2	; BPL3PT = $4DCB2
	dc.w	BPL4PTH,$0004,BPL4PTL,$DCD6	; BPL4PT = $4DCD6
	dc.w	BPL5PTH,$0004,BPL5PTL,$DCFA	; BPL5PT = $4DCFA
	dc.w	BPLCON1,$0000	; no fine scroll
	dc.w	$FFFF,$FFFE	; end of list
; COPPER_B2: SCREEN_3
	dc.w	BPL1PTH,$0005,BPL1PTL,$906A	; BPL1PT = $5906A
	dc.w	BPL2PTH,$0005,BPL2PTL,$908E	; BPL2PT = $5908E
	dc.w	BPL3PTH,$0005,BPL3PTL,$90B2	; BPL3PT = $590B2
	dc.w	BPL4PTH,$0005,BPL4PTL,$90D6	; BPL4PT = $590D6
	dc.w	BPL5PTH,$0005,BPL5PTL,$90FA	; BPL5PT = $590FA
	dc.w	BPLCON1,$0000	; no fine scroll
	dc.w	$FFFF,$FFFE	; end of list
; COPPER_MAP: the between-level progress map (50-byte lines, modulo $D8 then $92)
	dc.w	BPL1PTH,$0004,BPL1PTL,$DC6A	; BPL1PT = $4DC6A
	dc.w	BPL2PTH,$0004,BPL2PTL,$DC9C	; BPL2PT = $4DC9C
	dc.w	BPL3PTH,$0004,BPL3PTL,$DCCE	; BPL3PT = $4DCCE
	dc.w	BPL4PTH,$0004,BPL4PTL,$DD00	; BPL4PT = $4DD00
	dc.w	BPL5PTH,$0004,BPL5PTL,$DD32	; BPL5PT = $4DD32
	dc.w	BPLCON1,$0000	; no fine scroll
	dc.w	BPL1MOD,$00D8
	dc.w	BPL2MOD,$00D8
	dc.w	$FFE1,$FFFE	; WAIT line $FF, x $E0 (the PAL wrap: later waits are lines $100+)
	dc.w	$2401,$FF00	; WAIT line $24 ($124 after the wrap)
	dc.w	BPL1MOD,$0092
	dc.w	BPL2MOD,$0092
	dc.w	$FFFF,$FFFE	; end of list

;---------------------------------------------------------------------------
; LevelFileIndex - per level a word offset, from the entry, to its tile file in FileTable
; (LoadLevel).
;---------------------------------------------------------------------------
LevelFileIndex:
	dc.w	FileLevel0-*	; level 0
	dc.w	FileLevel1-*	; level 1
	dc.w	FileLevel2-*	; level 2
	dc.w	FileLevel3-*	; level 3
	dc.w	FileLevel4-*	; level 4
	dc.w	FileLevel5-*	; level 5
	dc.w	FileLevel6-*	; level 6

;---------------------------------------------------------------------------
; FileTable - every file the program loads (FENTRY: load address, length in bytes, first
; track; a1 points at an entry for LoadFile, which reads length / 6,312 tracks, rounded up).
; The bootblock loads the rest: the loading screen and the main program. tools/disk/mkdisk.py
; reads this table (from the assembled binaries of both builds) to lay out the disk.
;---------------------------------------------------------------------------
FileTable:
	FENTRY	$37468,$05400,33	; tracks 33-36: Arthur's sprite frames
FileSmallBobs:
	FENTRY	$311E8,$00D20,37	; track 37: small item / scenery BOBs
FileEnemyBobs:
	FENTRY	$37468,$1D042,38	; tracks 38-56: enemy BOB sets
FileItemGfx2:
	FENTRY	$1CF8E,$00EA6,57	; track 57: weapon / effect BOBs, tail
FileEnemyShotGfx:
	FENTRY	$1A298,$01234,58	; track 58: enemy shot BOBs
FileItemGfx:
	FENTRY	$1B4CC,$01AC2,59	; tracks 59-60: weapon / pickup / effect BOBs
FileFont:
	FENTRY	$37468,$01840,61	; track 61: font
FileProgressMap:
	FENTRY	$311E8,$01D5C,62	; tracks 62-63: progress map (RLE)
FileMusic:
	FENTRY	$28E54,$07D64,126	; tracks 126-131: sound driver and effects (512K)
FileCopyrightScreen:
	FENTRY	$4DC68,$025FE,82	; tracks 82-83: copyright warning screen (RLE)
FileLevel0:
	FENTRY	$65548,$07440,84	; tracks 84-88: level 0 tiles
FileLevel1:
	FENTRY	$65548,$0C120,89	; tracks 89-96: level 1 tiles
FileLevel2:
	FENTRY	$65548,$05460,97	; tracks 97-100: level 2 tiles
FileLevel3:
	FENTRY	$65548,$04880,101	; tracks 101-103: level 3 tiles
FileLevel4:
	FENTRY	$65548,$02760,104	; tracks 104-105: level 4 tiles
FileLevel5:
	FENTRY	$65548,$029E0,106	; tracks 106-107: level 5 tiles
FileLevel6:
	FENTRY	$65548,$019A0,108	; tracks 108-109: level 6 tiles

;---------------------------------------------------------------------------
; Switch to the screen RedrawScreen has just drawn at g_NewTileX/Y: the pending
; offsets become the current ones (fine scroll clamped to -16..15), then the buffers
; are rotated (falls into SwapScreens)
;---------------------------------------------------------------------------
CameraJump:
        move.w  g_PendFineX(a6),d0              ; 08046
        move.w  d0,g_CamDeltaX(a6)              ; 0804A
        cmp.w   #$f,d0                          ; 0804E
        ble.b   l_08058                         ; 08052
        moveq   #$f,d0                          ; 08054
        bra.b   l_08060                         ; 08056
l_08058:
        cmp.w   #$fff0,d0                       ; 08058
        bge.b   l_08060                         ; 0805C
        moveq   #-16,d0                         ; 0805E
l_08060:
        move.w  d0,g_ScrollFineX(a6)            ; 08060
        move.w  g_PendFineY(a6),d0              ; 08064
        move.w  d0,g_CamDeltaY(a6)              ; 08068
        cmp.w   #$f,d0                          ; 0806C
        ble.b   l_08076                         ; 08070
        moveq   #$f,d0                          ; 08072
        bra.b   l_0807E                         ; 08074
l_08076:
        cmp.w   #$fff0,d0                       ; 08076
        bge.b   l_0807E                         ; 0807A
        moveq   #-16,d0                         ; 0807C
l_0807E:
        move.w  d0,g_ScrollFineY(a6)            ; 0807E

;---------------------------------------------------------------------------
; SwapScreens - adopt the new tile origin (g_NewTileX/Y) and rotate the four screen
; buffers and copper lists: the two just redrawn become the working pair, the old pair
; the spares for the next redraw. Both restore lists are emptied.
;---------------------------------------------------------------------------
SwapScreens:
        move.w  g_NewTileX(a6),g_ScrollTileX(a6); 08082
        move.w  g_NewTileY(a6),g_ScrollTileY(a6); 08088
        movea.l g_ScreenBack(a6),a1             ; 0808E
        movea.l g_ScreenFront(a6),a2            ; 08092
        move.l  g_ScreenSpare1(a6),g_ScreenBack(a6); 08096
        move.l  g_ScreenSpare2(a6),g_ScreenFront(a6); 0809C
        move.l  a1,g_ScreenSpare1(a6)           ; 080A2
        move.l  a2,g_ScreenSpare2(a6)           ; 080A6
        movea.l g_CopperFront(a6),a1            ; 080AA
        movea.l g_CopperBack(a6),a2             ; 080AE
        move.l  g_CopperSpare1(a6),g_CopperFront(a6); 080B2
        move.l  g_CopperSpare2(a6),g_CopperBack(a6); 080B8
        move.l  a1,g_CopperSpare1(a6)           ; 080BE
        move.l  a2,g_CopperSpare2(a6)           ; 080C2
        lea.l   g_RestoreBufB(a6),a1            ; 080C6
        clr.w   -(a1)                           ; 080CA
        move.l  a1,g_RestoreListA(a6)           ; 080CC
        lea.l   g_SpawnQuota(a6),a1             ; 080D0
        clr.w   -(a1)                           ; 080D4
        move.l  a1,g_RestoreListB(a6)           ; 080D6
        rts                                     ; 080DA

;---------------------------------------------------------------------------
; ShowBackBuffer - wait for the copper interrupt (INTREQ bit 4, raised by the copper
; list), point COP2LC at the copper list just built, then swap front and back screens,
; save areas, restore lists and save pointers for the next frame
;---------------------------------------------------------------------------
ShowBackBuffer:
        lea.l   CUSTOM,a0                       ; 080DC
        movea.l g_CopperBack(a6),a1             ; 080E2
        move.l  g_CopperFront(a6),g_CopperBack(a6); 080E6
        move.l  a1,g_CopperFront(a6)            ; 080EC
l_080F0:
        moveq   #$10,d0                         ; 080F0  wait for the copper interrupt
        and.w   INTREQR(a0),d0                  ; 080F2
        beq.b   l_080F0                         ; 080F6
        move.l  a1,COP2LCH(a0)                  ; 080F8
        move.w  #INTF_COPER,INTREQ(a0)          ; 080FC
        movea.l g_ScreenFront(a6),a1            ; 08102
        move.l  g_ScreenBack(a6),g_ScreenFront(a6); 08106
        move.l  a1,g_ScreenBack(a6)             ; 0810C
        movea.l g_SavePtr(a6),a1                ; 08110  swap the save-area pointers, restore lists and save areas
        move.l  g_SavePtrB(a6),g_SavePtr(a6)    ; 08114
        move.l  a1,g_SavePtrB(a6)               ; 0811A
        movea.l g_RestoreListA(a6),a1           ; 0811E
        move.l  g_RestoreListB(a6),g_RestoreListA(a6); 08122
        move.l  a1,g_RestoreListB(a6)           ; 08128
        movea.l g_SaveBufA(a6),a1               ; 0812C
        move.l  g_SaveBufB(a6),g_SaveBufA(a6)   ; 08130
        move.l  a1,g_SaveBufB(a6)               ; 08136
        rts                                     ; 0813A

;---------------------------------------------------------------------------
; Compute SPRxPOS/CTL for Arthur's two attached sprite pairs (hidden while flashing)
;---------------------------------------------------------------------------
ArthurSpritePos:
        moveq   #$0,d0                          ; 0813C
        moveq   #$20,d1                         ; 0813E
        move.w  g_ScrollTileY(a6),d0            ; 08140
        lsl.w   #$4,d0                          ; 08144
        add.w   g_ScrollFineY(a6),d0            ; 08146
        sub.w   g_ArthurY(a6),d0                ; 0814A
        moveq   #-16,d2                         ; 0814E
        cmp.w   d2,d0                           ; 08150
        ble.b   l_08156                         ; 08152
        move.l  d2,d0                           ; 08154
l_08156:
        addi.w  #$124,d0                        ; 08156
        add.w   d0,d1                           ; 0815A
        moveq   #$0,d2                          ; 0815C
        sub.w   g_ScrollTileX(a6),d2            ; 0815E
        asl.w   #$4,d2                          ; 08162
        sub.w   g_ScrollFineX(a6),d2            ; 08164
        addi.w  #$90,d2                         ; 08168
        add.w   g_ArthurX(a6),d2                ; 0816C
        tst.b   g_ArthurFlash(a6)               ; 08170
        beq.b   l_08182                         ; 08174
        btst    #$2,g_VblCount+1(a6)            ; 08176
        beq.b   l_08182                         ; 0817C
        move.w  #$1a1,d2                        ; 0817E
l_08182:
        swap    d0                              ; 08182
        rol.l   #$8,d0                          ; 08184
        lsl.w   #$2,d0                          ; 08186
        lsr.w   #$1,d2                          ; 08188
        swap    d2                              ; 0818A
        roxl.w  #$1,d2                          ; 0818C
        rol.w   #$8,d1                          ; 0818E
        lsl.b   #$1,d1                          ; 08190
        or.l    d1,d0                           ; 08192
        or.l    d2,d0                           ; 08194
        move.l  d0,d1                           ; 08196
        bset    #$7,d1                          ; 08198
        move.l  #$80000,d2                      ; 0819C
        move.l  d0,g_ArthurSprCtl(a6)           ; 081A2
        move.l  d1,g_ArthurSprCtl+4(a6)         ; 081A6
