        move.w  (a0),(a1)+                      ; 081C4
        move.w  d0,(a0)+                        ; 081C6
        dbra    d7,l_081C2                      ; 081C8
        not.b   g_CurPlayer(a6)                 ; 081CC
        rts                                     ; 081D0

;---------------------------------------------------------------------------
; Probe the map under Arthur's feet; snaps Y to the floor. Out: N set = in the air
