ArthurFloorCheck:
        moveq   #-8,d6                          ; 081D2  probe 8 px left of centre, 16 px below
        add.w   g_ArthurX(a6),d6                ; 081D4
        moveq   #-16,d7                         ; 081D8
        add.w   g_ArthurY(a6),d7                ; 081DA
        bsr.w   MapTileAt                       ; 081DE
        move.b  $4(a1),d0                       ; 081E2
        andi.b  #$c0,d0                         ; 081E6
        bne.b   l_08202                         ; 081EA
        move.b  (a1),d0                         ; 081EC
        ext.w   d0                              ; 081EE
        lea.l   FloorProfile(pc),a1             ; 081F0
        adda.w  d0,a1                           ; 081F4
        move.b  (a1),d1                         ; 081F6
        beq.b   l_08202                         ; 081F8
        moveq   #$f,d0                          ; 081FA
        and.b   d7,d0                           ; 081FC
        sub.b   d0,d1                           ; 081FE
        bcc.b   l_08236                         ; 08200
l_08202:
        moveq   #$8,d6                          ; 08202  then 8 px right
        add.w   g_ArthurX(a6),d6                ; 08204
        moveq   #-16,d7                         ; 08208
        add.w   g_ArthurY(a6),d7                ; 0820A
        bsr.w   MapTileAt                       ; 0820E
        move.b  $4(a1),d0                       ; 08212
        andi.b  #$c0,d0                         ; 08216
        bne.b   l_08232                         ; 0821A
        move.b  (a1),d0                         ; 0821C
        ext.w   d0                              ; 0821E
        lea.l   FloorProfile(pc),a1             ; 08220
        adda.w  d0,a1                           ; 08224
        move.b  (a1),d1                         ; 08226
        beq.b   l_08232                         ; 08228
        moveq   #$f,d0                          ; 0822A
        and.w   d7,d0                           ; 0822C
        sub.b   d0,d1                           ; 0822E
        bcc.b   l_08236                         ; 08230
l_08232:
