;---------------------------------------------------------------------------
; Per item type 1-5 (shootable scenery, then the platforms): width Arthur can stand on
;---------------------------------------------------------------------------
PlatformSizes:
	dc.b	$18,$1E,$3E,$20,$34

;---------------------------------------------------------------------------
; Per item type 1-5: height (Arthur stands on the top). Item type 1 - gravestones and
; other shootable scenery - is solid too; only types 2-5 carry him (Itm_Rider).
;---------------------------------------------------------------------------
PlatformHeights:
	dc.b	$26,$30,$30,$2E,$2A

;---------------------------------------------------------------------------
; d3,d4 = probe point. Out: Z clear if standing on a moving platform/item
;---------------------------------------------------------------------------
ArthurOnPlatform:
        lea.l   g_Items(a6),a5                  ; 0824A
        moveq   #$1d,d7                         ; 0824E
l_08250:
        tst.b   O_OnScreen(a5)                  ; 08250  each on-screen item of type 1-5
        beq.w   l_082E2                         ; 08254
        clr.w   d0                              ; 08258
        move.b  O_Type(a5),d0                   ; 0825A
        beq.w   l_082E2                         ; 0825E
        subq.w  #$1,d0                          ; 08262  width and height of this item type
        lea.l   PlatformSizes(pc,d0.w),a1       ; 08264
        lea.l   PlatformHeights(pc,d0.w),a2     ; 08268
        clr.w   d1                              ; 0826C
        move.b  (a1),d1                         ; 0826E
        move.w  d1,d2                           ; 08270  probe X within the width?
        lsr.w   #$1,d2                          ; 08272
        add.w   d3,d2                           ; 08274
        sub.w   O_X(a5),d2                      ; 08276
        cmp.w   d1,d2                           ; 0827A
        bhi.b   l_082E2                         ; 0827C
        clr.w   d1                              ; 0827E
        move.b  (a2),d1                         ; 08280
        move.w  d1,d2                           ; 08282  probe Y within the height?
        lsr.w   #$1,d2                          ; 08284
        add.w   d4,d2                           ; 08286
        sub.w   O_Y(a5),d2                      ; 08288
        cmp.w   d1,d2                           ; 0828C
        bhi.b   l_082E2                         ; 0828E
        tst.b   g_Falling(a6)                   ; 08290  falling: only when he is above its middle
        beq.b   l_082A0                         ; 08294
        move.w  g_ArthurY(a6),d1                ; 08296
        sub.w   O_Y(a5),d1                      ; 0829A
        bmi.b   l_082E2                         ; 0829E
l_082A0:
        move.w  g_ArthurY(a6),d2                ; 082A0  within 3 px of the top: snap onto it
        sub.w   O_Y(a5),d2                      ; 082A4
        addq.w  #$3,d2                          ; 082A8
        cmp.w   #$6,d2                          ; 082AA
        bcs.b   l_082BE                         ; 082AE
        clr.w   d1                              ; 082B0
        move.b  (a2),d1                         ; 082B2
        lsr.w   #$1,d1                          ; 082B4
        add.w   O_Y(a5),d1                      ; 082B6
        move.w  d1,g_ArthurY(a6)                ; 082BA
l_082BE:
        cmpi.b  #$2,O_Type(a5)                  ; 082BE  type 2-5 (moving): it carries him - mark it as his platform
        bcs.b   l_082DE                         ; 082C4
        move.l  g_ArthurPlatform(a6),d0         ; 082C6
        beq.b   l_082D2                         ; 082CA
        movea.l d0,a0                           ; 082CC
        clr.b   $18(a0)                         ; 082CE
l_082D2:
        move.l  a5,g_ArthurPlatform(a6)         ; 082D2
        st.b    Itm_Rider(a5)                   ; 082D6
        st.b    g_OnPlatform(a6)                ; 082DA
l_082DE:
        moveq   #-1,d0                          ; 082DE
        rts                                     ; 082E0
l_082E2:
        lea.l   $1c(a5),a5                      ; 082E2
        dbra    d7,l_08250                      ; 082E6
        moveq   #$0,d0                          ; 082EA
        rts                                     ; 082EC

;---------------------------------------------------------------------------
; a1 = animation table (two variants selected by facing)
;---------------------------------------------------------------------------
ArthurSetAnim:
        tst.b   g_ArthurFacing(a6)              ; 082EE
        bpl.b   l_082F6                         ; 082F2
        addq.l  #$2,a1                          ; 082F4
l_082F6:
        adda.w  (a1),a1                         ; 082F6

;---------------------------------------------------------------------------
; Start Arthur's animation script a1 as it is (no facing table) and show its first frame
;---------------------------------------------------------------------------
ArthurSetScript:
        move.l  a1,g_ArthurAnim(a6)             ; 082F8
        clr.b   g_ArthurAnimTimer(a6)           ; 082FC
        bra.b   l_08308                         ; 08300

;---------------------------------------------------------------------------
; Step Arthur's animation script; armour-less frames are +$10
;---------------------------------------------------------------------------
ArthurAnimate:
        subq.b  #$1,g_ArthurAnimTimer(a6)       ; 08302
        bne.b   l_08346                         ; 08306
l_08308:
        movea.l g_ArthurAnim(a6),a1             ; 08308
        move.b  (a1)+,g_ArthurFrame(a6)         ; 0830C
        move.b  (a1)+,d0                        ; 08310
        bpl.b   l_08318                         ; 08312
        neg.b   d0                              ; 08314
        adda.w  (a1),a1                         ; 08316
l_08318:
        move.b  d0,g_ArthurAnimTimer(a6)        ; 08318
        move.l  a1,g_ArthurAnim(a6)             ; 0831C
        tst.b   g_ArthurState(a6)               ; 08320
        bne.b   l_08346                         ; 08324
        tst.b   g_FrogTimer(a6)                 ; 08326
        bne.b   l_08346                         ; 0832A
        tst.b   g_NoArmour(a6)                  ; 0832C
        beq.b   l_08346                         ; 08330
        tst.b   g_ArthurFrame(a6)               ; 08332
        bmi.b   l_08340                         ; 08336
        addi.b  #$10,g_ArthurFrame(a6)          ; 08338
        rts                                     ; 0833E
l_08340:
        subi.b  #$10,g_ArthurFrame(a6)          ; 08340
l_08346:
        rts                                     ; 08346
ArmourDebris:
	dc.b	$01,$08,$08,$02,$08,$F8,$03,$F8,$F8,$04,$F8,$08

;---------------------------------------------------------------------------
; State 1. With armour: it flies off as 4 pieces (shot type 5, sound 1) and he is knocked
; back. Without: he dies (the 1MB build plays tune 8, or 7 on the last life).
;---------------------------------------------------------------------------
ArthurHit:
        clr.b   g_FrogTimer(a6)                 ; 08354  no longer a frog
        tst.b   g_NoArmour(a6)                  ; 08358
        bne.b   l_083AE                         ; 0835C
        lea.l   ArmourDebris(pc),a1             ; 0835E
        lea.l   g_Shots(a6),a5                  ; 08362
        moveq   #$3,d7                          ; 08366
l_08368:
        clr.b   O_State(a5)                     ; 08368
        clr.b   O_Step(a5)                      ; 0836C
        clr.b   O_Step2(a5)                     ; 08370
        move.b  #$2,(a5)                        ; 08374
        clr.b   O_OnScreen(a5)                  ; 08378
        move.b  (a1)+,O_Dir(a5)                 ; 0837C
        move.b  (a1)+,d0                        ; 08380
        ext.w   d0                              ; 08382
        add.w   g_ArthurX(a6),d0                ; 08384
        move.w  d0,O_X(a5)                      ; 08388
        move.b  (a1)+,d0                        ; 0838C
        ext.w   d0                              ; 0838E
        add.w   g_ArthurY(a6),d0                ; 08390
        move.w  d0,O_Y(a5)                      ; 08394
        move.b  #$5,O_Type(a5)                  ; 08398  shot type 5: a piece of armour
        lea.l   $26(a5),a5                      ; 0839E
        dbra    d7,l_08368                      ; 083A2
        moveq   #SFX_ARTHUR_HIT,d0              ; 083A6
        bsr.w   PlaySfx                         ; 083A8
        bra.b   l_083BA                         ; 083AC
l_083AE:
        moveq   #$8,d0                          ; 083AE  no armour: dying. d0 = tune for the 1MB build: 8, or 7 (game over) on the last life
        cmpi.b  #$1,g_Lives(a6)                 ; 083B0
        bne.b   l_083BA                         ; 083B6
        moveq   #TUNE_GAME_OVER,d0              ; 083B8
l_083BA:
        addq.b  #AS_HIT,g_ArthurState(a6)       ; 083BA  [1MB build: BSR PlayMusic here - d0 is tune no.; call removed in 512K]
        rts                                     ; 083BE

;---------------------------------------------------------------------------
; State 2: thrown up and away from the enemy (the same launch as a jump: 4.25 up,
; 0.5 across), facing it
;---------------------------------------------------------------------------
ArthurKnockback:
        move.b  g_ArthurDir(a6),g_ArthurFacing(a6); 083C0  face the enemy (the opposite of the way he is pushed)
        neg.b   g_ArthurFacing(a6)              ; 083C6
        st.b    g_Jumping(a6)                   ; 083CA
        move.w  g_ArthurY(a6),g_ArthurAux(a6)   ; 083CE
        clr.b   g_Falling(a6)                   ; 083D4
        clr.b   g_FireCooldown(a6)              ; 083D8
        clr.b   g_LadderDir(a6)                 ; 083DC
        move.l  #$8000,g_ArthurVelX(a6)         ; 083E0  0.5 px/frame away
        move.l  #$44000,g_ArthurVelY(a6)        ; 083E8  4.25 px/frame up
        lea.l   ArthurAnimKnockback(pc),a1      ; 083F0
        tst.b   g_NoArmour(a6)                  ; 083F4
        beq.b   l_083FE                         ; 083F8
        lea.l   ArthurAnimKnockbackBare(pc),a1  ; 083FA
l_083FE:
        bsr.w   ArthurSetAnim                   ; 083FE
        addq.b  #AS_HIT,g_ArthurState(a6)       ; 08402
        rts                                     ; 08406

;---------------------------------------------------------------------------
; State 3: fly until he lands
;---------------------------------------------------------------------------
ArthurKnockFly:
        bsr.w   ArthurJump                      ; 08408
        tst.b   g_Jumping(a6)                   ; 0840C
        bne.b   l_08416                         ; 08410
        addq.b  #AS_HIT,g_ArthurState(a6)       ; 08412
l_08416:
        rts                                     ; 08416

;---------------------------------------------------------------------------
; State 4: landed. Armour lost now: flash (invulnerable) for 120 frames and carry on in
; his underwear; already without armour: start dying (20 + 40 + 225 frames)
;---------------------------------------------------------------------------
ArthurLand:
        bsr.w   ArthurFall                      ; 08418
        tst.b   g_Falling(a6)                   ; 0841C
        bne.b   l_08450                         ; 08420
        tst.b   g_NoArmour(a6)                  ; 08422
        beq.b   l_08452                         ; 08426
        tst.b   g_OnPlatform(a6)                ; 08428
        beq.b   l_0843E                         ; 0842C
        move.l  g_ArthurPlatform(a6),d0         ; 0842E
        beq.b   l_0843E                         ; 08432
        movea.l d0,a0                           ; 08434
        clr.b   $18(a0)                         ; 08436
        clr.b   g_OnPlatform(a6)                ; 0843A
l_0843E:
        lea.l   ArthurAnimDie1(pc),a1           ; 0843E
        bsr.w   ArthurSetAnim                   ; 08442
        move.b  #$14,g_StateTimer(a6)           ; 08446
        addq.b  #AS_HIT,g_ArthurState(a6)       ; 0844C
l_08450:
        rts                                     ; 08450
l_08452:
        move.b  #$78,g_ArthurFlash(a6)          ; 08452  flash for 120 frames: enemies cannot hurt him
        neg.b   g_ArthurFacing(a6)              ; 08458
        st.b    g_NoArmour(a6)                  ; 0845C  armour gone
        lea.l   ArthurAnims(pc),a1              ; 08460
        bsr.w   ArthurSetAnim                   ; 08464
        clr.b   g_ArthurDir(a6)                 ; 08468
        clr.b   g_ArthurState(a6)               ; 0846C
        clr.b   g_Jumping(a6)                   ; 08470
        clr.b   g_Falling(a6)                   ; 08474
        clr.b   g_OnLadder(a6)                  ; 08478
        rts                                     ; 0847C
ArthurDie1:
        subq.b  #$1,g_StateTimer(a6)            ; 0847E
        bne.w   ArthurAnimate                   ; 08482
        clr.b   g_FrogTimer(a6)                 ; 08486
        move.b  #$28,g_StateTimer(a6)           ; 0848A
        lea.l   ArthurAnimDie2(pc),a1           ; 08490
        bsr.w   ArthurSetAnim                   ; 08494
        addq.b  #AS_HIT,g_ArthurState(a6)       ; 08498
        rts                                     ; 0849C
ArthurDie2:
        subq.b  #$1,g_StateTimer(a6)            ; 0849E
        bne.w   ArthurAnimate                   ; 084A2
        move.b  #$e1,g_StateTimer(a6)           ; 084A6  225 frames
        addq.b  #AS_HIT,g_ArthurState(a6)       ; 084AC
        rts                                     ; 084B0

;---------------------------------------------------------------------------
; Sets g_PlayerDied when the death animation finishes
;---------------------------------------------------------------------------
ArthurDie3:
        subq.b  #$1,g_StateTimer(a6)            ; 084B2
        bne.b   l_084C0                         ; 084B6
        clr.b   g_ArthurState(a6)               ; 084B8
        st.b    g_PlayerDied(a6)                ; 084BC  tell the game loop
l_084C0:
        rts                                     ; 084C0

;---------------------------------------------------------------------------
; ==================================================================
; ArthurUpdate - Arthur's state machine (g_ArthurState):
;  0 normal (walk / jump / fall / crouch / ladder / frog)   1 hit
;  2 knockback start   3 knockback flight   4 landed after the knockback
;  5-7 death animation
; Positions and speeds are 16.16 fixed point, Y increasing upwards.
;   walk     1.125 px/frame (ArthurWalk)
;   jump     up 4.25 px/frame, gravity 0.24 px/frame^2 (falls at up to 5 px/frame):
;            rises for 17 frames, about 39 px high; forward jumps start at 0.5 px/frame and
;            speed up by 0.06 px/frame while rising - about 44 px over a 35-frame jump.
;            Direction is fixed for the whole jump.
;   ladder   1.375 px/frame up or down
;   frog     g_FrogTimer x 64 frames (8 = 512 frames); can walk and jump, not climb or fire
; ===================================================================
;---------------------------------------------------------------------------
ArthurUpdate:
        clr.w   d0                              ; 084C2
        move.b  g_ArthurState(a6),d0            ; 084C4
        add.w   d0,d0                           ; 084C8
        add.w   d0,d0                           ; 084CA
        jmp     ArthurUpdate_Jumps(pc,d0.w)     ; 084CC
ArthurUpdate_Jumps:
        bra.w   ArthurNormal                    ; 084D0
        bra.w   ArthurHit                       ; 084D4
        bra.w   ArthurKnockback                 ; 084D8
        bra.w   ArthurKnockFly                  ; 084DC
        bra.w   ArthurLand                      ; 084E0
        bra.w   ArthurDie1                      ; 084E4
        bra.w   ArthurDie2                      ; 084E8
        bra.w   ArthurDie3                      ; 084EC

;---------------------------------------------------------------------------
; State 0: frog / jumping / falling / crouching / ladder / walking. Order: up or down
; (ladder, jump, crouch), climb, fire, left / right, then the floor test (walking off an
; edge starts a fall) and the platform test.
;---------------------------------------------------------------------------
ArthurNormal:
        tst.b   g_FrogTimer(a6)                 ; 084F0
        bne.w   ArthurFrog                      ; 084F4
        tst.b   g_ArthurFlash(a6)               ; 084F8
        beq.b   l_08502                         ; 084FC
        subq.b  #$1,g_ArthurFlash(a6)           ; 084FE  invulnerable flash counting down
l_08502:
        tst.b   g_Jumping(a6)                   ; 08502
        bne.w   ArthurJump                      ; 08506
        tst.b   g_Falling(a6)                   ; 0850A
        bne.w   ArthurFall                      ; 0850E
        tst.b   g_Crouching(a6)                 ; 08512
        bne.w   ArthurCrouch                    ; 08516
        bsr.w   ArthurReadUpDown                ; 0851A
        tst.b   d0                              ; 0851E
        beq.b   l_08528                         ; 08520
        tst.b   g_OnLadder(a6)                  ; 08522
        bne.b   l_08576                         ; 08526
l_08528:
        tst.b   g_OnLadder(a6)                  ; 08528
        bne.w   ArthurClimb                     ; 0852C
        bsr.w   ArthurFire                      ; 08530  fire (ArthurFire) before moving
        tst.b   g_Jumping(a6)                   ; 08534
        bne.b   l_08576                         ; 08538
        bsr.w   ArthurReadLeftRight             ; 0853A
        tst.b   g_ArthurDir(a6)                 ; 0853E
        beq.b   l_08548                         ; 08542
        bsr.w   ArthurWalk                      ; 08544
l_08548:
        tst.b   g_OnPlatform(a6)                ; 08548
        beq.b   l_0855A                         ; 0854C
        movea.l g_ArthurPlatform(a6),a0         ; 0854E
        clr.b   $18(a0)                         ; 08552
        clr.b   g_OnPlatform(a6)                ; 08556
l_0855A:
        bsr.w   ArthurFloorCheck                ; 0855A  floor under his feet? no: start falling
        smi.b   g_Falling(a6)                   ; 0855E
        move.w  g_ArthurX(a6),d3                ; 08562
        move.w  g_ArthurY(a6),d4                ; 08566
        subq.w  #$1,d4                          ; 0856A
        bsr.w   ArthurOnPlatform                ; 0856C
        beq.b   l_08576                         ; 08570
        clr.b   g_Falling(a6)                   ; 08572
l_08576:
        tst.b   g_Falling(a6)                   ; 08576
        bpl.b   l_08580                         ; 0857A
        clr.b   g_ArthurDir(a6)                 ; 0857C
l_08580:
        rts                                     ; 08580

;---------------------------------------------------------------------------
; Normal state while transformed into a frog (g_FrogTimer)
;---------------------------------------------------------------------------
ArthurFrog:
        tst.b   g_ArthurFlash(a6)               ; 08582
        beq.b   l_0858C                         ; 08586
        subq.b  #$1,g_ArthurFlash(a6)           ; 08588
l_0858C:
        moveq   #$3f,d0                         ; 0858C
        and.w   g_GameFrame(a6),d0              ; 0858E
        bne.b   l_085A2                         ; 08592
        subq.b  #$1,g_FrogTimer(a6)             ; 08594  every 64 frames
        bne.b   l_085A2                         ; 08598
        lea.l   ArthurAnims(pc),a1              ; 0859A  back to normal
        bra.w   ArthurSetAnim                   ; 0859E
l_085A2:
        tst.b   g_Jumping(a6)                   ; 085A2
        bne.b   l_0860A                         ; 085A6
        tst.b   g_Falling(a6)                   ; 085A8
        bne.w   l_086AC                         ; 085AC
        bsr.w   ArthurReadUpDown                ; 085B0
        bne.w   ArthurClimb                     ; 085B4
        bsr.w   ArthurReadLeftRight             ; 085B8
        tst.b   g_ArthurDir(a6)                 ; 085BC
        beq.b   l_085C6                         ; 085C0
        bsr.w   ArthurWalk                      ; 085C2
l_085C6:
        tst.b   g_OnPlatform(a6)                ; 085C6
        beq.b   l_085D8                         ; 085CA
        movea.l g_ArthurPlatform(a6),a0         ; 085CC
        clr.b   $18(a0)                         ; 085D0
        clr.b   g_OnPlatform(a6)                ; 085D4
l_085D8:
        bsr.w   ArthurFloorCheck                ; 085D8
        smi.b   g_Falling(a6)                   ; 085DC
        move.w  g_ArthurX(a6),d3                ; 085E0
        move.w  g_ArthurY(a6),d4                ; 085E4
        subq.w  #$1,d4                          ; 085E8
        bsr.w   ArthurOnPlatform                ; 085EA
        beq.b   l_085F4                         ; 085EE
        clr.b   g_Falling(a6)                   ; 085F0
l_085F4:
        tst.b   g_Falling(a6)                   ; 085F4
        bpl.b   l_085FE                         ; 085F8
        clr.b   g_ArthurDir(a6)                 ; 085FA
l_085FE:
        rts                                     ; 085FE

;---------------------------------------------------------------------------
; Jump (and knockback) physics. Rising: X += vx (if moving), Y += vy, vx += $FA0,
; vy -= $3D90; below $3DFF it starts to fall: Y -= vy, vy += $3D90 up to 5 px/frame.
; Walls stop the horizontal part. Leaving a platform drops it.
;---------------------------------------------------------------------------
ArthurJump:
        tst.b   g_ArthurState(a6)               ; 08600
        bne.b   l_0860A                         ; 08604
        bsr.w   ArthurFire                      ; 08606
l_0860A:
