        tst.b   g_ArthurDir(a6)                 ; 0860E
        beq.b   l_08634                         ; 08612
        bpl.b   l_08626                         ; 08614
        bsr.w   WallCheckLeft                   ; 08616  jumping left
        bne.b   l_08634                         ; 0861A
        move.l  g_ArthurVelX(a6),d0             ; 0861C
        sub.l   d0,g_ArthurX(a6)                ; 08620
        bra.b   l_08634                         ; 08624
