;---------------------------------------------------------------------------
ArthurFall:
        tst.b   g_ArthurState(a6)               ; 08698
        bne.b   l_086AC                         ; 0869C
        bsr.w   ArthurFire                      ; 0869E
        tst.b   g_FireCooldown(a6)              ; 086A2
        bne.b   l_086AC                         ; 086A6
        bsr.w   ArthurAnimate                   ; 086A8
l_086AC:
        move.l  g_ArthurVelX(a6),d0             ; 086AC
        tst.b   g_ArthurDir(a6)                 ; 086B0
        beq.b   l_086BE                         ; 086B4
        bpl.b   l_086BA                         ; 086B6
        neg.l   d0                              ; 086B8
l_086BA:
        add.l   d0,g_ArthurX(a6)                ; 086BA
l_086BE:
        move.l  g_ArthurVelY(a6),d0             ; 086BE
        sub.l   d0,g_ArthurY(a6)                ; 086C2
        move.l  g_ArthurVelX(a6),d0             ; 086C6
        addi.l  #$fa0,d0                        ; 086CA
        tst.w   d0                              ; 086D0
        bmi.b   l_086D8                         ; 086D2
        move.l  d0,g_ArthurVelX(a6)             ; 086D4
l_086D8:
        cmpi.w  #$5,g_ArthurVelY(a6)            ; 086D8
        bcc.b   l_086E8                         ; 086DE
        addi.l  #$3d90,g_ArthurVelY(a6)         ; 086E0
l_086E8:
