        move.w  g_ArthurY(a6),d4                ; 086EC
        subq.w  #$1,d4                          ; 086F0
        bsr.w   ArthurOnPlatform                ; 086F2
        bne.b   l_08726                         ; 086F6
        bsr.w   ArthurFloorCheck                ; 086F8
        smi.b   g_Falling(a6)                   ; 086FC
        bmi.b   l_08724                         ; 08700
        clr.l   g_ArthurVelX(a6)                ; 08702  landed
        clr.b   g_Jumping(a6)                   ; 08706
        tst.b   g_FrogTimer(a6)                 ; 0870A
        beq.b   l_08716                         ; 0870E
        lea.l   ArthurAnimFrog(pc),a1           ; 08710
        bra.b   l_0871A                         ; 08714
l_08716:
