        clr.b   g_Jumping(a6)                   ; 0872A
        lea.l   ArthurAnims(pc),a1              ; 0872E
        tst.b   g_Crouching(a6)                 ; 08732
        beq.b   l_0873C                         ; 08736
        lea.l   ArthurAnimCrouch(pc),a1         ; 08738
l_0873C:
        bsr.w   ArthurSetAnim                   ; 0873C
