ArthurCrouch:
        clr.b   g_ArthurDir(a6)                 ; 08744
        bsr.w   ArthurReadUpDown                ; 08748
        bsr.w   ArthurFire                      ; 0874C
        bsr.w   ArthurAnimate                   ; 08750
        tst.b   g_OnPlatform(a6)                ; 08754
        beq.b   l_08770                         ; 08758
        bsr.w   ArthurOnPlatform                ; 0875A
        seq.b   g_Falling(a6)                   ; 0875E
        bne.b   l_08770                         ; 08762
        clr.b   g_OnPlatform(a6)                ; 08764
        movea.l g_ArthurPlatform(a6),a0         ; 08768
        clr.b   $18(a0)                         ; 0876C
l_08770:
