        bne.b   l_087B0                         ; 08796
        tst.b   g_Crouching(a6)                 ; 08798
        beq.b   l_087A8                         ; 0879C
        lea.l   ArthurAnimCrouch(pc),a1         ; 0879E
        bsr.w   ArthurSetAnim                   ; 087A2
        bra.b   l_087B0                         ; 087A6
l_087A8:
        lea.l   ArthurAnims(pc),a1              ; 087A8
l_087AC:
        bsr.w   ArthurSetAnim                   ; 087AC
l_087B0:
