;---------------------------------------------------------------------------
; Up: climb a ladder he stands at (or carry on climbing / step off at the top), else
; jump (sound 4). Down: step onto a ladder 18 px below his feet (moving 14 px down), carry
; on down, else crouch. Out: d0 nonzero = up or down was acted on.
;---------------------------------------------------------------------------
ArthurReadUpDown:
        clr.b   g_Crouching(a6)                 ; 087E6  up / down only count when held for two VBL samples
        move.w  g_Joy(a6),d0                    ; 087EA
        and.w   g_JoyPrev(a6),d0                ; 087EE
        btst    #$8,d0                          ; 087F2  up held (bit 8)
        bne.b   l_08808                         ; 087F6
        btst    #$0,d0                          ; 087F8  down held (bit 0)
        bne.w   l_088E6                         ; 087FC
        clr.b   g_LadderDir(a6)                 ; 08800  neither: not on a ladder move
        st.b    d0                              ; 08804
        rts                                     ; 08806
l_08808:
        tst.b   g_FrogTimer(a6)                 ; 08808  up: a frog cannot climb, he jumps
        bne.b   l_08884                         ; 0880C
        move.w  g_ArthurX(a6),d6                ; 0880E
        move.w  g_ArthurY(a6),d7                ; 08812
        bsr.w   LadderCheck                     ; 08816  ladder here?
        beq.b   l_08840                         ; 0881A
        tst.b   g_LadderDir(a6)                 ; 0881C  already climbing up: carry on
        bgt.b   l_0883C                         ; 08820
        st.b    g_OnLadder(a6)                  ; 08822  start climbing up
        clr.b   g_ArthurDir(a6)                 ; 08826
        lea.l   ArthurAnimClimb(pc),a1          ; 0882A
        bsr.w   ArthurSetScript                 ; 0882E
        move.b  #$1,g_LadderDir(a6)             ; 08832
        st.b    d0                              ; 08838
        rts                                     ; 0883A
l_0883C:
        clr.b   d0                              ; 0883C
        rts                                     ; 0883E
l_08840:
        tst.b   g_OnLadder(a6)                  ; 08840  no ladder at his feet: at the top of one?
        beq.b   l_08884                         ; 08844
        move.b  g_StateTimer(a6),d0             ; 08846  at the top of a ladder: getting-off animation steps (0, 10, 17)
        beq.b   l_0885A                         ; 0884A
        cmp.b   #$a,d0                          ; 0884C
        beq.b   l_08860                         ; 08850
        cmp.b   #$11,d0                         ; 08852
        beq.b   l_08870                         ; 08856
        bra.b   l_08868                         ; 08858
l_0885A:
        lea.l   ArthurAnimLadderTop1(pc),a1     ; 0885A
        bra.b   l_08864                         ; 0885E
l_08860:
        lea.l   ArthurAnimLadderTop2(pc),a1     ; 08860
l_08864:
        bsr.w   ArthurSetScript                 ; 08864
l_08868:
        addq.b  #$1,g_StateTimer(a6)            ; 08868
        st.b    d0                              ; 0886C
        rts                                     ; 0886E
l_08870:
        clr.b   g_OnLadder(a6)                  ; 08870  off the ladder: standing
        clr.b   g_StateTimer(a6)                ; 08874
        lea.l   ArthurAnims(pc),a1              ; 08878
        bsr.w   ArthurSetAnim                   ; 0887C
        clr.b   d0                              ; 08880
        rts                                     ; 08882
l_08884:
        tst.b   g_LadderDir(a6)                 ; 08884  up and not on a ladder: jump (not while climbing)
        bhi.b   l_0883C                         ; 08888
        st.b    g_Jumping(a6)                   ; 0888A  jump
        tst.b   g_FrogTimer(a6)                 ; 0888E
        beq.b   l_0889A                         ; 08892
        lea.l   ArthurAnimFrogJump(pc),a1       ; 08894
        bra.b   l_088A8                         ; 08898
l_0889A:
        lea.l   ArthurAnimJump(pc),a1           ; 0889A
        tst.b   g_ArthurDir(a6)                 ; 0889E
        beq.b   l_088A8                         ; 088A2
        lea.l   ArthurAnimJumpFwd(pc),a1        ; 088A4
l_088A8:
        bsr.w   ArthurSetAnim                   ; 088A8
        moveq   #SFX_JUMP,d0                    ; 088AC
        bsr.w   PlaySfx                         ; 088AE
l_088B2:
        move.w  g_ArthurY(a6),g_ArthurAux(a6)   ; 088B2
        clr.l   g_ArthurVelX(a6)                ; 088B8
        move.l  #$8000,g_ArthurVelX(a6)         ; 088BC  0.5 px/frame forward if he is moving, else straight up
        tst.b   g_ArthurDir(a6)                 ; 088C4
        bne.b   l_088CE                         ; 088C8
        clr.l   g_ArthurVelX(a6)                ; 088CA
l_088CE:
        move.l  #$44000,g_ArthurVelY(a6)        ; 088CE  4.25 px/frame up
        clr.b   g_FireCooldown(a6)              ; 088D6
        clr.b   g_LadderDir(a6)                 ; 088DA
        tst.b   g_ArthurDir(a6)                 ; 088DE
        st.b    d0                              ; 088E2
        rts                                     ; 088E4
l_088E6:
        tst.b   g_FrogTimer(a6)                 ; 088E6  down: a frog cannot climb
        bne.b   l_08926                         ; 088EA
        move.w  g_ArthurX(a6),d6                ; 088EC
        moveq   #-18,d7                         ; 088F0  ladder 18 px below his feet?
        add.w   g_ArthurY(a6),d7                ; 088F2
        bsr.w   LadderCheck                     ; 088F6
        beq.b   l_0896C                         ; 088FA
        tst.b   g_LadderDir(a6)                 ; 088FC  already on a ladder going down: carry on
        bmi.b   l_0891C                         ; 08900
        tst.b   g_OnLadder(a6)                  ; 08902
        bne.b   l_0891C                         ; 08906
        st.b    g_LadderDir(a6)                 ; 08908
        subi.w  #$e,g_ArthurY(a6)               ; 0890C  step down onto it
        st.b    g_OnLadder(a6)                  ; 08912
        clr.b   g_ArthurDir(a6)                 ; 08916
        bra.b   l_0892A                         ; 0891A
l_0891C:
        st.b    g_LadderDir(a6)                 ; 0891C  stepping down from the top: run the getting-on poses
        tst.b   g_StateTimer(a6)                ; 08920
        bne.b   l_0892A                         ; 08924
l_08926:
        clr.b   d0                              ; 08926
        rts                                     ; 08928
l_0892A:
        tst.b   g_StateTimer(a6)                ; 0892A
        bne.b   l_08938                         ; 0892E
        move.b  #$11,g_StateTimer(a6)           ; 08930
        bra.b   l_08948                         ; 08936
l_08938:
        cmpi.b  #$11,g_StateTimer(a6)           ; 08938  BUG: compares d0 ($FF from LadderCheck) instead of g_StateTimer, so the
        beq.b   l_08948                         ; 0893E
        cmp.b   #$a,d0                          ; 08940  second pose (ArthurAnimLadderTop1 at step 10) never shows going down
        beq.b   l_0894E                         ; 08944
        bra.b   l_08956                         ; 08946
l_08948:
        lea.l   ArthurAnimLadderTop2(pc),a1     ; 08948
        bra.b   l_08952                         ; 0894C
l_0894E:
        lea.l   ArthurAnimLadderTop1(pc),a1     ; 0894E
l_08952:
        bsr.w   ArthurSetScript                 ; 08952
l_08956:
        subq.b  #$1,g_StateTimer(a6)            ; 08956
        beq.b   l_08960                         ; 0895A
        st.b    d0                              ; 0895C
        rts                                     ; 0895E
l_08960:
        lea.l   ArthurAnimClimb(pc),a1          ; 08960  poses done: climbing
        bsr.w   ArthurSetScript                 ; 08964
        clr.b   d0                              ; 08968
        rts                                     ; 0896A
l_0896C:
        st.b    g_Crouching(a6)                 ; 0896C  crouch
        clr.b   g_OnLadder(a6)                  ; 08970
        tst.b   g_FireCooldown(a6)              ; 08974
        bne.b   l_08988                         ; 08978
        tst.b   g_LadderDir(a6)                 ; 0897A
        bmi.b   l_08988                         ; 0897E
        lea.l   ArthurAnimCrouch(pc),a1         ; 08980
        bsr.w   ArthurSetAnim                   ; 08984
l_08988:
        st.b    d0                              ; 08988
        rts                                     ; 0898A

;---------------------------------------------------------------------------
; torch 2, lance 3, axe 2, cross 3, dagger 3
;---------------------------------------------------------------------------
MaxShotsPerWeapon:
	dc.b	$02,$03,$02,$03,$03,$00

;---------------------------------------------------------------------------
; On fire press: spawn a shot of type g_Weapon if a slot is free (sfx 6)
;---------------------------------------------------------------------------
ArthurFire:
        tst.b   g_PlayerDied(a6)                ; 08992
        bne.w   l_08A62                         ; 08996
        cmpi.b  #$5,g_FireCooldown(a6)          ; 0899A  can fire again once the cooldown is down to 5
        bhi.w   l_08A40                         ; 089A0
        move.w  g_JoyPrev(a6),d0                ; 089A4  fire newly pressed?
        not.w   d0                              ; 089A8
        and.w   g_Joy(a6),d0                    ; 089AA
        bpl.w   l_08A40                         ; 089AE
        lea.l   g_Shots(a6),a0                  ; 089B2
        move.w  g_Weapon(a6),d0                 ; 089B6
        move.b  MaxShotsPerWeapon(pc,d0.w),d0   ; 089BA  slots this weapon may use
        moveq   #$26,d1                         ; 089BE
l_089C0:
        tst.b   (a0)                            ; 089C0
        beq.b   l_089CC                         ; 089C2
        adda.w  d1,a0                           ; 089C4
        subq.b  #$1,d0                          ; 089C6
        bne.b   l_089C0                         ; 089C8
        bra.b   l_08A40                         ; 089CA
l_089CC:
        move.b  #$1,(a0)                        ; 089CC
        move.b  #$1,$1(a0)                      ; 089D0
        clr.b   $13(a0)                         ; 089D6
        clr.b   $5(a0)                          ; 089DA
        clr.b   $4(a0)                          ; 089DE
        clr.b   $3(a0)                          ; 089E2
        move.b  g_Weapon+1(a6),$1a(a0)          ; 089E6  shot type = g_Weapon (low byte)
        moveq   #$9,d0                          ; 089EC  from 9 px above his feet, or 3 below when crouching
        tst.b   g_Crouching(a6)                 ; 089EE
        beq.b   l_089F6                         ; 089F2
        moveq   #-3,d0                          ; 089F4
l_089F6:
        add.w   g_ArthurY(a6),d0                ; 089F6
        move.w  d0,$a(a0)                       ; 089FA
        tst.b   g_ArthurFacing(a6)              ; 089FE
        bpl.b   l_08A12                         ; 08A02
        move.w  g_ArthurX(a6),$6(a0)            ; 08A04
        move.b  #$2,$12(a0)                     ; 08A0A  facing left: from his X, direction 2
        bra.b   l_08A22                         ; 08A10
l_08A12:
        moveq   #$f,d0                          ; 08A12  facing right: 15 px ahead, direction 1
        add.w   g_ArthurX(a6),d0                ; 08A14
        move.w  d0,$6(a0)                       ; 08A18
        move.b  #$1,$12(a0)                     ; 08A1C
l_08A22:
        move.b  #$f,g_FireCooldown(a6)          ; 08A22  15-frame cooldown with the throw animation
        lea.l   ArthurAnimThrow(pc),a1          ; 08A28
        tst.b   g_Crouching(a6)                 ; 08A2C
        beq.b   l_08A36                         ; 08A30
        lea.l   ArthurAnimThrowCrouch(pc),a1    ; 08A32
l_08A36:
        bsr.w   ArthurSetAnim                   ; 08A36
        moveq   #SFX_THROW,d0                   ; 08A3A
        bsr.w   PlaySfx                         ; 08A3C
l_08A40:
        tst.b   g_FireCooldown(a6)              ; 08A40
        beq.b   l_08A62                         ; 08A44
        bsr.w   ArthurAnimate                   ; 08A46
        subq.b  #$1,g_FireCooldown(a6)          ; 08A4A
        bne.b   l_08A62                         ; 08A4E
        lea.l   ArthurAnims(pc),a1              ; 08A50
        tst.b   g_Crouching(a6)                 ; 08A54
        beq.b   l_08A5E                         ; 08A58
        lea.l   ArthurAnimCrouch(pc),a1         ; 08A5A
l_08A5E:
        bsr.w   ArthurSetAnim                   ; 08A5E
l_08A62:
        rts                                     ; 08A62

;---------------------------------------------------------------------------
; Walk 1.125 px/frame unless firing; stopped by platforms and walls
;---------------------------------------------------------------------------
ArthurWalk:
        tst.b   g_FireCooldown(a6)              ; 08A64
        bne.w   ArthurAnimate                   ; 08A68
        tst.b   g_ArthurDir(a6)                 ; 08A6C
        bmi.b   l_08A98                         ; 08A70
        move.w  g_ArthurX(a6),d3                ; 08A72
        move.w  g_ArthurY(a6),d4                ; 08A76
        addq.w  #$1,d3                          ; 08A7A
        addq.w  #$1,d4                          ; 08A7C
        bsr.w   ArthurOnPlatform                ; 08A7E
        bne.w   ArthurAnimate                   ; 08A82
        bsr.b   WallCheckRight                  ; 08A86
        bne.w   ArthurAnimate                   ; 08A88
        addi.l  #$12000,g_ArthurX(a6)           ; 08A8C  1.125 px/frame right
        bra.w   ArthurAnimate                   ; 08A94
l_08A98:
        move.w  g_ArthurX(a6),d3                ; 08A98
        move.w  g_ArthurY(a6),d4                ; 08A9C
        subq.w  #$1,d3                          ; 08AA0
        addq.w  #$1,d4                          ; 08AA2
        bsr.w   ArthurOnPlatform                ; 08AA4
        bne.w   ArthurAnimate                   ; 08AA8
        bsr.b   WallCheckLeft                   ; 08AAC
        bne.w   ArthurAnimate                   ; 08AAE
        subi.l  #$12000,g_ArthurX(a6)           ; 08AB2  1.125 px/frame left
        bra.w   ArthurAnimate                   ; 08ABA

;---------------------------------------------------------------------------
; Wall 16 px to the right at knee height (Y - 7)? Push him out of it (WallProfileR);
; if that leaves him within 10 px of the right edge of the screen he stops walking.
; Out: Z clear = wall.
;---------------------------------------------------------------------------
WallCheckRight:
        moveq   #$10,d6                         ; 08ABE
        add.w   g_ArthurX(a6),d6                ; 08AC0
        moveq   #-7,d7                          ; 08AC4
        add.w   g_ArthurY(a6),d7                ; 08AC6
        bsr.w   MapTileAt                       ; 08ACA
