;---------------------------------------------------------------------------
; Enemy bodies against Arthur (boxes per enemy type: EnemyContactBoxes, smaller when he
; crouches). Skipped while he flashes or is already hit. Fire (type 14) only hurts at its full
; flare (size class 10). A touch knocks him back (g_ArthurState 1, pushed away from the enemy),
; except with the cheat on once his armour is gone.
;---------------------------------------------------------------------------
EnemyVsArthur:
        tst.b   g_ArthurFlash(a6)               ; 08E08
        bne.b   l_08E8C                         ; 08E0C
        tst.b   g_ArthurState(a6)               ; 08E0E
        bne.b   l_08E8C                         ; 08E12
        lea.l   EnemyContactBoxes(pc),a1        ; 08E14
        tst.b   g_Crouching(a6)                 ; 08E18
        beq.b   l_08E22                         ; 08E1C
        lea.l   EnemyContactBoxesCrouch(pc),a1  ; 08E1E
l_08E22:
        lea.l   g_Enemies(a6),a5                ; 08E22
        moveq   #$27,d7                         ; 08E26
l_08E28:
        move.b  (a5),d0                         ; 08E28
        and.b   O_OnScreen(a5),d0               ; 08E2A
        beq.b   l_08E84                         ; 08E2E
        clr.w   d0                              ; 08E30
        move.b  O_Type(a5),d0                   ; 08E32
        cmp.b   #$e,d0                          ; 08E36
        bne.b   l_08E44                         ; 08E3A
        cmpi.b  #$a,O_Size(a5)                  ; 08E3C  fire: only at full flare
        bne.b   l_08E84                         ; 08E42
l_08E44:
        lsl.w   #$3,d0                          ; 08E44
        lea.l   (a1,d0.w),a0                    ; 08E46
        moveq   #-1,d1                          ; 08E4A
        move.w  O_X(a5),d0                      ; 08E4C
        sub.w   g_ArthurX(a6),d0                ; 08E50
        bpl.b   l_08E58                         ; 08E54
        moveq   #$1,d1                          ; 08E56
l_08E58:
        add.w   (a0)+,d0                        ; 08E58
        cmp.w   (a0)+,d0                        ; 08E5A
        bhi.b   l_08E84                         ; 08E5C
        move.w  O_Y(a5),d0                      ; 08E5E
        sub.w   g_ArthurY(a6),d0                ; 08E62
        add.w   (a0)+,d0                        ; 08E66
        cmp.w   (a0)+,d0                        ; 08E68
        bhi.b   l_08E84                         ; 08E6A
        tst.b   g_CheatOn(a6)                   ; 08E6C  cheat: no effect once the armour is gone
        beq.b   l_08E78                         ; 08E70
        tst.b   g_NoArmour(a6)                  ; 08E72
        bne.b   l_08E84                         ; 08E76
l_08E78:
        move.b  #AS_HIT,g_ArthurState(a6)       ; 08E78
        move.b  d1,g_ArthurDir(a6)              ; 08E7E
        bra.b   l_08E8C                         ; 08E82
l_08E84:
        lea.l   $3c(a5),a5                      ; 08E84
        dbra    d7,l_08E28                      ; 08E88
l_08E8C:
        rts                                     ; 08E8C

