;---------------------------------------------------------------------------
; Enemy shots against Arthur. Shot type 0 (the Magician's spell) turns him into a frog
; (g_FrogTimer = 8); any other hits him (g_ArthurState 1), except when the cheat is on
; and g_NoArmour is set. A shot that hits is removed. Skipped while Arthur flashes or is
; already hit; crouching uses the smaller box table.
;---------------------------------------------------------------------------
EnemyShotsVsArthur:
        tst.b   g_ArthurFlash(a6)               ; 08F4E  not while flashing or already hit
        bne.w   l_09000                         ; 08F52
        tst.b   g_ArthurState(a6)               ; 08F56
        bne.w   l_09000                         ; 08F5A
        lea.l   EnemyShotBoxes(pc),a1           ; 08F5E  boxes by enemy-shot type (smaller set while crouching)
        tst.b   g_Crouching(a6)                 ; 08F62
        beq.b   l_08F6C                         ; 08F66
        lea.l   EnemyShotBoxesCrouch(pc),a1     ; 08F68
l_08F6C:
        lea.l   g_EnemyShots(a6),a5             ; 08F6C
        moveq   #$5,d7                          ; 08F70
l_08F72:
        move.b  (a5),d0                         ; 08F72  each active, on-screen enemy shot
        and.b   O_OnScreen(a5),d0               ; 08F74
        beq.b   l_08FF8                         ; 08F78
        move.b  O_Type(a5),d0                   ; 08F7A
        ext.w   d0                              ; 08F7E
        lsl.w   #$3,d0                          ; 08F80
        lea.l   (a1,d0.w),a0                    ; 08F82
        move.w  O_X(a5),d0                      ; 08F86  X inside the box? d1 = side it came from (knock-back direction)
        sub.w   g_ArthurX(a6),d0                ; 08F8A
        add.w   (a0)+,d0                        ; 08F8E
        cmp.w   (a0)+,d0                        ; 08F90
        bhi.b   l_08FF8                         ; 08F92
        moveq   #-1,d1                          ; 08F94
        sub.w   -$4(a0),d0                      ; 08F96
        bmi.b   l_08F9E                         ; 08F9A
        moveq   #$1,d1                          ; 08F9C
l_08F9E:
        move.w  O_Y(a5),d0                      ; 08F9E  Y inside the box?
        sub.w   g_ArthurY(a6),d0                ; 08FA2
        add.w   (a0)+,d0                        ; 08FA6
        cmp.w   (a0)+,d0                        ; 08FA8
        bhi.b   l_08FF8                         ; 08FAA
        tst.b   O_Type(a5)                      ; 08FAC  type 0: the frog spell
        bne.b   l_08FCE                         ; 08FB0
        move.b  #$8,g_FrogTimer(a6)             ; 08FB2
        clr.b   g_OnLadder(a6)                  ; 08FB8
        clr.b   g_FireCooldown(a6)              ; 08FBC
        clr.b   g_Crouching(a6)                 ; 08FC0
        lea.l   ArthurAnimFrog(pc),a1           ; 08FC4
        bsr.w   ArthurSetAnim                   ; 08FC8
        bra.b   l_08FE4                         ; 08FCC
l_08FCE:
        tst.b   g_CheatOn(a6)                   ; 08FCE  cheat on and no armour: no harm
        beq.b   l_08FDA                         ; 08FD2
        tst.b   g_NoArmour(a6)                  ; 08FD4
        bne.b   l_08FF8                         ; 08FD8
l_08FDA:
        move.b  #AS_HIT,g_ArthurState(a6)       ; 08FDA  hit: knocked back away from the shot
        move.b  d1,g_ArthurDir(a6)              ; 08FE0
l_08FE4:
        move.b  #$2,(a5)                        ; 08FE4  the shot is used up
        move.b  #ST_KILLED,O_State(a5)          ; 08FE8
        clr.b   O_Step(a5)                      ; 08FEE
        clr.b   O_Step2(a5)                     ; 08FF2
        bra.b   l_09000                         ; 08FF6
l_08FF8:
        lea.l   $1c(a5),a5                      ; 08FF8
        dbra    d7,l_08F72                      ; 08FFC
l_09000:
        rts                                     ; 09000

