;---------------------------------------------------------------------------
; Arthur's weapon shots (4 slots x $26 at g_Shots).
; Handler = ShotTable[(type*4 + state)]: type 0 torch, 1 lance, 2 axe,
; 3 cross, 4 dagger, 5 armour debris, 6 special
;---------------------------------------------------------------------------
UpdateShots:
        lea.l   g_Shots(a6),a5                  ; 0916A
        moveq   #$3,d7                          ; 0916E
l_09170:
        tst.b   (a5)                            ; 09170
        beq.b   l_09198                         ; 09172
        bsr.w   CheckOnScreen                   ; 09174
        clr.w   d0                              ; 09178
        move.b  O_Type(a5),d0                   ; 0917A
        add.w   d0,d0                           ; 0917E
        add.w   d0,d0                           ; 09180
        add.b   O_State(a5),d0                  ; 09182
        add.w   d0,d0                           ; 09186
        add.w   d0,d0                           ; 09188
        jsr     ShotTable(pc,d0.w)              ; 0918A
        tst.b   O_OnScreen(a5)                  ; 0918E
        beq.b   l_09198                         ; 09192
        bsr.w   QueueObjectDraw                 ; 09194
l_09198:
        lea.l   $26(a5),a5                      ; 09198
        dbra    d7,l_09170                      ; 0919C
        rts                                     ; 091A0

;---------------------------------------------------------------------------
; ShotTable - Arthur's shots, dispatched on O_Type x 4 + O_State.
; O_Type = weapon: 0 torch, 1 lance, 2 axe, 3 cross, 4 dagger; 5 = the pieces of armour that
; fly off when Arthur is hit (ArthurHit puts 4 of them in the shot slots). O_State: 0 start, 1 fly, 2 hit / end, 3 free.
;   torch  4.19 px/frame for 48 px, then falls in an arc (ShotArcMove) and burns on the ground
;          for 2 x 32 frames (a bigger flame, then a smaller one)
;   lance  4.19 px/frame for 192 px
;   axe    4.19 px/frame for 48 px, then falls in an arc
;   cross  4.19 px/frame for 48 px only - but it is not used up when it kills
;   dagger 5.63 px/frame for 197 px
; State 2 (set by EnemyHitByShot): step 1 deflected (sound 10, 15 frames), step 3 hit an enemy
; that survives (sound 12, 8 frames), step 0 gone.
;---------------------------------------------------------------------------
ShotTable:
        bra.w   Torch_Start                     ; 091A2
        bra.w   Torch_Fly                       ; 091A6
        bra.w   Shot_Hit                        ; 091AA
        bra.w   Shot_Free                       ; 091AE
        bra.w   Lance_Start                     ; 091B2
        bra.w   Lance_Fly                       ; 091B6
        bra.w   Shot_Hit                        ; 091BA
        bra.w   Shot_Free                       ; 091BE
        bra.w   Axe_Start                       ; 091C2
        bra.w   Axe_Fly                         ; 091C6
        bra.w   Shot_Hit                        ; 091CA
        bra.w   Shot_Free                       ; 091CE
        bra.w   Cross_Start                     ; 091D2
        bra.w   Cross_Fly                       ; 091D6
        bra.w   Shot_Hit                        ; 091DA
        bra.w   Shot_Free                       ; 091DE
        bra.w   Dagger_Start                    ; 091E2
        bra.w   Cross_Fly                       ; 091E6
        bra.w   Shot_Hit                        ; 091EA
        bra.w   Shot_Free                       ; 091EE
        bra.w   ArmourDebris_Start              ; 091F2
        bra.w   ArmourDebris_Fly                ; 091F6
        bra.w   Shot_Hit                        ; 091FA
        bra.w   Shot_Free                       ; 091FE
ShotSpeeds:
	dc.b	$00,$00,$00,$00,$04,$30,$00,$00,$FB,$D0,$00,$00
DaggerSpeeds:
	dc.b	$00,$00,$00,$00,$05,$A0,$00,$00,$FA,$60,$00,$00

;---------------------------------------------------------------------------
; type 5 (armour pieces): diagonal directions at 2.3 px/frame
;---------------------------------------------------------------------------
ArmourDebrisSpeeds:
	dc.b	$00,$00,$00,$00,$02,$50,$02,$50,$02,$50,$FD,$B0,$FD,$B0,$FD,$B0
	dc.b	$FD,$B0,$02,$50

;---------------------------------------------------------------------------
; Weapon and armour-debris animations (shot types 0-5). Direction tables: one script per
; O_Dir. AF frame,ticks / AL frame,ticks,next (see anim_data.py).
;---------------------------------------------------------------------------
Torch_Anim:
	dc.w	Torch_Anim_0-*	; 0
	dc.w	Torch_Anim_1-*	; 1
Torch_Anim_0:
	AF	$2D,2
	AF	$2E,2
	AF	$2F,2
	AL	$30,2,Torch_Anim_0
Torch_Anim_1:
	AF	$2E,2
	AF	$2D,2
	AF	$30,2
	AL	$2F,2,Torch_Anim_1
Torch_AnimBurn:
	AF	$33,3
	AL	$34,3,Torch_AnimBurn
Torch_AnimBurnSmall:
	AF	$31,3
	AL	$32,3,Torch_AnimBurnSmall
Lance_Anim:
	dc.w	Lance_Anim_0-*	; 0
	dc.w	Lance_Anim_1-*	; 1
Lance_Anim_0:
	AL	$35,127,Lance_Anim_0
Lance_Anim_1:
	AL	$36,127,Lance_Anim_1
Axe_Anim:
	dc.w	Axe_Anim_0-*	; 0
	dc.w	Axe_Anim_1-*	; 1
Axe_Anim_0:
	AF	$27,2
	AF	$28,2
	AF	$29,2
	AL	$2A,2,Axe_Anim_0
Axe_Anim_1:
	AF	$27,2
	AF	$28,2
	AF	$29,2
	AL	$2A,2,Axe_Anim_1
Cross_Anim:
	dc.w	Cross_Anim_0-*	; 0
	dc.w	Cross_Anim_1-*	; 1
Cross_Anim_0:
	AL	$2C,127,Cross_Anim_0
Cross_Anim_1:
	AL	$2B,127,Cross_Anim_1
Dagger_Anim:
	dc.w	Dagger_Anim_0-*	; 0
	dc.w	Dagger_Anim_1-*	; 1
Dagger_Anim_0:
	AL	$25,127,Dagger_Anim_0
Dagger_Anim_1:
	AL	$26,127,Dagger_Anim_1
Debris_Anim:
	dc.w	Debris_Anim_0-*	; 0
	dc.w	Debris_Anim_1-*	; 1
	dc.w	Debris_Anim_2-*	; 2
	dc.w	Debris_Anim_3-*	; 3
Debris_Anim_0:
	AL	$22,127,Dagger_Anim_1
Debris_Anim_1:
	AL	$24,127,Dagger_Anim_1
Debris_Anim_2:
	AL	$23,127,Dagger_Anim_1
Debris_Anim_3:
	AL	$21,127,Dagger_Anim_1
Torch_Start:
        clr.b   O_Size(a5)                      ; 092A6
        lea.l   ShotSpeeds(pc),a1               ; 092AA
        lea.l   Torch_Anim(pc),a0               ; 092AE
        bra.b   Shot_StartCommon                ; 092B2

;---------------------------------------------------------------------------
; size class 2
;---------------------------------------------------------------------------
Lance_Start:
        move.b  #$2,O_Size(a5)                  ; 092B4
        lea.l   ShotSpeeds(pc),a1               ; 092BA
        lea.l   Lance_Anim(pc),a0               ; 092BE
        bra.b   Shot_StartCommon                ; 092C2
Axe_Start:
        clr.b   O_Size(a5)                      ; 092C4
        lea.l   ShotSpeeds(pc),a1               ; 092C8
        lea.l   Axe_Anim(pc),a0                 ; 092CC
        bra.b   Shot_StartCommon                ; 092D0
Cross_Start:
        clr.b   O_Size(a5)                      ; 092D2
        lea.l   ShotSpeeds(pc),a1               ; 092D6
        lea.l   Cross_Anim(pc),a0               ; 092DA
        bra.b   Shot_StartCommon                ; 092DE
Dagger_Start:
        clr.b   O_Size(a5)                      ; 092E0
        lea.l   DaggerSpeeds(pc),a1             ; 092E4
        lea.l   Dagger_Anim(pc),a0              ; 092E8
        bra.b   Shot_StartCommon                ; 092EC
ArmourDebris_Start:
        clr.b   O_Size(a5)                      ; 092EE
        lea.l   ArmourDebrisSpeeds(pc),a1       ; 092F2
        lea.l   Debris_Anim(pc),a0              ; 092F6

;---------------------------------------------------------------------------
; Animation for the direction, move table, remember the start X, fly
;---------------------------------------------------------------------------
Shot_StartCommon:
        subq.l  #$2,a0                          ; 092FA
        bsr.w   SetAnimIndexed                  ; 092FC
        move.l  a1,O_MoveTable(a5)              ; 09300
        move.w  O_X(a5),Shot_StartX(a5)         ; 09304
        move.b  #$1,O_State(a5)                 ; 0930A
        clr.b   O_Step(a5)                      ; 09310
        rts                                     ; 09314

;---------------------------------------------------------------------------
; O_Step: 0 straight, 1 start the fall, 2 fall, 3 big flame, 4 small flame, 5 end
;---------------------------------------------------------------------------
Torch_Fly:
        bsr.w   CheckFarAway                    ; 09316
        clr.w   d0                              ; 0931A
        move.b  O_Step(a5),d0                   ; 0931C
        add.w   d0,d0                           ; 09320
        add.w   d0,d0                           ; 09322
        jmp     Torch_Fly_Jumps(pc,d0.w)        ; 09324
Torch_Fly_Jumps:
        bra.w   Shot_Straight                   ; 09328
        bra.w   Shot_StartFall                  ; 0932C
        bra.w   Torch_Fall                      ; 09330
        bra.w   Torch_Burn                      ; 09334
        bra.w   Torch_BurnSmall                 ; 09338
        bra.w   Torch_BurnEnd                   ; 0933C

;---------------------------------------------------------------------------
; vx 2.93, vy 1.01 px/frame
;---------------------------------------------------------------------------
Shot_StartFall:
        move.l  #$2ef00,Shot_VX(a5)             ; 09340
        move.l  #$10300,Shot_VY(a5)             ; 09348
        addq.b  #$1,O_Step(a5)                  ; 09350
        rts                                     ; 09354
Torch_Fall:
        bsr.b   ShotArcMove                     ; 09356
        bne.b   l_0935E                         ; 09358
        addq.b  #$1,O_Step(a5)                  ; 0935A
l_0935E:
        rts                                     ; 0935E

;---------------------------------------------------------------------------
; Ballistic fall (torch, axe): X += vx (slowing by $BA1 a frame to 0), Y -= vy
; (vy growing by $FF0 a frame up to 5 px). Ends with ObjectMapCollide: Z set = landed.
;---------------------------------------------------------------------------
ShotArcMove:
        move.l  Shot_VX(a5),d0                  ; 09360
        cmpi.b  #$1,O_Dir(a5)                   ; 09364
        beq.b   l_0936E                         ; 0936A
        neg.l   d0                              ; 0936C
l_0936E:
        add.l   d0,O_X(a5)                      ; 0936E
        move.l  Shot_VY(a5),d0                  ; 09372
        sub.l   d0,O_Y(a5)                      ; 09376
        subi.l  #$ba1,Shot_VX(a5)               ; 0937A
        bpl.b   l_09388                         ; 09382
        clr.l   Shot_VX(a5)                     ; 09384
l_09388:
        cmpi.l  #$50000,Shot_VY(a5)             ; 09388
        bcc.b   l_0939A                         ; 09390
        addi.l  #$ff0,Shot_VY(a5)               ; 09392
l_0939A:
        bsr.w   Animate                         ; 0939A
        bra.w   ObjectMapCollide                ; 0939E

;---------------------------------------------------------------------------
; Landed: size class 3 flame for 32 frames
;---------------------------------------------------------------------------
Torch_Burn:
        move.b  #$3,d0                          ; 093A2  [1MB build: extra sound effect $B played here]
        bsr.w   SetBoxClass                     ; 093A6
        lea.l   Torch_AnimBurn(pc),a0           ; 093AA
        bsr.w   SetAnim                         ; 093AE
        move.b  #$20,O_Param(a5)                ; 093B2
        addq.b  #$1,O_Step(a5)                  ; 093B8
        rts                                     ; 093BC

;---------------------------------------------------------------------------
; then size class 0 for 32 frames
;---------------------------------------------------------------------------
Torch_BurnSmall:
        subq.b  #$1,O_Param(a5)                 ; 093BE
        bne.w   Animate                         ; 093C2
        move.b  #$0,d0                          ; 093C6
        bsr.w   SetBoxClass                     ; 093CA
        lea.l   Torch_AnimBurnSmall(pc),a0      ; 093CE
        bsr.w   SetAnim                         ; 093D2
        move.b  #$20,O_Param(a5)                ; 093D6
        addq.b  #$1,O_Step(a5)                  ; 093DC
        rts                                     ; 093E0
Torch_BurnEnd:
        subq.b  #$1,O_Param(a5)                 ; 093E2
        bne.w   Animate                         ; 093E6
l_093EA:
        move.b  #$3,O_State(a5)                 ; 093EA
        clr.b   O_Step(a5)                      ; 093F0
        rts                                     ; 093F4
Lance_Fly:
        bsr.w   CheckFarAway                    ; 093F6
        clr.w   d0                              ; 093FA
        move.b  O_Step(a5),d0                   ; 093FC
        add.w   d0,d0                           ; 09400
        add.w   d0,d0                           ; 09402
        jmp     Lance_Fly_Jumps(pc,d0.w)        ; 09404
Lance_Fly_Jumps:
        bra.w   Shot_Straight                   ; 09408
        bra.w   Shot_End                        ; 0940C
Shot_End:
        move.b  #$2,O_State(a5)                 ; 09410
        clr.b   O_Step(a5)                      ; 09416
        rts                                     ; 0941A

;---------------------------------------------------------------------------
; O_Step: 0 straight, 1 start the fall, 2 fall, 3 end
;---------------------------------------------------------------------------
Axe_Fly:
        clr.w   d0                              ; 0941C
        move.b  O_Step(a5),d0                   ; 0941E
        add.w   d0,d0                           ; 09422
        add.w   d0,d0                           ; 09424
        jmp     Axe_Fly_Jumps(pc,d0.w)          ; 09426
Axe_Fly_Jumps:
        bra.w   Shot_Straight                   ; 0942A
        bra.w   Shot_StartFall                  ; 0942E
        bra.w   Axe_Fall                        ; 09432
        bra.w   l_093EA                         ; 09436
Axe_Fall:
        bsr.w   ShotArcMove                     ; 0943A
        bne.b   l_09444                         ; 0943E
        addq.b  #$1,O_Step(a5)                  ; 09440
l_09444:
        rts                                     ; 09444

;---------------------------------------------------------------------------
; Cross and dagger: straight to their range
;---------------------------------------------------------------------------
Cross_Fly:
        clr.w   d0                              ; 09446
        move.b  O_Step(a5),d0                   ; 09448
        add.w   d0,d0                           ; 0944C
        add.w   d0,d0                           ; 0944E
        jmp     Cross_Fly_Jumps(pc,d0.w)        ; 09450
Cross_Fly_Jumps:
        bra.w   Shot_Straight                   ; 09454
        bra.w   l_09460                         ; 09458
        bra.w   l_09466                         ; 0945C
l_09460:
        addq.b  #$1,O_Step(a5)                  ; 09460
        rts                                     ; 09464
l_09466:
        move.b  #$2,O_State(a5)                 ; 09466
        clr.b   O_Step(a5)                      ; 0946C
        rts                                     ; 09470
ArmourDebris_Fly:
        tst.b   O_Step(a5)                      ; 09472
        beq.b   Shot_Straight                   ; 09476
        bra.b   Shot_End                        ; 09478

;---------------------------------------------------------------------------
; Move; next step once ShotRanges[type] px from the start X
;---------------------------------------------------------------------------
Shot_Straight:
        bsr.w   ApplyMoveTable                  ; 0947A
        move.w  O_X(a5),d1                      ; 0947E
        sub.w   Shot_StartX(a5),d1              ; 09482
        clr.w   d0                              ; 09486
        move.b  O_Type(a5),d0                   ; 09488
        move.b  ShotRanges(pc,d0.w),d0          ; 0948C
        add.w   d0,d1                           ; 09490
        add.w   d0,d0                           ; 09492
        cmp.w   d0,d1                           ; 09494
        bcs.w   Animate                         ; 09496
        addq.b  #$1,O_Step(a5)                  ; 0949A
        rts                                     ; 0949E

;---------------------------------------------------------------------------
; px before the next step: torch 48, lance 192, axe 48, cross 48, dagger 197, armour 38
;---------------------------------------------------------------------------
ShotRanges:
	dc.b	$30,$C0,$30,$30,$C5,$26

;---------------------------------------------------------------------------
; State 2. O_Step: 0 gone, 1-2 deflected, 3-4 hit
;---------------------------------------------------------------------------
Shot_Hit:
        move.b  O_Step(a5),d0                   ; 094A6
        ext.w   d0                              ; 094AA
        add.w   d0,d0                           ; 094AC
        add.w   d0,d0                           ; 094AE
        jmp     Shot_Hit_Jumps(pc,d0.w)         ; 094B0
Shot_Hit_Jumps:
        bra.w   Shot_Gone                       ; 094B4
        bra.w   Shot_Deflected                  ; 094B8
        bra.w   Shot_HitWait                    ; 094BC
        bra.w   Shot_HitEnemy                   ; 094C0
        bra.w   Shot_HitWait                    ; 094C4
Shot_Gone:
        move.b  #$3,O_State(a5)                 ; 094C8
        rts                                     ; 094CE

;---------------------------------------------------------------------------
; sound 10, 15 frames
;---------------------------------------------------------------------------
Shot_Deflected:
        clr.b   O_Size(a5)                      ; 094D0
        lea.l   Shot_AnimDeflect(pc),a0         ; 094D4
        bsr.w   SetAnim                         ; 094D8
        move.b  #$f,O_Param(a5)                 ; 094DC
        moveq   #SFX_DEFLECT,d0                 ; 094E2
        bsr.w   PlaySfx                         ; 094E4
        addq.b  #$1,O_Step(a5)                  ; 094E8
        rts                                     ; 094EC
Shot_HitWait:
        subq.b  #$1,O_Param(a5)                 ; 094EE
        bne.w   Animate                         ; 094F2
        bra.b   Shot_Gone                       ; 094F6

;---------------------------------------------------------------------------
; sound 12, 8 frames
;---------------------------------------------------------------------------
Shot_HitEnemy:
        clr.b   O_Size(a5)                      ; 094F8
        lea.l   Shot_AnimHit(pc),a0             ; 094FC
        bsr.w   SetAnim                         ; 09500
        move.b  #$8,O_Param(a5)                 ; 09504
        moveq   #SFX_ENEMY_HIT,d0               ; 0950A
        bsr.w   PlaySfx                         ; 0950C
        addq.b  #$1,O_Step(a5)                  ; 09510
        rts                                     ; 09514
Shot_Free:
        clr.b   (a5)                            ; 09516
        rts                                     ; 09518
Shot_AnimHit:
	AF	$19,4
	AL	$1A,127,Shot_AnimHit
Shot_AnimDeflect:
	AF	$10,5
	AF	$11,5
	AL	$12,127,Shot_AnimHit

;---------------------------------------------------------------------------
; Per enemy type, 8 bytes: x offset.w, width.w, y offset.w, height.w
;---------------------------------------------------------------------------
EnemyHitboxes:
	dc.w	12,24,16,32	; E_WOODYPIG
	dc.w	12,24,16,24	; E_CROW
	dc.w	12,24,10,20	; E_PETITEDEVIL
	dc.w	12,24,16,32	; E_FLYINGKNIGHT
	dc.w	12,24,8,16	; E_BLUEKILLER
	dc.w	10,20,13,26	; E_REDARREMER
	dc.w	16,32,16,32	; E_SATAN
	dc.w	12,24,13,26	; E_MAGICIAN
	dc.w	16,32,21,42	; E_UNICORN
	dc.w	12,24,12,24	; E_SKELETON
	dc.w	14,28,14,28	; E_BIGMAN
	dc.w	12,24,18,28	; E_ZOMBIE
	dc.w	12,24,10,20	; E_DRAGON
	dc.w	10,20,9,18	; E_ASTAROTH
	dc.w	12,24,8,16	; E_FIRE
	dc.w	12,24,8,16	; E_PRINCESS
	dc.w	12,24,8,16	; E_TYPE16
	dc.w	12,24,16,32	; E_PLANT
	dc.w	12,24,24,48	; E_FIREPILLAR

;---------------------------------------------------------------------------
; Per enemy type: bitmask of weapon types that can hurt it (bit n = weapon n). Astaroth: cross only; Fire: nothing.
;---------------------------------------------------------------------------
EnemyVulnerability:
	dc.b	%00011111	; E_WOODYPIG: torch, lance, axe, cross, dagger
	dc.b	%00011111	; E_CROW: torch, lance, axe, cross, dagger
	dc.b	%00011111	; E_PETITEDEVIL: torch, lance, axe, cross, dagger
	dc.b	%00011111	; E_FLYINGKNIGHT: torch, lance, axe, cross, dagger
	dc.b	%00011111	; E_BLUEKILLER: torch, lance, axe, cross, dagger
	dc.b	%00011111	; E_REDARREMER: torch, lance, axe, cross, dagger
	dc.b	%00011111	; E_SATAN: torch, lance, axe, cross, dagger
	dc.b	%00011111	; E_MAGICIAN: torch, lance, axe, cross, dagger
	dc.b	%00011111	; E_UNICORN: torch, lance, axe, cross, dagger
	dc.b	%00011111	; E_SKELETON: torch, lance, axe, cross, dagger
	dc.b	%00011111	; E_BIGMAN: torch, lance, axe, cross, dagger
	dc.b	%00011111	; E_ZOMBIE: torch, lance, axe, cross, dagger
	dc.b	%00011111	; E_DRAGON: torch, lance, axe, cross, dagger
	dc.b	%00001000	; E_ASTAROTH: cross
	dc.b	%00000000	; E_FIRE: nothing
	dc.b	%00011111	; E_PRINCESS: torch, lance, axe, cross, dagger
	dc.b	%00011111	; E_TYPE16: torch, lance, axe, cross, dagger
	dc.b	%00011111	; E_PLANT: torch, lance, axe, cross, dagger
	dc.b	%00011111	; E_FIREPILLAR: torch, lance, axe, cross, dagger
	dc.b	31	; pad

;---------------------------------------------------------------------------
; EnemyHitByShot - test Arthur's shots against enemy a5.
; Hitbox from EnemyHitboxes; Astaroth (type 13) can only be hit within +-9 px of his
; centre line. If the weapon's bit is clear in EnemyVulnerability the shot bounces off.
; Otherwise O_HP is decremented; at 0 the enemy dies (state 2) and EnemyPoints is
; awarded. The CROSS (weapon 3) is not used up when it kills an enemy - it carries on.
;---------------------------------------------------------------------------
EnemyHitByShot:
        lea.l   EnemyVulnerability(pc),a1       ; 095D4  weapon bitmask and hit box of this enemy type
        clr.w   d0                              ; 095D8
        move.b  O_Type(a5),d0                   ; 095DA
        adda.w  d0,a1                           ; 095DE
        lea.l   EnemyHitboxes(pc),a0            ; 095E0
        lsl.w   #$3,d0                          ; 095E4
        adda.w  d0,a0                           ; 095E6
        lea.l   g_Shots(a6),a4                  ; 095E8
        moveq   #$3,d6                          ; 095EC
l_095EE:
        move.b  (a4),d0                         ; 095EE  each of Arthur's active, on-screen shots
        and.b   $1(a4),d0                       ; 095F0
        beq.w   l_096E6                         ; 095F4
        cmpi.b  #E_ASTAROTH,O_Type(a5)          ; 095F8  Astaroth: within 32 px, and only a 9-px band either side of his centre
        bne.b   l_0963C                         ; 095FE
        move.w  O_X(a5),d0                      ; 09600
        sub.w   $6(a4),d0                       ; 09604
        addi.w  #$20,d0                         ; 09608
        cmp.w   #$40,d0                         ; 0960C
        bhi.w   l_096E6                         ; 09610
        move.w  O_Y(a5),d0                      ; 09614
        sub.w   $a(a4),d0                       ; 09618
        addi.w  #$20,d0                         ; 0961C
        cmp.w   #$40,d0                         ; 09620
        bhi.w   l_096E6                         ; 09624
        move.w  O_Y(a5),d0                      ; 09628  outside the band: deflected
        sub.w   $a(a4),d0                       ; 0962C
        addi.w  #$9,d0                          ; 09630
        cmp.w   #$12,d0                         ; 09634
        bcc.w   l_096D2                         ; 09638
l_0963C:
        move.w  O_X(a5),d0                      ; 0963C  inside the hit box?
        sub.w   $6(a4),d0                       ; 09640
        add.w   (a0),d0                         ; 09644
        cmp.w   $2(a0),d0                       ; 09646
        bhi.w   l_096E6                         ; 0964A
        move.w  O_Y(a5),d0                      ; 0964E
        sub.w   $a(a4),d0                       ; 09652
        add.w   $4(a0),d0                       ; 09656
        cmp.w   $6(a0),d0                       ; 0965A
        bhi.w   l_096E6                         ; 0965E
        moveq   #$0,d0                          ; 09662  weapon bit set in EnemyVulnerability?
        move.b  $1a(a4),d0                      ; 09664
        btst    d0,(a1)                         ; 09668
        beq.b   l_096D2                         ; 0966A
        tst.b   (a5)                            ; 0966C  active byte bit 7: shots pass through (deflected)
        bmi.b   l_096D2                         ; 0966E
        tst.b   O_HP(a5)                        ; 09670  hit points (0 counts as 1)
        beq.b   l_09684                         ; 09674
        subq.b  #$1,O_HP(a5)                    ; 09676
        beq.b   l_09684                         ; 0967A
        move.b  #$1,O_Param(a5)                 ; 0967C  hurt, not dead: O_Param = 1 (hit reaction)
        bra.b   l_096B2                         ; 09682
l_09684:
        move.b  O_Type(a5),d0                   ; 09684  killed: points, state 2
        move.b  EnemyPoints(pc,d0.w),d0         ; 09688
        bsr.w   AddScore                        ; 0968C
        move.b  #$2,(a5)                        ; 09690
        move.b  #ST_KILLED,O_State(a5)          ; 09694
        clr.b   O_Step(a5)                      ; 0969A
        clr.b   O_Step2(a5)                     ; 0969E
        cmpi.b  #E_ASTAROTH,O_Type(a5)          ; 096A2
        beq.b   l_096B2                         ; 096A8
        cmpi.b  #$3,$1a(a4)                     ; 096AA  the cross carries on after a kill (except on Astaroth)
        beq.b   l_096E6                         ; 096B0
l_096B2:
        move.b  #$2,(a4)                        ; 096B2  the shot ends: step 0 normally, 3 (a hit spark) if the enemy survived
        move.b  #$2,$3(a4)                      ; 096B6
        clr.b   $4(a4)                          ; 096BC
        clr.b   $5(a4)                          ; 096C0
        tst.b   O_HP(a5)                        ; 096C4
        beq.b   l_096E6                         ; 096C8
        move.b  #$3,$4(a4)                      ; 096CA
        bra.b   l_096E6                         ; 096D0
l_096D2:
        move.b  #$2,(a4)                        ; 096D2  deflected: the enemy is immune to this weapon or shots pass through it
        move.b  #$2,$3(a4)                      ; 096D6
        move.b  #$1,$4(a4)                      ; 096DC
        clr.b   $5(a4)                          ; 096E2
l_096E6:
        lea.l   $26(a4),a4                      ; 096E6
        dbra    d6,l_095EE                      ; 096EA
        rts                                     ; 096EE

;---------------------------------------------------------------------------
; Per enemy type: AddScore index awarded when its hit points run out
;---------------------------------------------------------------------------
EnemyPoints:
	dc.b	3	; E_WOODYPIG: 100
	dc.b	3	; E_CROW: 100
	dc.b	3	; E_PETITEDEVIL: 100
	dc.b	3	; E_FLYINGKNIGHT: 100
	dc.b	3	; E_BLUEKILLER: 100
	dc.b	9	; E_REDARREMER: 1000
	dc.b	11	; E_SATAN: 3000
	dc.b	10	; E_MAGICIAN: 2000
	dc.b	10	; E_UNICORN: 2000
	dc.b	3	; E_SKELETON: 100
	dc.b	7	; E_BIGMAN: 500
	dc.b	4	; E_ZOMBIE: 200
	dc.b	4	; E_DRAGON: 200
	dc.b	18	; E_ASTAROTH: 10000
	dc.b	3	; E_FIRE: 100
	dc.b	3	; E_PRINCESS: 100
	dc.b	3	; E_TYPE16: 100
	dc.b	3	; E_PLANT: 100
	dc.b	3	; E_FIREPILLAR: 100
	dc.b	0	; pad

;---------------------------------------------------------------------------
; ShotsVsEnemyShots - Arthur's shots against enemy shots.
;  Without the cross only fire-pillar shots (type 5) collide, and only Arthur's shot is
;  stopped. With the cross every enemy shot except the frog spell (0) and Astaroth's (10)
;  collides, and both shots are destroyed.
;  BUG: the box pointer a0 is set once per enemy shot and advanced by each test, so after
;  a miss the next of Arthur's shots is tested against the following words of the table
;  (another type's box). With one shot on screen it makes no difference.
;---------------------------------------------------------------------------
ShotsVsEnemyShots:
        lea.l   g_EnemyShots(a6),a1             ; 09704
        moveq   #$5,d7                          ; 09708
l_0970A:
        move.b  (a1),d0                         ; 0970A
        and.b   $1(a1),d0                       ; 0970C
        beq.w   l_097A0                         ; 09710
        moveq   #$0,d1                          ; 09714  d1 = 0 no collision, 1 Arthur's shot stops, 2 both destroyed
        move.b  $1a(a1),d0                      ; 09716
        cmpi.w  #$3,g_Weapon(a6)                ; 0971A
        beq.b   l_0972C                         ; 09720
        cmp.b   #$5,d0                          ; 09722  not the cross: only fire-pillar shots
        bne.b   l_09738                         ; 09726
        moveq   #$1,d1                          ; 09728
        bra.b   l_09738                         ; 0972A
l_0972C:
        tst.b   d0                              ; 0972C  cross: all but the frog spell and Astaroth's shots
        beq.b   l_09738                         ; 0972E
        cmp.b   #$a,d0                          ; 09730
        beq.b   l_09738                         ; 09734
        moveq   #$2,d1                          ; 09736
l_09738:
        tst.b   d1                              ; 09738
        beq.b   l_097A0                         ; 0973A
        ext.w   d0                              ; 0973C  box for this enemy-shot type (a0 advances through it below)
        lsl.w   #$3,d0                          ; 0973E
        lea.l   EnemyShotBlockBoxes(pc,d0.w),a0 ; 09740
        lea.l   g_Shots(a6),a2                  ; 09744
        moveq   #$3,d6                          ; 09748
l_0974A:
        move.b  (a2),d0                         ; 0974A
        and.b   $1(a2),d0                       ; 0974C
        beq.b   l_09798                         ; 09750
        move.w  $6(a1),d0                       ; 09752  X test
        sub.w   $6(a2),d0                       ; 09756
        add.w   (a0)+,d0                        ; 0975A
        cmp.w   (a0)+,d0                        ; 0975C
        bhi.b   l_09798                         ; 0975E
        move.w  $a(a1),d0                       ; 09760  Y test
        sub.w   $a(a2),d0                       ; 09764
        add.w   (a0)+,d0                        ; 09768
        cmp.w   (a0)+,d0                        ; 0976A
        bhi.b   l_09798                         ; 0976C
        subq.b  #$1,d1                          ; 0976E
        beq.b   l_09784                         ; 09770
        move.b  #$2,(a1)                        ; 09772  cross: the enemy shot is destroyed too
        move.b  #$2,$3(a1)                      ; 09776
        clr.b   $4(a1)                          ; 0977C
        clr.b   $5(a1)                          ; 09780
l_09784:
        move.b  #$2,(a2)                        ; 09784  Arthur's shot: state 2, step 1
        move.b  #$2,$3(a2)                      ; 09788
        move.b  #$1,$4(a2)                      ; 0978E
        clr.b   $5(a2)                          ; 09794
l_09798:
        lea.l   $26(a2),a2                      ; 09798
        dbra    d6,l_0974A                      ; 0979C
l_097A0:
        lea.l   $1c(a1),a1                      ; 097A0
        dbra    d7,l_0970A                      ; 097A4
        rts                                     ; 097A8

;---------------------------------------------------------------------------
; Boxes for Arthur's shots against enemy shots, per enemy-shot type (ShotsVsEnemyShots).
; Only types 0-11 exist; entries 12-18 are never used.
;---------------------------------------------------------------------------
EnemyShotBlockBoxes:
	dc.w	12,24,8,16	; enemy shot type 0
	dc.w	12,24,8,16	; enemy shot type 1
	dc.w	12,24,8,16	; enemy shot type 2
	dc.w	12,24,8,16	; enemy shot type 3
	dc.w	12,24,8,16	; enemy shot type 4
	dc.w	12,24,13,24	; enemy shot type 5
	dc.w	16,32,16,32	; enemy shot type 6
	dc.w	12,24,13,26	; enemy shot type 7
	dc.w	16,32,16,32	; enemy shot type 8
	dc.w	12,24,12,24	; enemy shot type 9
	dc.w	5,10,5,10	; enemy shot type 10
	dc.w	12,24,12,24	; enemy shot type 11
	dc.w	12,24,8,16	; enemy shot type 12
	dc.w	10,20,8,16	; enemy shot type 13
	dc.w	12,24,8,16	; enemy shot type 14
	dc.w	12,24,8,16	; enemy shot type 15
	dc.w	12,24,8,16	; enemy shot type 16
	dc.w	12,24,8,16	; enemy shot type 17
	dc.w	12,24,24,48	; enemy shot type 18

;---------------------------------------------------------------------------
; Arthur's shots against shootable scenery (item type 1, gravestones): the shot is
; stopped (deflected), and every hit counts down the item's counter (+$1B, 15 at level
; start). When it runs out, the Magician's spawner is started at the gravestone
; (g_SceneryHitX/Y, 16 px higher).
;---------------------------------------------------------------------------
ShotsVsScenery:
        lea.l   g_Items(a6),a1                  ; 09842
        moveq   #$1d,d7                         ; 09846
l_09848:
        move.b  (a1),d0                         ; 09848
        and.b   $1(a1),d0                       ; 0984A
        beq.w   l_098F0                         ; 0984E
        cmpi.b  #$1,$1a(a1)                     ; 09852
        bne.w   l_098F0                         ; 09858
        tst.b   $1b(a1)                         ; 0985C
        beq.w   l_098F0                         ; 09860
        lea.l   g_Shots(a6),a2                  ; 09864
        moveq   #$3,d6                          ; 09868
l_0986A:
        move.b  (a2),d0                         ; 0986A
        and.b   $1(a2),d0                       ; 0986C
        beq.b   l_098E8                         ; 09870
        move.w  $6(a1),d0                       ; 09872
        sub.w   $6(a2),d0                       ; 09876
        addi.w  #$e,d0                          ; 0987A
        cmp.w   #$1c,d0                         ; 0987E
        bhi.b   l_098E8                         ; 09882
        move.w  $a(a1),d0                       ; 09884
        sub.w   $a(a2),d0                       ; 09888
        addq.w  #$8,d0                          ; 0988C
        cmp.w   #$c,d0                          ; 0988E
        bhi.b   l_098E8                         ; 09892
        move.b  #$2,(a2)                        ; 09894
        move.b  #$2,$3(a2)                      ; 09898
        move.b  #$1,$4(a2)                      ; 0989E
        clr.b   $5(a2)                          ; 098A4
        tst.b   $1b(a1)                         ; 098A8  scenery hit counter (15 for gravestones)
        beq.b   l_098E8                         ; 098AC
        subq.b  #$1,$1b(a1)                     ; 098AE
        bne.b   l_098E8                         ; 098B2
        lea.l   Spawn_Magician_0(pc),a3         ; 098B4  counter ran out: start the Magician spawner (slot 7) with its one-entry script
        lea.l   g_Spawners+84(a6),a4            ; 098B8
        st.b    (a4)                            ; 098BC
        move.l  a3,$6(a4)                       ; 098BE
        move.w  (a3)+,d0                        ; 098C2
        move.b  d0,$1(a4)                       ; 098C4
        move.l  a3,$2(a4)                       ; 098C8
        move.b  #$a,$a(a4)                      ; 098CC
        clr.b   $b(a4)                          ; 098D2
        move.w  $6(a1),g_SceneryHitX(a6)        ; 098D6
        move.w  $a(a1),g_SceneryHitY(a6)        ; 098DC
        addi.w  #$10,g_SceneryHitY(a6)          ; 098E2
l_098E8:
        lea.l   $26(a2),a2                      ; 098E8
        dbra    d6,l_0986A                      ; 098EC
l_098F0:
        lea.l   $1c(a1),a1                      ; 098F0
        dbra    d7,l_09848                      ; 098F4
        rts                                     ; 098F8

;---------------------------------------------------------------------------
; UpdateSpecialObjs - 2 slots x $20: bonus prizes.
; Slot 0 (O_Type 0) is the prize carried by every 6th spawned enemy (UpdateSpawners): it rides
; on the enemy (O_MoveTable = the enemy's slot) and drops when the enemy is killed; if the
; enemy leaves instead, the prize goes with it. Slot 1 (O_Type 1) is called by an invisible
; trigger item and falls from above.
; O_State: 0 attach, 1 prize (O_Step 0 ride, 1 fall, 2 reveal, 3 wait to be touched),
; 2 collected (30 frames), 3 free.
; O_Param = what it is: 0 armour, 1-5 weapon (g_Weapon = param - 1), 6-11 the level's
; treasure (200 points on level 0, 400 elsewhere), 12 rare treasure (4000), 13-19 points:
; 200, 500, 800, 1000, 2000, 5000, 10000. Sound 28 when collected (not for weapons).
;---------------------------------------------------------------------------
UpdateSpecialObjs:
        lea.l   g_SpecialObjs(a6),a5            ; 098FA
        moveq   #$2,d7                          ; 098FE
l_09900:
        tst.b   (a5)                            ; 09900
        beq.b   l_09932                         ; 09902
        move.b  d7,d0                           ; 09904
        add.w   g_GameFrame(a6),d0              ; 09906
        andi.b  #$f,d0                          ; 0990A
        bne.b   l_09914                         ; 0990E
        bsr.w   CheckOnScreen                   ; 09910
l_09914:
        clr.w   d0                              ; 09914
        move.b  O_State(a5),d0                  ; 09916
        add.w   d0,d0                           ; 0991A
        add.w   d0,d0                           ; 0991C
        jsr     SpecialStateTable(pc,d0.w)      ; 0991E
        tst.b   O_OnScreen(a5)                  ; 09922
        beq.b   l_09932                         ; 09926
        tst.l   O_Anim(a5)                      ; 09928
        beq.b   l_09932                         ; 0992C
        bsr.w   QueueObjectDraw                 ; 0992E
l_09932:
        lea.l   $20(a5),a5                      ; 09932
        subq.w  #$1,d7                          ; 09936
        bne.b   l_09900                         ; 09938
        rts                                     ; 0993A
SpecialStateTable:
        bra.w   Special_Attach                  ; 0993C
        bra.w   Special_Prize                   ; 09940
        bra.w   Special_Collected               ; 09944
        bra.w   Special_Free                    ; 09948

;---------------------------------------------------------------------------
; Type 0: wait for the carrier to become active; type 1: start falling
;---------------------------------------------------------------------------
Special_Attach:
        move.b  #$0,O_Size(a5)                  ; 0994C
        clr.l   O_Anim(a5)                      ; 09952
        tst.b   O_Type(a5)                      ; 09956
        bne.b   l_09978                         ; 0995A
        movea.l O_MoveTable(a5),a4              ; 0995C
        cmpi.b  #$1,$3(a4)                      ; 09960
        bne.b   l_09976                         ; 09966
        move.b  #$1,O_State(a5)                 ; 09968
        clr.b   O_Step(a5)                      ; 0996E
        clr.b   O_Step2(a5)                     ; 09972
l_09976:
        rts                                     ; 09976
l_09978:
        move.b  #$1,O_State(a5)                 ; 09978
        move.b  #$1,O_Step(a5)                  ; 0997E
        clr.b   O_Step2(a5)                     ; 09984
        rts                                     ; 09988
Special_Prize:
        move.b  O_Step(a5),d0                   ; 0998A
        add.w   d0,d0                           ; 0998E
        add.w   d0,d0                           ; 09990
        jsr     Special_Prize_Jumps(pc,d0.w)    ; 09992
        bra.w   CheckFarAway                    ; 09996
Special_Prize_Jumps:
        bra.w   Special_Ride                    ; 0999A
        bra.w   Special_Fall                    ; 0999E
        bra.w   Special_Reveal                  ; 099A2
        bra.w   Special_Wait                    ; 099A6

;---------------------------------------------------------------------------
; Y offset of the prize on its carrier, per enemy type
;---------------------------------------------------------------------------
SpecialRideOffsets:
	dc.b	$F8,$F2,$F0,$10,$10,$F0,$F0,$F0,$F0,$F0,$F0,$F8,$F0,$F0,$F0,$F0

;---------------------------------------------------------------------------
; Follow the carrier; it is killed (state 2): fall; it is gone: remove
;---------------------------------------------------------------------------
Special_Ride:
        movea.l O_MoveTable(a5),a4              ; 099BA
        tst.b   O_Step2(a5)                     ; 099BE
        bne.b   l_099DC                         ; 099C2
        lea.l   Special_AnimPot(pc),a0          ; 099C4
        bsr.w   SetAnim                         ; 099C8
        move.b  $1a(a4),d0                      ; 099CC
        ext.w   d0                              ; 099D0
        move.b  SpecialRideOffsets(pc,d0.w),O_Dir(a5); 099D2
        addq.b  #$1,O_Step2(a5)                 ; 099D8
l_099DC:
        move.w  $6(a4),O_X(a5)                  ; 099DC
        move.b  O_Dir(a5),d0                    ; 099E2
        ext.w   d0                              ; 099E6
        add.w   $a(a4),d0                       ; 099E8
        move.w  d0,O_Y(a5)                      ; 099EC
        tst.b   (a4)                            ; 099F0
        beq.b   l_09A08                         ; 099F2
        cmpi.b  #$2,$3(a4)                      ; 099F4
        bne.b   l_09A06                         ; 099FA
        move.b  #$1,O_Step(a5)                  ; 099FC
        clr.b   O_Step2(a5)                     ; 09A02
l_09A06:
        rts                                     ; 09A06
l_09A08:
        move.b  #$3,O_State(a5)                 ; 09A08
        rts                                     ; 09A0E

;---------------------------------------------------------------------------
; Fall (gravity 0.07 px/frame^2, up to 4 px/frame) until it lands
;---------------------------------------------------------------------------
Special_Fall:
        tst.b   O_Step2(a5)                     ; 09A10
        bne.b   l_09A26                         ; 09A14
        lea.l   Special_AnimPot(pc),a0          ; 09A16
        bsr.w   SetAnim                         ; 09A1A
        clr.l   Spc_VY(a5)                      ; 09A1E
        addq.b  #$1,O_Step2(a5)                 ; 09A22
l_09A26:
        move.l  Spc_VY(a5),d0                   ; 09A26
        add.l   d0,O_Y(a5)                      ; 09A2A
        cmpi.w  #$fffc,Spc_VY(a5)               ; 09A2E
        blt.b   l_09A3E                         ; 09A34
        addi.l  #$ffffed4a,Spc_VY(a5)           ; 09A36
l_09A3E:
        bsr.w   ObjectMapCollide                ; 09A3E
        bne.b   l_09A4E                         ; 09A42
        move.b  #$2,O_Step(a5)                  ; 09A44
        clr.b   O_Step2(a5)                     ; 09A4A
l_09A4E:
