;---------------------------------------------------------------------------
; 10 frames, then show the prize for O_Param
;---------------------------------------------------------------------------
Special_Reveal:
        tst.b   O_Step2(a5)                     ; 09A50
        bne.b   l_09A60                         ; 09A54
        move.b  #$a,O_HP(a5)                    ; 09A56
        addq.b  #$1,O_Step2(a5)                 ; 09A5C
l_09A60:
        subq.b  #$1,O_HP(a5)                    ; 09A60
        bne.w   Animate                         ; 09A64
        move.b  O_Param(a5),d0                  ; 09A68
        ext.w   d0                              ; 09A6C
        move.b  SpecialPrizeSizes(pc,d0.w),O_Size(a5); 09A6E
        lea.l   Special_AnimPrizes(pc),a0       ; 09A74
        add.w   d0,d0                           ; 09A78
        adda.w  d0,a0                           ; 09A7A
