;---------------------------------------------------------------------------
; UpdateEnemyShots - 6 slots x $1C at g_EnemyShots. O_State: 0 start (by type), 1 fly,
; 2 hit Arthur (set by EnemyShotsVsArthur), 3 free. O_Type = who fired it:
;    0 Magician's frog spell     1 Unicorn          2 (unused)        3 Big Man
;    4 Woody Pig's bomb          5 fire pillar      6 plant           7 Red Arremer
;    8 Petite Devil              9 Dragon's fire   10 Astaroth       11 Satan
; Move table and animation per type come from EnemyShotMoves / EnemyShotAnims (O_Dir
; selects the entry). Types 4 and 10 stop when they reach the floor.
;---------------------------------------------------------------------------
UpdateEnemyShots:
        lea.l   g_EnemyShots(a6),a5             ; 09C58
        moveq   #$5,d7                          ; 09C5C
l_09C5E:
        tst.b   (a5)                            ; 09C5E
        beq.b   l_09C92                         ; 09C60
        move.w  g_GameFrame(a6),d0              ; 09C62
        add.b   d7,d0                           ; 09C66
        andi.b  #$3,d0                          ; 09C68
        bne.b   l_09C72                         ; 09C6C
        bsr.w   CheckOnScreen                   ; 09C6E
l_09C72:
        clr.w   d0                              ; 09C72
        move.b  O_State(a5),d0                  ; 09C74
        add.w   d0,d0                           ; 09C78
        add.w   d0,d0                           ; 09C7A
        jsr     EnemyShotStateTable(pc,d0.w)    ; 09C7C
        tst.b   O_OnScreen(a5)                  ; 09C80
        beq.b   l_09C92                         ; 09C84
        cmpi.b  #$1,O_State(a5)                 ; 09C86
        bhi.b   l_09C92                         ; 09C8C
        bsr.w   QueueEnemyShotDraw              ; 09C8E
l_09C92:
        lea.l   $1c(a5),a5                      ; 09C92
        dbra    d7,l_09C5E                      ; 09C96
        rts                                     ; 09C9A
EnemyShotStateTable:
        bra.w   EShot_Start                     ; 09C9C
        bra.w   EShot_Fly                       ; 09CA0
        bra.w   EShot_Hit                       ; 09CA4
        bra.w   EShot_Free                      ; 09CA8

;---------------------------------------------------------------------------
; State 0: per type
;---------------------------------------------------------------------------
EShot_Start:
        move.b  O_Type(a5),d0                   ; 09CAC
        add.w   d0,d0                           ; 09CB0
        add.w   d0,d0                           ; 09CB2
        jmp     EnemyShotTypeTable(pc,d0.w)     ; 09CB4
EnemyShotTypeTable:
