        bra.w   EShot_StartDir                  ; 09CBC
        bra.w   EShot_StartDir                  ; 09CC0
        bra.w   EShot_StartDir                  ; 09CC4
        bra.w   EShot_Carried                   ; 09CC8
        bra.w   EShot_StartDir                  ; 09CCC
        bra.w   EShot_StartAimed                ; 09CD0
        bra.w   EShot_StartAimedAnim            ; 09CD4
        bra.w   EShot_StartSub                  ; 09CD8
        bra.w   EShot_StartDir                  ; 09CDC
        bra.w   EShot_StartSub                  ; 09CE0
        bra.w   EShot_StartPlain                ; 09CE4
EShot_09CE8:	; (no references found - unused/debug code)
        rts                                     ; 09CE8

