        lea.l   EnemyShotAnims(pc),a0           ; 09DAC
        adda.w  d0,a0                           ; 09DB0
        adda.w  (a0),a0                         ; 09DB2
        rts                                     ; 09DB4

;---------------------------------------------------------------------------
