;---------------------------------------------------------------------------
EShot_Fly:
        cmpi.b  #$4,O_Type(a5)                  ; 09DB6
        beq.b   l_09DD6                         ; 09DBC
        cmpi.b  #$a,O_Type(a5)                  ; 09DBE
        beq.b   l_09DD6                         ; 09DC4
        bsr.w   CheckOnScreen                   ; 09DC6
        bsr.w   ApplyMoveTable                  ; 09DCA
