        lea.l   EffectFrames(pc),a2             ; 09FF4
        move.b  O_Frame(a5),d0                  ; 09FF8
        ext.w   d0                              ; 09FFC
        add.w   d0,d0                           ; 09FFE
        add.w   d0,d0                           ; 0A000
        adda.w  d0,a2                           ; 0A002
        adda.w  (a2),a1                         ; 0A004
        moveq   #$10,d0                         ; 0A006  grid step 16 px
        cmpi.b  #$4,O_Size(a5)                  ; 0A008  size class 4: 3 x 3; above: 4 x 4
        beq.b   l_0A054                         ; 0A00E
        bhi.w   l_0A0E4                         ; 0A010
        movea.l g_BlitListPtr(a6),a0            ; 0A014  2 x 2
