;---------------------------------------------------------------------------
; QueueEnemyDraw - queue enemy a5 for DrawBobs.
; Dying enemies (state 2) are drawn as an explosion (QueueExplosionDraw) during the step
; that shows it; removed ones (state 3) not at all. Position = O_X/O_Y less half the
; BoxSizeTable size; graphics = g_BobSets[type] (the Crow / bat uses the bat or red-crow
; set by O_Param) + the frame's offset from BobFrameDescs, whose entries are
; (offset.w, y adjust.b, height.b). The Unicorn (type 8) is two BOBs: body
; (48 x 32, frame / 8 + 8) and legs (48 x 16, frame & 7).
;---------------------------------------------------------------------------
QueueEnemyDraw:
        cmpi.b  #ST_KILLED,O_State(a5)          ; 0A1E4  dying: explosion; removed: nothing
        bcs.b   l_0A21A                         ; 0A1EA
        bhi.b   l_0A218                         ; 0A1EC
        cmpi.b  #E_DRAGON,O_Type(a5)            ; 0A1EE  Dragon: during its steps 2 and 5
        bne.b   l_0A208                         ; 0A1F4
        cmpi.b  #$2,O_Step(a5)                  ; 0A1F6
        beq.b   l_0A210                         ; 0A1FC
        cmpi.b  #$5,O_Step(a5)                  ; 0A1FE
        beq.b   l_0A210                         ; 0A204
        bra.b   l_0A218                         ; 0A206
l_0A208:
        cmpi.b  #$1,O_Step(a5)                  ; 0A208
        bne.b   l_0A218                         ; 0A20E
l_0A210:
        tst.b   O_Step2(a5)                     ; 0A210
        bne.w   QueueExplosionDraw              ; 0A214
l_0A218:
        rts                                     ; 0A218
l_0A21A:
        cmpi.b  #E_UNICORN,O_Type(a5)           ; 0A21A  Unicorn: two BOBs
        beq.w   l_0A2B6                         ; 0A220
        lea.l   BoxSizeTable(pc),a1             ; 0A224  box size: the BOB is centred on O_X / O_Y
        moveq   #$0,d0                          ; 0A228
        move.b  O_Size(a5),d0                   ; 0A22A
        add.w   d0,d0                           ; 0A22E
        adda.w  d0,a1                           ; 0A230
        clr.w   d3                              ; 0A232
        clr.w   d4                              ; 0A234
