        lea.l   $1b4cc.l,a1                     ; 0A3C2
        lea.l   EffectFrames(pc),a2             ; 0A3C8
        move.b  O_Frame(a5),d0                  ; 0A3CC
        add.w   d0,d0                           ; 0A3D0
        add.w   d0,d0                           ; 0A3D2
        adda.w  d0,a2                           ; 0A3D4
        adda.w  (a2)+,a1                        ; 0A3D6
        sub.w   d4,d2                           ; 0A3D8
        move.b  (a2)+,d0                        ; 0A3DA
        ext.w   d0                              ; 0A3DC
        add.w   d0,d2                           ; 0A3DE
        move.b  (a2)+,d4                        ; 0A3E0
        add.w   d4,d2                           ; 0A3E2
        movea.l g_BlitListPtr(a6),a0            ; 0A3E4
        move.l  a1,-(a0)                        ; 0A3E8
