;---------------------------------------------------------------------------
; Item handlers by O_Type (placed from LevelItemLists):
;   0  touch item. Param 0 and 1 are invisible trigger points: param 0 calls a special
;      object (type 1) 100 px ahead - only if Arthur has lost his armour; param 1 calls one
;      100 px ahead and 128 px up. Param 2 / 3 are point pickups (sound 28, 200 / 500 points).
;   1  shootable scenery (gravestones etc.) - nothing to do here; see ShotsVsScenery
;   2  moving platform on a scripted path (ItemPaths / ItemPathScripts)
;   3  platform that starts moving once Arthur stands on it, until it is below the level
;   4  platform that waits until Arthur reaches X $980, then moves
;   5  solid moving block: pushes Arthur sideways and stops him jumping up through it
; A platform carries Arthur while he stands on it (its O_Frame byte is used as the rider flag, Itm_Rider, set by ArthurOnPlatform).
;---------------------------------------------------------------------------
ItemTypeTable:
        bra.w   Item_Touch                      ; 0A444
        bra.w   Item_Scenery                    ; 0A448
        bra.w   Item_Platform                   ; 0A44C
        bra.w   Item_RidePlatform               ; 0A450
        bra.w   Item_WaitPlatform               ; 0A454
        bra.w   Item_Block                      ; 0A458

;---------------------------------------------------------------------------
; Arthur within 12 px across and 8 px vertically: collect / trigger
;---------------------------------------------------------------------------
Item_Touch:
        tst.b   O_State(a5)                     ; 0A45C
        bne.b   l_0A48A                         ; 0A460
        move.w  O_X(a5),d0                      ; 0A462
        sub.w   g_ArthurX(a6),d0                ; 0A466
        addi.w  #$c,d0                          ; 0A46A
        cmp.w   #$18,d0                         ; 0A46E
        bhi.b   l_0A488                         ; 0A472
        move.w  O_Y(a5),d0                      ; 0A474
        sub.w   g_ArthurY(a6),d0                ; 0A478
        addq.w  #$8,d0                          ; 0A47C
        cmp.w   #$10,d0                         ; 0A47E
        bhi.b   l_0A488                         ; 0A482
        addq.b  #$1,O_State(a5)                 ; 0A484
l_0A488:
        rts                                     ; 0A488
l_0A48A:
        clr.w   d0                              ; 0A48A
        move.b  O_Param(a5),d0                  ; 0A48C
        add.w   d0,d0                           ; 0A490
        add.w   d0,d0                           ; 0A492
        jmp     Item_Touch_Jumps(pc,d0.w)       ; 0A494
Item_Touch_Jumps:
        bra.w   Item_TriggerArmour              ; 0A498
        bra.w   Item_TriggerCall                ; 0A49C
        bra.w   Item_Coin                       ; 0A4A0
        bra.w   Item_MoneyBag                   ; 0A4A4

;---------------------------------------------------------------------------
; Param 0: no armour? call special object type 1 at X + 100
;---------------------------------------------------------------------------
Item_TriggerArmour:
        clr.b   (a5)                            ; 0A4A8
        tst.b   g_NoArmour(a6)                  ; 0A4AA
        beq.b   l_0A4DE                         ; 0A4AE
        lea.l   g_SpecialObjs+32(a6),a4         ; 0A4B0
        moveq   #$64,d0                         ; 0A4B4
        add.w   O_X(a5),d0                      ; 0A4B6
        move.w  d0,$6(a4)                       ; 0A4BA
        move.w  O_Y(a5),$a(a4)                  ; 0A4BE
        move.b  #$1,$1a(a4)                     ; 0A4C4
        clr.b   $2(a4)                          ; 0A4CA
        clr.b   $3(a4)                          ; 0A4CE
        clr.b   $4(a4)                          ; 0A4D2
        clr.b   $5(a4)                          ; 0A4D6
        move.b  #$1,(a4)                        ; 0A4DA
l_0A4DE:
        rts                                     ; 0A4DE

;---------------------------------------------------------------------------
; Param 1: call special object type 1 (param $13) at X + 100, Y + 128
;---------------------------------------------------------------------------
Item_TriggerCall:
        clr.b   (a5)                            ; 0A4E0
        lea.l   g_SpecialObjs+32(a6),a4         ; 0A4E2
        moveq   #$64,d0                         ; 0A4E6
        add.w   O_X(a5),d0                      ; 0A4E8
        move.w  d0,$6(a4)                       ; 0A4EC
        move.w  O_Y(a5),d0                      ; 0A4F0
        addi.w  #$80,d0                         ; 0A4F4
        move.w  d0,$a(a4)                       ; 0A4F8
        move.b  #$1,$1a(a4)                     ; 0A4FC
        move.b  #$13,$2(a4)                     ; 0A502
        clr.b   $3(a4)                          ; 0A508
        clr.b   $4(a4)                          ; 0A50C
        clr.b   $5(a4)                          ; 0A510
        move.b  #$1,(a4)                        ; 0A514
        rts                                     ; 0A518

;---------------------------------------------------------------------------
; Param 2: 200 points
;---------------------------------------------------------------------------
Item_Coin:
        moveq   #SFX_PICKUP,d0                  ; 0A51A
        bsr.w   PlaySfx                         ; 0A51C
        moveq   #PTS_200,d0                     ; 0A520
        bsr.w   AddScore                        ; 0A522
        clr.b   (a5)                            ; 0A526
        rts                                     ; 0A528

;---------------------------------------------------------------------------
; Param 3: 500 points
;---------------------------------------------------------------------------
Item_MoneyBag:
        moveq   #SFX_PICKUP,d0                  ; 0A52A
        bsr.w   PlaySfx                         ; 0A52C
        moveq   #PTS_500,d0                     ; 0A530
        bsr.w   AddScore                        ; 0A532
        clr.b   (a5)                            ; 0A536
        rts                                     ; 0A538
Item_Scenery:
        rts                                     ; 0A53A
Item_Platform:
        tst.b   O_State(a5)                     ; 0A53C
        bne.b   l_0A546                         ; 0A540
        bsr.w   Item_PathStart                  ; 0A542
l_0A546:
        bra.w   Item_PathScript                 ; 0A546
Item_RidePlatform:
        tst.b   O_State(a5)                     ; 0A54A
        bne.b   l_0A554                         ; 0A54E
        bsr.w   Item_PathStart                  ; 0A550
l_0A554:
        tst.b   O_Param(a5)                     ; 0A554
        bne.w   Item_RideMove                   ; 0A558
        bra.w   Item_PathScript                 ; 0A55C

;---------------------------------------------------------------------------
; Waits until Arthur X >= $980
;---------------------------------------------------------------------------
Item_WaitPlatform:
        tst.b   O_State(a5)                     ; 0A560
        bne.b   l_0A56A                         ; 0A564
        bsr.w   Item_PathStart                  ; 0A566
l_0A56A:
        tst.b   O_Step2(a5)                     ; 0A56A
        bne.b   l_0A57C                         ; 0A56E
        cmpi.w  #$980,g_ArthurX(a6)             ; 0A570
        scc.b   O_Step2(a5)                     ; 0A576
        rts                                     ; 0A57A
l_0A57C:
        bra.w   Item_PathScript                 ; 0A57C

;---------------------------------------------------------------------------
; Solid block: bump Arthur's head when he jumps up into it (Y - 20); push him out
; sideways when he walks into it; turn him round once
;---------------------------------------------------------------------------
Item_Block:
        tst.b   O_State(a5)                     ; 0A580
        bne.b   l_0A58E                         ; 0A584
        clr.b   O_HP(a5)                        ; 0A586
        bra.w   Item_PathStart                  ; 0A58A
l_0A58E:
