        tst.b   g_Jumping(a6)                   ; 0A592
        beq.b   Item_BlockPush                  ; 0A596
        move.w  O_X(a5),d0                      ; 0A598
        sub.w   g_ArthurX(a6),d0                ; 0A59C
        addi.w  #$14,d0                         ; 0A5A0
        cmp.w   #$28,d0                         ; 0A5A4
        bhi.b   l_0A5C2                         ; 0A5A8
        move.w  O_Y(a5),d0                      ; 0A5AA
        sub.w   g_ArthurY(a6),d0                ; 0A5AE
        bcs.b   l_0A5C0                         ; 0A5B2
        cmp.w   #$14,d0                         ; 0A5B4
        bhi.b   l_0A5C0                         ; 0A5B8
        addi.w  #$ffec,g_ArthurY(a6)            ; 0A5BA  head bump: push Arthur 20 px down
l_0A5C0:
        rts                                     ; 0A5C0
l_0A5C2:
        move.w  O_X(a5),d0                      ; 0A5C2
        sub.w   g_ArthurX(a6),d0                ; 0A5C6
        bpl.b   l_0A5D6                         ; 0A5CA
        cmpi.b  #$ff,g_ArthurDir(a6)            ; 0A5CC
        beq.b   l_0A5E0                         ; 0A5D2
        rts                                     ; 0A5D4
l_0A5D6:
        cmpi.b  #$1,g_ArthurDir(a6)             ; 0A5D6
        beq.b   l_0A5E0                         ; 0A5DC
        rts                                     ; 0A5DE
l_0A5E0:
        tst.b   O_HP(a5)                        ; 0A5E0
        bne.b   l_0A5C0                         ; 0A5E4
        move.w  O_Y(a5),d0                      ; 0A5E6
        sub.w   g_ArthurY(a6),d0                ; 0A5EA
        addi.w  #$10,d0                         ; 0A5EE
        cmp.w   #$20,d0                         ; 0A5F2
        bhi.b   l_0A5C0                         ; 0A5F6
        move.w  O_X(a5),d0                      ; 0A5F8
        sub.w   g_ArthurX(a6),d0                ; 0A5FC
        addi.w  #$20,d0                         ; 0A600
        cmp.w   #$40,d0                         ; 0A604
        bhi.b   l_0A5C0                         ; 0A608
        neg.b   g_ArthurDir(a6)                 ; 0A60A  walked into it: turn Arthur round
        st.b    O_HP(a5)                        ; 0A60E
        rts                                     ; 0A612
Item_BlockPush:
        clr.b   O_HP(a5)                        ; 0A614
        move.w  O_Y(a5),d0                      ; 0A618
        sub.w   g_ArthurY(a6),d0                ; 0A61C
        addi.w  #$10,d0                         ; 0A620
        cmp.w   #$20,d0                         ; 0A624
        bhi.b   l_0A5C0                         ; 0A628
        move.w  O_X(a5),d0                      ; 0A62A
        sub.w   g_ArthurX(a6),d0                ; 0A62E
        addi.w  #$20,d0                         ; 0A632
        cmp.w   #$40,d0                         ; 0A636
        bhi.b   l_0A5C0                         ; 0A63A
        move.w  d0,d1                           ; 0A63C
        cmp.w   #$20,d0                         ; 0A63E
        bcs.b   l_0A658                         ; 0A642
        neg.w   d1                              ; 0A644
        addi.w  #$40,d1                         ; 0A646
        cmp.w   #$5,d1                          ; 0A64A
        bhi.b   l_0A652                         ; 0A64E
        moveq   #$4,d1                          ; 0A650
l_0A652:
        sub.w   d1,g_ArthurX(a6)                ; 0A652
        rts                                     ; 0A656
l_0A658:
        cmp.w   #$5,d1                          ; 0A658
        bhi.b   l_0A660                         ; 0A65C
        moveq   #$4,d1                          ; 0A65E
l_0A660:
        add.w   d1,g_ArthurX(a6)                ; 0A660
        rts                                     ; 0A664

;---------------------------------------------------------------------------
; O_Anim = step table, O_MoveTable = script for the type and param
;---------------------------------------------------------------------------
Item_PathStart:
        lea.l   ItemPaths(pc),a0                ; 0A666
        clr.w   d0                              ; 0A66A
        move.b  O_Type(a5),d0                   ; 0A66C
        add.w   d0,d0                           ; 0A670
        adda.w  d0,a0                           ; 0A672
        adda.w  (a0),a0                         ; 0A674
        move.b  O_Param(a5),d0                  ; 0A676
        add.w   d0,d0                           ; 0A67A
        adda.w  d0,a0                           ; 0A67C
        adda.w  (a0),a0                         ; 0A67E
        move.l  a0,O_Anim(a5)                   ; 0A680
        clr.b   O_AnimTimer(a5)                 ; 0A684
        clr.b   O_Step(a5)                      ; 0A688
        lea.l   ItemPathScripts(pc),a0          ; 0A68C
        move.b  O_Type(a5),d0                   ; 0A690
        add.w   d0,d0                           ; 0A694
        adda.w  d0,a0                           ; 0A696
        adda.w  (a0),a0                         ; 0A698
        move.b  O_Param(a5),d0                  ; 0A69A
        add.w   d0,d0                           ; 0A69E
        adda.w  d0,a0                           ; 0A6A0
        adda.w  (a0),a0                         ; 0A6A2
        move.l  a0,O_MoveTable(a5)              ; 0A6A4
        move.b  #$1,O_State(a5)                 ; 0A6A8
        rts                                     ; 0A6AE

;---------------------------------------------------------------------------
; Next (step, frames) pair from the script; bit 7 = loop
;---------------------------------------------------------------------------
Item_PathScript:
        tst.b   O_AnimTimer(a5)                 ; 0A6B0
        bne.b   Item_PathMove                   ; 0A6B4
        movea.l O_MoveTable(a5),a0              ; 0A6B6
        move.b  (a0)+,O_Step(a5)                ; 0A6BA
        move.b  (a0)+,d0                        ; 0A6BE
        bpl.b   l_0A6C8                         ; 0A6C0
        andi.b  #$7f,d0                         ; 0A6C2
        adda.w  (a0),a0                         ; 0A6C6
l_0A6C8:
        move.b  d0,O_AnimTimer(a5)              ; 0A6C8
        move.l  a0,O_MoveTable(a5)              ; 0A6CC
        rts                                     ; 0A6D0

;---------------------------------------------------------------------------
; Move by the step's (dx, dy); carry Arthur if he is on it
;---------------------------------------------------------------------------
Item_PathMove:
        movea.l O_Anim(a5),a0                   ; 0A6D2
        clr.w   d0                              ; 0A6D6
        move.b  O_Step(a5),d0                   ; 0A6D8
        add.w   d0,d0                           ; 0A6DC
        add.w   d0,d0                           ; 0A6DE
        adda.w  d0,a0                           ; 0A6E0
        subq.b  #$1,O_AnimTimer(a5)             ; 0A6E2
        move.w  (a0)+,d0                        ; 0A6E6
        ext.l   d0                              ; 0A6E8
        asl.l   #$8,d0                          ; 0A6EA
        add.l   d0,O_X(a5)                      ; 0A6EC
        move.w  (a0)+,d1                        ; 0A6F0
        ext.l   d1                              ; 0A6F2
        asl.l   #$8,d1                          ; 0A6F4
        add.l   d1,O_Y(a5)                      ; 0A6F6
        tst.b   O_Frame(a5)                     ; 0A6FA
        beq.b   l_0A70E                         ; 0A6FE
        add.l   d0,g_ArthurX(a6)                ; 0A700
        tst.b   g_Jumping(a6)                   ; 0A704
        bne.b   l_0A70E                         ; 0A708
        add.l   d1,g_ArthurY(a6)                ; 0A70A
l_0A70E:
        rts                                     ; 0A70E
Item_RideMove:
        tst.b   O_Frame(a5)                     ; 0A710
        beq.b   l_0A71C                         ; 0A714
        move.b  #$2,O_Step(a5)                  ; 0A716
l_0A71C:
        cmpi.b  #$2,O_Step(a5)                  ; 0A71C
        bne.b   l_0A72C                         ; 0A722
        tst.w   O_Y(a5)                         ; 0A724
        bmi.b   l_0A70E                         ; 0A728
        bsr.b   Item_PathMove                   ; 0A72A
l_0A72C:
        rts                                     ; 0A72C

;---------------------------------------------------------------------------
; ItemPaths - moving platforms (item types 2-5, Item_PathStart): per type a word offset to a
; table per param, each entry an offset to a step table of (dx, dy) moves in pixels x 256 a frame
; (Item_PathMove). Steps: 0 still, 1 right, 2 down, 3 left, 4 up. Types 0 and 1 never start a path.
;---------------------------------------------------------------------------
ItemPaths:
	dc.w	ItemPathsType2-*	; type 0 (types 0-1 never start a path)
	dc.w	ItemPathsType2-*	; type 1 (types 0-1 never start a path)
	dc.w	ItemPathsType2-*	; type 2
	dc.w	ItemPathsType3-*	; type 3
	dc.w	ItemPathsType4-*	; type 4
	dc.w	ItemPathsType5-*	; type 5
ItemPathsType2:
	dc.w	ItemSteps2_0-*	; param 0
	dc.w	ItemSteps2_0-*	; param 1
	dc.w	ItemSteps2_0-*	; param 2
	dc.w	ItemSteps2_0-*	; param 3
ItemPathsType3:
	dc.w	ItemSteps3_0-*	; param 0
	dc.w	ItemSteps3_1-*	; param 1
	dc.w	ItemSteps3_0-*	; param 2
	dc.w	ItemSteps3_1-*	; param 3
ItemPathsType4:
	dc.w	ItemSteps4_0-*	; param 0
	dc.w	ItemSteps4_0-*	; param 1
	dc.w	ItemSteps4_0-*	; param 2
	dc.w	ItemSteps4_0-*	; param 3
ItemPathsType5:
	dc.w	ItemSteps5_0-*	; param 0
	dc.w	ItemSteps5_1-*	; param 1
	dc.w	ItemSteps5_2-*	; param 2
	dc.w	ItemSteps5_3-*	; param 3
	dc.w	ItemSteps5_0-*	; param 4
	dc.w	ItemSteps5_0-*	; param 5
	dc.w	ItemSteps5_0-*	; param 6
; step tables: (dx, dy) per step number, pixels x 256 a frame (Y up)
ItemSteps2_0:
	dc.w	0,0	; step 0: dx +0.00, dy +0.00
	dc.w	206,0	; step 1: dx +0.80, dy +0.00
	dc.w	0,-206	; step 2: dx +0.00, dy -0.80
	dc.w	-206,0	; step 3: dx -0.80, dy +0.00
	dc.w	0,206	; step 4: dx +0.00, dy +0.80
ItemSteps3_0:
	dc.w	0,0	; step 0: dx +0.00, dy +0.00
	dc.w	238,0	; step 1: dx +0.93, dy +0.00
	dc.w	0,-238	; step 2: dx +0.00, dy -0.93
	dc.w	-238,0	; step 3: dx -0.93, dy +0.00
	dc.w	0,238	; step 4: dx +0.00, dy +0.93
ItemSteps3_1:
	dc.w	0,0	; step 0: dx +0.00, dy +0.00
	dc.w	238,0	; step 1: dx +0.93, dy +0.00
	dc.w	0,-768	; step 2: dx +0.00, dy -3.00
	dc.w	-238,0	; step 3: dx -0.93, dy +0.00
	dc.w	0,768	; step 4: dx +0.00, dy +3.00
ItemSteps4_0:
	dc.w	0,0	; step 0: dx +0.00, dy +0.00
	dc.w	288,0	; step 1: dx +1.12, dy +0.00
	dc.w	0,-288	; step 2: dx +0.00, dy -1.12
	dc.w	-288,0	; step 3: dx -1.12, dy +0.00
	dc.w	0,288	; step 4: dx +0.00, dy +1.12
ItemSteps5_0:
	dc.w	0,0	; step 0: dx +0.00, dy +0.00
	dc.w	352,0	; step 1: dx +1.38, dy +0.00
	dc.w	0,-352	; step 2: dx +0.00, dy -1.38
	dc.w	-352,0	; step 3: dx -1.38, dy +0.00
	dc.w	0,352	; step 4: dx +0.00, dy +1.38
ItemSteps5_1:
	dc.w	0,0	; step 0: dx +0.00, dy +0.00
	dc.w	293,0	; step 1: dx +1.14, dy +0.00
	dc.w	0,-293	; step 2: dx +0.00, dy -1.14
	dc.w	-293,0	; step 3: dx -1.14, dy +0.00
	dc.w	0,293	; step 4: dx +0.00, dy +1.14
ItemSteps5_2:
	dc.w	0,0	; step 0: dx +0.00, dy +0.00
	dc.w	373,0	; step 1: dx +1.46, dy +0.00
	dc.w	0,-373	; step 2: dx +0.00, dy -1.46
	dc.w	-373,0	; step 3: dx -1.46, dy +0.00
	dc.w	0,373	; step 4: dx +0.00, dy +1.46
ItemSteps5_3:
	dc.w	0,0	; step 0: dx +0.00, dy +0.00
	dc.w	144,0	; step 1: dx +0.56, dy +0.00
	dc.w	0,-144	; step 2: dx +0.00, dy -0.56
	dc.w	-144,0	; step 3: dx -0.56, dy +0.00


;---------------------------------------------------------------------------
; ItemPathScripts - the platforms' scripts, indexed the same way: (step, frames) pairs (ISTEP);
; the last has bit 7 on frames and an offset back to the start (ILOOP), read by Item_PathScript.
; Types 2 and 3 have only a param-0 entry: the one type-3 platform with param 1 (level 1) reads the
; next word and so runs type 4's first script with its own steps (ItemSteps3_1, 3 px a frame up
; and down). Type 1's entry points into type 4's scripts but is never used.
;---------------------------------------------------------------------------
ItemPathScripts:
	dc.w	0		; type 0: no path
	dc.w	ItemScript4_2-*	; type 1 (types 0-1 never start a path)
	dc.w	ItemScriptsType2-*	; type 2
	dc.w	ItemScriptsType3-*	; type 3
	dc.w	ItemScriptsType4-*	; type 4
	dc.w	ItemScriptsType5-*	; type 5
ItemScriptsType2:
	dc.w	ItemScript2_0-*	; param 0
ItemScriptsType3:
	dc.w	ItemScript3_0-*	; param 0
ItemScriptsType4:
	dc.w	ItemScript4_0-*	; param 0
	dc.w	ItemScript4_1-*	; param 1
	dc.w	ItemScript4_2-*	; param 2
	dc.w	ItemScript4_3-*	; param 3
ItemScriptsType5:
	dc.w	ItemScript5_0-*	; param 0
	dc.w	ItemScript5_1-*	; param 1
	dc.w	ItemScript5_2-*	; param 2
	dc.w	ItemScript5_3-*	; param 3
	dc.w	ItemScript5_4-*	; param 4
	dc.w	ItemScript5_5-*	; param 5
	dc.w	ItemScript5_6-*	; param 6
; scripts: (step, frames); the last entry has bit 7 set on frames and loops back
ItemScript2_0:
	ISTEP	1,55
	ISTEP	3,55
	ISTEP	1,120
	ISTEP	3,120
	ISTEP	1,120
	ISTEP	1,20
	ISTEP	3,85
	ISTEP	1,85
	ISTEP	3,20
	ILOOP	3,120,ItemScript2_0
