        move.b  O_Type(a5),d0                   ; 0A920
        ext.w   d0                              ; 0A924
        move.b  (a1,d0.w),d0                    ; 0A926
        lea.l   BoxSizeTable(pc),a1             ; 0A92A
        add.w   d0,d0                           ; 0A92E
        adda.w  d0,a1                           ; 0A930
        clr.w   d3                              ; 0A932
        clr.w   d4                              ; 0A934
        move.b  (a1)+,d3                        ; 0A936
        move.b  (a1)+,d4                        ; 0A938
        move.w  O_X(a5),d1                      ; 0A93A
        move.w  d3,d0                           ; 0A93E
        lsr.w   #$1,d0                          ; 0A940
        sub.w   d0,d1                           ; 0A942
        move.w  O_Y(a5),d2                      ; 0A944
        move.w  d4,d0                           ; 0A948
        lsr.w   #$1,d0                          ; 0A94A
        sub.w   d0,d2                           ; 0A94C
        lea.l   ItemImageTable(pc),a1           ; 0A94E
        move.b  O_Type(a5),d0                   ; 0A952
        add.w   d0,d0                           ; 0A956
        adda.w  d0,a1                           ; 0A958
        adda.w  (a1),a1                         ; 0A95A
        move.b  O_Param(a5),d0                  ; 0A95C
        adda.w  d0,a1                           ; 0A960
        move.b  (a1),d0                         ; 0A962
        bmi.b   l_0A990                         ; 0A964
        lea.l   g_SmallBobSets(a6),a1           ; 0A966
        add.w   d0,d0                           ; 0A96A
        add.w   d0,d0                           ; 0A96C
        adda.w  d0,a1                           ; 0A96E
        movea.l (a1),a1                         ; 0A970
        lsr.w   #$1,d0                          ; 0A972
        lea.l   SmallBobSizes(pc,d0.w),a2       ; 0A974
        add.w   d4,d2                           ; 0A978
        move.b  (a2)+,d0                        ; 0A97A
        sub.w   d0,d2                           ; 0A97C
        move.b  (a2)+,d4                        ; 0A97E
        sub.w   d4,d2                           ; 0A980
        movea.l g_BlitListPtr(a6),a0            ; 0A982
        move.l  a1,-(a0)                        ; 0A986
        movem.w d1-d4,-(a0)                     ; 0A988
        move.l  a0,g_BlitListPtr(a6)            ; 0A98C
l_0A990:
