;---------------------------------------------------------------------------
; y-adjust.b, height.b for each of the 10 small BOB images
;---------------------------------------------------------------------------
SmallBobSizes:
	dc.b	$03,$0D,$01,$0F,$00,$10,$00,$10,$0C,$14,$0C,$14,$0C,$14,$0B,$15
	dc.b	$02,$0E,$00,$0A

;---------------------------------------------------------------------------
; Enemy spawners (16 slots x $C at g_Spawners, slot = enemy type).
; Slot: +0 active, +1 entries left, +2 script pointer, +6 script start, +$A frames to the
; next spawn, +$B flags (bit 0 world coords, bit 1 run once, bit 2 new zones only).
; Script (SpawnScripts): count.w, then per entry x.w, y.w (camera-relative unless flag
; bit 0), param.b, delay.b. A spawn needs a free enemy slot and g_SpawnQuota[type] > 0.
; Type 7 (the Magician) appears at the last shootable scenery hit instead; zombies 128 px further
; right. Every 6th spawned enemy carries a bonus (special object 0) - see BonusKinds.
;---------------------------------------------------------------------------
UpdateSpawners:
        lea.l   g_Spawners(a6),a2               ; 0A9A6  a2 = spawner slot ($C bytes), d7 = its enemy type
        clr.w   d7                              ; 0A9AA
l_0A9AC:
        tst.b   (a2)                            ; 0A9AC
        beq.w   l_0AADC                         ; 0A9AE
        tst.b   $1(a2)                          ; 0A9B2  entries left?
        bhi.b   l_0A9E8                         ; 0A9B6
        btst    #$1,$b(a2)                      ; 0A9B8  script finished: a 'run once' spawner stops, the others start again
        seq.b   (a2)                            ; 0A9BE
        bne.w   l_0AADC                         ; 0A9C0
        bra.b   l_0A9DA                         ; 0A9C4
	dc.b	$4A,$2A,$00,$19,$67,$0E,$08,$2A,$00,$02,$00,$0B,$66,$06,$42,$12
	dc.b	$60,$00,$01,$04
l_0A9DA:
        movea.l $6(a2),a1                       ; 0A9DA  restart the script: count and first entry
        move.w  (a1)+,d0                        ; 0A9DE
        move.b  d0,$1(a2)                       ; 0A9E0
        move.l  a1,$2(a2)                       ; 0A9E4
l_0A9E8:
        subq.b  #$1,$a(a2)                      ; 0A9E8  count down to the next spawn
        bne.w   l_0AADC                         ; 0A9EC
        lea.l   g_Enemies(a6),a5                ; 0A9F0  find a free enemy slot (none: stop for this frame)
        moveq   #$3c,d2                         ; 0A9F4
        moveq   #$27,d1                         ; 0A9F6
l_0A9F8:
        tst.b   (a5)                            ; 0A9F8
        beq.b   l_0AA06                         ; 0A9FA
        adda.w  d2,a5                           ; 0A9FC
        dbra    d1,l_0A9F8                      ; 0A9FE
        bra.w   l_0AAEA                         ; 0AA02
l_0AA06:
        lea.l   g_SpawnQuota(a6),a0             ; 0AA06  quota for this enemy type used up?
        adda.w  d7,a0                           ; 0AA0A
        tst.b   (a0)                            ; 0AA0C
        beq.w   l_0AADC                         ; 0AA0E
        subq.b  #$1,(a0)                        ; 0AA12
        move.b  #$1,(a5)                        ; 0AA14  new enemy: active, state 0, type = spawner number
        clr.b   O_OnScreen(a5)                  ; 0AA18
        clr.b   O_Step2(a5)                     ; 0AA1C
        clr.b   O_Step(a5)                      ; 0AA20
        clr.b   O_State(a5)                     ; 0AA24
        clr.b   O_Size(a5)                      ; 0AA28
        clr.b   O_HP(a5)                        ; 0AA2C
        clr.l   O_Anim(a5)                      ; 0AA30
        move.b  d7,O_Type(a5)                   ; 0AA34
        movea.l $2(a2),a1                       ; 0AA38  script entry: x, y, param, frames to the next spawn
        move.w  (a1)+,d1                        ; 0AA3C
        move.w  (a1)+,d2                        ; 0AA3E
        move.b  (a1)+,O_Param(a5)               ; 0AA40
        move.b  (a1)+,$a(a2)                    ; 0AA44
        cmp.w   #$7,d7                          ; 0AA48  type 7 (Magician): at the last scenery hit, spawner stops
        bne.b   l_0AA5A                         ; 0AA4C
        move.w  g_SceneryHitX(a6),d1            ; 0AA4E
        move.w  g_SceneryHitY(a6),d2            ; 0AA52
        clr.b   (a2)                            ; 0AA56
        bra.b   l_0AA7E                         ; 0AA58
l_0AA5A:
        btst    #$0,$b(a2)                      ; 0AA5A  flag bit 0: world coordinates; otherwise relative to the camera
        bne.b   l_0AA76                         ; 0AA60
        cmp.b   #$b,d7                          ; 0AA62  zombies (11): 128 px further right
        bne.b   l_0AA6C                         ; 0AA66
        addi.w  #$80,d1                         ; 0AA68
l_0AA6C:
        add.w   g_CameraX(a6),d1                ; 0AA6C
        add.w   g_CameraY(a6),d2                ; 0AA70
        bra.b   l_0AA7E                         ; 0AA74
l_0AA76:
        sub.w   g_LevelOriginX(a6),d1           ; 0AA76
        sub.w   g_LevelOriginY(a6),d2           ; 0AA7A
l_0AA7E:
        move.w  d1,O_X(a5)                      ; 0AA7E
        move.w  d2,O_Y(a5)                      ; 0AA82
        subq.b  #$1,g_BonusEvery(a6)            ; 0AA86  every 6th spawn carries a bonus
        bgt.b   l_0AAD4                         ; 0AA8A
        move.b  #$6,g_BonusEvery(a6)            ; 0AA8C
        lea.l   g_SpecialObjs(a6),a4            ; 0AA92  special object 0 free? it becomes the bonus this enemy carries
        tst.b   (a4)                            ; 0AA96
        bne.b   l_0AAD4                         ; 0AA98
        clr.b   $3(a4)                          ; 0AA9A
        clr.b   $4(a4)                          ; 0AA9E
        clr.b   $5(a4)                          ; 0AAA2
        move.b  #$1,(a4)                        ; 0AAA6
        clr.b   $1a(a4)                         ; 0AAAA
        move.l  a5,$e(a4)                       ; 0AAAE  special object 0 follows the new enemy
        addq.b  #$1,g_BonusCycle(a6)            ; 0AAB2  next kind in the 7-step cycle (BonusKinds)
        move.b  g_BonusCycle(a6),d0             ; 0AAB6
        cmp.b   #$7,d0                          ; 0AABA
        bcs.b   l_0AAC6                         ; 0AABE
        clr.b   d0                              ; 0AAC0
        clr.b   g_BonusCycle(a6)                ; 0AAC2
l_0AAC6:
        ext.w   d0                              ; 0AAC6
        add.w   d0,d0                           ; 0AAC8
        add.w   d0,d0                           ; 0AACA
        jsr     BonusKinds(pc,d0.w)             ; 0AACC
        move.b  d0,$2(a4)                       ; 0AAD0
l_0AAD4:
        move.l  a1,$2(a2)                       ; 0AAD4  next script entry
        subq.b  #$1,$1(a2)                      ; 0AAD8
l_0AADC:
        lea.l   $c(a2),a2                       ; 0AADC  next spawner
        addq.w  #$1,d7                          ; 0AAE0
        cmp.w   #$10,d7                         ; 0AAE2
        bne.w   l_0A9AC                         ; 0AAE6
l_0AAEA:
        rts                                     ; 0AAEA

;---------------------------------------------------------------------------
; Kind of bonus for the next carrier, cycling 0-6: treasure, treasure, weapon,
; treasure, kind 13, treasure, weapon. Treasure = 6 + level (kind 12 when g_BonusRoll
; carries); weapon = 1 + weapon number, picked by adding the level's weights (WeaponOddsTable) to
; the five g_WeaponOdds accumulators: the first that carries and is not Arthur's weapon.
;---------------------------------------------------------------------------
BonusKinds:
        bra.w   l_0AB08                         ; 0AAEC
        bra.w   l_0AB08                         ; 0AAF0
        bra.w   l_0AB1A                         ; 0AAF4
        bra.w   l_0AB08                         ; 0AAF8
        bra.w   l_0AB54                         ; 0AAFC
        bra.w   l_0AB08                         ; 0AB00
        bra.w   l_0AB1A                         ; 0AB04
l_0AB08:
        moveq   #$c,d0                          ; 0AB08  treasure: 6 + level, or kind 12 when g_BonusRoll carries (+21 a time)
        addi.b  #$15,g_BonusRoll(a6)            ; 0AB0A
        bcs.b   l_0AB18                         ; 0AB10
        moveq   #$6,d0                          ; 0AB12
        add.w   g_Level(a6),d0                  ; 0AB14
l_0AB18:
        rts                                     ; 0AB18
l_0AB1A:
        move.w  g_Level(a6),d0                  ; 0AB1A  weapon: add the level's weights to the five g_WeaponOdds accumulators
        add.w   d0,d0                           ; 0AB1E
        lea.l   WeaponOddsTable(pc,d0.w),a0     ; 0AB20
        adda.w  (a0),a0                         ; 0AB24
        addq.l  #$5,a0                          ; 0AB26
        lea.l   g_BossCountdown(a6),a3          ; 0AB28
        clr.b   d1                              ; 0AB2C
        moveq   #$4,d6                          ; 0AB2E
l_0AB30:
        move.b  -(a0),d0                        ; 0AB30
        add.b   d0,-(a3)                        ; 0AB32
        addx.b  d1,d1                           ; 0AB34
        dbra    d6,l_0AB30                      ; 0AB36
        moveq   #$0,d0                          ; 0AB3A
l_0AB3C:
        btst    d0,d1                           ; 0AB3C  the first weapon whose accumulator carried ...
        bne.b   l_0AB4A                         ; 0AB3E
        addq.w  #$1,d0                          ; 0AB40
        cmp.w   #$5,d0                          ; 0AB42
        bne.b   l_0AB3C                         ; 0AB46
        bra.b   l_0AB1A                         ; 0AB48
l_0AB4A:
        cmp.w   g_Weapon(a6),d0                 ; 0AB4A  ... unless it is Arthur's weapon: then try again
        beq.b   l_0AB1A                         ; 0AB4E
        addq.b  #$1,d0                          ; 0AB50
        rts                                     ; 0AB52
l_0AB54:
        moveq   #$d,d0                          ; 0AB54
        add.w   g_Level(a6),d0                  ; 0AB56
        rts                                     ; 0AB5A

;---------------------------------------------------------------------------
; Per level: word offset to 5 weights (one per weapon) for BonusKinds
;---------------------------------------------------------------------------
WeaponOddsTable:
	dc.b	$00,$0E,$00,$11,$00,$14,$00,$17,$00,$1A,$00,$1D,$00,$20,$66,$40
	dc.b	$00,$00,$59,$40,$40,$33,$00,$4C,$19,$40,$00,$33,$66,$00,$40,$0C
	dc.b	$6E,$4C,$33,$33,$33,$80,$00,$00,$33,$19,$80,$19,$00,$40,$19,$80
	dc.b	$19,$00

;---------------------------------------------------------------------------
