;---------------------------------------------------------------------------
SetBoxClass:
        move.l  a0,-(a7)                        ; 0AB8E
        move.w  d1,-(a7)                        ; 0AB90
        clr.w   d1                              ; 0AB92
        move.b  O_Size(a5),d1                   ; 0AB94
        add.w   d1,d1                           ; 0AB98
        lea.l   BoxSizeTable(pc),a0             ; 0AB9A
        move.b  $1(a0,d1.w),d1                  ; 0AB9E
        move.b  d0,O_Size(a5)                   ; 0ABA2
        ext.w   d0                              ; 0ABA6
        add.w   d0,d0                           ; 0ABA8
        move.b  $1(a0,d0.w),d0                  ; 0ABAA
        sub.w   d1,d0                           ; 0ABAE
        asr.w   #$1,d0                          ; 0ABB0
        add.w   d0,O_Y(a5)                      ; 0ABB2
        move.w  (a7)+,d1                        ; 0ABB6
        movea.l (a7)+,a0                        ; 0ABB8
        rts                                     ; 0ABBA

;---------------------------------------------------------------------------
; a0 = table of word offsets, index = +$12(a5)
