SetAnimIndexed:
        clr.w   d0                              ; 0ABBC
        move.b  O_Dir(a5),d0                    ; 0ABBE
        add.w   d0,d0                           ; 0ABC2
        adda.w  d0,a0                           ; 0ABC4
        adda.w  (a0),a0                         ; 0ABC6

;---------------------------------------------------------------------------
; Start animation script a0 on object a5
