SetAnim:
        move.l  a0,O_Anim(a5)                   ; 0ABC8
        clr.b   O_AnimTimer(a5)                 ; 0ABCC

;---------------------------------------------------------------------------
; Step object animation: script = (frame.b, time.b [bit7: loop, offset.w follows])
;---------------------------------------------------------------------------
Animate:
        tst.b   O_AnimTimer(a5)                 ; 0ABD0
        bne.b   l_0ABF6                         ; 0ABD4
        move.l  O_Anim(a5),d0                   ; 0ABD6
        beq.b   l_0ABFA                         ; 0ABDA
        movea.l d0,a0                           ; 0ABDC
        move.b  (a0)+,O_Frame(a5)               ; 0ABDE
        move.b  (a0)+,d0                        ; 0ABE2
        bpl.b   l_0ABEC                         ; 0ABE4
        andi.b  #$7f,d0                         ; 0ABE6
        adda.w  (a0),a0                         ; 0ABEA
l_0ABEC:
        move.b  d0,O_AnimTimer(a5)              ; 0ABEC
        move.l  a0,O_Anim(a5)                   ; 0ABF0
        rts                                     ; 0ABF4
l_0ABF6:
        subq.b  #$1,O_AnimTimer(a5)             ; 0ABF6
l_0ABFA:
        rts                                     ; 0ABFA

