        add.w   d0,d0                           ; 0AC1E
        jsr     EnemyTypeTable(pc,d0.w)         ; 0AC20
        move.b  (a5),d0                         ; 0AC24
        beq.b   l_0AC48                         ; 0AC26
        move.b  O_OnScreen(a5),d1               ; 0AC28
        beq.b   l_0AC48                         ; 0AC2C
        and.b   d0,d1                           ; 0AC2E
        beq.b   l_0AC3E                         ; 0AC30
        cmpi.b  #ST_KILLED,O_State(a5)          ; 0AC32
