        bsr.w   EnemyHitByShot                  ; 0AC3A
l_0AC3E:
        tst.l   O_Anim(a5)                      ; 0AC3E
        beq.b   l_0AC48                         ; 0AC42
        bsr.w   QueueEnemyDraw                  ; 0AC44
l_0AC48:
