;---------------------------------------------------------------------------
; EnemyTypeTable - handler per enemy type (+$1A). Type = graphics set:
;   0 Woody Pig      1 Crow (set 19 bat / set 20 red crow by param)
;   2 Petite Devil   3 Flying Knight   4 Blue Killer   5 Red Arremer
;   6 Satan          7 Magician (frog spell)           8 Unicorn (2-part BOB)
;   9 Skeleton      10 Big Man        11 Zombie       12 Dragon
;  13 Astaroth      14 Fire           15 Princess     16 (unused)
;  17 Man-eater plant                 18 Fire pillar
; Only a few enemies are placed (LevelEnemyLists); most are created by the spawners
; (UpdateSpawners), one per type, started by the map zone under the camera.
;---------------------------------------------------------------------------
EnemyTypeTable:
        bra.w   Enemy_WoodyPig                  ; 0AC52
        bra.w   Enemy_Crow                      ; 0AC56
        bra.w   Enemy_PetiteDevil               ; 0AC5A
        bra.w   Enemy_FlyingKnight              ; 0AC5E
        bra.w   Enemy_BlueKiller                ; 0AC62
        bra.w   Enemy_RedArremer                ; 0AC66
        bra.w   Enemy_Satan                     ; 0AC6A
        bra.w   Enemy_Magician                  ; 0AC6E
        bra.w   Enemy_Unicorn                   ; 0AC72
        bra.w   Enemy_Skeleton                  ; 0AC76
        bra.w   Enemy_BigMan                    ; 0AC7A
        bra.w   Enemy_Zombie                    ; 0AC7E
        bra.w   Enemy_Dragon                    ; 0AC82
        bra.w   Enemy_Astaroth                  ; 0AC86
        bra.w   Enemy_Fire                      ; 0AC8A
        bra.w   Enemy_Princess_Unused16_Plant   ; 0AC8E
        bra.w   Enemy_Princess_Unused16_Plant   ; 0AC92
        bra.w   Enemy_Princess_Unused16_Plant   ; 0AC96
        bra.w   Enemy_FirePillar                ; 0AC9A

;---------------------------------------------------------------------------
; Last boss hit: level 6 -> Ending, level 5 without cross -> WeaponUseless, else drop the key
;---------------------------------------------------------------------------
BossKilled:
        subq.b  #$1,g_BossCountdown(a6)         ; 0AC9E
        bne.b   l_0ACEC                         ; 0ACA2
        cmpi.w  #$6,g_Level(a6)                 ; 0ACA4
        bne.b   l_0ACB8                         ; 0ACAA
        move.b  #SS_ENDING,g_SubState(a6)       ; 0ACAC
        clr.b   g_SubState2(a6)                 ; 0ACB2
        rts                                     ; 0ACB6
l_0ACB8:
        cmpi.w  #$5,g_Level(a6)                 ; 0ACB8
        bne.b   l_0ACDA                         ; 0ACBE
        cmpi.w  #$3,g_Weapon(a6)                ; 0ACC0
        beq.b   l_0ACDA                         ; 0ACC6
        move.b  #SS_WEAPONUSELESS,g_SubState(a6); 0ACC8
        clr.b   g_SubState2(a6)                 ; 0ACCE
        move.b  #$ff,g_StateTimer(a6)           ; 0ACD2
        rts                                     ; 0ACD8
l_0ACDA:
        st.b    g_KeyState(a6)                  ; 0ACDA
        move.b  #$24,g_StateTimer(a6)           ; 0ACDE
        clr.b   g_SubState2(a6)                 ; 0ACE4
        clr.b   g_SubState3(a6)                 ; 0ACE8
l_0ACEC:
        rts                                     ; 0ACEC
OnScreenBoxes:
	dc.b	$00,$08,$01,$00,$00,$08,$00,$F0,$00,$10,$01,$00,$00,$10,$00,$F0
	dc.b	$00,$18,$01,$10,$00,$18,$01,$00,$00,$20,$00,$F8,$00,$20,$01,$00
	dc.b	$00,$08,$01,$00,$00,$18,$00,$F0,$00,$08,$00,$F8

