;---------------------------------------------------------------------------
; Out: d0 = 16-way direction from object a5 to Arthur: 0 right, 4 down, 8 left,
; 12 up (clockwise on screen). Picks one of five 4-entry tables (one entry per quadrant)
; by the slope |dy|/|dx|. Data bug: the 45-degree table gives 5 instead of 6 for
; 'left and below'.
;---------------------------------------------------------------------------
DirectionToArthur:
        movem.l d1-d3/a0,-(a7)                  ; 0ADA4
        clr.w   d0                              ; 0ADA8
        move.w  g_ArthurX(a6),d1                ; 0ADAA
        sub.w   O_X(a5),d1                      ; 0ADAE
        bpl.b   l_0ADB8                         ; 0ADB2
        neg.w   d1                              ; 0ADB4
        addq.w  #$1,d0                          ; 0ADB6
l_0ADB8:
        move.w  g_ArthurY(a6),d2                ; 0ADB8
        sub.w   O_Y(a5),d2                      ; 0ADBC
        bpl.b   l_0ADC6                         ; 0ADC0
        neg.w   d2                              ; 0ADC2
        addq.w  #$2,d0                          ; 0ADC4
l_0ADC6:
        tst.w   d1                              ; 0ADC6
        bne.b   l_0ADD0                         ; 0ADC8
        move.w  #$ff,d2                         ; 0ADCA
        bra.b   l_0ADD4                         ; 0ADCE
l_0ADD0:
        ext.l   d2                              ; 0ADD0
        divu.w  d1,d2                           ; 0ADD2
l_0ADD4:
        move.l  d2,d3                           ; 0ADD4
        swap    d3                              ; 0ADD6
        mulu.w  #$64,d2                         ; 0ADD8
        lea.l   DirTabSteep(pc),a0              ; 0ADDC
        cmp.w   #$258,d2                        ; 0ADE0
        bcc.b   l_0AE08                         ; 0ADE4
        lea.l   DirTab60(pc),a0                 ; 0ADE6
        cmp.w   #$96,d2                         ; 0ADEA
        bcc.b   l_0AE08                         ; 0ADEE
        lea.l   DirTab45(pc),a0                 ; 0ADF0
        cmp.w   #$4b,d2                         ; 0ADF4
        bcc.b   l_0AE08                         ; 0ADF8
        lea.l   DirTabFlat(pc),a0               ; 0ADFA
        lsr.w   #$2,d1                          ; 0ADFE
        cmp.w   d3,d1                           ; 0AE00
        bhi.b   l_0AE08                         ; 0AE02
        lea.l   DirTabLow(pc),a0                ; 0AE04
l_0AE08:
        move.b  (a0,d0.w),d0                    ; 0AE08
        movem.l (a7)+,d1-d3/a0                  ; 0AE0C
        rts                                     ; 0AE10

;---------------------------------------------------------------------------
; DirectionToArthur results (0 right, 4 down, 8 left, 12 up) by quadrant: Arthur
; right-above, left-above, right-below, left-below. One table per slope band |dy|/|dx|:
; the slope is taken as the integer quotient q = |dy| div |dx|: Steep q >= 6, 60 2 <= q < 6,
; 45 q = 1, and for q = 0 Low when |dy| >= |dx| / 4, else Flat (checked in the emulator).
; The code's x100 thresholds (75, 150, 600) only see whole quotients, so the 1.5 step never
; happens.
;---------------------------------------------------------------------------
DirTabLow:
	dc.b	$0F,$09,$01,$07
DirTabFlat:
	dc.b	$00,$08,$00,$08
DirTab60:
	dc.b	$0D,$0B,$03,$05
DirTabSteep:
	dc.b	$0C,$0C,$04,$04

;---------------------------------------------------------------------------
; 45-degree band: the last entry is 5 where 6 is expected (the data bug)
;---------------------------------------------------------------------------
DirTab45:
	dc.b	$0E,$0A,$02,$05

;---------------------------------------------------------------------------
; Out: d0.b = pseudo-random byte (shift register in g_RandSeed)
;---------------------------------------------------------------------------
Random:
        move.w  d1,-(a7)                        ; 0AE26
        move.b  g_RandSeed+1(a6),d0             ; 0AE28
        move.b  g_RandSeed(a6),d1               ; 0AE2C
        eor.b   d1,d0                           ; 0AE30
        not.b   d0                              ; 0AE32
        lsl.b   #$2,d0                          ; 0AE34
        rol.w   g_RandSeed(a6)                  ; 0AE36
        move.w  (a7)+,d1                        ; 0AE3A
        move.b  g_RandSeed+1(a6),d0             ; 0AE3C
        rts                                     ; 0AE40

;---------------------------------------------------------------------------
