;---------------------------------------------------------------------------
; PrintChar - draw character d0 at byte column d1, line d2 (line < 32: the HUD
; area, CLEAR_AREA; otherwise the playfield, allowing for the fine scroll).
; The font (MASK_BUF, 16 bytes a character) has two bit-planes, 8 lines of 2 bytes, so
; 4 colours: first plane only = g_TextShadow, second only = g_TextInk, both =
; g_TextPaper, neither = transparent on the playfield (the background shows) or colour 0
; in the HUD. Each of the 5 screen planes is worked out bit by bit from the three
; colour numbers (fully unrolled).
;---------------------------------------------------------------------------
PrintChar:
        movem.l a0-a5,-(a7)                     ; 0B0B0
        lea.l   (MASK_BUF).l,a0                 ; 0B0B4
        andi.w  #$ff,d0                         ; 0B0BA
        lsl.w   #$4,d0                          ; 0B0BE
        adda.w  d0,a0                           ; 0B0C0
        movem.l d1-d7,-(a7)                     ; 0B0C2
        cmp.w   #$20,d2                         ; 0B0C6
        scc.b   d7                              ; 0B0CA
        bcc.b   l_0B0D6                         ; 0B0CC
        lea.l   (CLEAR_AREA).l,a1               ; 0B0CE
        bra.b   l_0B0E2                         ; 0B0D4
l_0B0D6:
        movea.l g_ScreenFront(a6),a1            ; 0B0D6
        moveq   #-16,d0                         ; 0B0DA
        add.w   g_ScrollFineY(a6),d0            ; 0B0DC
        add.w   d0,d2                           ; 0B0E0
l_0B0E2:
        move.w  d2,d0                           ; 0B0E2
        mulu.w  #$b4,d0                         ; 0B0E4
        add.l   d1,d0                           ; 0B0E8
        addq.l  #$2,d0                          ; 0B0EA
        adda.l  d0,a1                           ; 0B0EC
        lea.l   $24(a1),a2                      ; 0B0EE
        lea.l   $24(a2),a3                      ; 0B0F2
        lea.l   $24(a3),a4                      ; 0B0F6
        lea.l   $24(a4),a5                      ; 0B0FA
