;---------------------------------------------------------------------------
; NameGridLetters - the 65 cells of the name-entry grid: A-Z, a-z, ! ? & , . ( ) / : * @,
; then the rub-out ($1E) and END ($1F) glyphs. Cell 62 ('@') enters a space.
;---------------------------------------------------------------------------
NameGridLetters:
	dc.b	'ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz!?&,.()/:*@'
	dc.b	$1E,$1F
TxtInitial:
	dc.b	'INITIAL'
	dc.b	$00,$00

;---------------------------------------------------------------------------
; RestoreBackground - undo last time's BOBs in this buffer: copy each saved rectangle
; back (A->D blits) from the restore list, then reset the list
;---------------------------------------------------------------------------
RestoreBackground:
        movea.l g_RestoreListA(a6),a5           ; 0B9EC
        tst.w   (a5)                            ; 0B9F0
        beq.b   l_0BA3C                         ; 0B9F2
        lea.l   CUSTOM,a2                       ; 0B9F4
l_0B9FA:
        btst    #$6,DMACONR(a2)                 ; 0B9FA  A->D copy, no masking
        bne.b   l_0B9FA                         ; 0BA00
        move.l  #$9f00000,BLTCON0(a2)           ; 0BA02
        moveq   #-1,d0                          ; 0BA0A
        move.l  d0,BLTAFWM(a2)                  ; 0BA0C
        moveq   #$0,d0                          ; 0BA10
l_0BA12:
        move.w  (a5)+,d4                        ; 0BA12  entry: BLTSIZE (0 = end), modulo, screen address, save address
        beq.b   l_0BA36                         ; 0BA14
        move.w  (a5)+,d0                        ; 0BA16
        movea.l (a5)+,a0                        ; 0BA18
        movea.l (a5)+,a1                        ; 0BA1A
l_0BA1C:
        btst    #$6,DMACONR(a2)                 ; 0BA1C
        bne.b   l_0BA1C                         ; 0BA22
        move.l  d0,BLTAMOD(a2)                  ; 0BA24
        move.l  a1,BLTAPTH(a2)                  ; 0BA28
        move.l  a0,BLTDPTH(a2)                  ; 0BA2C
        move.w  d4,BLTSIZE(a2)                  ; 0BA30
        bra.b   l_0BA12                         ; 0BA34
l_0BA36:
        subq.l  #$2,a5                          ; 0BA36
        move.l  a5,g_RestoreListA(a6)           ; 0BA38
l_0BA3C:
        rts                                     ; 0BA3C

;---------------------------------------------------------------------------
; DrawBobs - draw this frame's BOB list. The Queue*Draw routines push 12-byte entries
; (x.w, y.w, width.w, height.w, graphics.l) downwards from g_SaveBufA's address in the
; globals; this walks them from g_BlitListPtr back up, so the last queued is drawn first
; and the first queued ends up on top. g_SavePtr restarts at g_SaveBufA.
;---------------------------------------------------------------------------
DrawBobs:
        move.l  g_SaveBufA(a6),g_SavePtr(a6)    ; 0BA3E  rewind the save area
        movea.l g_BlitListPtr(a6),a3            ; 0BA44  walk the draw list up to its top
        lea.l   g_SaveBufA(a6),a5               ; 0BA48
l_0BA4C:
        cmpa.l  a5,a3                           ; 0BA4C
        beq.b   l_0BA5A                         ; 0BA4E
        movem.w (a3)+,d1-d4                     ; 0BA50
        movea.l (a3)+,a1                        ; 0BA54
        bsr.b   DrawBob                         ; 0BA56
        bra.b   l_0BA4C                         ; 0BA58
l_0BA5A:
        rts                                     ; 0BA5A

;---------------------------------------------------------------------------
; DrawBob - masked blit of one BOB into the back buffer.
; In: a1 = frame graphics, d1,d2 = level x,y (y up), d3 = width, d4 = height.
; The screen buffer is 288 x 256 (18 x 16 tiles) plus a 16-px margin on the left,
; line-interleaved: each 180-byte line holds the 5 planes of 36 bytes. Y is measured up
; from the bottom of the buffer.
;  - clip left, right (288 px) and top/bottom (256 lines), adjusting the graphics
;    pointer and the first/last-word masks
;  - if the background save area would pass $3000 bytes this frame, the BOB is
;    not drawn at all (so a very busy screen loses BOBs rather than corrupting)
;  - save the background under it (A->D) and add a restore-list entry
;  - mask = OR of the 5 planes (colour 0 transparent), built in two blits at $371E8
;    (A|B|C, then mask|B|C), minterm $FE
;  - 5 cookie-cut blits (minterm $CA: D = A ? B : C) with the X shift in BLTCON0/1.
;  BUG: a BOB clipped at the top of the buffer skips twice the graphics lines it should
;  ($BAF4: the line count is multiplied by twice the words per line, then by 10), so the
;  part still on screen is drawn from the wrong lines of the image (or the next frame's
;  data). The same code is right in the 1MB build, whose masked graphics have twice the
;  bytes a line; the 512K build kept it. DrawSceneryOnRedraw has it too ($C2EA).
;---------------------------------------------------------------------------
DrawBob:
        move.w  g_ScrollTileX(a6),d0            ; 0BA5C  level -> buffer coordinates (16-px left margin)
        lsl.w   #$4,d0                          ; 0BA60
        sub.w   d0,d1                           ; 0BA62
        addi.w  #$10,d1                         ; 0BA64
        move.w  g_ScrollTileY(a6),d0            ; 0BA68
        lsl.w   #$4,d0                          ; 0BA6C
        sub.w   d0,d2                           ; 0BA6E
        moveq   #$f,d7                          ; 0BA70  d6 = width in words; d0 = words touched at this X
        add.w   d3,d7                           ; 0BA72
        lsr.w   #$4,d7                          ; 0BA74
        move.l  d7,d6                           ; 0BA76
        moveq   #$f,d0                          ; 0BA78
