RedrawScreen:
        movea.l g_ScreenSpare1(a6),a1           ; 0BFDE
        adda.l  #$a8c0,a1                       ; 0BFE2  start at the bottom row: 240 lines down
        lea.l   CUSTOM+INTENA,a2                ; 0BFE8
        movea.l g_MapPtr(a6),a3                 ; 0BFEE
        lea.l   CellTiles(pc),a4                ; 0BFF2
        movea.l g_LevelFileAddr(a6),a5          ; 0BFF6
        move.w  g_NewTileX(a6),d1               ; 0BFFA
        move.w  g_NewTileY(a6),d2               ; 0BFFE
        cmpi.w  #$1,g_Level(a6)                 ; 0C002  level 1: second tile bank for some cells
        seq.b   d5                              ; 0C008
        moveq   #$f,d7                          ; 0C00A  16 rows
l_0C00C:
        moveq   #$11,d6                         ; 0C00C  18 columns
l_0C00E:
        moveq   #$10,d0                         ; 0C00E  map cell of this tile; d4 / d3 = column / row within the cell
        sub.w   d6,d0                           ; 0C010
        add.w   d1,d0                           ; 0C012
        moveq   #$f,d4                          ; 0C014
        and.w   d0,d4                           ; 0C016
        asr.w   #$4,d0                          ; 0C018
        lea.l   (a3,d0.w),a0                    ; 0C01A
        move.w  d7,d0                           ; 0C01E
        sub.w   d2,d0                           ; 0C020
        moveq   #$f,d3                          ; 0C022
        and.w   d0,d3                           ; 0C024
        andi.w  #$fff0,d0                       ; 0C026
        add.w   d0,d0                           ; 0C02A
        suba.w  d0,a0                           ; 0C02C

;---------------------------------------------------------------------------
; cell $67 -> a0 = LEVEL_FILE (tile 0); otherwise look up the tile number.
; Note: tile 0 is still blitted - it is the first tile of the level file.
;---------------------------------------------------------------------------
