        add.w   d3,d0                           ; 0C03C
        lsl.w   #$4,d0                          ; 0C03E
        add.w   d4,d0                           ; 0C040
        move.b  (a4,d0.w),d3                    ; 0C042
        beq.b   l_0C06C                         ; 0C046
        tst.b   d5                              ; 0C048
        beq.b   l_0C068                         ; 0C04A
        move.b  (a0),d0                         ; 0C04C
        cmp.b   #$1f,d0                         ; 0C04E
        beq.b   l_0C064                         ; 0C052
        cmp.b   #$1d,d0                         ; 0C054
        bne.b   l_0C068                         ; 0C058
        cmp.b   #$9,d3                          ; 0C05A
        bhi.b   l_0C068                         ; 0C05E
        bcs.b   l_0C064                         ; 0C060
        clr.b   d3                              ; 0C062
l_0C064:
        addi.w  #$100,d3                        ; 0C064
l_0C068:
        mulu.w  #$a0,d3                         ; 0C068  160 bytes a tile
l_0C06C:
