        movem.l (a4)+,d0-d7/a0-a3               ; 0C0E8
        movem.l d0-d7/a0-a3,(a5)                ; 0C0EC
        lea.l   $30(a5),a5                      ; 0C0F0
        movem.l (a4)+,d0-d7/a0-a3               ; 0C0F4
        movem.l d0-d7/a0-a3,(a5)                ; 0C0F8
