        lea.l   $30(a5),a5                      ; 0C120
        movem.l (a4)+,d0-d7/a0-a3               ; 0C124
        movem.l d0-d7/a0-a3,(a5)                ; 0C128
        lea.l   $30(a5),a5                      ; 0C12C
