;---------------------------------------------------------------------------
; ==================================================================
; LoadFile - the game's copy of the bootblock trackloader
; In: a1 -> file record: dest.L, length.L, start_track.W
; Out: a5 = end of loaded data
; Track format: one block per track after DSKSYNC $A245 (set by the
; boot loader), track-number word, $62A longs of odd/even MFM data and
; a checksum long = NOT(sum). Reads $1900 words into $33FE8 by DMA.
; Up to 8 retries per track; a bad track number re-seeks via track 0.
; ==================================================================
;---------------------------------------------------------------------------
LoadFile:
        movea.l (a1)+,a5                        ; 0C476  a5 = destination
        move.l  (a1)+,d5                        ; 0C478  d5 = length in bytes
        move.w  (a1)+,(LDR_TRACK).w             ; 0C47A  start track
        lea.l   CUSTOM,a0                       ; 0C47E
        lea.l   $bfe001.l,a1                    ; 0C484
        lea.l   CIAB_PRB,a2                     ; 0C48A
        st.b    (a2)                            ; 0C490  select DF0, motor on
        bclr    #$7,(a2)                        ; 0C492
        bclr    #$3,(a2)                        ; 0C496
        move.l  d5,d7                           ; 0C49A  tracks = (length + $18A7) / $18A8 (6312 bytes per track)
        addi.l  #$18a7,d7                       ; 0C49C
        divu.w  #$18a8,d7                       ; 0C4A2
        subq.w  #$1,d7                          ; 0C4A6
l_0C4A8:
        move.w  #$8,(LDR_RETRY).w               ; 0C4A8  8 attempts per track
        bsr.w   SeekTrack                       ; 0C4AE  seek to LDR_TRACK
l_0C4B2:
        bsr.w   ReadTrackDMA                    ; 0C4B2  DMA one track
        bsr.w   DecodeTrack                     ; 0C4B6  decode and checksum
        cmp.l   d4,d1                           ; 0C4BA  checksum ok?
        beq.b   l_0C4CC                         ; 0C4BC
        subq.w  #$1,(LDR_RETRY).w               ; 0C4BE
        beq.b   l_0C4E6                         ; 0C4C2
        addi.l  #$18a8,d5                       ; 0C4C4
        bra.b   l_0C4B2                         ; 0C4CA
l_0C4CC:
        cmp.w   (LDR_TRACK).w,d2                ; 0C4CC  right track number?
        bne.b   l_0C4F2                         ; 0C4D0
        addq.w  #$1,(LDR_TRACK).w               ; 0C4D2
        movea.l a4,a5                           ; 0C4D6
        dbra    d7,l_0C4A8                      ; 0C4D8
        st.b    (a2)                            ; 0C4DC  deselect, motor off
        bclr    #$3,(a2)                        ; 0C4DE
        st.b    (a2)                            ; 0C4E2
        rts                                     ; 0C4E4
l_0C4E6:
        bsr.w   SeekTrack0                      ; 0C4E6  too many errors: recalibrate to track 0
        addi.l  #$18a8,d5                       ; 0C4EA
        bra.b   l_0C4A8                         ; 0C4F0
l_0C4F2:
        bsr.w   SeekTrack0                      ; 0C4F2
        addi.l  #$18a8,d5                       ; 0C4F6
        bra.b   l_0C4A8                         ; 0C4FC

;---------------------------------------------------------------------------
; Pulse the step line, wait 3ms (17ms on direction change) on CIA-B TOD
;---------------------------------------------------------------------------
StepHead:
        btst    #$1,(a2)                        ; 0C4FE
        seq.b   d0                              ; 0C502
        cmp.b   (LDR_DIRFLAG).w,d0              ; 0C504
        beq.b   l_0C516                         ; 0C508
        move.l  #$11d,d1                        ; 0C50A
        not.b   (LDR_DIRFLAG).w                 ; 0C510
        bra.b   l_0C518                         ; 0C514
l_0C516:
