        move.b  $900(a2),d0                     ; 0C51A
        lsl.w   #$8,d0                          ; 0C51E
        move.b  $800(a2),d0                     ; 0C520
        lsl.l   #$8,d0                          ; 0C524
        move.b  $700(a2),d0                     ; 0C526
        cmp.l   d1,d0                           ; 0C52A
        bls.b   l_0C518                         ; 0C52C
        bclr    #$0,(a2)                        ; 0C52E
        bset    #$0,(a2)                        ; 0C532
        clr.b   $900(a2)                        ; 0C536
