        clr.b   $700(a2)                        ; 0C53E
        rts                                     ; 0C542
WaitDiskReady:
        btst    #$5,(a1)                        ; 0C544
        bne.b   WaitDiskReady                   ; 0C548
        rts                                     ; 0C54A

;---------------------------------------------------------------------------
; DSKPT = $33FE8, DSKLEN $9900 written twice, wait for DSKBLK
