        move.l  #$33fe8,$20(a0)                 ; 0C54E  DSKPT = MFM buffer
        move.w  #$9900,$24(a0)                  ; 0C556  DSKLEN written twice to start DMA ($1900 words)
        move.w  #$9900,$24(a0)                  ; 0C55C
l_0C562:
        move.w  $1e(a0),d0                      ; 0C562  wait DSKBLK
        andi.w  #$2,d0                          ; 0C566
        beq.b   l_0C562                         ; 0C56A
        move.w  d0,$9c(a0)                      ; 0C56C
        clr.w   d0                              ; 0C570
        move.w  d0,$24(a0)                      ; 0C572
        rts                                     ; 0C576

