;---------------------------------------------------------------------------
; MFM decode into a5 (handles a partial last long); out d1 = stored checksum, d4 = computed, d2 = track number
;---------------------------------------------------------------------------
DecodeTrack:
        lea.l   $33fea.l,a3                     ; 0C580
        movea.l a5,a4                           ; 0C586
        move.l  #$55555555,d3                   ; 0C588
        move.w  (a3)+,d2                        ; 0C58E
        move.w  (a3)+,d1                        ; 0C590
        and.w   d3,d2                           ; 0C592
        and.w   d3,d1                           ; 0C594
        add.w   d2,d2                           ; 0C596
        or.w    d2,d1                           ; 0C598
        move.w  d1,-(a7)                        ; 0C59A
        moveq   #-1,d4                          ; 0C59C  checksum accumulator = -1, minus each long = NOT(sum)
        move.w  #$629,d6                        ; 0C59E
l_0C5A2:
        move.l  d3,d1                           ; 0C5A2
        and.l   $18ac(a3),d1                    ; 0C5A4  even bits from second half ($18AC bytes on)
        move.l  d3,d2                           ; 0C5A8
        and.l   (a3)+,d2                        ; 0C5AA  odd bits from first half
        add.l   d2,d2                           ; 0C5AC
        or.l    d2,d1                           ; 0C5AE
        sub.l   d1,d4                           ; 0C5B0
        subq.l  #$4,d5                          ; 0C5B2  stop at the exact file length (last long may be partial)
        bmi.b   l_0C5CE                         ; 0C5B4
        move.l  d1,(a4)+                        ; 0C5B6
l_0C5B8:
        dbra    d6,l_0C5A2                      ; 0C5B8
        move.l  $18ac(a3),d1                    ; 0C5BC
        and.l   d3,d1                           ; 0C5C0
        move.l  (a3)+,d2                        ; 0C5C2
        and.l   d3,d2                           ; 0C5C4
        add.l   d2,d2                           ; 0C5C6
        or.l    d2,d1                           ; 0C5C8
        move.w  (a7)+,d2                        ; 0C5CA
        rts                                     ; 0C5CC
l_0C5CE:
        cmp.l   #$fffffffd,d5                   ; 0C5CE
        blt.b   l_0C5B8                         ; 0C5D4
        beq.b   l_0C5EC                         ; 0C5D6
        cmp.l   #$fffffffe,d5                   ; 0C5D8
        beq.b   l_0C5E6                         ; 0C5DE
        ror.l   #$8,d1                          ; 0C5E0
