        move.b  #$2,(a5)                        ; 0C694
        clr.b   Pig_Drop(a5)                    ; 0C698
        clr.b   Pig_Unused31(a5)                ; 0C69C
        clr.b   Pig_Unused32(a5)                ; 0C6A0
