        move.b  d0,Pig_Loops(a5)                ; 0C6BE
        move.b  #$2,O_Size(a5)                  ; 0C6C2
        move.b  #$1,O_Dir(a5)                   ; 0C6C8
        move.w  O_X(a5),d0                      ; 0C6CE
        cmp.w   g_ArthurX(a6),d0                ; 0C6D2
        blt.b   l_0C6DE                         ; 0C6D6
        move.b  #$9,O_Dir(a5)                   ; 0C6D8
l_0C6DE:
        clr.l   O_Anim(a5)                      ; 0C6DE
        lea.l   WoodyPigMoveTable(pc),a0        ; 0C6E2
        move.w  g_GameFrame(a6),d0              ; 0C6E6
        add.w   d7,d0                           ; 0C6EA
        andi.w  #$3,d0                          ; 0C6EC
