;---------------------------------------------------------------------------
; State 0: graphics, size class and move table for the parameter
;---------------------------------------------------------------------------
Crow_Init:
        lea.l   CrowWaits(pc),a0                ; 0CBF0
        move.l  a0,Crw_WaitList(a5)             ; 0CBF4
        move.w  O_Y(a5),Crw_BaseY(a5)           ; 0CBF8
        move.b  #$10,Crw_Amp(a5)                ; 0CBFE
        clr.w   Crw_Phase(a5)                   ; 0CC04
        clr.b   Crw_Crow(a5)                    ; 0CC08
        clr.b   Crw_Look(a5)                    ; 0CC0C
        clr.b   Crw_Speed(a5)                   ; 0CC10
        move.w  O_X(a5),d0                      ; 0CC14
        cmp.w   g_ArthurX(a6),d0                ; 0CC18
        slt.b   O_Dir(a5)                       ; 0CC1C
        neg.b   O_Dir(a5)                       ; 0CC20
        move.b  #$2,O_Size(a5)                  ; 0CC24
        lea.l   Bat_AnimFly(pc),a0              ; 0CC2A
        cmpi.b  #$3,O_Param(a5)                 ; 0CC2E  param 3+: crow
        bcs.b   l_0CC56                         ; 0CC34
        clr.b   O_Size(a5)                      ; 0CC36
        move.b  #$1,Crw_Crow(a5)                ; 0CC3A
        lea.l   Crow_AnimFly(pc),a0             ; 0CC40
        cmpi.b  #$4,O_Param(a5)                 ; 0CC44  param 4: 16 px higher
        bne.b   l_0CC56                         ; 0CC4A
        addi.w  #$10,Crw_BaseY(a5)              ; 0CC4C
        lea.l   Crow_AnimFlyHigh(pc),a0         ; 0CC52
l_0CC56:
        bsr.w   SetAnimIndexed                  ; 0CC56  start animation for current direction
