;---------------------------------------------------------------------------
; === Petite Devil (type 2, 100 pts) ===
; Small flying devil: homes on Arthur (DirectionToArthur), random changes of direction, fires projectiles.
; Dispatches on O_State: 0 main behaviour, 1 type-specific second phase, 2 killed (set by EnemyHitByShot after scoring), 3 remove.
;
; Behaviour, as coded: flies in for 80-111 frames (shots pass through for the first 32),
; then hunts Arthur in up to 4 legs of 48-111 frames: at the start of each leg it picks a
; direction towards him and a turn rate from the vertical distance, then turns 1/16 at a time
; towards it. It fires one shot only (enemy shot type 8): sideways at Arthur when level with
; him (within 16 px up, 50 px across), or straight down when directly above (5 px across,
; 60 px above), and then recoils in a turning sweep. After its legs it leaves. It never flies
; below Y = 54 (world).
; Bug (checked in the emulator, tools/verify): the turning code (PetiteDevil_TurnCW/CCW)
; works out the new direction in d0 and then stores #1 instead, so once a devil starts
; turning it flies in direction 1 - right and a little down - whatever it was turning to.
;---------------------------------------------------------------------------
Enemy_PetiteDevil:
        move.b  O_State(a5),d0                  ; 0D160
        add.w   d0,d0                           ; 0D164
        add.w   d0,d0                           ; 0D166
        jmp     Enemy_PetiteDevil_Jumps(pc,d0.w)             ; 0D168
Enemy_PetiteDevil_Jumps:
        bra.w   PetiteDevil_Init                ; 0D16C
        bra.w   PetiteDevil_Active              ; 0D170
        bra.w   PetiteDevil_Dying               ; 0D174
        bra.w   PetiteDevil_Free                ; 0D178

;---------------------------------------------------------------------------
; State 0, by O_Param: 0 fly in, 1 fly in (finer turns), 2 random timers
;---------------------------------------------------------------------------
PetiteDevil_Init:
        move.b  O_Param(a5),d0                  ; 0D17C
        add.w   d0,d0                           ; 0D180
        add.w   d0,d0                           ; 0D182
        jmp     PetiteDevil_Init_Jumps(pc,d0.w) ; 0D184
PetiteDevil_Init_Jumps:
        bra.w   PetiteDevil_Init0               ; 0D188
        bra.w   PetiteDevil_Init1               ; 0D18C
        bra.w   PetiteDevil_Init2               ; 0D190
PetiteDevil_Init0:
        tst.b   O_Step(a5)                      ; 0D194
        beq.b   l_0D210                         ; 0D198
        bsr.w   CheckOnScreen                   ; 0D19A  visible?
        move.b  (a5),d0                         ; 0D19E
        add.b   d0,(a5)                         ; 0D1A0
        bsr.b   PetiteDevil_Setup               ; 0D1A2
        lea.l   PetiteDevil_AnimStartA(pc),a0   ; 0D1A4
        clr.b   O_Dir(a5)                       ; 0D1A8
        move.w  O_X(a5),d0                      ; 0D1AC
        cmp.w   g_ArthurX(a6),d0                ; 0D1B0
        ble.b   l_0D1C0                         ; 0D1B4
        move.b  #$1,O_Dir(a5)                   ; 0D1B6
        lea.l   PetiteDevil_AnimStartB(pc),a0   ; 0D1BC
l_0D1C0:
        bsr.w   SetAnim                         ; 0D1C0  start animation
        clr.b   O_Size(a5)                      ; 0D1C4
        lea.l   PetiteDevilMove16(pc),a0        ; 0D1C8
        move.l  a0,PD_MoveTable(a5)             ; 0D1CC
        clr.b   PD_Fine(a5)                     ; 0D1D0
        move.b  #$1,PD_Shot(a5)                 ; 0D1D4
        rts                                     ; 0D1DA

;---------------------------------------------------------------------------
; Size 0, move table, 4 legs, aim at Arthur's height, go to state 1
;---------------------------------------------------------------------------
PetiteDevil_Setup:
        clr.b   O_Size(a5)                      ; 0D1DC
        lea.l   PetiteDevilMoveTable(pc),a0     ; 0D1E0
        move.l  a0,O_MoveTable(a5)              ; 0D1E4
        move.b  #$4,PD_Legs(a5)                 ; 0D1E8
        move.b  #$2,PD_Turn(a5)                 ; 0D1EE
        move.w  g_ArthurY(a6),PD_TargetY(a5)    ; 0D1F4
        move.b  #$1,PD_EarlyShot(a5)            ; 0D1FA
        move.b  #ST_ACTIVE,O_State(a5)          ; 0D200
        clr.b   O_Step(a5)                      ; 0D206
        clr.b   O_Step2(a5)                     ; 0D20A
        rts                                     ; 0D20E
l_0D210:
        addq.b  #$1,O_Step(a5)                  ; 0D210  next step
        rts                                     ; 0D214

;---------------------------------------------------------------------------
; Unused: follow a list of map positions (PetiteDevilPath) and appear at the first
; one that is on screen
;---------------------------------------------------------------------------
PetiteDevil_PathUnused:	; (no references found - unused/debug code)
        tst.b   O_Step2(a5)                     ; 0D216
        bne.b   l_0D266                         ; 0D21A
        clr.l   O_Anim(a5)                      ; 0D21C
        clr.w   O_X(a5)                         ; 0D220
        clr.w   O_Y(a5)                         ; 0D224
        moveq   #$1,d0                          ; 0D228
        and.w   g_GameFrame(a6),d0              ; 0D22A
        move.b  d0,PD_Time(a5)                  ; 0D22E
        lea.l   PetiteDevilPath(pc),a0          ; 0D232
        bsr.b   PetiteDevil_PathNext            ; 0D236
        move.b  #$9,PD_TurnRate(a5)             ; 0D238
        addq.b  #$1,O_Step2(a5)                 ; 0D23E
        rts                                     ; 0D242
PetiteDevil_PathNext:
        move.w  (a0)+,d0                        ; 0D244  path list entry: offset to a segment set, then its turn count
        move.l  a0,PD_PathPos(a5)               ; 0D246
        adda.w  d0,a0                           ; 0D24A
        move.w  (a0)+,d0                        ; 0D24C
        move.b  d0,PD_TurnWait(a5)              ; 0D24E
        move.b  PD_Time(a5),d0                  ; 0D252  PD_Time 0 picks the alternative set (one entry back)
        bne.b   l_0D260                         ; 0D256
        subq.b  #$1,d0                          ; 0D258
        lsl.b   #$2,d0                          ; 0D25A
        ext.w   d0                              ; 0D25C
        adda.w  d0,a0                           ; 0D25E
l_0D260:
        move.l  a0,PD_PathSeg(a5)               ; 0D260
        rts                                     ; 0D264
l_0D266:
        movea.l PD_PathSeg(a5),a0               ; 0D266  is the segment start on screen (camera X .. +256, Y + 32 .. + 224)?
        move.w  g_CameraX(a6),d0                ; 0D26A
        cmp.w   (a0),d0                         ; 0D26E
        bhi.b   l_0D2A8                         ; 0D270
        addi.w  #$100,d0                        ; 0D272
        cmp.w   (a0),d0                         ; 0D276
        bcs.b   l_0D2A8                         ; 0D278
        move.w  g_CameraY(a6),d0                ; 0D27A
        addi.w  #$20,d0                         ; 0D27E
        cmp.w   $2(a0),d0                       ; 0D282
        bhi.b   l_0D2A8                         ; 0D286
        addi.w  #$c0,d0                         ; 0D288
        cmp.w   $2(a0),d0                       ; 0D28C
        bcs.b   l_0D2A8                         ; 0D290
        nop                                     ; 0D292
        move.w  (a0)+,O_X(a5)                   ; 0D294  yes: appear there
        move.w  (a0)+,O_Y(a5)                   ; 0D298
        move.b  #$1,O_Step(a5)                  ; 0D29C
        clr.b   O_Step2(a5)                     ; 0D2A2
        rts                                     ; 0D2A6
l_0D2A8:
        subq.l  #$4,a0                          ; 0D2A8  no: try the next segment (or the alternative)
        tst.b   PD_Time(a5)                     ; 0D2AA
        bne.b   l_0D2B2                         ; 0D2AE
        addq.l  #$8,a0                          ; 0D2B0
l_0D2B2:
        move.l  a0,PD_PathSeg(a5)               ; 0D2B2
        subq.b  #$1,PD_TurnWait(a5)             ; 0D2B6  after PD_TurnWait tries take the next entry; when PD_TurnRate runs out, give up
        bne.b   l_0D2CE                         ; 0D2BA
        movea.l PD_PathPos(a5),a0               ; 0D2BC
        bsr.b   PetiteDevil_PathNext            ; 0D2C0
        subq.b  #$1,PD_TurnRate(a5)             ; 0D2C2
        bne.b   l_0D2CE                         ; 0D2C6
        move.b  #ST_REMOVE,O_State(a5)          ; 0D2C8
l_0D2CE:
        rts                                     ; 0D2CE

;---------------------------------------------------------------------------
; PetiteDevilPath (unused) - nine word offsets, each from its entry to a list: count, then
; that many (x, y) world positions where the devil may appear.
; BUG (in the unused PetiteDevil_PathUnused): PetiteDevil_PathNext adds the offset after
; stepping past it, so it lands 2 bytes on: the first X is taken as the count and the segment
; pointer starts at a Y. The lists only work when read from the entry itself.
;---------------------------------------------------------------------------
PetiteDevilPath:
	dc.w	PetiteDevilPath_0-*	; 0
	dc.w	PetiteDevilPath_1-*	; 1
	dc.w	PetiteDevilPath_2-*	; 2
	dc.w	PetiteDevilPath_3-*	; 3
	dc.w	PetiteDevilPath_4-*	; 4
	dc.w	PetiteDevilPath_5-*	; 5
	dc.w	PetiteDevilPath_6-*	; 6
	dc.w	PetiteDevilPath_7-*	; 7
	dc.w	PetiteDevilPath_8-*	; 8
PetiteDevilPath_8:
	dc.w	2		; points
	dc.w	$0E48,$0098	; world x, y
	dc.w	$0E48,$00F4	; world x, y
PetiteDevilPath_7:
	dc.w	1		; points
	dc.w	$0E98,$0064	; world x, y
PetiteDevilPath_6:
	dc.w	4		; points
	dc.w	$0EF8,$0088	; world x, y
	dc.w	$0EF8,$00E8	; world x, y
	dc.w	$0EF8,$0148	; world x, y
	dc.w	$0EF8,$0188	; world x, y
PetiteDevilPath_5:
	dc.w	2		; points
	dc.w	$0F48,$0194	; world x, y
	dc.w	$0F48,$01C4	; world x, y
PetiteDevilPath_4:
	dc.w	4		; points
	dc.w	$0F78,$0054	; world x, y
	dc.w	$0F78,$0074	; world x, y
	dc.w	$0F78,$0118	; world x, y
	dc.w	$0F78,$0154	; world x, y
PetiteDevilPath_3:
	dc.w	3		; points
	dc.w	$0FD8,$00F4	; world x, y
	dc.w	$0FD8,$0148	; world x, y
	dc.w	$0FD8,$0184	; world x, y
PetiteDevilPath_2:
	dc.w	3		; points
	dc.w	$1008,$0064	; world x, y
	dc.w	$1008,$00A8	; world x, y
	dc.w	$1018,$01A8	; world x, y
PetiteDevilPath_1:
	dc.w	4		; points
	dc.w	$1068,$0058	; world x, y
	dc.w	$1068,$00B8	; world x, y
	dc.w	$1058,$0108	; world x, y
	dc.w	$1068,$0168	; world x, y
PetiteDevilPath_0:
	dc.w	3		; points
	dc.w	$10D8,$00B4	; world x, y
	dc.w	$10D8,$00F4	; world x, y
	dc.w	$10D8,$0168	; world x, y
PetiteDevil_Init1:
        bsr.w   PetiteDevil_Setup               ; 0D35C
        move.b  #$2,O_Dir(a5)                   ; 0D360
        lea.l   PetiteDevil_AnimFly(pc),a0      ; 0D366
        bsr.w   SetAnim                         ; 0D36A  start animation
        lea.l   PetiteDevilMove16Fast(pc),a0    ; 0D36E
        move.l  a0,PD_MoveTable(a5)             ; 0D372
        move.b  #$1,PD_Fine(a5)                 ; 0D376
        move.b  #$1,PD_Shot(a5)                 ; 0D37C
        rts                                     ; 0D382

;---------------------------------------------------------------------------
; Random early-shot flag and 64-95 frames before it may fire
;---------------------------------------------------------------------------
PetiteDevil_Init2:
        bsr.w   PetiteDevil_Setup               ; 0D384
        move.b  (a5),d0                         ; 0D388
        add.b   d0,(a5)                         ; 0D38A
        lea.l   PetiteDevil_AnimA(pc),a0        ; 0D38C
        clr.b   O_Dir(a5)                       ; 0D390
        move.w  O_X(a5),d0                      ; 0D394
        cmp.w   g_ArthurX(a6),d0                ; 0D398
        ble.b   l_0D3A8                         ; 0D39C
        move.b  #$1,O_Dir(a5)                   ; 0D39E
        lea.l   PetiteDevil_AnimB(pc),a0        ; 0D3A4
l_0D3A8:
        move.l  a0,O_Anim(a5)                   ; 0D3A8
        clr.b   O_Size(a5)                      ; 0D3AC
        lea.l   PetiteDevilMove16(pc),a0        ; 0D3B0
        move.l  a0,PD_MoveTable(a5)             ; 0D3B4
        clr.b   PD_Fine(a5)                     ; 0D3B8
        bsr.w   Random                          ; 0D3BC  random number
        andi.w  #$f,d0                          ; 0D3C0
        move.b  PetiteDevilArriveShot(pc,d0.w),PD_EarlyShot(a5); 0D3C4
        bsr.w   Random                          ; 0D3CA  random number
        andi.b  #$1f,d0                         ; 0D3CE
        addi.b  #$40,d0                         ; 0D3D2
        move.b  d0,PD_ShotTime(a5)              ; 0D3D6
        clr.b   PD_Ready(a5)                    ; 0D3DA
        clr.b   PD_Shot(a5)                     ; 0D3DE
        rts                                     ; 0D3E2
PetiteDevilArriveShot:
	dc.b	$00,$00,$01,$00,$00,$00,$01,$00,$01,$00,$00,$01,$00,$00,$10,$00

;---------------------------------------------------------------------------
; move table after the first 32 frames
;---------------------------------------------------------------------------
PetiteDevilFlyIn:
	dc.b	$01,$65,$00,$00,$FE,$9B,$00,$00,$00,$00,$01,$65

;---------------------------------------------------------------------------
; State 1. O_Step: 0 arrive, 1 hunt, 2 recoil, 3 leave. Param 0: removed when off screen.
;---------------------------------------------------------------------------
PetiteDevil_Active:
        move.w  g_GameFrame(a6),d0              ; 0D400
        add.w   d7,d0                           ; 0D404
        andi.w  #$1f,d0                         ; 0D406
        bne.b   l_0D40E                         ; 0D40A
        moveq   #$b,d0                          ; 0D40C  d0 is overwritten at once (a sound call removed in both builds)
l_0D40E:
        move.b  O_Step(a5),d0                   ; 0D40E
        add.w   d0,d0                           ; 0D412
        add.w   d0,d0                           ; 0D414
        jsr     PetiteDevil_RemoveOffScreen_Jumps(pc,d0.w)             ; 0D416
        tst.b   O_Param(a5)                     ; 0D41A
        bne.b   l_0D42C                         ; 0D41E
PetiteDevil_RemoveOffScreen:
        tst.b   O_OnScreen(a5)                  ; 0D420
        bne.b   l_0D42C                         ; 0D424
        move.b  #ST_REMOVE,O_State(a5)          ; 0D426
l_0D42C:
        rts                                     ; 0D42C
PetiteDevil_RemoveOffScreen_Jumps:
        bra.w   PetiteDevil_Arrive              ; 0D42E
        bra.w   PetiteDevil_Hunt                ; 0D432
        bra.w   PetiteDevil_Recoil              ; 0D436
        bra.w   PetiteDevil_Leave               ; 0D43A
PetiteDevil_Arrive:
        tst.b   O_Step2(a5)                     ; 0D43E
        bne.b   l_0D45C                         ; 0D442
        bsr.w   Random                          ; 0D444  random number
        andi.b  #$1f,d0                         ; 0D448
        addi.b  #$50,d0                         ; 0D44C
        move.b  d0,PD_Time(a5)                  ; 0D450
        move.b  d0,PD_LegLen(a5)                ; 0D454
        addq.b  #$1,O_Step2(a5)                 ; 0D458
l_0D45C:
        cmpi.b  #$5,PD_Time(a5)                 ; 0D45C
        beq.b   l_0D474                         ; 0D462
        subq.b  #$1,PD_Time(a5)                 ; 0D464
        bne.b   l_0D488                         ; 0D468
        addq.b  #$1,O_Step(a5)                  ; 0D46A  next step
        clr.b   O_Step2(a5)                     ; 0D46E
        rts                                     ; 0D472
l_0D474:
        subq.b  #$1,PD_Time(a5)                 ; 0D474
        tst.b   PD_EarlyShot(a5)                ; 0D478
        bne.b   l_0D488                         ; 0D47C
        move.b  #$1,PD_Ready(a5)                ; 0D47E
        bra.w   PetiteDevil_TryShoot            ; 0D484
l_0D488:
        move.b  PD_LegLen(a5),d0                ; 0D488  after 32 frames: hittable, normal move table
        sub.b   PD_Time(a5),d0                  ; 0D48C
        cmp.b   #$20,d0                         ; 0D490
        bne.b   l_0D4A2                         ; 0D494
        move.b  #$1,(a5)                        ; 0D496
        lea.l   PetiteDevilFlyIn(pc),a0         ; 0D49A
        move.l  a0,O_MoveTable(a5)              ; 0D49E
l_0D4A2:
        bsr.w   ApplyMoveTable                  ; 0D4A2  move by the movement table
        bsr.w   Animate                         ; 0D4A6  animate
        bra.w   CheckFarAway                    ; 0D4AA

;---------------------------------------------------------------------------
; O_Step2: 0-1 a leg towards Arthur, 2-3 a further leg, then the next
;---------------------------------------------------------------------------
PetiteDevil_Hunt:
        clr.w   d0                              ; 0D4AE
        move.b  O_Step2(a5),d0                  ; 0D4B0
        add.w   d0,d0                           ; 0D4B4
        add.w   d0,d0                           ; 0D4B6
        jmp     PetiteDevil_Hunt_Jumps(pc,d0.w) ; 0D4B8
PetiteDevil_Hunt_Jumps:
        bra.w   PetiteDevil_LegStart            ; 0D4BC
        bra.w   PetiteDevil_Leg                 ; 0D4C0
        bra.w   PetiteDevil_Leg2Start           ; 0D4C4
        bra.w   PetiteDevil_Leg2                ; 0D4C8

;---------------------------------------------------------------------------
; Out of legs: leave
;---------------------------------------------------------------------------
PetiteDevil_LegStart:
        subq.b  #$1,PD_Legs(a5)                 ; 0D4CC
        beq.b   l_0D50C                         ; 0D4D0
        bsr.w   Random                          ; 0D4D2  random number
        andi.b  #$2f,d0                         ; 0D4D6
        addi.b  #$30,d0                         ; 0D4DA
        move.b  d0,PD_Time(a5)                  ; 0D4DE
        lea.l   PetiteDevilMove16Slow(pc),a0    ; 0D4E2
        move.l  a0,O_MoveTable(a5)              ; 0D4E6
        move.w  g_ArthurY(a6),PD_TargetY(a5)    ; 0D4EA
        bsr.w   PetiteDevil_Aim                 ; 0D4F0
        lea.l   PetiteDevil_AnimLegs(pc),a0     ; 0D4F4
        tst.b   PD_Shot(a5)                     ; 0D4F8
        beq.b   l_0D502                         ; 0D4FC
        lea.l   PetiteDevil_AnimFly(pc),a0      ; 0D4FE
l_0D502:
        bsr.w   SetAnim                         ; 0D502  start animation
        addq.b  #$1,O_Step2(a5)                 ; 0D506
        rts                                     ; 0D50A
l_0D50C:
        move.b  #$3,O_Step(a5)                  ; 0D50C
        clr.b   O_Step2(a5)                     ; 0D512
        rts                                     ; 0D516
PetiteDevil_Leg:
        bsr.w   PetiteDevil_TryShoot            ; 0D518
        subq.b  #$1,PD_Time(a5)                 ; 0D51C
        bne.b   l_0D52E                         ; 0D520
        move.l  PD_MoveTable(a5),O_MoveTable(a5); 0D522
        addq.b  #$1,O_Step2(a5)                 ; 0D528
        rts                                     ; 0D52C
l_0D52E:
        clr.w   d0                              ; 0D52E
        move.b  PD_Turn(a5),d0                  ; 0D530
        add.w   d0,d0                           ; 0D534
        add.w   d0,d0                           ; 0D536
        jsr     PetiteDevilTurnModes(pc,d0.w)   ; 0D538
        bra.w   PetiteDevil_Move                ; 0D53C
PetiteDevil_Leg2Start:
        bsr.w   Random                          ; 0D540  random number
        andi.b  #$1f,d0                         ; 0D544
        addi.b  #$50,d0                         ; 0D548
        move.b  d0,PD_Time(a5)                  ; 0D54C
        move.w  g_ArthurY(a6),PD_TargetY(a5)    ; 0D550
        bsr.w   PetiteDevil_Aim                 ; 0D556
        addq.b  #$1,O_Step2(a5)                 ; 0D55A
        rts                                     ; 0D55E
PetiteDevil_Leg2:
        bsr.w   PetiteDevil_TryShoot            ; 0D560
        subq.b  #$1,PD_Time(a5)                 ; 0D564
        bne.b   l_0D570                         ; 0D568
        clr.b   O_Step2(a5)                     ; 0D56A
        rts                                     ; 0D56E
l_0D570:
        clr.w   d0                              ; 0D570
        move.b  PD_Turn(a5),d0                  ; 0D572
        add.w   d0,d0                           ; 0D576
        add.w   d0,d0                           ; 0D578
        jsr     PetiteDevilTurnModes(pc,d0.w)   ; 0D57A
        bra.w   PetiteDevil_Move                ; 0D57E
PetiteDevilTurnModes:
        bra.w   PetiteDevil_TurnCW              ; 0D582
        bra.w   PetiteDevil_TurnCCW             ; 0D586
        bra.w   PetiteDevil_TurnCW              ; 0D58A
        bra.w   PetiteDevil_TurnCCW             ; 0D58E

;---------------------------------------------------------------------------
; Every PD_TurnRate frames turn one step towards PD_WantDir.
; Bug: stores #1 into O_Dir instead of the new direction in d0.
;---------------------------------------------------------------------------
PetiteDevil_TurnCW:
        subq.b  #$1,PD_TurnWait(a5)             ; 0D592
        bne.b   l_0D5B4                         ; 0D596
        move.b  O_Dir(a5),d0                    ; 0D598
        cmp.b   PD_WantDir(a5),d0               ; 0D59C
        beq.b   l_0D5B4                         ; 0D5A0
        addq.b  #$1,d0                          ; 0D5A2
        andi.b  #$f,d0                          ; 0D5A4
        move.b  #$1,O_Dir(a5)                   ; 0D5A8  BUG?: d0 (the new direction) is discarded - move.b d0,O_Dir(a5) intended?
        move.b  PD_TurnRate(a5),PD_TurnWait(a5) ; 0D5AE
l_0D5B4:
        rts                                     ; 0D5B4

;---------------------------------------------------------------------------
; As PetiteDevil_TurnCW, the other way (same bug)
;---------------------------------------------------------------------------
PetiteDevil_TurnCCW:
        subq.b  #$1,PD_TurnWait(a5)             ; 0D5B6
        bne.b   l_0D5D8                         ; 0D5BA
        move.b  O_Dir(a5),d0                    ; 0D5BC
        cmp.b   PD_WantDir(a5),d0               ; 0D5C0
        beq.b   l_0D5D8                         ; 0D5C4
        subq.b  #$1,d0                          ; 0D5C6
        andi.b  #$f,d0                          ; 0D5C8
        move.b  #$1,O_Dir(a5)                   ; 0D5CC  BUG?: as above
        move.b  PD_TurnRate(a5),PD_TurnWait(a5) ; 0D5D2
l_0D5D8:
        rts                                     ; 0D5D8

;---------------------------------------------------------------------------
; After its shot: sweep the direction round (by the shot's direction), then hunt
;---------------------------------------------------------------------------
PetiteDevil_Recoil:
        clr.w   d0                              ; 0D5DA
        move.b  O_Step2(a5),d0                  ; 0D5DC
        add.w   d0,d0                           ; 0D5E0
        add.w   d0,d0                           ; 0D5E2
        jmp     PetiteDevil_Recoil_Jumps(pc,d0.w)             ; 0D5E4
PetiteDevil_Recoil_Jumps:
        bra.w   PetiteDevil_RecoilStart         ; 0D5E8
        bra.w   PetiteDevil_RecoilDown          ; 0D5EC
        bra.w   PetiteDevil_RecoilUp            ; 0D5F0
        bra.w   PetiteDevil_RecoilBack          ; 0D5F4
PetiteDevil_RecoilStart:
        move.l  PD_MoveTable(a5),O_MoveTable(a5); 0D5F8
        move.b  #$2,PD_StepTime(a5)             ; 0D5FE
        lea.l   PetiteDevil_AnimRecoilA(pc),a0  ; 0D604
        move.b  #$f,O_Dir(a5)                   ; 0D608
        tst.b   PD_ShotDir(a5)                  ; 0D60E
        beq.b   l_0D638                         ; 0D612
        lea.l   PetiteDevil_AnimRecoilB(pc),a0  ; 0D614
        move.b  #$9,O_Dir(a5)                   ; 0D618
        cmpi.b  #$1,PD_ShotDir(a5)              ; 0D61E
        beq.b   l_0D634                         ; 0D624
        lea.l   PetiteDevil_AnimFly(pc),a0      ; 0D626
        move.b  #$c,O_Dir(a5)                   ; 0D62A
        addq.b  #$1,O_Step2(a5)                 ; 0D630
l_0D634:
        addq.b  #$1,O_Step2(a5)                 ; 0D634
l_0D638:
        addq.b  #$1,O_Step2(a5)                 ; 0D638
        bsr.w   SetAnim                         ; 0D63C  start animation
        rts                                     ; 0D640
PetiteDevil_RecoilDown:
        subq.b  #$1,PD_StepTime(a5)             ; 0D642
        bne.b   l_0D656                         ; 0D646
        move.b  #$2,PD_StepTime(a5)             ; 0D648
        cmpi.b  #$8,O_Dir(a5)                   ; 0D64E
        beq.b   l_0D65C                         ; 0D654
l_0D656:
        subq.b  #$1,O_Dir(a5)                   ; 0D656
        bra.b   PetiteDevil_Move                ; 0D65A
l_0D65C:
        move.b  #$1,O_Step(a5)                  ; 0D65C
        clr.b   O_Step2(a5)                     ; 0D662
        rts                                     ; 0D666
PetiteDevil_RecoilUp:
        subq.b  #$1,PD_StepTime(a5)             ; 0D668
