        move.b  #$1,PD_StepTime(a5)             ; 0D66E
        cmpi.b  #$f,O_Dir(a5)                   ; 0D674
        beq.b   l_0D65C                         ; 0D67A
        addq.b  #$1,O_Dir(a5)                   ; 0D67C
        bra.b   PetiteDevil_Move                ; 0D680
PetiteDevil_RecoilBack:
