        bne.b   PetiteDevil_Move                ; 0D686
        move.b  #$2,PD_StepTime(a5)             ; 0D688
        cmpi.b  #$4,O_Dir(a5)                   ; 0D68E
        beq.b   l_0D65C                         ; 0D694
        subq.b  #$8,O_Dir(a5)                   ; 0D696
        bra.b   PetiteDevil_Move                ; 0D69A

;---------------------------------------------------------------------------
; Fly off in a fixed direction
;---------------------------------------------------------------------------
PetiteDevil_Leave:
        tst.b   O_Step2(a5)                     ; 0D69C
        bne.b   PetiteDevil_Move                ; 0D6A0
        clr.w   d0                              ; 0D6A2
        move.b  PD_Turn(a5),d0                  ; 0D6A4
        move.b  PetiteDevilLeaveDirs(pc,d0.w),O_Dir(a5); 0D6A8
        move.l  PD_MoveTable(a5),O_MoveTable(a5); 0D6AE
        addq.b  #$1,O_Step2(a5)                 ; 0D6B4
        rts                                     ; 0D6B8
PetiteDevilLeaveDirs:
	dc.b	$08,$00,$00,$08

;---------------------------------------------------------------------------
