;---------------------------------------------------------------------------
PetiteDevil_Move:
        bsr.w   ApplyMoveTable                  ; 0D6BE  move by the movement table
        cmpi.w  #$35,O_Y(a5)                    ; 0D6C2  never below Y 54
        bhi.b   l_0D6D0                         ; 0D6C8
        move.w  #$36,O_Y(a5)                    ; 0D6CA
l_0D6D0:
        tst.b   O_Param(a5)                     ; 0D6D0
        bne.b   l_0D6FA                         ; 0D6D4
