        bcs.b   l_0D6FA                         ; 0D6E4
        cmp.w   g_ArthurX(a6),d0                ; 0D6E6
        bcc.b   l_0D6FA                         ; 0D6EA
        clr.b   PD_Turn(a5)                     ; 0D6EC
        move.b  #$3,O_Step(a5)                  ; 0D6F0
        clr.b   O_Step2(a5)                     ; 0D6F6
l_0D6FA:
