;---------------------------------------------------------------------------
; Fire once (enemy shot type 8): sideways when level with Arthur, down when above him
;---------------------------------------------------------------------------
PetiteDevil_TryShoot:
        subq.b  #$1,PD_ShotTime(a5)             ; 0D7DC  count down to the next shot
        bne.b   l_0D7E8                         ; 0D7E0
        move.b  #$1,PD_Ready(a5)                ; 0D7E2
l_0D7E8:
        tst.b   PD_Shot(a5)                     ; 0D7E8  one shot at a time, when ready, if an enemy-shot slot is free
        bne.b   l_0D84E                         ; 0D7EC
        tst.b   PD_Ready(a5)                    ; 0D7EE
        beq.b   l_0D84E                         ; 0D7F2
        bsr.w   FindFreeEnemyShot               ; 0D7F4  find a free enemy-projectile slot (fires a shot)
        bne.b   l_0D84E                         ; 0D7F8
        move.w  g_ArthurY(a6),d0                ; 0D7FA  within 16 px above Arthur and 50 px either side: shoot sideways
        addi.w  #$10,d0                         ; 0D7FE
        cmp.w   O_Y(a5),d0                      ; 0D802
        bcs.b   l_0D82A                         ; 0D806
        subi.w  #$10,d0                         ; 0D808
        cmp.w   O_Y(a5),d0                      ; 0D80C
        bhi.b   l_0D82A                         ; 0D810
        move.w  g_ArthurX(a6),d0                ; 0D812
        subi.w  #$32,d0                         ; 0D816
        cmp.w   O_X(a5),d0                      ; 0D81A
        bhi.b   l_0D850                         ; 0D81E
        addi.w  #$64,d0                         ; 0D820
        cmp.w   O_X(a5),d0                      ; 0D824
        bcs.b   l_0D850                         ; 0D828
l_0D82A:
        move.w  g_ArthurX(a6),d0                ; 0D82A  or within 5 px of his X and up to 60 px above: shoot down
        subq.w  #$5,d0                          ; 0D82E
        cmp.w   O_X(a5),d0                      ; 0D830
        bhi.b   l_0D84E                         ; 0D834
        addi.w  #$a,d0                          ; 0D836
        cmp.w   O_X(a5),d0                      ; 0D83A
        bcs.b   l_0D84E                         ; 0D83E
        move.w  g_ArthurY(a6),d0                ; 0D840
        addi.w  #$3c,d0                         ; 0D844
        cmp.w   O_Y(a5),d0                      ; 0D848
        bcs.b   l_0D862                         ; 0D84C
l_0D84E:
        rts                                     ; 0D84E
l_0D850:
        move.w  g_ArthurX(a6),d0                ; 0D850  sideways, towards Arthur
        cmp.w   O_X(a5),d0                      ; 0D854
        scs.b   $12(a4)                         ; 0D858
        neg.b   $12(a4)                         ; 0D85C
        bra.b   l_0D868                         ; 0D860
l_0D862:
        move.b  #$2,$12(a4)                     ; 0D862  straight down
l_0D868:
        clr.b   $2(a4)                          ; 0D868  the shot: type 8, 10 px below the devil
        move.w  O_X(a5),$6(a4)                  ; 0D86C
        move.w  O_Y(a5),d0                      ; 0D872
        subi.w  #$a,d0                          ; 0D876
        move.w  d0,$a(a4)                       ; 0D87A
        clr.b   $3(a4)                          ; 0D87E
        clr.b   $4(a4)                          ; 0D882
        clr.b   $5(a4)                          ; 0D886
        move.b  #$1,(a4)                        ; 0D88A
        move.b  #$8,$1a(a4)                     ; 0D88E  enemy shot type 8
        move.b  #$1,PD_Shot(a5)                 ; 0D894
        move.b  $12(a4),PD_ShotDir(a5)          ; 0D89A
        move.b  #$2,O_Step(a5)                  ; 0D8A0
        clr.b   O_Step2(a5)                     ; 0D8A6
        rts                                     ; 0D8AA

