;---------------------------------------------------------------------------
; === Flying Knight (type 3, 100 pts) ===
; Shielded knight flying in a wave pattern (movement table, random variation). Sound effect 20.
; Dispatches on O_State: 0 main behaviour, 1 type-specific second phase, 2 killed (set by EnemyHitByShot after scoring), 3 remove.
;
; Behaviour, as coded: flies left at 1.06 px/frame in a wave about 50 px up and down from
; where it started (random first half-wave up or down). Its shield makes it immune
; (O_Active $81, shots pass through) until it has flown past Arthur - only then can it be hit
; (from behind).
;---------------------------------------------------------------------------
Enemy_FlyingKnight:
        move.b  O_State(a5),d0                  ; 0DA38
        add.w   d0,d0                           ; 0DA3C
        add.w   d0,d0                           ; 0DA3E
        jmp     Enemy_FlyingKnight_Jumps(pc,d0.w)             ; 0DA40
Enemy_FlyingKnight_Jumps:
        bra.w   FlyingKnight_Init               ; 0DA44
        bra.w   FlyingKnight_Active             ; 0DA48
        bra.w   FlyingKnight_Dying              ; 0DA4C
        bra.w   FlyingKnight_Free               ; 0DA50

;---------------------------------------------------------------------------
; State 0: size 1, move table, wave
;---------------------------------------------------------------------------
FlyingKnight_Init:
        move.b  #$1,O_Size(a5)                  ; 0DA54
        clr.b   O_Dir(a5)                       ; 0DA5A
        lea.l   FlyingKnight_AnimUp(pc),a0      ; 0DA5E
        bsr.w   SetAnim                         ; 0DA62  start animation
        lea.l   FlyingKnightMove(pc),a0         ; 0DA66
        move.l  a0,O_MoveTable(a5)              ; 0DA6A
        addq.b  #ST_ACTIVE,O_State(a5)          ; 0DA6E
        clr.b   O_Step(a5)                      ; 0DA72
        rts                                     ; 0DA76
FlyingKnight_AnimUp:
	AF	$00,3
	AL	$01,3,FlyingKnight_AnimUp
FlyingKnight_AnimDown:
	AF	$02,3
	AL	$03,3,FlyingKnight_AnimDown

;---------------------------------------------------------------------------
; -1.06 px/frame for both halves of the wave
;---------------------------------------------------------------------------
FlyingKnightMove:
	dc.b	$FE,$F0,$00,$00,$FE,$F0,$00,$00
FlyingKnightSteps:
        bra.w   FlyingKnight_Start              ; 0DA8C
        bra.w   FlyingKnight_WaveUp             ; 0DA90
        bra.w   FlyingKnight_WaveDown           ; 0DA94

;---------------------------------------------------------------------------
; State 1. O_Step: 0 start, 1 upper half-wave, 2 lower half-wave
;---------------------------------------------------------------------------
FlyingKnight_Active:
        clr.w   d0                              ; 0DA98
        move.b  O_Step(a5),d0                   ; 0DA9A
        add.w   d0,d0                           ; 0DA9E
        add.w   d0,d0                           ; 0DAA0
        jsr     FlyingKnightSteps(pc,d0.w)      ; 0DAA2
        move.w  g_GameFrame(a6),d0              ; 0DAA6
        addq.b  #$1,d0                          ; 0DAAA
        andi.b  #$1f,d0                         ; 0DAAC
        bne.w   CheckFarAway                    ; 0DAB0
        rts                                     ; 0DAB4

;---------------------------------------------------------------------------
; Shielded ($81); random first half-wave
;---------------------------------------------------------------------------
FlyingKnight_Start:
        move.w  O_Y(a5),FK_BaseY(a5)            ; 0DAB6
        clr.b   FK_Phase(a5)                    ; 0DABC
        move.b  #$81,(a5)                       ; 0DAC0  shield up: shots pass through
        clr.b   d1                              ; 0DAC4
        bsr.w   Random                          ; 0DAC6  random number
        andi.b  #$1,d0                          ; 0DACA
        beq.b   l_0DADE                         ; 0DACE
        lea.l   FlyingKnight_AnimDown(pc),a0    ; 0DAD0
        bsr.w   SetAnim                         ; 0DAD4  start animation
        addq.b  #$1,d1                          ; 0DAD8
        addq.b  #$1,O_Step(a5)                  ; 0DADA  next step
l_0DADE:
        addq.b  #$1,O_Step(a5)                  ; 0DADE  next step
        move.b  d1,O_Dir(a5)                    ; 0DAE2
        rts                                     ; 0DAE6
FlyingKnight_WaveUp:
        bsr.b   FlyingKnight_Move               ; 0DAE8
        add.w   FK_BaseY(a5),d0                 ; 0DAEA
        move.w  d0,O_Y(a5)                      ; 0DAEE
        addq.b  #$6,FK_Phase(a5)                ; 0DAF2
        bcc.b   l_0DB08                         ; 0DAF6
        addq.b  #$1,O_Dir(a5)                   ; 0DAF8
        lea.l   FlyingKnight_AnimDown(pc),a0    ; 0DAFC
        bsr.w   SetAnim                         ; 0DB00  start animation
        addq.b  #$1,O_Step(a5)                  ; 0DB04  next step
l_0DB08:
        rts                                     ; 0DB08
FlyingKnight_WaveDown:
        bsr.b   FlyingKnight_Move               ; 0DB0A
        neg.w   d0                              ; 0DB0C
        add.w   FK_BaseY(a5),d0                 ; 0DB0E
        move.w  d0,O_Y(a5)                      ; 0DB12
        addq.b  #$6,FK_Phase(a5)                ; 0DB16
        bcc.b   l_0DB08                         ; 0DB1A
        clr.b   O_Dir(a5)                       ; 0DB1C
        move.b  #$1,O_Step(a5)                  ; 0DB20
        lea.l   FlyingKnight_AnimUp(pc),a0      ; 0DB26
        bsr.w   SetAnim                         ; 0DB2A  start animation
        rts                                     ; 0DB2E

;---------------------------------------------------------------------------
; Move, animate; drop the shield once past Arthur; d0 = sin(phase) x 2 x 50 / 256
;---------------------------------------------------------------------------
FlyingKnight_Move:
        bsr.w   ApplyMoveTable                  ; 0DB30  move by the movement table
        bsr.w   Animate                         ; 0DB34  animate
        tst.b   (a5)                            ; 0DB38
        bpl.b   l_0DB4A                         ; 0DB3A
        move.w  O_X(a5),d0                      ; 0DB3C
        cmp.w   g_ArthurX(a6),d0                ; 0DB40
        bcc.b   l_0DB4A                         ; 0DB44
        move.b  #$1,(a5)                        ; 0DB46  past Arthur: can be hit
l_0DB4A:
        lea.l   SineTable(pc),a0                ; 0DB4A
        clr.w   d0                              ; 0DB4E
        move.b  FK_Phase(a5),d0                 ; 0DB50
        move.b  (a0,d0.w),d0                    ; 0DB54
        lsl.b   #$1,d0                          ; 0DB58
        mulu.w  #$32,d0                         ; 0DB5A
        lsr.w   #$8,d0                          ; 0DB5E
        rts                                     ; 0DB60

;---------------------------------------------------------------------------
; State 2: sound 20, EnemyBurst
;---------------------------------------------------------------------------
FlyingKnight_Dying:
        cmpi.b  #$1,O_Step(a5)                  ; 0DB62
        beq.b   l_0DB78                         ; 0DB68
        bcc.b   l_0DB7C                         ; 0DB6A
        moveq   #SFX_ENEMY_DIE2,d0              ; 0DB6C
        bsr.w   PlaySfx                         ; 0DB6E  sound effect 20 (enemy event)
        addq.b  #$1,O_Step(a5)                  ; 0DB72  next step
        rts                                     ; 0DB76
l_0DB78:
        bra.w   EnemyBurst                      ; 0DB78
l_0DB7C:
        move.b  #ST_REMOVE,O_State(a5)          ; 0DB7C
        rts                                     ; 0DB82

;---------------------------------------------------------------------------
; State 3: free the slot, give the spawn quota back
;---------------------------------------------------------------------------
FlyingKnight_Free:
        clr.b   (a5)                            ; 0DB84  free this enemy slot
        addq.b  #$1,g_SpawnQuota+3(a6)          ; 0DB86
        rts                                     ; 0DB8A

;---------------------------------------------------------------------------
; 256 bytes: 127 x sin(pi x i / 256) - a half sine, 0 up to 127 and back.
; Shared by most flying enemies for their arcs and waves.
;---------------------------------------------------------------------------
SineTable:
	dc.b	$00,$02,$03,$05,$06,$08,$09,$0B,$0C,$0E,$10,$11,$13,$14,$16,$17
	dc.b	$19,$1A,$1C,$1D,$1F
	dc.b	' "#%&()+,./1235689:<=?@ACDEGHIJLMNOQRSTUVXYZ[\]^_`abcdefghijjklmnoopqqrsstuuvvwxxyyzzz{{|||}}}}~~~~~'
	dc.b	$7F,$7F,$7F,$7F,$7F,$7F,$7F

;---------------------------------------------------------------------------
; SineTable + 128 (127 down to 0): used as a cosine for the Red Arremer's dive
;---------------------------------------------------------------------------
SineTableFalling:
	dc.b	$7F,$7F,$7F,$7F,$7F,$7F,$7F,$7F
	dc.b	'~~~~~}}}}|||{{zzzyyxxwvvuutssrqqpoonmlkjjihgfedcba`_^]\[ZYXVUTSRQONMLJIHGEDCA@?=<:9865321/.,+)(&%#" '
	dc.b	$1F,$1D,$1C,$1A,$19,$17,$16,$14,$13,$11,$10,$0E,$0C,$0B,$09,$08
	dc.b	$06,$05,$03,$02

;---------------------------------------------------------------------------
; === Blue Killer (type 4, 100 pts) ===
; Small winged devil that drops/hops along the scenery (map collision), random behaviour. Sound effect 17.
; Dispatches on O_State: 0 main behaviour, 1 type-specific second phase, 2 killed (set by EnemyHitByShot after scoring), 3 remove.
;
; Behaviour, as coded:
;   * Parameter 0: walks in from the edge of the screen. Other parameters: drops from above
;     (shots pass through until it appears), swooping down in a curve towards Arthur, or
;     straight down when it is over him, then lands.
;   * On the floor it walks towards Arthur at 1.43 px/frame for random times (16-180
;     frames), hopping (32 or 48 px, 64 frames) out of the way when one of Arthur's shots
;     comes at it while he is more than 128 px away, and hopping off ledges.
;   * After 3600 frames (72 s) it turns into a Red Arremer (O_Type 5, O_Param 2: the blink-in
;     start mode, which then takes 26,352 frames - see Enemy_RedArremer).
;---------------------------------------------------------------------------
Enemy_BlueKiller:
        move.b  O_State(a5),d0                  ; 0DC8C
        add.w   d0,d0                           ; 0DC90
        add.w   d0,d0                           ; 0DC92
        jmp     Enemy_BlueKiller_Jumps(pc,d0.w) ; 0DC94
Enemy_BlueKiller_Jumps:
        bra.w   BlueKiller_Init                 ; 0DC98
        bra.w   BlueKiller_Active               ; 0DC9C
        bra.w   BlueKiller_Dying                ; 0DCA0
        bra.w   BlueKiller_Free                 ; 0DCA4

;---------------------------------------------------------------------------
; State 0. Parameter 0: walk in from the screen edge; otherwise drop from above
;---------------------------------------------------------------------------
BlueKiller_Init:
        tst.b   O_Param(a5)                     ; 0DCA8
        bne.b   BlueKiller_DropInit             ; 0DCAC
        tst.b   O_Step(a5)                      ; 0DCAE
        bne.b   BlueKiller_WalkIn               ; 0DCB2
BlueKiller_Setup:
        move.w  O_Y(a5),BK_BaseY(a5)            ; 0DCB4
        move.b  #$10,BK_HopHeight(a5)           ; 0DCBA
        clr.b   BK_Unused31(a5)                 ; 0DCC0
        clr.w   BK_Phase(a5)                    ; 0DCC4
        clr.b   O_Size(a5)                      ; 0DCC8
        bsr.w   BlueKiller_FaceArthur           ; 0DCCC
        lea.l   BlueKiller_AnimWalk(pc),a0      ; 0DCD0
        bsr.w   SetAnimIndexed                  ; 0DCD4  start animation for current direction
        lea.l   BlueKillerMoveTable(pc),a0      ; 0DCD8
        move.l  a0,O_MoveTable(a5)              ; 0DCDC
        addq.b  #$1,O_Step(a5)                  ; 0DCE0  next step
        rts                                     ; 0DCE4

;---------------------------------------------------------------------------
; Animate until 16-240 px inside the screen, then start the 3600-frame timer
;---------------------------------------------------------------------------
BlueKiller_WalkIn:
        move.w  O_X(a5),d0                      ; 0DCE6
        sub.w   g_CameraX(a6),d0                ; 0DCEA
        subi.w  #$10,d0                         ; 0DCEE
        cmp.w   #$e0,d0                         ; 0DCF2
        bls.b   l_0DCFC                         ; 0DCF6
        bra.w   Animate                         ; 0DCF8
l_0DCFC:
        move.w  #$e10,BK_Morph(a5)              ; 0DCFC
        addq.b  #ST_ACTIVE,O_State(a5)          ; 0DD02
        clr.b   O_Step(a5)                      ; 0DD06
        rts                                     ; 0DD0A
BlueKiller_DropInit:
        tst.b   O_Step(a5)                      ; 0DD0C
        bne.b   BlueKiller_DropSetup            ; 0DD10
        bsr.w   Random                          ; 0DD12  random number
        andi.b  #$f,d0                          ; 0DD16
        addi.b  #$a,d0                          ; 0DD1A
        move.b  d0,BK_CurveWait(a5)             ; 0DD1E
        clr.l   O_Anim(a5)                      ; 0DD22
        addq.b  #$1,O_Step(a5)                  ; 0DD26  next step
        subq.b  #$1,BK_CurveWait(a5)            ; 0DD2A
        bne.b   l_0DD3A                         ; 0DD2E
        move.b  (a5),d0                         ; 0DD30
        lsr.b   #$1,d0                          ; 0DD32
        move.b  d0,(a5)                         ; 0DD34
        addq.b  #$1,O_Step(a5)                  ; 0DD36  next step
l_0DD3A:
        rts                                     ; 0DD3A

;---------------------------------------------------------------------------
; Shots pass through; curve rate from the height above Arthur; step 4 (param 2: 5)
;---------------------------------------------------------------------------
BlueKiller_DropSetup:
        move.b  (a5),d0                         ; 0DD3C
        lsl.b   #$1,d0                          ; 0DD3E
        move.b  d0,(a5)                         ; 0DD40
        bsr.w   CheckOnScreen                   ; 0DD42  visible?
        move.w  #$e10,BK_Morph(a5)              ; 0DD46
        addq.b  #ST_ACTIVE,O_State(a5)          ; 0DD4C
        clr.b   O_Step(a5)                      ; 0DD50
        bsr.w   BlueKiller_Setup                ; 0DD54
        move.w  O_Y(a5),d0                      ; 0DD58
        move.w  g_ArthurY(a6),d1                ; 0DD5C
        sub.b   d1,d0                           ; 0DD60
        lsr.b   #$3,d0                          ; 0DD62
        move.b  d0,BK_CurveRate(a5)             ; 0DD64
        move.b  d0,BK_CurveWait(a5)             ; 0DD68
        move.b  #$a,BK_Appear(a5)               ; 0DD6C
        lea.l   BlueKiller_AnimDrop(pc),a0      ; 0DD72
        move.l  a0,O_Anim(a5)                   ; 0DD76
        bsr.w   SetAnim                         ; 0DD7A  start animation
        move.b  #ST_ACTIVE,O_State(a5)          ; 0DD7E
        move.b  #$4,O_Step(a5)                  ; 0DD84
        clr.b   O_Step2(a5)                     ; 0DD8A
        cmpi.b  #$2,O_Param(a5)                 ; 0DD8E
        bne.b   l_0DD9A                         ; 0DD94
        addq.b  #$1,O_Step(a5)                  ; 0DD96  next step
l_0DD9A:
        rts                                     ; 0DD9A

;---------------------------------------------------------------------------
; O_Dir 0 if Arthur is to the right, 1 if to the left
;---------------------------------------------------------------------------
BlueKiller_FaceArthur:
        move.w  O_X(a5),d0                      ; 0DD9C
        cmp.w   g_ArthurX(a6),d0                ; 0DDA0
        slt.b   d0                              ; 0DDA4
        addq.b  #$1,d0                          ; 0DDA6
        move.b  d0,O_Dir(a5)                    ; 0DDA8
        rts                                     ; 0DDAC

;---------------------------------------------------------------------------
; State 1. O_Step: 0 walk, 1 walk 2, 2 hop up, 3 hop down, 4 drop, 5 swoop
;---------------------------------------------------------------------------
BlueKiller_Active:
        clr.w   d0                              ; 0DDAE
        move.b  O_Step(a5),d0                   ; 0DDB0
        add.w   d0,d0                           ; 0DDB4
        add.w   d0,d0                           ; 0DDB6
        jsr     BlueKiller_MorphTimer_Jumps(pc,d0.w)             ; 0DDB8
        bsr.w   PetiteDevil_RemoveOffScreen     ; 0DDBC
        bsr.b   BlueKiller_MorphTimer           ; 0DDC0
        bra.w   CheckFarAway                    ; 0DDC2

;---------------------------------------------------------------------------
; After 3600 frames: become a Red Arremer (type 5, parameter 2), from state 0
;---------------------------------------------------------------------------
BlueKiller_MorphTimer:
        subq.w  #$1,BK_Morph(a5)                ; 0DDC6
        bne.b   l_0DDE4                         ; 0DDCA
        move.b  #E_REDARREMER,O_Type(a5)        ; 0DDCC  turn into a Red Arremer
        move.b  #$2,O_Param(a5)                 ; 0DDD2  start mode 2 (blink in)
        clr.b   O_State(a5)                     ; 0DDD8  -> state 0 (spawn)
        clr.b   O_Step(a5)                      ; 0DDDC
        clr.b   O_Step2(a5)                     ; 0DDE0
l_0DDE4:
        rts                                     ; 0DDE4
BlueKiller_MorphTimer_Jumps:
        bra.w   BlueKiller_Walk                 ; 0DDE6
        bra.w   BlueKiller_Walk2                ; 0DDEA
        bra.w   BlueKiller_HopUp                ; 0DDEE
        bra.w   BlueKiller_HopDown              ; 0DDF2
        bra.w   BlueKiller_Drop                 ; 0DDF6
        bra.w   BlueKiller_Swoop2               ; 0DDFA

;---------------------------------------------------------------------------
; 120, 160, 60, 16 frames
;---------------------------------------------------------------------------
BlueKillerWalkTimes:
	dc.b	$78,$A0,$3C,$10

;---------------------------------------------------------------------------
; dodge only when Arthur is more than 128 px away
;---------------------------------------------------------------------------
BlueKillerDodgeRange:
	dc.b	$00,$80,$01,$00
BlueKiller_Walk:
        lea.l   BlueKiller_Walking(pc),a0       ; 0DE06
        tst.b   O_Step2(a5)                     ; 0DE0A
        bne.b   l_0DE14                         ; 0DE0E
        lea.l   BlueKiller_WalkStart(pc),a0     ; 0DE10
l_0DE14:
        jsr     (a0)                            ; 0DE14
        lea.l   BlueKillerDodgeRange(pc),a0     ; 0DE16
        bsr.w   RedArremer_ShotThreat           ; 0DE1A
        bcc.b   l_0DE2A                         ; 0DE1E
        move.b  #$2,O_Step(a5)                  ; 0DE20
        clr.b   O_Step2(a5)                     ; 0DE26
l_0DE2A:
        rts                                     ; 0DE2A
BlueKiller_WalkStart:
        bsr.w   BlueKiller_FaceArthur           ; 0DE2C
        clr.b   O_Size(a5)                      ; 0DE30
        lea.l   BlueKiller_AnimWalk(pc),a0      ; 0DE34
        bsr.w   SetAnimIndexed                  ; 0DE38  start animation for current direction
        bsr.w   Random                          ; 0DE3C  random number
        andi.w  #$3,d0                          ; 0DE40
        move.b  BlueKillerWalkTimes(pc,d0.w),BK_WalkTime(a5); 0DE44
        addq.b  #$1,O_Step2(a5)                 ; 0DE4A

;---------------------------------------------------------------------------
; Walk; no floor ahead: hop down
;---------------------------------------------------------------------------
BlueKiller_Walking:
        bsr.w   Animate                         ; 0DE4E  animate
        subq.b  #$1,BK_WalkTime(a5)             ; 0DE52
        bne.b   l_0DE64                         ; 0DE56
l_0DE58:
        move.b  #$2,O_Step(a5)                  ; 0DE58
        clr.b   O_Step2(a5)                     ; 0DE5E
        rts                                     ; 0DE62
l_0DE64:
        bsr.w   Animate                         ; 0DE64  animate
        bsr.w   ApplyMoveTable                  ; 0DE68  move by the movement table
        subq.w  #$1,O_Y(a5)                     ; 0DE6C
        bsr.w   ObjectMapCollide                ; 0DE70  on the floor? (Z set = yes, Y snapped onto it)
        clr.w   d0                              ; 0DE74
        bne.b   l_0DE58                         ; 0DE76
        rts                                     ; 0DE78

;---------------------------------------------------------------------------
; 60, 90, 120, 180 frames
;---------------------------------------------------------------------------
BlueKillerWalkTimes2:
	dc.b	$3C,$5A,$78,$B4
BlueKiller_Walk2:
        lea.l   BlueKiller_Walking2(pc),a0      ; 0DE7E
        tst.b   O_Step2(a5)                     ; 0DE82
        bne.b   l_0DE8C                         ; 0DE86
        lea.l   BlueKiller_Walk2Start(pc),a0    ; 0DE88
l_0DE8C:
        jsr     (a0)                            ; 0DE8C
        lea.l   BlueKillerDodgeRange(pc),a0     ; 0DE8E
        bsr.w   RedArremer_ShotThreat           ; 0DE92
        bcc.b   l_0DEA2                         ; 0DE96
        move.b  #$3,O_Step(a5)                  ; 0DE98
        clr.b   O_Step2(a5)                     ; 0DE9E
l_0DEA2:
        rts                                     ; 0DEA2
BlueKiller_Walk2Start:
        lea.l   BlueKiller_AnimWalk2(pc),a0     ; 0DEA4
        bsr.w   SetAnimIndexed                  ; 0DEA8  start animation for current direction
        bsr.w   Random                          ; 0DEAC  random number
        andi.w  #$3,d0                          ; 0DEB0
        move.b  BlueKillerWalkTimes2(pc,d0.w),BK_WalkTime(a5); 0DEB4
        addq.b  #$1,O_Step2(a5)                 ; 0DEBA
BlueKiller_Walking2:
        bsr.w   Animate                         ; 0DEBE  animate
        subq.b  #$1,BK_WalkTime(a5)             ; 0DEC2
        bne.w   ApplyMoveTable                  ; 0DEC6
        move.b  #$3,O_Step(a5)                  ; 0DECA
        clr.b   O_Step2(a5)                     ; 0DED0
        rts                                     ; 0DED4

;---------------------------------------------------------------------------
; Size 2; hop 32 or 48 px high
;---------------------------------------------------------------------------
BlueKiller_HopUp:
        tst.b   O_Step2(a5)                     ; 0DED6
        bne.b   l_0DF0E                         ; 0DEDA
        move.b  #$2,O_Size(a5)                  ; 0DEDC
        lea.l   BlueKiller_AnimWalk2(pc),a0     ; 0DEE2
        bsr.w   SetAnimIndexed                  ; 0DEE6  start animation for current direction
        move.w  O_Y(a5),BK_BaseY(a5)            ; 0DEEA
        clr.w   BK_Phase(a5)                    ; 0DEF0
        clr.b   BK_Unused31(a5)                 ; 0DEF4
        bsr.w   Random                          ; 0DEF8  random number
        andi.b  #$1,d0                          ; 0DEFC
        lsl.b   #$4,d0                          ; 0DF00
        addi.b  #$20,d0                         ; 0DF02
        move.b  d0,BK_HopHeight(a5)             ; 0DF06
        addq.b  #$1,O_Step2(a5)                 ; 0DF0A
l_0DF0E:
        bsr.w   ApplyMoveTable                  ; 0DF0E  move by the movement table
        bsr.w   Animate                         ; 0DF12  animate
        addi.w  #$400,BK_Phase(a5)              ; 0DF16
        bpl.b   BlueKiller_HopY                 ; 0DF1C
        move.b  #$1,O_Step(a5)                  ; 0DF1E
        clr.b   O_Step2(a5)                     ; 0DF24
        rts                                     ; 0DF28

;---------------------------------------------------------------------------
; Y = BK_BaseY + sin(phase) x 2 x BK_HopHeight / 256
;---------------------------------------------------------------------------
BlueKiller_HopY:
        lea.l   SineTable(pc),a0                ; 0DF2A
        move.w  BK_Phase(a5),d0                 ; 0DF2E
        lsr.w   #$8,d0                          ; 0DF32
        move.b  (a0,d0.w),d0                    ; 0DF34
        bpl.b   l_0DF3C                         ; 0DF38
        neg.b   d0                              ; 0DF3A
l_0DF3C:
        add.b   d0,d0                           ; 0DF3C
