        move.b  BK_HopHeight(a5),d1             ; 0DF40
        mulu.w  d1,d0                           ; 0DF44
        lsr.w   #$8,d0                          ; 0DF46
        add.w   BK_BaseY(a5),d0                 ; 0DF48
        move.w  d0,O_Y(a5)                      ; 0DF4C
