;---------------------------------------------------------------------------
; Second half of the hop, then fall 2 px/frame until it lands
;---------------------------------------------------------------------------
BlueKiller_HopDown:
        cmpi.b  #$1,O_Step2(a5)                 ; 0DF52
        beq.b   l_0DF68                         ; 0DF58
        bhi.b   l_0DF86                         ; 0DF5A
        lea.l   BlueKiller_AnimWalk2(pc),a0     ; 0DF5C
        bsr.w   SetAnimIndexed                  ; 0DF60  start animation for current direction
        addq.b  #$1,O_Step2(a5)                 ; 0DF64
l_0DF68:
        bsr.w   ApplyMoveTable                  ; 0DF68  move by the movement table
        bsr.w   Animate                         ; 0DF6C  animate
        addi.w  #$400,BK_Phase(a5)              ; 0DF70
        bcs.b   l_0DF80                         ; 0DF76
        bsr.b   BlueKiller_HopY                 ; 0DF78
        bsr.w   ObjectMapCollide                ; 0DF7A  on the floor? (Z set = yes, Y snapped onto it)
        rts                                     ; 0DF7E
l_0DF80:
        addq.b  #$1,O_Step2(a5)                 ; 0DF80
        rts                                     ; 0DF84
l_0DF86:
