        lsr.b   #$1,d0                          ; 0DFF4
        move.b  d0,(a5)                         ; 0DFF6
        move.b  #$2,O_Size(a5)                  ; 0DFF8
        lea.l   BlueKiller_AnimAppear(pc),a0    ; 0DFFE
        move.l  a0,O_Anim(a5)                   ; 0E002
        clr.b   O_AnimTimer(a5)                 ; 0E006
        bsr.w   BlueKiller_FaceArthur           ; 0E00A
        move.b  O_Dir(a5),BK_SwoopMode(a5)      ; 0E00E
        clr.b   O_Dir(a5)                       ; 0E014
        move.w  g_ArthurX(a6),d0                ; 0E018
        subi.w  #$a,d0                          ; 0E01C
        cmp.w   O_X(a5),d0                      ; 0E020
        bhi.b   l_0E036                         ; 0E024
        addi.w  #$14,d0                         ; 0E026
        cmp.w   O_X(a5),d0                      ; 0E02A
        bcs.b   l_0E036                         ; 0E02E
        move.b  #$2,BK_SwoopMode(a5)            ; 0E030
l_0E036:
        move.b  #$1,BK_SwoopSet(a5)             ; 0E036
        move.w  g_ArthurX(a6),d0                ; 0E03C
        subi.w  #$40,d0                         ; 0E040
        cmp.w   O_X(a5),d0                      ; 0E044
        bhi.b   l_0E058                         ; 0E048
        addi.w  #$80,d0                         ; 0E04A
        cmp.w   O_X(a5),d0                      ; 0E04E
        bcs.b   l_0E058                         ; 0E052
        clr.b   BK_SwoopMode(a5)                ; 0E054
l_0E058:
