        beq.b   l_0E08A                         ; 0E06E
        clr.w   d0                              ; 0E070
        move.b  BK_SwoopMode(a5),d0             ; 0E072
        add.w   d0,d0                           ; 0E076
        add.w   d0,d0                           ; 0E078
        jsr     BlueKillerSwoopModes(pc,d0.w)   ; 0E07A
        bsr.w   ApplyMoveTable                  ; 0E07E  move by the movement table
        bsr.w   Animate                         ; 0E082  animate
        bra.w   CheckFarAway                    ; 0E086
l_0E08A:
        bsr.w   BlueKiller_Setup                ; 0E08A
        clr.b   O_Step(a5)                      ; 0E08E
        clr.b   O_Step2(a5)                     ; 0E092
        rts                                     ; 0E096
BlueKillerSwoopModes:
        bra.w   l_0E0A4                         ; 0E098
        bra.w   l_0E0D4                         ; 0E09C
        bra.w   l_0E106                         ; 0E0A0
l_0E0A4:
