        bne.b   l_0E0BE                         ; 0E0A8
        move.b  O_Dir(a5),d0                    ; 0E0AA
        subq.b  #$5,d0                          ; 0E0AE
        beq.b   l_0E0BA                         ; 0E0B0
        addq.b  #$1,O_Dir(a5)                   ; 0E0B2
        move.b  BK_CurveRate(a5),d0             ; 0E0B6
l_0E0BA:
        move.b  d0,BK_CurveWait(a5)             ; 0E0BA
l_0E0BE:
        lea.l   BlueKillerSwoopA(pc),a0         ; 0E0BE
        move.b  BK_SwoopSet(a5),d0              ; 0E0C2
        ext.w   d0                              ; 0E0C6
        add.w   d0,d0                           ; 0E0C8
        adda.w  d0,a0                           ; 0E0CA
        adda.w  (a0),a0                         ; 0E0CC
        move.l  a0,O_MoveTable(a5)              ; 0E0CE
        rts                                     ; 0E0D2
l_0E0D4:
        subq.b  #$1,BK_CurveWait(a5)            ; 0E0D4
        bne.b   l_0E0F0                         ; 0E0D8
        move.b  O_Dir(a5),d0                    ; 0E0DA
        cmp.b   #$5,d0                          ; 0E0DE
        beq.b   l_0E0EC                         ; 0E0E2
        addq.b  #$1,O_Dir(a5)                   ; 0E0E4
        move.b  BK_CurveRate(a5),d0             ; 0E0E8
l_0E0EC:
        move.b  d0,BK_CurveWait(a5)             ; 0E0EC
l_0E0F0:
        lea.l   BlueKillerSwoopB(pc),a0         ; 0E0F0
        move.b  BK_SwoopSet(a5),d0              ; 0E0F4
        ext.w   d0                              ; 0E0F8
        add.w   d0,d0                           ; 0E0FA
        adda.w  d0,a0                           ; 0E0FC
        adda.w  (a0),a0                         ; 0E0FE
        move.l  a0,O_MoveTable(a5)              ; 0E100
        rts                                     ; 0E104
l_0E106:
        clr.b   O_Dir(a5)                       ; 0E106
        lea.l   BlueKillerFallTable(pc),a0      ; 0E10A
        move.l  a0,O_MoveTable(a5)              ; 0E10E
        rts                                     ; 0E112
BlueKiller_Swoop2:
        tst.b   O_Step2(a5)                     ; 0E114
        beq.w   BlueKiller_Appear               ; 0E118
        bra.w   BlueKiller_Swoop                ; 0E11C

;---------------------------------------------------------------------------
; State 2: sound 17, EnemyDieFacing
;---------------------------------------------------------------------------
BlueKiller_Dying:
        cmpi.b  #$1,O_Step(a5)                  ; 0E120
        beq.b   l_0E136                         ; 0E126
        bcc.b   l_0E13A                         ; 0E128
        moveq   #SFX_ENEMY_DIE,d0               ; 0E12A
        bsr.w   PlaySfx                         ; 0E12C  sound effect 17 (enemy event)
        addq.b  #$1,O_Step(a5)                  ; 0E130  next step
        rts                                     ; 0E134
l_0E136:
        bra.w   EnemyDieFacing                  ; 0E136
l_0E13A:
        move.b  #ST_REMOVE,O_State(a5)          ; 0E13A
        rts                                     ; 0E140

;---------------------------------------------------------------------------
