	dc.w	-79,-439	;  1: dx -0.31, dy -1.71
	dc.w	-120,-439	;  2: dx -0.47, dy -1.71
	dc.w	-192,-439	;  3: dx -0.75, dy -1.71
	dc.w	-408,-439	;  4: dx -1.59, dy -1.71
	dc.w	-480,-439	;  5: dx -1.88, dy -1.71
BlueKillerSwoopA_1:
