;---------------------------------------------------------------------------
; State 1. O_Step: 0 walk, 1 fly, 2 shoot, 3 glide, 4 rage, 5 dodge / hover, 6 swoop.
; Then the hit flinch, and removal when it is far above or below the camera.
;---------------------------------------------------------------------------
RedArremer_Active:
        move.b  O_Step(a5),d0                   ; 0E406
        add.w   d0,d0                           ; 0E40A
        add.w   d0,d0                           ; 0E40C
        jsr     RedArremer_Active_Jumps(pc,d0.w)             ; 0E40E
        bsr.w   RedArremer_Flinch               ; 0E412
        move.w  O_Y(a5),d0                      ; 0E416  more than 64 px below or 320 above the camera: remove
        sub.w   g_CameraY(a6),d0                ; 0E41A
        addi.w  #$40,d0                         ; 0E41E
        cmp.w   #$180,d0                        ; 0E422
        bls.b   l_0E42E                         ; 0E426
        move.b  #ST_REMOVE,O_State(a5)          ; 0E428
l_0E42E:
        rts                                     ; 0E42E
RedArremer_Active_Jumps:
        bra.w   RedArremer_Walk                 ; 0E430
        bra.w   RedArremer_Fly                  ; 0E434
        bra.w   RedArremer_Shoot                ; 0E438
        bra.w   RedArremer_Glide                ; 0E43C
        bra.w   RedArremer_Rage                 ; 0E440
        bra.w   RedArremer_Dodge                ; 0E444
        bra.w   RedArremer_Swoop                ; 0E448

;---------------------------------------------------------------------------
; walking: +-0.8 px/frame
;---------------------------------------------------------------------------
RedArremerWalkMove:
	dc.b	$00,$CD,$FF,$33

;---------------------------------------------------------------------------
; Step 0: walk, and check the shot, swoop, take-off, distance, dodge and rage timers
