        bsr.w   RedArremer_SwoopTimer           ; 0E460
        bsr.w   RedArremer_TakeOffTimer         ; 0E464
        bsr.w   RedArremer_CheckGlide           ; 0E468
        bsr.w   RedArremer_CheckDodge           ; 0E46C
        bra.w   RedArremer_RageTimer            ; 0E470
RedArremer_WalkStart:
        lea.l   RedArremerWalkMove(pc),a0       ; 0E474
        move.l  a0,O_MoveTable(a5)              ; 0E478
        move.b  #$3,O_Size(a5)                  ; 0E47C
