        cmp.w   O_X(a5),d0                      ; 0E486
        shi.b   O_Dir(a5)                       ; 0E48A
        addq.b  #$1,O_Dir(a5)                   ; 0E48E
        lea.l   RedArremer_AnimWalk(pc),a0      ; 0E492
        bsr.w   SetAnimIndexed                  ; 0E496  start animation for current direction
        addq.b  #$1,O_Step2(a5)                 ; 0E49A
        rts                                     ; 0E49E

;---------------------------------------------------------------------------
; Walk; if there is no floor under it any more, fly
;---------------------------------------------------------------------------
RedArremer_Walking:
        bsr.w   RedArremer_WalkScriptStep       ; 0E4A0
        bsr.w   RedArremer_MoveX                ; 0E4A4
        subq.w  #$2,O_Y(a5)                     ; 0E4A8
        bsr.w   ObjectMapCollide                ; 0E4AC  on the floor? (Z set = yes, Y snapped onto it)
        beq.b   l_0E4BC                         ; 0E4B0
        move.b  #$1,O_Step(a5)                  ; 0E4B2
        clr.b   O_Step2(a5)                     ; 0E4B8
l_0E4BC:
