;---------------------------------------------------------------------------
RedArremer_Fly:
        move.b  O_Step2(a5),d0                  ; 0E4BE
        add.w   d0,d0                           ; 0E4C2
        add.w   d0,d0                           ; 0E4C4
        jsr     RedArremer_Fly_Jumps(pc,d0.w)   ; 0E4C6
        move.b  O_Step2(a5),d0                  ; 0E4CA
        subq.b  #$2,d0                          ; 0E4CE
        cmp.b   #$1,d0                          ; 0E4D0
        bhi.b   l_0E4DE                         ; 0E4D4
        bsr.w   RedArremer_ShotTimer            ; 0E4D6
        bra.w   RedArremer_SwoopTimer           ; 0E4DA
l_0E4DE:
