        bra.w   RedArremer_FlyPast              ; 0E4EC
        bra.w   RedArremer_Hover                ; 0E4F0
        bra.w   RedArremer_Descend              ; 0E4F4
        bra.w   RedArremer_Drop                 ; 0E4F8

;---------------------------------------------------------------------------
; +-1.75 px/frame (calm), +-2.0 (after its rage)
