        move.w  O_Y(a5),$a(a4)                  ; 0E650
        clr.b   $3(a4)                          ; 0E656
        clr.b   $4(a4)                          ; 0E65A
        clr.b   $5(a4)                          ; 0E65E
        move.b  #$1,(a4)                        ; 0E662
        move.b  #$6,RA_ShotTime(a5)             ; 0E666
        addq.b  #$1,O_Step2(a5)                 ; 0E66C
l_0E670:
