        bsr.w   RedArremer_CurveY               ; 0EC88
        addq.b  #$8,RA_Phase(a5)                ; 0EC8C
        bcc.b   l_0ECB2                         ; 0EC90
        move.l  O_Y(a5),-(a7)                   ; 0EC92
        bsr.w   ObjectMapCollide                ; 0EC96  on the floor? (Z set = yes, Y snapped onto it)
        move.l  (a7)+,O_Y(a5)                   ; 0EC9A
        tst.w   d0                              ; 0EC9E
        bne.b   l_0ECB4                         ; 0ECA0
        movea.l RA_FlyPtr(a5),a0                ; 0ECA2
        move.b  (a0),RA_Phase(a5)               ; 0ECA6
        clr.b   O_Step(a5)                      ; 0ECAA
        clr.b   O_Step2(a5)                     ; 0ECAE
l_0ECB2:
        rts                                     ; 0ECB2
l_0ECB4:
        addq.b  #$1,O_Step2(a5)                 ; 0ECB4
        rts                                     ; 0ECB8
RedArremer_Fall:
        subq.w  #$4,O_Y(a5)                     ; 0ECBA
        bsr.w   ObjectMapCollide                ; 0ECBE  on the floor? (Z set = yes, Y snapped onto it)
        bne.b   l_0ECD4                         ; 0ECC2
        movea.l RA_FlyPtr(a5),a0                ; 0ECC4
        move.b  (a0),RA_Phase(a5)               ; 0ECC8
        clr.b   O_Step(a5)                      ; 0ECCC
        clr.b   O_Step2(a5)                     ; 0ECD0
l_0ECD4:
        rts                                     ; 0ECD4

;---------------------------------------------------------------------------
; Within 48 px of the bottom of the screen: back to RA_BaseY and fly again
;---------------------------------------------------------------------------
RedArremer_TooLow:
        move.w  O_Y(a5),d0                      ; 0ECD6
        sub.w   g_CameraY(a6),d0                ; 0ECDA
        bmi.b   l_0ECE6                         ; 0ECDE
        cmp.w   #$30,d0                         ; 0ECE0
        bhi.b   l_0ECF6                         ; 0ECE4
l_0ECE6:
        move.b  #$1,O_Step(a5)                  ; 0ECE6
        clr.b   O_Step2(a5)                     ; 0ECEC
        move.w  RA_BaseY(a5),O_Y(a5)            ; 0ECF0
l_0ECF6:
        rts                                     ; 0ECF6
RedArremer_FaceArthur:
        move.w  g_ArthurX(a6),d0                ; 0ECF8
        cmp.w   O_X(a5),d0                      ; 0ECFC
        shi.b   O_Dir(a5)                       ; 0ED00
        addq.b  #$1,O_Dir(a5)                   ; 0ED04
        lea.l   RedArremer_AnimWalk(pc),a0      ; 0ED08
        bra.w   SetAnimIndexed                  ; 0ED0C
RedArremer_CurveUp:
        bsr.w   Animate                         ; 0ED10  animate
        bsr.b   RedArremer_CurveY               ; 0ED14
        addq.b  #$8,RA_Phase(a5)                ; 0ED16
        cmpi.b  #$a0,RA_Phase(a5)               ; 0ED1A
        bls.b   l_0ED2C                         ; 0ED20
        move.b  #$80,RA_Phase(a5)               ; 0ED22
        addq.b  #$1,O_Step2(a5)                 ; 0ED28
l_0ED2C:
        rts                                     ; 0ED2C

;---------------------------------------------------------------------------
; Y = RA_BaseY + RA_RadiusY x 2 x sin(RA_Phase) / 256
;---------------------------------------------------------------------------
RedArremer_CurveY:
        clr.w   d0                              ; 0ED2E
        move.b  RA_Phase(a5),d0                 ; 0ED30
        lea.l   SineTable(pc),a0                ; 0ED34
        move.b  (a0,d0.w),d0                    ; 0ED38
        add.b   d0,d0                           ; 0ED3C
        clr.w   d1                              ; 0ED3E
        move.b  RA_RadiusY(a5),d1               ; 0ED40
        mulu.w  d0,d1                           ; 0ED44
        lsr.w   #$8,d1                          ; 0ED46
        add.w   RA_BaseY(a5),d1                 ; 0ED48
        move.w  d1,O_Y(a5)                      ; 0ED4C
        rts                                     ; 0ED50
RedArremer_TooFarToDive:
        move.b  #$5,O_Step(a5)                  ; 0ED52
        move.b  #$3,O_Step2(a5)                 ; 0ED58
        move.b  #$80,RA_Phase(a5)               ; 0ED5E
        rts                                     ; 0ED64

;---------------------------------------------------------------------------
; State 2: sound 12, EnemyBurst, 63 frames
;---------------------------------------------------------------------------
RedArremer_Dying:
        cmpi.b  #$1,O_Step(a5)                  ; 0ED66
        beq.b   l_0ED80                         ; 0ED6C
        bcc.b   l_0ED84                         ; 0ED6E
        moveq   #SFX_ENEMY_HIT,d0               ; 0ED70
        bsr.w   PlaySfx                         ; 0ED72  sound effect 12 (weapon/boss hit)
        move.b  #$3f,RA_RadiusX(a5)             ; 0ED76
        addq.b  #$1,O_Step(a5)                  ; 0ED7C  next step
l_0ED80:
        bra.w   EnemyBurst                      ; 0ED80
l_0ED84:
        move.b  #$2,O_Size(a5)                  ; 0ED84
        subq.b  #$1,RA_RadiusX(a5)              ; 0ED8A
        bne.b   l_0ED96                         ; 0ED8E
        move.b  #ST_REMOVE,O_State(a5)          ; 0ED90
l_0ED96:
        rts                                     ; 0ED96

;---------------------------------------------------------------------------
; State 3: free, give the spawn quota back
;---------------------------------------------------------------------------
RedArremer_Free:
        clr.b   (a5)                            ; 0ED98  free this enemy slot
        addq.b  #$1,g_SpawnQuota+5(a6)          ; 0ED9A
        tst.b   g_BigEnemyCount(a6)             ; 0ED9E
        beq.b   l_0EDA8                         ; 0EDA2
        subq.b  #$1,g_BigEnemyCount(a6)         ; 0EDA4
l_0EDA8:
        rts                                     ; 0EDA8
RedArremer_AnimPerch:
	AF	$03,5
	AL	$04,5,RedArremer_AnimPerch
RedArremer_AnimWalk:
	dc.w	RedArremer_AnimWalk_0-*	; 0
	dc.w	RedArremer_AnimWalk_1-*	; 1
RedArremer_AnimWalk_0:
	AF	$08,3
	AF	$09,3
	AF	$0A,3
	AL	$09,3,RedArremer_AnimWalk_0
RedArremer_AnimWalk_1:
	AF	$00,3
	AF	$01,3
	AF	$02,3
	AL	$01,3,RedArremer_AnimWalk_1
RedArremer_AnimFly:
	dc.w	RedArremer_AnimFly_0-*	; 0
	dc.w	RedArremer_AnimFly_1-*	; 1
RedArremer_AnimFly_0:
	AF	$14,3
	AF	$15,3
	AF	$16,3
	AL	$15,3,RedArremer_AnimFly_0
RedArremer_AnimFly_1:
	AF	$10,3
	AF	$11,3
	AF	$12,3
	AL	$11,3,RedArremer_AnimFly_1
RedArremer_AnimShoot:
	dc.w	RedArremer_AnimShoot_0-*	; 0
	dc.w	RedArremer_AnimShoot_1-*	; 1
RedArremer_AnimShoot_0:
	dc.w	RedArremer_AnimShoot_0_0-*	; 0
	dc.w	RedArremer_AnimShoot_0_1-*	; 1
RedArremer_AnimShoot_0_0:
	AF	$0D,4
	AF	$0E,6
	AL	$0D,4,RedArremer_AnimWalk_0
RedArremer_AnimShoot_0_1:
	AF	$05,4
	AF	$06,6
	AL	$05,4,RedArremer_AnimWalk_1
RedArremer_AnimShoot_1:
	dc.w	RedArremer_AnimShoot_1_0-*	; 0
	dc.w	RedArremer_AnimShoot_1_1-*	; 1
RedArremer_AnimShoot_1_0:
