;---------------------------------------------------------------------------
; === Satan (type 6, 3000 pts, 4 hits (boss)) ===
; Big winged demon boss of levels 4-5: flies at Arthur, fires, and on its last hit calls BossKilled (key drop / weapon check).
; Dispatches on O_State: 0 main behaviour, 1 type-specific second phase, 2 killed (set by EnemyHitByShot after scoring), 3 remove.
;
; Behaviour, as coded:
;   * Sleeps until it is in view (parameter 1: for a further 6 x 64 frames, during which
;     it can be hit; 3 hits wake it, but its HP is then reset to 4).
;   * Hovers for 180 frames, drifting slowly (one of 4 directions, re-chosen every
;     128 frames; always down when Arthur is 64+ pixels below), turning to face Arthur.
;     While hovering it fires (enemy shot type 11, aimed in 16 directions) every 45-65
;     frames, and every 47-90 frames folds its wings for 30 frames, when shots pass
;     through it (O_Active bit 7).
;   * Then attacks: from above, a U-shaped dive (sine curve) down to around Arthur's
;     height and up again while flying across at 2-2.25 px/frame; level with Arthur, it
;     flies across and climbs out of the second half of the dive; from below, it flies
;     straight at him at 3.5 px/frame. Then it hovers again.
;   * If it leaves the screen it flies back in for 16-31 frames, then attacks again.
; Bug: the dying state waits for its timer to reach 0 the wrong way round (beq instead
; of bne), so the 63-frame pause after the explosion is skipped.
;---------------------------------------------------------------------------
Enemy_Satan:
        move.b  O_State(a5),d0                  ; 0EE1C
        add.w   d0,d0                           ; 0EE20
        add.w   d0,d0                           ; 0EE22
        jmp     Enemy_Satan_Jumps(pc,d0.w)      ; 0EE24
Enemy_Satan_Jumps:
        bra.w   Satan_Init                      ; 0EE28
        bra.w   Satan_Active                    ; 0EE2C
        bra.w   Satan_Dying                     ; 0EE30
        bra.w   Satan_Free                      ; 0EE34

;---------------------------------------------------------------------------
; State 0: 4 HP, size class 4, face Arthur, then sleep until in view
;---------------------------------------------------------------------------
Satan_Init:
        tst.b   O_Step(a5)                      ; 0EE38
        bne.b   Satan_Sleep                     ; 0EE3C
        move.b  #$4,O_HP(a5)                    ; 0EE3E
        move.b  #$4,O_Size(a5)                  ; 0EE44
        move.w  O_X(a5),d0                      ; 0EE4A
        cmp.w   g_ArthurX(a6),d0                ; 0EE4E
        slt.b   O_Dir(a5)                       ; 0EE52  O_Dir 0 if Arthur is to the right, 1 if to the left
        addq.b  #$1,O_Dir(a5)                   ; 0EE56
        lea.l   Satan_AnimGuard(pc),a0          ; 0EE5A
        bsr.w   SetAnimIndexed                  ; 0EE5E  start animation for current direction
        clr.b   Sat_Returning(a5)               ; 0EE62
        clr.b   Sat_Hold(a5)                    ; 0EE66
        move.b  #$6,Sat_WakeDelay(a5)           ; 0EE6A
        addq.b  #$1,O_Step(a5)                  ; 0EE70  next step
        rts                                     ; 0EE74

;---------------------------------------------------------------------------
; Shots pass through while it sleeps ($81). Wake when inside the camera window
; (0-256, 0-240); parameter 1 waits a further Sat_WakeDelay x 64 frames.
;---------------------------------------------------------------------------
Satan_Sleep:
        move.b  #$81,(a5)                       ; 0EE76  active, shots pass through
        move.w  O_X(a5),d0                      ; 0EE7A
        sub.w   g_CameraX(a6),d0                ; 0EE7E
        cmp.w   #$100,d0                        ; 0EE82
        bhi.b   l_0EED2                         ; 0EE86
        move.w  O_Y(a5),d0                      ; 0EE88
        sub.w   g_CameraY(a6),d0                ; 0EE8C
        cmp.w   #$f0,d0                         ; 0EE90
        bhi.b   l_0EED2                         ; 0EE94
        tst.b   O_Param(a5)                     ; 0EE96
        beq.b   l_0EEBA                         ; 0EE9A
        move.b  #$1,(a5)                        ; 0EE9C
        cmpi.b  #$1,O_HP(a5)                    ; 0EEA0  parameter 1 is hittable while it waits: down to 1 HP wakes it at once
        beq.b   l_0EEBA                         ; 0EEA6
        moveq   #$3f,d0                         ; 0EEA8  every 64 frames
        and.w   g_GameFrame(a6),d0              ; 0EEAA
        cmp.w   #$3f,d0                         ; 0EEAE
        bne.b   l_0EED2                         ; 0EEB2
        subq.b  #$1,Sat_WakeDelay(a5)           ; 0EEB4
        bne.b   l_0EED2                         ; 0EEB8
l_0EEBA:
        move.b  #$4,O_HP(a5)                    ; 0EEBA  4 hits (damage taken while waiting is forgotten)
        move.b  #ST_ACTIVE,O_State(a5)          ; 0EEC0
        clr.b   O_Step(a5)                      ; 0EEC6
        clr.b   O_Step2(a5)                     ; 0EECA
        move.b  #$1,(a5)                        ; 0EECE
l_0EED2:
        rts                                     ; 0EED2

;---------------------------------------------------------------------------
; State 1. O_Step 0 = hover (O_Step2 0 count, 1 set up, 2 face, 3 hover),
; O_Step 1 = attack (O_Step2 0 aim, 1 dive, 2 fly to the dive point, 3 fly straight).
;---------------------------------------------------------------------------
Satan_Active:
        tst.b   O_Step(a5)                      ; 0EED4
        bne.w   Satan_Attack                    ; 0EED8
        clr.w   d0                              ; 0EEDC
        move.b  O_Step2(a5),d0                  ; 0EEDE
        add.w   d0,d0                           ; 0EEE2
        add.w   d0,d0                           ; 0EEE4
        jmp     Satan_Active_Jumps(pc,d0.w)     ; 0EEE6
Satan_Active_Jumps:
        bra.w   Satan_Engage                    ; 0EEEA
        bra.w   Satan_HoverStart                ; 0EEEE
        bra.w   Satan_Face                      ; 0EEF2
        bra.w   Satan_Hover                     ; 0EEF6
Satan_Engage:
        addq.b  #$1,g_BigEnemyCount(a6)         ; 0EEFA
        addq.b  #$1,O_Step2(a5)                 ; 0EEFE
        rts                                     ; 0EF02

;---------------------------------------------------------------------------
; 180 frames of hovering
;---------------------------------------------------------------------------
Satan_HoverStart:
        move.b  #$b4,Sat_Timer(a5)              ; 0EF04
        clr.b   Sat_FirePhase(a5)               ; 0EF0A
        move.b  #$1e,Sat_GuardTime(a5)          ; 0EF0E  guard 30 frames
        bsr.w   Satan_RandomFireTime            ; 0EF14
        move.b  d0,Sat_FireTime(a5)             ; 0EF18
        clr.b   Sat_Swoop(a5)                   ; 0EF1C
        clr.b   Sat_Drift(a5)                   ; 0EF20
        move.w  g_ArthurX(a6),d0                ; 0EF24
        cmp.w   O_X(a5),d0                      ; 0EF28
        scs.b   O_Dir(a5)                       ; 0EF2C
        addq.b  #$1,O_Dir(a5)                   ; 0EF30
        addq.b  #$1,O_Step2(a5)                 ; 0EF34
        rts                                     ; 0EF38
Satan_Face:
        lea.l   Satan_AnimHover(pc),a0          ; 0EF3A
        bsr.w   SetAnimIndexed                  ; 0EF3E  start animation for current direction
        addq.b  #$1,O_Step2(a5)                 ; 0EF42
Satan_Hover:
        bsr.w   Animate                         ; 0EF46  animate
        bsr.w   Satan_KeepOnScreen              ; 0EF4A
        tst.b   Sat_Returning(a5)               ; 0EF4E
        bne.b   l_0EF94                         ; 0EF52
        tst.b   Sat_Hold(a5)                    ; 0EF54
        bne.b   l_0EF8E                         ; 0EF58
        move.w  O_X(a5),d0                      ; 0EF5A  turn round when Arthur passes it
        cmp.w   g_ArthurX(a6),d0                ; 0EF5E
        scs.b   d0                              ; 0EF62
        addq.b  #$1,d0                          ; 0EF64
        cmp.b   O_Dir(a5),d0                    ; 0EF66
        beq.b   l_0EF76                         ; 0EF6A
        move.b  d0,O_Dir(a5)                    ; 0EF6C
        move.b  #$2,O_Step2(a5)                 ; 0EF70
l_0EF76:
        bsr.b   Satan_FireCycle                 ; 0EF76
        subq.b  #$1,Sat_Timer(a5)               ; 0EF78
        bne.b   l_0EF9A                         ; 0EF7C
l_0EF7E:
        move.b  #$1,O_Step(a5)                  ; 0EF7E
        clr.b   O_Step2(a5)                     ; 0EF84
        move.b  #$1,(a5)                        ; 0EF88
        rts                                     ; 0EF8C
l_0EF8E:
        subq.b  #$1,Sat_Timer(a5)               ; 0EF8E
        beq.b   l_0EF7E                         ; 0EF92
l_0EF94:
        move.b  #$1,(a5)                        ; 0EF94
        rts                                     ; 0EF98
l_0EF9A:
        moveq   #$7f,d0                         ; 0EF9A  every 128 frames pick a new drift
        and.w   g_GameFrame(a6),d0              ; 0EF9C
        cmp.w   #$7f,d0                         ; 0EFA0
        bne.b   l_0EFC8                         ; 0EFA4
        move.w  g_ArthurY(a6),d0                ; 0EFA6  Arthur 64+ px below: drift down
        addi.w  #$40,d0                         ; 0EFAA
        sub.w   O_Y(a5),d0                      ; 0EFAE
        bpl.b   l_0EFBC                         ; 0EFB2
        moveq   #$3,d0                          ; 0EFB4
        move.b  d0,Sat_Drift(a5)                ; 0EFB6
        bra.b   l_0EFC8                         ; 0EFBA
l_0EFBC:
        bsr.w   Random                          ; 0EFBC  random number
        andi.b  #$3,d0                          ; 0EFC0
        move.b  d0,Sat_Drift(a5)                ; 0EFC4
l_0EFC8:
        lea.l   Satan_DriftSpeed(pc),a0         ; 0EFC8
        move.b  Sat_Drift(a5),d0                ; 0EFCC
        bsr.w   Satan_MoveDir                   ; 0EFD0
        bra.w   Satan_KeepAboveGround           ; 0EFD4

;---------------------------------------------------------------------------
; Hover drift (8.8): +-0.44 px/frame horizontally (0, 1), vertically (2, 3)
;---------------------------------------------------------------------------
Satan_DriftSpeed:
	dc.b	$00,$70,$FF,$90,$00,$70,$FF,$90

;---------------------------------------------------------------------------
; Shoot every Sat_ShotWait frames for Sat_FireTime frames, then guard for 30 frames
; (shots pass through), then start again
;---------------------------------------------------------------------------
Satan_FireCycle:
        tst.b   Sat_FirePhase(a5)               ; 0EFE0
        bne.b   l_0F008                         ; 0EFE4
        tst.b   O_OnScreen(a5)                  ; 0EFE6
        beq.b   l_0EFFC                         ; 0EFEA
        subq.b  #$1,Sat_ShotWait(a5)            ; 0EFEC  shot gap
        bne.b   l_0EFFC                         ; 0EFF0
        bsr.w   Satan_Shoot                     ; 0EFF2
        bsr.b   Satan_RandomShotGap             ; 0EFF6
        move.b  d0,Sat_ShotWait(a5)             ; 0EFF8
l_0EFFC:
        subq.b  #$1,Sat_FireTime(a5)            ; 0EFFC
        bne.b   l_0F052                         ; 0F000
        addq.b  #$1,Sat_FirePhase(a5)           ; 0F002
        rts                                     ; 0F006
l_0F008:
        cmpi.b  #$1,Sat_FirePhase(a5)           ; 0F008
        bne.b   l_0F02C                         ; 0F00E
        lea.l   Satan_AnimGuard(pc),a0          ; 0F010
        bsr.w   SetAnimIndexed                  ; 0F014  start animation for current direction
        move.b  #$81,(a5)                       ; 0F018  guarding: shots pass through
        subq.b  #$1,Sat_GuardTime(a5)           ; 0F01C
        bne.b   l_0F052                         ; 0F020
        addq.b  #$1,Sat_FirePhase(a5)           ; 0F022
        move.b  #$1,(a5)                        ; 0F026  hittable again
        rts                                     ; 0F02A
l_0F02C:
        cmpi.b  #$2,Sat_FirePhase(a5)           ; 0F02C
        bne.b   l_0F052                         ; 0F032
        lea.l   Satan_AnimHover(pc),a0          ; 0F034
        bsr.w   SetAnimIndexed                  ; 0F038  start animation for current direction
        clr.b   Sat_FirePhase(a5)               ; 0F03C
        move.b  #$1e,Sat_GuardTime(a5)          ; 0F040
        bsr.b   Satan_RandomFireTime            ; 0F046
        move.b  d0,Sat_FireTime(a5)             ; 0F048
        move.b  #$5,Sat_ShotWait(a5)            ; 0F04C
l_0F052:
        rts                                     ; 0F052
Satan_RandomFireTime:
        bsr.w   Random                          ; 0F054  random number
        andi.w  #$3,d0                          ; 0F058
        move.b  SatanFireTimes(pc,d0.w),d0      ; 0F05C
        rts                                     ; 0F060
Satan_RandomShotGap:
        bsr.w   Random                          ; 0F062  random number
        andi.w  #$3,d0                          ; 0F066
        move.b  SatanShotGaps(pc,d0.w),d0       ; 0F06A
        rts                                     ; 0F06E

;---------------------------------------------------------------------------
; 47, 60, 90, 47 frames
;---------------------------------------------------------------------------
SatanFireTimes:
	dc.b	$2F,$3C,$5A,$2F

;---------------------------------------------------------------------------
; 65, 60, 50, 45 frames
;---------------------------------------------------------------------------
SatanShotGaps:
	dc.b	$41,$3C,$32,$2D

;---------------------------------------------------------------------------
; Dive animation for its 16-way direction (facing left for directions 5-12)
;---------------------------------------------------------------------------
Satan_DiveAnim:
        moveq   #$2,d0                          ; 0F078
        move.b  O_Dir(a5),d1                    ; 0F07A
        cmp.b   #$5,d1                          ; 0F07E
        bcs.b   l_0F08C                         ; 0F082
        cmp.b   #$c,d1                          ; 0F084
        bhi.b   l_0F08C                         ; 0F088
        moveq   #$0,d0                          ; 0F08A
l_0F08C:
        lea.l   Satan_AnimDive(pc),a0           ; 0F08C
        adda.w  d0,a0                           ; 0F090
        adda.w  (a0),a0                         ; 0F092
Satan_SetAnim:
        bra.w   SetAnim                         ; 0F094

;---------------------------------------------------------------------------
; X += word table a0[O_Dir] (8.8)
;---------------------------------------------------------------------------
Satan_MoveX:
        move.b  O_Dir(a5),d0                    ; 0F098
l_0F09C:
        ext.w   d0                              ; 0F09C
        add.w   d0,d0                           ; 0F09E
        move.w  (a0,d0.w),d0                    ; 0F0A0
        ext.l   d0                              ; 0F0A4
        asl.l   #$8,d0                          ; 0F0A6
        add.l   d0,O_X(a5)                      ; 0F0A8
        rts                                     ; 0F0AC

;---------------------------------------------------------------------------
; Y += word table a0[d0] (8.8)
;---------------------------------------------------------------------------
Satan_MoveY:
        ext.w   d0                              ; 0F0AE
        add.w   d0,d0                           ; 0F0B0
        move.w  (a0,d0.w),d0                    ; 0F0B2
        ext.l   d0                              ; 0F0B6
        asl.l   #$8,d0                          ; 0F0B8
        add.l   d0,O_Y(a5)                      ; 0F0BA
        rts                                     ; 0F0BE
Satan_Attack:
        bsr.w   Satan_KeepOnScreen              ; 0F0C0
