        bne.b   l_0F0E2                         ; 0F0C8
        tst.b   O_Step(a5)                      ; 0F0CA
        beq.b   l_0F0E2                         ; 0F0CE
        clr.w   d0                              ; 0F0D0
        move.b  O_Step2(a5),d0                  ; 0F0D2
        add.w   d0,d0                           ; 0F0D6
        add.w   d0,d0                           ; 0F0D8
        jsr     Satan_Attack_Jumps(pc,d0.w)     ; 0F0DA
        bra.w   CheckFarAway                    ; 0F0DE
l_0F0E2:
