;---------------------------------------------------------------------------
; Choose the attack. Level with Arthur (direction 0 or 8): swoop. Below him: fly
; straight at him. Above him: dive to his Y +-24/32 (random), with the phase step
; worked out from the height so a deeper dive takes longer.
;---------------------------------------------------------------------------
Satan_Aim:
        move.w  g_ArthurX(a6),Sat_TargetX(a5)   ; 0F0F4
        bsr.w   DirectionToArthur               ; 0F0FA  directions 0 / 8: level with Arthur
        andi.b  #$7,d0                          ; 0F0FE
        beq.b   l_0F11E                         ; 0F102
        move.w  O_Y(a5),d0                      ; 0F104  below Arthur?
        sub.w   g_ArthurY(a6),d0                ; 0F108
        bpl.b   l_0F124                         ; 0F10C
        bsr.w   DirectionToArthur               ; 0F10E  direction towards Arthur
        move.b  d0,O_Dir(a5)                    ; 0F112
        move.b  #$3,O_Step2(a5)                 ; 0F116
        rts                                     ; 0F11C
l_0F11E:
        move.b  #$1,Sat_Swoop(a5)               ; 0F11E
l_0F124:
        move.w  O_Y(a5),d0                      ; 0F124
        sub.w   g_ArthurY(a6),d0                ; 0F128
        ext.l   d0                              ; 0F12C
        bpl.b   l_0F132                         ; 0F12E
        neg.l   d0                              ; 0F130
l_0F132:
        lea.l   SatanDiveSpeed(pc),a0           ; 0F132
        move.l  a0,Sat_FlySpeed(a5)             ; 0F136
        move.w  $2(a0),d1                       ; 0F13A
        lsl.l   #$8,d0                          ; 0F13E
        divu.w  d1,d0                           ; 0F140  d0 = |dy| / 2
        bne.b   l_0F14A                         ; 0F142
        move.b  #$ff,d1                         ; 0F144
        bra.b   l_0F154                         ; 0F148
l_0F14A:
        move.l  #$7f00,d1                       ; 0F14A  phase step = 127 / d0: the whole dive takes about |dy| frames
        divu.w  d0,d1                           ; 0F150
        lsr.w   #$8,d1                          ; 0F152
l_0F154:
        move.b  d1,Sat_Timer(a5)                ; 0F154
        move.w  O_X(a5),d0                      ; 0F158
        cmp.w   g_ArthurX(a6),d0                ; 0F15C
        scc.b   O_Dir(a5)                       ; 0F160  O_Dir 0 = fly left, 1 = fly right
        addq.b  #$1,O_Dir(a5)                   ; 0F164
        lea.l   Satan_AnimDive(pc),a0           ; 0F168
        bsr.w   SetAnimIndexed                  ; 0F16C  start animation for current direction
        bsr.w   Random                          ; 0F170  random number
        andi.w  #$3,d0                          ; 0F174
        add.w   d0,d0                           ; 0F178
        lea.l   SatanDiveOffsets(pc),a0         ; 0F17A
        adda.w  d0,a0                           ; 0F17E
        move.w  g_ArthurY(a6),d0                ; 0F180
        add.w   (a0),d0                         ; 0F184
        sub.w   O_Y(a5),d0                      ; 0F186
        bpl.b   l_0F18E                         ; 0F18A
        neg.w   d0                              ; 0F18C
l_0F18E:
        move.b  d0,Sat_ArcHeight(a5)            ; 0F18E
        move.w  O_Y(a5),Sat_ArcBaseY(a5)        ; 0F192
        clr.b   Sat_ArcPhase(a5)                ; 0F198
        tst.b   Sat_Swoop(a5)                   ; 0F19C
        beq.b   l_0F1BC                         ; 0F1A0
        addi.w  #$60,Sat_ArcBaseY(a5)           ; 0F1A2  swoop: start at the bottom of a 96-pixel dive
        move.b  #$80,Sat_ArcPhase(a5)           ; 0F1A8
        move.b  #$60,Sat_ArcHeight(a5)          ; 0F1AE
        move.b  #$2,O_Step2(a5)                 ; 0F1B4
        rts                                     ; 0F1BA
l_0F1BC:
        addq.b  #$1,O_Step2(a5)                 ; 0F1BC
        rts                                     ; 0F1C0

;---------------------------------------------------------------------------
; Horizontal dive speed, 8.8: first half -2/+2, second half -2.25/+2.25 (0 = left)
;---------------------------------------------------------------------------
SatanDiveSpeed:
	dc.b	$FE,$00,$02,$00

;---------------------------------------------------------------------------
; X speed by O_Dir for the second half of the dive: -2.25 / +2.25 px/frame (8.8)
;---------------------------------------------------------------------------
SatanDiveSpeedFast:
	dc.b	$FD,$C0,$02,$40

