SatanFlyTable:
	dc.b	$03,$80,$00,$00,$03,$3B,$FE,$AA,$02,$79,$FD,$87,$01,$56,$FC,$C5
	dc.b	$00,$00,$FC,$80,$FE,$AA,$FC,$C5,$FD,$87,$FD,$87,$FC,$C5,$FE,$AA
	dc.b	$FC,$80,$00,$00,$FC,$C5,$01,$56,$FD,$87,$02,$79,$FE,$AA,$03,$3B
	dc.b	$00,$00,$03,$80,$01,$56,$03,$3B,$02,$79,$02,$79,$03,$3B,$01,$56

;---------------------------------------------------------------------------
; Y = Sat_ArcBaseY - Sat_ArcHeight x 2 x sin(phase); ends when the phase wraps.
; Falls through into Satan_FlyToDive, so it moves sideways twice per frame.
;---------------------------------------------------------------------------
Satan_Dive:
        movea.l Sat_FlySpeed(a5),a0             ; 0F21A
        tst.b   Sat_Swoop(a5)                   ; 0F21E
        bne.b   l_0F230                         ; 0F222
        cmpi.b  #$7f,Sat_ArcPhase(a5)           ; 0F224  second half of the dive: 2.25 px/frame
        bcs.b   l_0F230                         ; 0F22A
        lea.l   SatanDiveSpeedFast(pc),a0       ; 0F22C
l_0F230:
        bsr.w   Satan_MoveX                     ; 0F230
        bsr.w   Animate                         ; 0F234  animate
        lea.l   SineTable(pc),a0                ; 0F238  sine table (shared with the Blue Killer)
        clr.w   d0                              ; 0F23C
        move.b  Sat_ArcPhase(a5),d0             ; 0F23E
        move.b  (a0,d0.w),d0                    ; 0F242
        add.b   d0,d0                           ; 0F246
        clr.w   d1                              ; 0F248
        move.b  Sat_ArcHeight(a5),d1            ; 0F24A
        mulu.w  d1,d0                           ; 0F24E
        lsr.w   #$8,d0                          ; 0F250
        move.w  d0,Sat_ArcDepth(a5)             ; 0F252
        move.w  Sat_ArcBaseY(a5),d1             ; 0F256
        sub.w   d0,d1                           ; 0F25A
        move.w  d1,O_Y(a5)                      ; 0F25C
        bsr.w   Satan_KeepAboveGround           ; 0F260
        move.b  Sat_ArcPhase(a5),d0             ; 0F264
        add.b   Sat_Timer(a5),d0                ; 0F268  phase wrapped: hover again
        bcc.b   l_0F278                         ; 0F26C
        clr.b   O_Step(a5)                      ; 0F26E
        move.b  #$1,O_Step2(a5)                 ; 0F272
l_0F278:
        move.b  d0,Sat_ArcPhase(a5)             ; 0F278

;---------------------------------------------------------------------------
; Fly sideways until within 16 px of Sat_TargetX, then dive
;---------------------------------------------------------------------------
Satan_FlyToDive:
        movea.l Sat_FlySpeed(a5),a0             ; 0F27C
        bsr.w   Satan_MoveX                     ; 0F280
        bsr.w   Animate                         ; 0F284  animate
        move.w  O_X(a5),d0                      ; 0F288
        sub.w   Sat_TargetX(a5),d0              ; 0F28C
        addi.w  #$10,d0                         ; 0F290
        cmp.w   #$20,d0                         ; 0F294
        bcc.b   l_0F2A0                         ; 0F298
        move.b  #$1,O_Step2(a5)                 ; 0F29A
l_0F2A0:
