;---------------------------------------------------------------------------
; Fly in its 16-way direction until it leaves the screen
;---------------------------------------------------------------------------
Satan_FlyStraight:
        lea.l   SatanFlyTable(pc),a0            ; 0F2A2
        bsr.w   ApplyMoveA0                     ; 0F2A6
        bsr.w   Satan_DiveAnim                  ; 0F2AA
        rts                                     ; 0F2AE

;---------------------------------------------------------------------------
; Enemy shot type 11 aimed at Arthur (16 directions)
;---------------------------------------------------------------------------
Satan_Shoot:
        bsr.w   FindFreeEnemyShot               ; 0F2B0  find a free enemy-projectile slot (fires a shot)
        bne.b   l_0F2E0                         ; 0F2B4
