        move.b  d0,$12(a4)                      ; 0F2BA
        move.w  O_X(a5),$6(a4)                  ; 0F2BE
        move.w  O_Y(a5),$a(a4)                  ; 0F2C4
        clr.b   $3(a4)                          ; 0F2CA
        clr.b   $4(a4)                          ; 0F2CE
        clr.b   $5(a4)                          ; 0F2D2
        move.b  #$1,(a4)                        ; 0F2D6
        move.b  #$b,$1a(a4)                     ; 0F2DA  enemy shot type 11
l_0F2E0:
        rts                                     ; 0F2E0

;---------------------------------------------------------------------------
; Near the bottom of the level (camera Y <= 46): keep Y >= 65 - camera Y
;---------------------------------------------------------------------------
Satan_KeepAboveGround:
        move.w  g_CameraY(a6),d0                ; 0F2E2
        cmp.w   #$2e,d0                         ; 0F2E6
        bhi.b   l_0F2FA                         ; 0F2EA
        moveq   #$41,d1                         ; 0F2EC
        sub.w   d0,d1                           ; 0F2EE
        sub.w   O_Y(a5),d1                      ; 0F2F0
        bmi.b   l_0F2FA                         ; 0F2F4
        add.w   d1,O_Y(a5)                      ; 0F2F6
l_0F2FA:
        rts                                     ; 0F2FA

;---------------------------------------------------------------------------
; Off screen (32 px left, 32 right, below or above the camera): fly back in for
; 16-31 frames, then attack again
;---------------------------------------------------------------------------
Satan_KeepOnScreen:
        tst.b   Sat_Returning(a5)               ; 0F2FC
        bne.b   l_0F36E                         ; 0F300
        move.w  g_CameraX(a6),d0                ; 0F302
        subi.w  #$20,d0                         ; 0F306
        cmp.w   O_X(a5),d0                      ; 0F30A
        bgt.b   l_0F330                         ; 0F30E
        addi.w  #$140,d0                        ; 0F310
        cmp.w   O_X(a5),d0                      ; 0F314
        blt.b   l_0F33E                         ; 0F318
        move.w  g_CameraY(a6),d0                ; 0F31A
        cmp.w   O_Y(a5),d0                      ; 0F31E
        bgt.b   l_0F34E                         ; 0F322
        addi.w  #$100,d0                        ; 0F324
        cmp.w   O_Y(a5),d0                      ; 0F328
        blt.b   l_0F356                         ; 0F32C
        bra.b   l_0F36E                         ; 0F32E
l_0F330:
        clr.b   Sat_ReturnDir(a5)               ; 0F330
        lea.l   Satan_AnimReturnL(pc),a0        ; 0F334
        bsr.w   Satan_SetAnim                   ; 0F338
        bra.b   l_0F35C                         ; 0F33C
l_0F33E:
        move.b  #$1,Sat_ReturnDir(a5)           ; 0F33E
        lea.l   Satan_AnimReturnR(pc),a0        ; 0F344
        bsr.w   Satan_SetAnim                   ; 0F348
        bra.b   l_0F35C                         ; 0F34C
l_0F34E:
        move.b  #$2,Sat_ReturnDir(a5)           ; 0F34E
        bra.b   l_0F35C                         ; 0F354
l_0F356:
        move.b  #$3,Sat_ReturnDir(a5)           ; 0F356
l_0F35C:
        moveq   #$3,d0                          ; 0F35C
        and.w   g_GameFrame(a6),d0              ; 0F35E
        move.b  SatanReturnTimes(pc,d0.w),Sat_ReturnTime(a5); 0F362
        move.b  #$1,Sat_Returning(a5)           ; 0F368
l_0F36E:
        tst.b   Sat_Returning(a5)               ; 0F36E
        beq.b   l_0F39C                         ; 0F372
        subq.b  #$1,Sat_ReturnTime(a5)          ; 0F374
        beq.b   l_0F38E                         ; 0F378
        lea.l   SatanReturnSpeed(pc),a0         ; 0F37A
        move.b  Sat_ReturnDir(a5),d0            ; 0F37E

;---------------------------------------------------------------------------
; d0 < 2: move X, else move Y, from word table a0
;---------------------------------------------------------------------------
Satan_MoveDir:
        cmp.b   #$2,d0                          ; 0F382
        bcs.w   l_0F09C                         ; 0F386
        bra.w   Satan_MoveY                     ; 0F38A
l_0F38E:
        move.b  #$1,O_Step(a5)                  ; 0F38E
        clr.b   O_Step2(a5)                     ; 0F394
        clr.b   Sat_Returning(a5)               ; 0F398
l_0F39C:
        rts                                     ; 0F39C

;---------------------------------------------------------------------------
; 31, 21, 26, 16 frames
;---------------------------------------------------------------------------
SatanReturnTimes:
	dc.b	$1F,$15,$1A,$10

;---------------------------------------------------------------------------
; +3, -3 px/frame in X; +4, -4 in Y
;---------------------------------------------------------------------------
SatanReturnSpeed:
	dc.b	$03,$00,$FD,$00,$04,$00,$FC,$00

;---------------------------------------------------------------------------
; State 2: sound 12, EnemyExplode, then (should) wait 63 frames
;---------------------------------------------------------------------------
Satan_Dying:
        cmpi.b  #$1,O_Step(a5)                  ; 0F3AA
        beq.b   l_0F3C4                         ; 0F3B0
        bcc.b   l_0F3C8                         ; 0F3B2
        move.b  #$3f,Sat_Returning(a5)          ; 0F3B4
        addq.b  #$1,O_Step(a5)                  ; 0F3BA  next step
        moveq   #SFX_ENEMY_HIT,d0               ; 0F3BE
        bra.w   PlaySfx                         ; 0F3C0
l_0F3C4:
