l_0F3C8:
        move.b  #$2,O_Size(a5)                  ; 0F3C8
        subq.b  #$1,Sat_Returning(a5)           ; 0F3CE  BUG: beq should be bne - goes to state 3 after one frame
        beq.b   l_0F3DA                         ; 0F3D2
        move.b  #ST_REMOVE,O_State(a5)          ; 0F3D4
l_0F3DA:
        rts                                     ; 0F3DA

