; State 3: free the slot, BossKilled, give the spawn quota back
;---------------------------------------------------------------------------
Satan_Free:
        clr.b   (a5)                            ; 0F3DC  free this enemy slot
        bsr.w   BossKilled                      ; 0F3DE  boss defeated
        addq.b  #$1,g_SpawnQuota+6(a6)          ; 0F3E2
        tst.b   g_BigEnemyCount(a6)             ; 0F3E6
        beq.b   l_0F3F0                         ; 0F3EA
        subq.b  #$1,g_BigEnemyCount(a6)         ; 0F3EC
l_0F3F0:
        rts                                     ; 0F3F0
Satan_AnimHover:
	dc.w	Satan_AnimHover_0-*	; 0
	dc.w	Satan_AnimFlap-*	; 1
Satan_AnimHover_0:
	AF	$05,10
	AF	$06,10
	AF	$07,10
	AL	$06,10,Satan_AnimHover_0

;---------------------------------------------------------------------------
; Satan flapping: frames 0, 1, 2, 1 (also the opening scene's demon)
;---------------------------------------------------------------------------
Satan_AnimFlap:
	AF	$00,10
	AF	$01,10
	AF	$02,10
	AL	$01,10,Satan_AnimFlap
Satan_AnimDive:
	dc.w	Satan_AnimReturnR-*	; 0
	dc.w	Satan_AnimReturnL-*	; 1
Satan_AnimReturnL:
	AL	$08,5,Satan_AnimReturnL
Satan_AnimReturnR:
	AL	$03,5,Satan_AnimReturnR
Satan_AnimGuard:
