;---------------------------------------------------------------------------
; === Magician (type 7, 2000 pts) ===
; Rises from a gravestone Arthur has shot (spawned at g_SceneryHitX/Y), throws off its cloak, casts one spell (enemy shot type 0: turns Arthur into a frog) and fades away. Sound effect 17 when killed.
; Dispatches on O_State: 0 main behaviour, 1 type-specific second phase, 2 killed (set by EnemyHitByShot after scoring), 3 remove.
;
; Behaviour, as coded: the spawner puts it where Arthur last shot a gravestone. It rises
; cloaked for 60 + 20 frames (shots pass through: O_Active 2), throws off the cloak and
; becomes hittable (size class 9), casts one spell at Arthur - enemy shot type 0, which turns
; him into a frog (EnemyShotsVsArthur) - waits 20 frames, then cloaks again and blinks out
; over 60 frames. The graphics are the hooded figure (frames 0-1) and the winged figure
; (frames 2-3).
;---------------------------------------------------------------------------
Enemy_Magician:
        move.b  O_State(a5),d0                  ; 0F422
        add.w   d0,d0                           ; 0F426
        add.w   d0,d0                           ; 0F428
        jmp     Enemy_Magician_Jumps(pc,d0.w)   ; 0F42A
Enemy_Magician_Jumps:
        bra.w   Magician_Init                   ; 0F42E
        bra.w   Magician_Active                 ; 0F432
        bra.w   Magician_Dying                  ; 0F436
        bra.w   Magician_Free                   ; 0F43A

;---------------------------------------------------------------------------
; State 0: shots pass through (O_Active 2), size 3, face Arthur, cloaked
;---------------------------------------------------------------------------
Magician_Init:
        move.b  #$2,(a5)                        ; 0F43E
        move.b  #$3,O_Size(a5)                  ; 0F442
        bsr.b   Magician_FaceArthur             ; 0F448
        lea.l   Magician_AnimCloak(pc),a0       ; 0F44A
        bsr.w   SetAnimIndexed                  ; 0F44E  start animation for current direction
        addq.b  #ST_ACTIVE,O_State(a5)          ; 0F452
        clr.b   O_Step(a5)                      ; 0F456
        clr.b   O_Step2(a5)                     ; 0F45A
        rts                                     ; 0F45E

;---------------------------------------------------------------------------
; O_Dir 0 if Arthur is to the right, 1 if to the left
;---------------------------------------------------------------------------
Magician_FaceArthur:
        move.w  g_ArthurX(a6),d0                ; 0F460
        cmp.w   O_X(a5),d0                      ; 0F464
        scs.b   O_Dir(a5)                       ; 0F468
        neg.b   O_Dir(a5)                       ; 0F46C
        rts                                     ; 0F470

;---------------------------------------------------------------------------
; State 1. O_Step: 0 rise, 1 cast, 2 fade
;---------------------------------------------------------------------------
Magician_Active:
        move.b  O_Step(a5),d0                   ; 0F472
        add.w   d0,d0                           ; 0F476
        add.w   d0,d0                           ; 0F478
        jmp     Magician_Active_Jumps(pc,d0.w)  ; 0F47A
Magician_Active_Jumps:
        bra.w   Magician_Rise                   ; 0F47E
        bra.w   Magician_Cast                   ; 0F482
        bra.w   Magician_Fade                   ; 0F486

;---------------------------------------------------------------------------
; 60 frames, turning to face Arthur
;---------------------------------------------------------------------------
Magician_Rise:
        tst.b   O_Step2(a5)                     ; 0F48A
        bne.b   l_0F49A                         ; 0F48E
        move.b  #$3c,Mag_Timer(a5)              ; 0F490
        addq.b  #$1,O_Step2(a5)                 ; 0F496
l_0F49A:
        subq.b  #$1,Mag_Timer(a5)               ; 0F49A
        beq.b   l_0F4A2                         ; 0F49E
        bra.b   Magician_FaceArthur             ; 0F4A0
l_0F4A2:
        addq.b  #$1,O_Step(a5)                  ; 0F4A2  next step
        clr.b   O_Step2(a5)                     ; 0F4A6
        rts                                     ; 0F4AA
Magician_Cast:
        move.b  O_Step2(a5),d0                  ; 0F4AC
        add.w   d0,d0                           ; 0F4B0
        add.w   d0,d0                           ; 0F4B2
        jmp     Magician_Cast_Jumps(pc,d0.w)    ; 0F4B4
Magician_Cast_Jumps:
        bra.w   Magician_CastStart              ; 0F4B8
        bra.w   Magician_Reveal                 ; 0F4BC
        bra.w   Magician_AfterCast              ; 0F4C0
Magician_CastStart:
        move.b  #$14,Mag_Cast(a5)               ; 0F4C4
        addq.b  #$1,O_Step2(a5)                 ; 0F4CA

;---------------------------------------------------------------------------
; After 20 frames: hittable, size 9, the winged figure, and cast the spell
;---------------------------------------------------------------------------
Magician_Reveal:
        subq.b  #$1,Mag_Cast(a5)                ; 0F4CE
        bne.b   l_0F4F4                         ; 0F4D2
        move.b  #$1,(a5)                        ; 0F4D4  hittable from now on
        move.b  #$9,O_Size(a5)                  ; 0F4D8
        bsr.b   Magician_FaceArthur             ; 0F4DE
        lea.l   Magician_AnimReveal(pc),a0      ; 0F4E0
        bsr.w   SetAnimIndexed                  ; 0F4E4  start animation for current direction
        bsr.b   Magician_Spell                  ; 0F4E8
        move.b  #$14,Mag_Cast(a5)               ; 0F4EA
        addq.b  #$1,O_Step2(a5)                 ; 0F4F0
l_0F4F4:
        bra.w   Animate                         ; 0F4F4

;---------------------------------------------------------------------------
; 20 frames, then fade
;---------------------------------------------------------------------------
Magician_AfterCast:
        subq.b  #$1,Mag_Cast(a5)                ; 0F4F8
        bne.b   l_0F508                         ; 0F4FC
        move.b  #$2,O_Step(a5)                  ; 0F4FE
        clr.b   O_Step2(a5)                     ; 0F504
l_0F508:
        rts                                     ; 0F508

;---------------------------------------------------------------------------
; Enemy shot type 0 (the frog spell) from 10 px below its centre, the way it faces
;---------------------------------------------------------------------------
Magician_Spell:
        bsr.w   FindFreeEnemyShot               ; 0F50A  find a free enemy-projectile slot (fires a shot)
        bne.b   l_0F53A                         ; 0F50E
        move.b  O_Dir(a5),$12(a4)               ; 0F510
        move.w  O_X(a5),$6(a4)                  ; 0F516
        moveq   #-10,d0                         ; 0F51C
        add.w   O_Y(a5),d0                      ; 0F51E
        move.w  d0,$a(a4)                       ; 0F522
        clr.b   $3(a4)                          ; 0F526
        clr.b   $4(a4)                          ; 0F52A
        clr.b   $5(a4)                          ; 0F52E
        move.b  #$1,(a4)                        ; 0F532
        clr.b   $1a(a4)                         ; 0F536  enemy shot type 0: the frog spell
l_0F53A:
        rts                                     ; 0F53A

;---------------------------------------------------------------------------
; Cloak again, shots pass through, blink for 60 frames, then remove
;---------------------------------------------------------------------------
Magician_Fade:
        tst.b   O_Step2(a5)                     ; 0F53C
        bne.b   l_0F562                         ; 0F540
        move.b  #$3c,Mag_Timer(a5)              ; 0F542
        move.b  #$2,(a5)                        ; 0F548  shots pass through again
        move.b  #$3,O_Size(a5)                  ; 0F54C
        bsr.w   Magician_FaceArthur             ; 0F552
        lea.l   Magician_AnimCloak(pc),a0       ; 0F556
        bsr.w   SetAnimIndexed                  ; 0F55A  start animation for current direction
        addq.b  #$1,O_Step2(a5)                 ; 0F55E
l_0F562:
        subq.b  #$1,Mag_Timer(a5)               ; 0F562
        bne.b   l_0F570                         ; 0F566
        move.b  #ST_REMOVE,O_State(a5)          ; 0F568
        rts                                     ; 0F56E
l_0F570:
        moveq   #$2,d0                          ; 0F570  invisible every other 2 frames
        and.w   g_GameFrame(a6),d0              ; 0F572
        beq.b   l_0F57C                         ; 0F576
        clr.l   O_Anim(a5)                      ; 0F578
l_0F57C:
        lea.l   Magician_AnimCloak(pc),a0       ; 0F57C
        bsr.w   SetAnimIndexed                  ; 0F580  start animation for current direction
        bra.w   CheckFarAway                    ; 0F584

;---------------------------------------------------------------------------
; State 2: sound 17, EnemyDieFacing, 63 frames
;---------------------------------------------------------------------------
Magician_Dying:
        cmpi.b  #$1,O_Step(a5)                  ; 0F588
        beq.b   l_0F5A4                         ; 0F58E
        bcc.b   l_0F5A8                         ; 0F590
        moveq   #SFX_ENEMY_DIE,d0               ; 0F592
        bsr.w   PlaySfx                         ; 0F594  sound effect 17 (enemy event)
        move.b  #$3f,Mag_Timer(a5)              ; 0F598
        addq.b  #$1,O_Step(a5)                  ; 0F59E  next step
        rts                                     ; 0F5A2
l_0F5A4:
        bra.w   EnemyDieFacing                  ; 0F5A4
l_0F5A8:
        move.b  #$2,O_Size(a5)                  ; 0F5A8
        subq.b  #$1,Mag_Timer(a5)               ; 0F5AE
        bne.b   l_0F5BA                         ; 0F5B2
        move.b  #ST_REMOVE,O_State(a5)          ; 0F5B4
l_0F5BA:
        rts                                     ; 0F5BA

;---------------------------------------------------------------------------
; State 3: give the spawn quota back, free the slot
;---------------------------------------------------------------------------
Magician_Free:
        addq.b  #$1,g_SpawnQuota+7(a6)          ; 0F5BC
        clr.b   (a5)                            ; 0F5C0  free this enemy slot
        rts                                     ; 0F5C2
Magician_AnimCloak:
	dc.w	Magician_AnimCloak_0-*	; 0
	dc.w	Magician_AnimCloak_1-*	; 1
Magician_AnimReveal:
	dc.w	Magician_AnimReveal_0-*	; 0
	dc.w	Magician_AnimReveal_1-*	; 1
Magician_AnimCloak_0:
	AL	$00,1,Magician_AnimCloak_0
Magician_AnimCloak_1:
	AL	$01,1,Magician_AnimCloak_1
Magician_AnimReveal_0:
	AL	$03,1,Magician_AnimReveal_0
Magician_AnimReveal_1:
	AL	$02,1,Magician_AnimReveal_1

;---------------------------------------------------------------------------
; === Unicorn (Cyclops) (type 8, 2000 pts, 10 hits (boss)) ===
; Boss of level 0 (one, at the gate) and level 1 (two); also on level 5. Drawn as two BOBs (legs + body).
; Dispatches on O_State: 0 main behaviour, 1 type-specific second phase, 2 killed (set by EnemyHitByShot after scoring), 3 remove.
;
; Behaviour, as coded:
;   * Waits (Uni_Delay x 16 frames) once Arthur is near its level, then walks to a walk
;     script, turning back at the edges of its arena (Unicorn_ChooseWalkDir).
;   * Fires a shot (enemy shot type 1, straight ahead) whenever Unicorn_ShotScript says so:
;     fire pose for 40 frames, shot, 25 frames recovery.
;   * Jumps over Arthur's weapons: any of Arthur's shots flying towards it within 56 pixels
;     starts a jump (Unicorn_CheckThreats).
;   * Keeps its distance: Uni_Approach asks to walk towards Arthur when he is 120+ pixels away
;     and away from him when closer than 32 (unicorn on the left) / 56 (on the right).
;   * After a random 51-130 frames it gets angry: next it either charges at Arthur
;     (Unicorn_Charge) or jumps at him (Unicorn_JumpAt), 50/50 (always the charge for variant 2).
;---------------------------------------------------------------------------
Enemy_Unicorn:
        move.b  O_State(a5),d0                  ; 0F5DC
        add.w   d0,d0                           ; 0F5E0
        add.w   d0,d0                           ; 0F5E2
        jmp     Enemy_Unicorn_Jumps(pc,d0.w)    ; 0F5E4
Enemy_Unicorn_Jumps:
        bra.w   Unicorn_Init                    ; 0F5E8
        bra.w   Unicorn_Active                  ; 0F5EC
        bra.w   Unicorn_Dying                   ; 0F5F0
        bra.w   Unicorn_Free                    ; 0F5F4

;---------------------------------------------------------------------------
; State 0: set up the slot (10 HP, size class 4, scripts, start delay) then wait
; until it is on screen.
;---------------------------------------------------------------------------
Unicorn_Init:
        tst.b   O_Step(a5)                      ; 0F5F8
        bne.w   Unicorn_WaitVisible             ; 0F5FC
        clr.b   Uni_Timer(a5)                   ; 0F600
        clr.b   Uni_Aiming(a5)                  ; 0F604
        clr.b   Uni_Angry(a5)                   ; 0F608
        clr.b   Uni_Approach(a5)                ; 0F60C
        clr.b   Uni_Gravity(a5)                 ; 0F610
        clr.b   Uni_Delay(a5)                   ; 0F614
        clr.w   Uni_ChargeX(a5)                 ; 0F618
        clr.b   Uni_JumpNext(a5)                ; 0F61C
        move.b  O_Param(a5),Uni_Variant(a5)     ; 0F620  variant from the spawn parameter
        move.b  #$4,O_Size(a5)                  ; 0F626
        move.w  O_X(a5),d0                      ; 0F62C
        cmp.w   g_ArthurX(a6),d0                ; 0F630
        slt.b   O_Dir(a5)                       ; 0F634  face Arthur: O_Dir = 1 (right) if he is to the right, else 2 (left)
        addq.b  #$2,O_Dir(a5)                   ; 0F638
        lea.l   Unicorn_AnimStand(pc),a0        ; 0F63C
        move.l  a0,Uni_AnimSet(a5)              ; 0F640
        bsr.w   SetAnimIndexed                  ; 0F644  start animation for current direction
        clr.b   O_AnimTimer(a5)                 ; 0F648
        bsr.w   Animate                         ; 0F64C  animate
        lea.l   Unicorn_ShotScript(pc),a0       ; 0F650
        move.b  (a0)+,Uni_ShotWait(a5)          ; 0F654
        move.l  a0,Uni_ShotPtr(a5)              ; 0F658
        move.b  #$a,O_HP(a5)                    ; 0F65C  10 hits
        move.b  Uni_Variant(a5),d0              ; 0F662
        cmp.b   #$4,d0                          ; 0F666  variant 4: becomes variant 0, delay 10
        beq.b   l_0F67C                         ; 0F66A
        cmp.b   #$3,d0                          ; 0F66C  variant 3: becomes variant 2, delay 10
        bne.b   l_0F680                         ; 0F670
        subq.b  #$1,d0                          ; 0F672
l_0F674:
        move.b  d0,Uni_Variant(a5)              ; 0F674
        moveq   #$a,d0                          ; 0F678
        bra.b   l_0F692                         ; 0F67A
l_0F67C:
        clr.b   d0                              ; 0F67C
        bra.b   l_0F674                         ; 0F67E
l_0F680:
        lea.l   Unicorn_StartDelays(pc),a0      ; 0F680  otherwise a delay of 2-4 x 16 frames
        move.w  g_GameFrame(a6),d0              ; 0F684
        add.w   d7,d0                           ; 0F688
        andi.w  #$3,d0                          ; 0F68A
        move.b  (a0,d0.w),d0                    ; 0F68E
l_0F692:
        move.b  d0,Uni_Delay(a5)                ; 0F692
        addq.b  #$1,O_Step(a5)                  ; 0F696  next step
        rts                                     ; 0F69A
Unicorn_WaitVisible:
        tst.b   O_OnScreen(a5)                  ; 0F69C
        beq.b   l_0F6B0                         ; 0F6A0
        move.b  #ST_ACTIVE,O_State(a5)          ; 0F6A2
        clr.b   O_Step(a5)                      ; 0F6A8
        clr.b   O_Step2(a5)                     ; 0F6AC
l_0F6B0:
        rts                                     ; 0F6B0
	dc.b	$00

;---------------------------------------------------------------------------
; Shot timing script: one byte per shot = frames to wait; bit 7 set = last entry,
; followed by a word offset back to the loop point.
;---------------------------------------------------------------------------
Unicorn_ShotScript:
	dc.b	',> GV6H#@'
	dc.b	$16
	dc.b	'/D8TCW'
	dc.b	$CA,$FF,$EF

;---------------------------------------------------------------------------
; Start delay per spawn (x 16 frames), picked with the frame counter
;---------------------------------------------------------------------------
Unicorn_StartDelays:
	dc.b	$02,$03,$04,$03

;---------------------------------------------------------------------------
; State 1. Does nothing while Arthur is 128+ pixels above it (variant != 0).
; O_Step: 0 wait, 1 walk, 2 jump, 3 charge, 4 reposition, 5 fire.
;---------------------------------------------------------------------------
Unicorn_Active:
        move.w  O_Y(a5),d0                      ; 0F6CA
        sub.w   g_ArthurY(a6),d0                ; 0F6CE
        bpl.b   l_0F6E2                         ; 0F6D2
        cmp.w   #$ff80,d0                       ; 0F6D4  Arthur 128+ pixels above it?
        bgt.b   l_0F6E2                         ; 0F6D8
        tst.b   Uni_Variant(a5)                 ; 0F6DA
        beq.b   l_0F6E2                         ; 0F6DE
        rts                                     ; 0F6E0
l_0F6E2:
        clr.w   d0                              ; 0F6E2
        move.b  O_Step(a5),d0                   ; 0F6E4
        add.w   d0,d0                           ; 0F6E8
        add.w   d0,d0                           ; 0F6EA
        jmp     Unicorn_Active_Jumps(pc,d0.w)   ; 0F6EC
Unicorn_Active_Jumps:
        bra.w   Unicorn_Wait                    ; 0F6F0
        bra.w   Unicorn_WalkStep                ; 0F6F4
        bra.w   Unicorn_JumpStep                ; 0F6F8
        bra.w   Unicorn_Charge                  ; 0F6FC
        bra.w   Unicorn_Reposition              ; 0F700
        bra.w   Unicorn_Fire                    ; 0F704

;---------------------------------------------------------------------------
; Step 0: snap onto the floor, then count down Uni_Delay (every 16 frames).
; Level 5: does not start until Arthur is on its level. Starts at once after a hit (HP 6).
;---------------------------------------------------------------------------
Unicorn_Wait:
        tst.b   O_Step2(a5)                     ; 0F708
        bne.b   l_0F718                         ; 0F70C
        bsr.w   ObjectMapCollide                ; 0F70E  first frame: snap onto the floor
        addq.b  #$1,O_Step2(a5)                 ; 0F712
        rts                                     ; 0F716
l_0F718:
        cmpi.w  #$5,g_Level(a6)                 ; 0F718  level 5: wait until Arthur is no more than 16 pixels below it
        bne.b   l_0F72E                         ; 0F71E
        move.w  g_ArthurY(a6),d0                ; 0F720
        addi.w  #$10,d0                         ; 0F724
        sub.w   O_Y(a5),d0                      ; 0F728
        bmi.b   l_0F756                         ; 0F72C
l_0F72E:
        cmpi.b  #$6,O_HP(a5)                    ; 0F72E  already hit (6 HP left)? start at once
        beq.b   l_0F748                         ; 0F734
        move.w  g_GameFrame(a6),d0              ; 0F736
        addq.w  #$1,d0                          ; 0F73A
        andi.w  #$f,d0                          ; 0F73C
        bne.b   l_0F756                         ; 0F740
        subq.b  #$1,Uni_Delay(a5)               ; 0F742  every 16 frames
        bne.b   l_0F756                         ; 0F746
l_0F748:
        addq.b  #$1,g_BigEnemyCount(a6)         ; 0F748  one more big enemy engaged
        move.b  #$1,O_Step(a5)                  ; 0F74C
        clr.b   O_Step2(a5)                     ; 0F752
l_0F756:
        rts                                     ; 0F756

;---------------------------------------------------------------------------
; Step 1: walk and shoot. Removed if it ends up far off screen.
;---------------------------------------------------------------------------
Unicorn_WalkStep:
        move.w  O_X(a5),d0                      ; 0F758  more than 256 px left / 768 right of the camera, or 160 below / 416 above it: remove
        sub.w   g_CameraX(a6),d0                ; 0F75C
        addi.w  #$100,d0                        ; 0F760
        cmp.w   #$400,d0                        ; 0F764
        bhi.b   l_0F77C                         ; 0F768
        move.w  O_Y(a5),d0                      ; 0F76A
        sub.w   g_CameraY(a6),d0                ; 0F76E
        addi.w  #$a0,d0                         ; 0F772
        cmp.w   #$240,d0                        ; 0F776
        bls.b   l_0F78A                         ; 0F77A
l_0F77C:
        move.b  #ST_REMOVE,O_State(a5)          ; 0F77C
        clr.b   O_Step(a5)                      ; 0F782
        clr.b   O_Step2(a5)                     ; 0F786
l_0F78A:
        tst.b   O_Step2(a5)                     ; 0F78A
        bne.b   l_0F796                         ; 0F78E
        bsr.w   Unicorn_WalkStart               ; 0F790
        bra.b   l_0F79A                         ; 0F794
l_0F796:
        bsr.w   Unicorn_Walk                    ; 0F796
l_0F79A:
        bsr.w   Unicorn_CheckThreats            ; 0F79A

;---------------------------------------------------------------------------
; Count down to the next shot; then take the fire pose for 40 frames and go to step 5
;---------------------------------------------------------------------------
Unicorn_ShotTimer:
        tst.b   Uni_Aiming(a5)                  ; 0F79E
        bne.b   l_0F7E4                         ; 0F7A2
        subq.b  #$1,Uni_ShotWait(a5)            ; 0F7A4
        bne.b   l_0F812                         ; 0F7A8
        movea.l Uni_ShotPtr(a5),a0              ; 0F7AA
        move.b  (a0)+,d0                        ; 0F7AE
        bpl.b   l_0F7B8                         ; 0F7B0  bit 7: last entry, loop
        adda.w  (a0),a0                         ; 0F7B2
        andi.b  #$7f,d0                         ; 0F7B4
l_0F7B8:
        move.l  a0,Uni_ShotPtr(a5)              ; 0F7B8
        move.b  d0,Uni_ShotWait(a5)             ; 0F7BC
        move.b  #$1,Uni_Aiming(a5)              ; 0F7C0
        lea.l   Unicorn_AnimAim(pc),a0          ; 0F7C6
        move.l  a0,Uni_AnimSet(a5)              ; 0F7CA
        cmpi.b  #$2,Uni_JumpType(a5)            ; 0F7CE
        bcs.b   l_0F7D8                         ; 0F7D4
        addq.l  #$4,a0                          ; 0F7D6
l_0F7D8:
        adda.w  (a0),a0                         ; 0F7D8
        bsr.w   SetAnim                         ; 0F7DA  start animation
        move.b  #$28,Uni_Timer(a5)              ; 0F7DE  fire pose for 40 frames
l_0F7E4:
        subq.b  #$1,Uni_Timer(a5)               ; 0F7E4
        bne.b   l_0F812                         ; 0F7E8
        lea.l   Unicorn_AnimFire(pc),a0         ; 0F7EA
        cmpi.b  #$2,Uni_JumpType(a5)            ; 0F7EE
        bcs.b   l_0F7F8                         ; 0F7F4
        addq.l  #$4,a0                          ; 0F7F6
l_0F7F8:
        adda.w  (a0),a0                         ; 0F7F8
        bsr.w   SetAnim                         ; 0F7FA  start animation
        move.b  #$19,Uni_Timer(a5)              ; 0F7FE  25 frames of recovery after the shot
        clr.b   Uni_Aiming(a5)                  ; 0F804
        move.b  #$5,O_Step(a5)                  ; 0F808
        clr.b   O_Step2(a5)                     ; 0F80E
l_0F812:
        rts                                     ; 0F812

;---------------------------------------------------------------------------
; 4 walk scripts (word offsets, picked with the frame counter), each a list of
; (direction, frames) pairs; direction 0 stand, 1 right, 2 left; bit 7 = loop (offset follows)
;---------------------------------------------------------------------------
Unicorn_WalkScripts:
	dc.b	$00,$08,$00,$12,$00,$1E,$00,$28,$01,$28,$00,$23,$02,$1F,$01,$24
	dc.b	$82,$22,$FF,$F6,$00,$14,$02,$25,$01,$14,$02,$1F,$01,$1A,$80,$2B
	dc.b	$FF,$F4,$02,$0F,$01,$23,$00,$28,$02,$22,$81,$14,$FF,$F6,$01,$1E
	dc.b	$02,$2D,$00,$1D,$02,$0A,$01,$1E,$80,$22,$FF,$F4

;---------------------------------------------------------------------------
; Move table for walking: (dx, dy) per direction, 8.8 fixed point (0, +0.53, -0.53)
;---------------------------------------------------------------------------
Unicorn_WalkMove:
	dc.b	$00,$00,$00,$00,$00,$88,$00,$00,$FF,$78,$00,$00

;---------------------------------------------------------------------------
; 8 random delays (frames) before the unicorn gets angry
;---------------------------------------------------------------------------
Unicorn_AngerDelays:
	dc.b	'ZnFcm3Z'
	dc.b	$82

;---------------------------------------------------------------------------
; Start walking: pick a walk script and anger delay, face Arthur.
; Variants other than 0 and 2 jump straight away.
;---------------------------------------------------------------------------
Unicorn_WalkStart:
        move.w  g_GameFrame(a6),d0              ; 0F864
        add.w   d7,d0                           ; 0F868
        addq.w  #$1,d0                          ; 0F86A
        andi.w  #$3,d0                          ; 0F86C
        add.w   d0,d0                           ; 0F870
        lea.l   Unicorn_WalkScripts(pc,d0.w),a0 ; 0F872
        move.l  a0,Uni_WalkPtr(a5)              ; 0F876
        clr.b   Uni_WalkTime(a5)                ; 0F87A
        bsr.w   Unicorn_ChooseWalkDir           ; 0F87E
        lea.l   Unicorn_WalkMove(pc),a0         ; 0F882
        move.l  a0,O_MoveTable(a5)              ; 0F886
        move.b  #$1,Uni_JumpType(a5)            ; 0F88A
        move.w  O_X(a5),d0                      ; 0F890
        cmp.w   g_ArthurX(a6),d0                ; 0F894
        blt.b   l_0F8A0                         ; 0F898
        move.b  #$2,Uni_JumpType(a5)            ; 0F89A
l_0F8A0:
        movea.l Uni_AnimSet(a5),a0              ; 0F8A0
        cmpi.b  #$2,Uni_JumpType(a5)            ; 0F8A4
        bcs.b   l_0F8AE                         ; 0F8AA
        addq.l  #$4,a0                          ; 0F8AC
l_0F8AE:
        adda.w  (a0),a0                         ; 0F8AE
        bsr.w   SetAnim                         ; 0F8B0  start animation
        bsr.w   Random                          ; 0F8B4  random number
        andi.w  #$7,d0                          ; 0F8B8
        move.b  Unicorn_AngerDelays(pc,d0.w),Uni_AngerTimer(a5); 0F8BC  random anger delay
        clr.b   Uni_Angry(a5)                   ; 0F8C2
        clr.b   Uni_Approach(a5)                ; 0F8C6
        move.b  Uni_Variant(a5),d0              ; 0F8CA  variants 1 and 3 start with a jump
        beq.b   l_0F8E2                         ; 0F8CE
        cmp.b   #$2,d0                          ; 0F8D0
        beq.b   l_0F8E2                         ; 0F8D4
        move.b  #$2,O_Step(a5)                  ; 0F8D6
        clr.b   O_Step2(a5)                     ; 0F8DC
        rts                                     ; 0F8E0
l_0F8E2:
        addq.b  #$1,O_Step2(a5)                 ; 0F8E2

;---------------------------------------------------------------------------
; One frame of walking; then work out Uni_Approach from the distance to Arthur
; (only while no scripted walk step is running).
;---------------------------------------------------------------------------
Unicorn_Walk:
        bsr.w   Unicorn_ChooseWalkDir           ; 0F8E6
        tst.b   O_Dir(a5)                       ; 0F8EA  O_Dir 0 = stand still
        beq.b   l_0F904                         ; 0F8EE
        move.w  g_GameFrame(a6),d0              ; 0F8F0
        addq.w  #$1,d0                          ; 0F8F4
        andi.b  #$1f,d0                         ; 0F8F6
        bne.b   l_0F8FE                         ; 0F8FA
        moveq   #$21,d0                         ; 0F8FC  d0 is not used by what follows. [1MB build: PlaySfx here, effect 24; the call was removed in 512K]
l_0F8FE:
        bsr.w   ApplyMoveTable                  ; 0F8FE  move by the movement table
        bra.b   l_0F91A                         ; 0F902
l_0F904:
        move.b  Uni_JumpType(a5),O_Dir(a5)      ; 0F904
        movea.l Uni_AnimSet(a5),a0              ; 0F90A
        bsr.w   SetAnimIndexed                  ; 0F90E  start animation for current direction
        clr.b   O_Dir(a5)                       ; 0F912
        clr.b   O_AnimTimer(a5)                 ; 0F916
l_0F91A:
        bsr.w   Animate                         ; 0F91A  animate
        subq.b  #$1,Uni_AngerTimer(a5)          ; 0F91E  anger timer
        bne.b   l_0F92A                         ; 0F922
        move.b  #$1,Uni_Angry(a5)               ; 0F924
l_0F92A:
        clr.b   Uni_Approach(a5)                ; 0F92A
        tst.b   Uni_WalkTime(a5)                ; 0F92E  scripted walk running: no approach decision
        bne.b   l_0F960                         ; 0F932
        move.b  #$2,Uni_Approach(a5)            ; 0F934
        move.w  O_X(a5),d0                      ; 0F93A
        cmp.w   g_ArthurX(a6),d0                ; 0F93E
        bhi.b   l_0F962                         ; 0F942
        move.w  g_ArthurX(a6),d0                ; 0F944  Arthur to the right: <= 32 px -> walk away (2), 120+ -> walk to him (1)
        sub.w   O_X(a5),d0                      ; 0F948
        cmp.w   #$20,d0                         ; 0F94C
        bls.b   l_0F960                         ; 0F950
        subq.b  #$1,Uni_Approach(a5)            ; 0F952
        cmp.w   #$78,d0                         ; 0F956
        bcc.b   l_0F960                         ; 0F95A
        subq.b  #$1,Uni_Approach(a5)            ; 0F95C
l_0F960:
        rts                                     ; 0F960
l_0F962:
        sub.w   g_ArthurX(a6),d0                ; 0F962  Arthur to the left: 120+ px -> walk to him (2), <= 56 -> walk away (1)
        cmp.w   #$78,d0                         ; 0F966
        bcc.b   l_0F960                         ; 0F96A
        subq.b  #$1,Uni_Approach(a5)            ; 0F96C
        cmp.w   #$38,d0                         ; 0F970
        bls.b   l_0F960                         ; 0F974
        subq.b  #$1,Uni_Approach(a5)            ; 0F976
        rts                                     ; 0F97A

;---------------------------------------------------------------------------
; Keep the unicorn in its arena (world X $1A18-... on level 1, $1D98-$1E48 for
; variant 2 on level 5, the level's right end otherwise): walk back in for 64 frames
; when outside it; otherwise follow the walk script.
;---------------------------------------------------------------------------
Unicorn_ChooseWalkDir:
        cmpi.b  #$2,Uni_Variant(a5)             ; 0F97C
