        lea.l   Unicorn_AnimJump(pc),a0         ; 0FA54
        tst.b   Uni_Aiming(a5)                  ; 0FA58
        beq.b   l_0FA62                         ; 0FA5C
        lea.l   Unicorn_AnimJumpAim(pc),a0      ; 0FA5E
l_0FA62:
