        cmpi.b  #$2,Uni_JumpType(a5)            ; 0FA66  rising script for this jump type (types 2+ use the second entry)
        bcs.b   l_0FA70                         ; 0FA6C
        addq.l  #$4,a0                          ; 0FA6E
l_0FA70:
        adda.w  (a0),a0                         ; 0FA70
        move.l  a0,O_Anim(a5)                   ; 0FA72
        move.b  Uni_Variant(a5),d0              ; 0FA76
        beq.b   l_0FA98                         ; 0FA7A
        cmp.b   #$2,d0                          ; 0FA7C
        beq.b   l_0FAB4                         ; 0FA80
        subq.b  #$1,Uni_Variant(a5)             ; 0FA82  variants 1/3: one long jump, then behave as variant 0/2
        moveq   #$10,d0                         ; 0FA86
        cmpi.b  #$1,Uni_JumpType(a5)            ; 0FA88
        bne.b   l_0FA92                         ; 0FA8E
        moveq   #$f,d0                          ; 0FA90
l_0FA92:
        move.b  d0,Uni_JumpType(a5)             ; 0FA92
        bra.b   l_0FAD2                         ; 0FA96
l_0FA98:
