        beq.b   l_0FAB4                         ; 0FA9C
        clr.b   Uni_JumpNext(a5)                ; 0FA9E
        moveq   #$5,d0                          ; 0FAA2
        cmpi.b  #$1,Uni_JumpType(a5)            ; 0FAA4
        bne.b   l_0FAAE                         ; 0FAAA
        moveq   #$6,d0                          ; 0FAAC
l_0FAAE:
        move.b  d0,Uni_JumpType(a5)             ; 0FAAE
        bra.b   l_0FAD2                         ; 0FAB2
l_0FAB4:
        lea.l   Unicorn_JumpChoices(pc),a0      ; 0FAB4  random next jump type (Unicorn_JumpChoicesAfter1 after a type-1 jump)
        cmpi.b  #$1,Uni_JumpType(a5)            ; 0FAB8
        bne.b   l_0FAC4                         ; 0FABE
        lea.l   Unicorn_JumpChoicesAfter1(pc),a0; 0FAC0
l_0FAC4:
