        andi.w  #$3,d0                          ; 0FAC8
        move.b  (a0,d0.w),Uni_JumpType(a5)      ; 0FACC
l_0FAD2:
        cmpi.w  #$5,g_Level(a6)                 ; 0FAD2  level 5 / level 1: do not jump out of the arena
        beq.b   l_0FB06                         ; 0FAD8
        cmpi.w  #$1,g_Level(a6)                 ; 0FADA
        bne.b   l_0FB34                         ; 0FAE0
        move.w  O_X(a5),d0                      ; 0FAE2  level 1: left of world X $1A60 an even jump type becomes a standing landing
        add.w   g_LevelOriginX(a6),d0           ; 0FAE6
        cmp.w   #$1a60,d0                       ; 0FAEA
        bhi.b   l_0FB34                         ; 0FAEE
        btst    #$0,Uni_JumpType(a5)            ; 0FAF0
        bne.b   l_0FB34                         ; 0FAF6
l_0FAF8:
