        tst.b   Uni_JumpType(a5)                ; 0FB24
        beq.b   l_0FAF8                         ; 0FB28
        btst    #$0,Uni_JumpType(a5)            ; 0FB2A
        beq.b   l_0FB34                         ; 0FB30
        bra.b   l_0FAF8                         ; 0FB32
l_0FB34:
