;---------------------------------------------------------------------------
; Gravity pairs (acceleration.w, max fall speed.w in px): $5000 (0.31 px/frame^2) up to
; 6 px/frame for the main rise and fall, $1900 (0.1) up to 1 near the apex
;---------------------------------------------------------------------------
Unicorn_Gravity:
	dc.b	$50,$00,$00,$06,$19,$00,$00,$01

;---------------------------------------------------------------------------
; Y += Uni_VelY, then slow it by the gravity for this phase
;---------------------------------------------------------------------------
Unicorn_RiseStep:
        move.l  Uni_VelY(a5),d0                 ; 0FB66
        add.l   d0,O_Y(a5)                      ; 0FB6A
        lea.l   Unicorn_Gravity(pc),a0          ; 0FB6E
        tst.b   Uni_Gravity(a5)                 ; 0FB72
        beq.b   l_0FB7A                         ; 0FB76
        addq.l  #$4,a0                          ; 0FB78
l_0FB7A:
        move.w  (a0),d0                         ; 0FB7A
        ext.l   d0                              ; 0FB7C
        sub.l   d0,Uni_VelY(a5)                 ; 0FB7E
