Unicorn_JumpApproachApex:
        bsr.b   Unicorn_MoveX                   ; 0FB84
        move.b  #$1,Uni_Gravity(a5)             ; 0FB86
        bsr.b   Unicorn_RiseStep                ; 0FB8C
        cmpi.l  #$1900,Uni_VelY(a5)             ; 0FB8E  until it is below 0.1 px/frame
        bhi.w   Animate                         ; 0FB96
        addq.b  #$1,O_Step2(a5)                 ; 0FB9A
        rts                                     ; 0FB9E
Unicorn_JumpApex:
        bsr.b   Unicorn_MoveX                   ; 0FBA0
        move.b  #$1,Uni_Gravity(a5)             ; 0FBA2
        bsr.b   Unicorn_FallStep                ; 0FBA8
        bra.w   Animate                         ; 0FBAA

;---------------------------------------------------------------------------
; Y -= Uni_VelY, speeding up to the limit for this phase
;---------------------------------------------------------------------------
Unicorn_FallStep:
        move.l  Uni_VelY(a5),d0                 ; 0FBAE
        sub.l   d0,O_Y(a5)                      ; 0FBB2
        lea.l   Unicorn_Gravity(pc),a0          ; 0FBB6
        tst.b   Uni_Gravity(a5)                 ; 0FBBA
        beq.b   l_0FBC2                         ; 0FBBE
        addq.l  #$4,a0                          ; 0FBC0
l_0FBC2:
        move.w  Uni_VelY(a5),d0                 ; 0FBC2
        cmp.w   $2(a0),d0                       ; 0FBC6
        bhi.b   l_0FBD4                         ; 0FBCA
        move.w  (a0),d0                         ; 0FBCC
        ext.l   d0                              ; 0FBCE
        add.l   d0,Uni_VelY(a5)                 ; 0FBD0
l_0FBD4:
