;---------------------------------------------------------------------------
; X += Unicorn_JumpSpeedX[Uni_JumpType] (8.8)
;---------------------------------------------------------------------------
Unicorn_MoveX:
        lea.l   Unicorn_JumpSpeedX(pc),a0       ; 0FBE0
        move.b  Uni_JumpType(a5),d0             ; 0FBE4
