        blt.b   l_0FC52                         ; 0FC48
        addq.b  #$1,O_Dir(a5)                   ; 0FC4A
        addq.b  #$1,Uni_JumpType(a5)            ; 0FC4E
l_0FC52:
        lea.l   Unicorn_AnimStand(pc),a0        ; 0FC52
