        move.b  #$19,Uni_Timer(a5)              ; 0FC64
        clr.b   Uni_Aiming(a5)                  ; 0FC6A
        move.b  #$5,O_Step(a5)                  ; 0FC6E
        clr.b   O_Step2(a5)                     ; 0FC74
