        clr.b   O_AnimTimer(a5)                 ; 0FC82
        bsr.w   Animate                         ; 0FC86  animate
        move.b  #$f,Uni_Pause(a5)               ; 0FC8A
        addq.b  #$1,O_Step2(a5)                 ; 0FC90
        rts                                     ; 0FC94

;---------------------------------------------------------------------------
; After the pause: angry -> walk again from scratch (Unicorn_WalkStart), else carry on walking
;---------------------------------------------------------------------------
Unicorn_LandPause:
        subq.b  #$1,Uni_Pause(a5)               ; 0FC96
        bne.b   l_0FCAE                         ; 0FC9A
        tst.b   Uni_Angry(a5)                   ; 0FC9C
        bne.b   l_0FCB0                         ; 0FCA0
        move.b  #$1,O_Step(a5)                  ; 0FCA2
        move.b  #$1,O_Step2(a5)                 ; 0FCA8
l_0FCAE:
        rts                                     ; 0FCAE
l_0FCB0:
