        move.w  O_X(a5),d0                      ; 0FDF6
        cmp.w   g_ArthurX(a6),d0                ; 0FDFA
        blt.b   l_0FE04                         ; 0FDFE
        addq.b  #$1,Uni_JumpType(a5)            ; 0FE00
l_0FE04:
