        move.w  O_X(a5),d0                      ; 0FE0A
        cmp.w   g_ArthurX(a6),d0                ; 0FE0E
        bhi.b   l_0FE46                         ; 0FE12
        cmpi.b  #$1,O_Dir(a5)                   ; 0FE14
        beq.b   l_0FE22                         ; 0FE1A
        subq.b  #$1,O_Step2(a5)                 ; 0FE1C
        rts                                     ; 0FE20
l_0FE22:
        cmpi.b  #$2,Uni_Variant(a5)             ; 0FE22
        beq.b   l_0FE44                         ; 0FE28
        bsr.w   Random                          ; 0FE2A  random number
