        bne.b   l_0FE44                         ; 0FE32
        move.b  #$1,Uni_JumpNext(a5)            ; 0FE34
        move.b  #$2,O_Step(a5)                  ; 0FE3A
        clr.b   O_Step2(a5)                     ; 0FE40
l_0FE44:
        rts                                     ; 0FE44
l_0FE46:
        cmpi.b  #$1,O_Dir(a5)                   ; 0FE46
        beq.b   l_0FE22                         ; 0FE4C
        subq.b  #$1,O_Step2(a5)                 ; 0FE4E
        rts                                     ; 0FE52

