Unicorn_CheckThreats:
        tst.b   Uni_Angry(a5)                   ; 0FEBE
        bne.b   l_0FF06                         ; 0FEC2
        tst.b   Uni_Aiming(a5)                  ; 0FEC4
        bne.b   l_0FEF4                         ; 0FEC8
        clr.b   d1                              ; 0FECA
        lea.l   g_Shots(a6),a0                  ; 0FECC
        bsr.b   Unicorn_ShotNear                ; 0FED0
        tst.b   d1                              ; 0FED2
        bne.b   l_0FF04                         ; 0FED4
        lea.l   $26(a0),a0                      ; 0FED6
        bsr.b   Unicorn_ShotNear                ; 0FEDA
        tst.b   d1                              ; 0FEDC
        bne.b   l_0FF04                         ; 0FEDE
        lea.l   $26(a0),a0                      ; 0FEE0
        bsr.b   Unicorn_ShotNear                ; 0FEE4
        tst.b   d1                              ; 0FEE6
        bne.b   l_0FF04                         ; 0FEE8
        lea.l   $26(a0),a0                      ; 0FEEA
        bsr.b   Unicorn_ShotNear                ; 0FEEE
        tst.b   d1                              ; 0FEF0
        bne.b   l_0FF04                         ; 0FEF2
l_0FEF4:
        tst.b   Uni_Approach(a5)                ; 0FEF4
        beq.b   l_0FF04                         ; 0FEF8
        move.b  #$4,O_Step(a5)                  ; 0FEFA
        clr.b   O_Step2(a5)                     ; 0FF00
l_0FF04:
