l_0FF06:
        cmpi.b  #$2,Uni_Variant(a5)             ; 0FF06  variant 2 always charges
        beq.b   l_0FF18                         ; 0FF0C
        bsr.w   Random                          ; 0FF0E  random number
        andi.b  #$1,d0                          ; 0FF12
        bne.b   l_0FF24                         ; 0FF16
l_0FF18:
        move.b  #$3,O_Step(a5)                  ; 0FF18
        clr.b   O_Step2(a5)                     ; 0FF1E
        rts                                     ; 0FF22
l_0FF24:
        move.b  #$2,O_Step(a5)                  ; 0FF24  jump at Arthur
        move.b  #$7,O_Step2(a5)                 ; 0FF2A
        rts                                     ; 0FF30

;---------------------------------------------------------------------------
; Shot slot a0 active, on screen, not flying the way the unicorn faces and within
; +-56 pixels horizontally -> d1+1 and start a jump
;---------------------------------------------------------------------------
Unicorn_ShotNear:
        move.b  (a0),d0                         ; 0FF32
        and.b   $1(a0),d0                       ; 0FF34
        beq.b   l_0FF62                         ; 0FF38
        move.b  Uni_JumpType(a5),d0             ; 0FF3A
        cmp.b   $12(a0),d0                      ; 0FF3E  shot flying the way the unicorn faces (away from it)? ignore
        beq.b   l_0FF62                         ; 0FF42
        move.w  O_X(a5),d0                      ; 0FF44
        sub.w   $6(a0),d0                       ; 0FF48
        addi.w  #$38,d0                         ; 0FF4C
        cmp.w   #$70,d0                         ; 0FF50
        bhi.b   l_0FF62                         ; 0FF54
        addq.b  #$1,d1                          ; 0FF56
        move.b  #$2,O_Step(a5)                  ; 0FF58
        clr.b   O_Step2(a5)                     ; 0FF5E
l_0FF62:
        rts                                     ; 0FF62

;---------------------------------------------------------------------------
; Step 5: after the wind-up, spawn enemy shot type 1 at the unicorn moving the way it
; faces, then walk on (or charge if angry)
;---------------------------------------------------------------------------
Unicorn_Fire:
        subq.b  #$1,Uni_Timer(a5)               ; 0FF64
        bne.w   Animate                         ; 0FF68
        bsr.w   FindFreeEnemyShot               ; 0FF6C  find a free enemy-projectile slot (fires a shot)
        bne.b   l_0FFC8                         ; 0FF70
        move.w  O_X(a5),$6(a4)                  ; 0FF72  shot starts at the unicorn
        move.w  O_Y(a5),$a(a4)                  ; 0FF78
        move.b  Uni_JumpType(a5),d0             ; 0FF7E
        subq.b  #$1,d0                          ; 0FF82
        move.b  d0,$12(a4)                      ; 0FF84
        clr.b   $3(a4)                          ; 0FF88
        clr.b   $4(a4)                          ; 0FF8C
        clr.b   $5(a4)                          ; 0FF90
        move.b  #$1,(a4)                        ; 0FF94
        move.b  #$1,$1a(a4)                     ; 0FF98  enemy shot type 1 (unicorn fireball)
        lea.l   Unicorn_AnimStand(pc),a0        ; 0FF9E
        move.l  a0,Uni_AnimSet(a5)              ; 0FFA2
        cmpi.b  #$2,Uni_JumpType(a5)            ; 0FFA6
        bcs.b   l_0FFB0                         ; 0FFAC
        addq.l  #$4,a0                          ; 0FFAE
l_0FFB0:
        adda.w  (a0),a0                         ; 0FFB0
        move.l  a0,O_Anim(a5)                   ; 0FFB2
        tst.b   Uni_Angry(a5)                   ; 0FFB6
        bne.b   l_0FFCA                         ; 0FFBA
        move.b  #$1,O_Step(a5)                  ; 0FFBC
        move.b  #$1,O_Step2(a5)                 ; 0FFC2
l_0FFC8:
        rts                                     ; 0FFC8
l_0FFCA:
        move.b  #$3,O_Step(a5)                  ; 0FFCA
        clr.b   O_Step2(a5)                     ; 0FFD0
        rts                                     ; 0FFD4

;---------------------------------------------------------------------------
; State 2: sound effect 12, the shared explosion (EnemyExplode), then 63 frames
;---------------------------------------------------------------------------
Unicorn_Dying:
        cmpi.b  #$1,O_Step(a5)                  ; 0FFD6
        beq.b   l_0FFF0                         ; 0FFDC
        bcc.b   l_0FFF4                         ; 0FFDE
        move.b  #$3f,Uni_Timer(a5)              ; 0FFE0
        addq.b  #$1,O_Step(a5)                  ; 0FFE6  next step
        moveq   #SFX_ENEMY_HIT,d0               ; 0FFEA  sound effect 12
        bra.w   PlaySfx                         ; 0FFEC
l_0FFF0:
