l_0FFF4:
        move.b  #$2,O_Size(a5)                  ; 0FFF4
        subq.b  #$1,Uni_Timer(a5)               ; 0FFFA
        bne.b   l_10006                         ; 0FFFE
        move.b  #ST_REMOVE,O_State(a5)          ; 10000
l_10006:
        rts                                     ; 10006

;---------------------------------------------------------------------------
; State 3: free the slot. Level 1: the boss is beaten (BossKilled).
;---------------------------------------------------------------------------
Unicorn_Free:
        addq.b  #$1,g_SpawnQuota+8(a6)          ; 10008  give the unicorn spawn quota back
        tst.b   g_BigEnemyCount(a6)             ; 1000C
        beq.b   l_10016                         ; 10010
        subq.b  #$1,g_BigEnemyCount(a6)         ; 10012  one big enemy fewer
l_10016:
        clr.b   (a5)                            ; 10016  free this enemy slot
        cmpi.w  #$5,g_Level(a6)                 ; 10018  on level 5 it is not the boss
        bne.w   BossKilled                      ; 1001E
        rts                                     ; 10022
Unicorn_AnimStand:
