;---------------------------------------------------------------------------
; === Skeleton (type 9, 100 pts) ===
; Rises out of the floor (map collision) on the castle levels. Sound effect 17.
; Dispatches on O_State: 0 main behaviour, 1 type-specific second phase, 2 killed (set by EnemyHitByShot after scoring), 3 remove.
;
; Behaviour, as coded: lies as a pile of bones (size class 0) until Arthur comes within
; 32 px of it, then rises out of the floor and hops: two small hops (3 px/frame up, 0.8
; px/frame across), turning towards Arthur when he is 64+ px away, then a big leap that
; lands where Arthur was (dx / 42 per frame, a sine arc about 80 px high), then hops again.
; It does not give its spawn quota back when it is removed (the others do).
;---------------------------------------------------------------------------
Enemy_Skeleton:
        move.b  O_State(a5),d0                  ; 10082
        add.w   d0,d0                           ; 10086
        add.w   d0,d0                           ; 10088
        jmp     Enemy_Skeleton_Jumps(pc,d0.w)   ; 1008A
Enemy_Skeleton_Jumps:
        bra.w   Skeleton_Init                   ; 1008E
        bra.w   Skeleton_Active                 ; 10092
        bra.w   Skeleton_Dying                  ; 10096
        bra.w   Skeleton_Free                   ; 1009A

;---------------------------------------------------------------------------
; State 0: lie dormant until Arthur is within 32 px both ways
;---------------------------------------------------------------------------
Skeleton_Init:
        tst.b   O_Step(a5)                      ; 1009E
        bne.b   Skeleton_Dormant                ; 100A2
        clr.b   O_Size(a5)                      ; 100A4
        lea.l   Skeleton_AnimBones(pc),a0       ; 100A8
        bsr.w   SetAnim                         ; 100AC  start animation
        addq.b  #$1,O_Step(a5)                  ; 100B0  next step
        rts                                     ; 100B4
Skeleton_Dormant:
        tst.b   O_OnScreen(a5)                  ; 100B6
        beq.b   l_100EE                         ; 100BA
        move.w  O_X(a5),d0                      ; 100BC
        sub.w   g_ArthurX(a6),d0                ; 100C0
        addi.w  #$20,d0                         ; 100C4
        cmp.w   #$40,d0                         ; 100C8
        bhi.b   l_100EE                         ; 100CC
        move.w  O_Y(a5),d0                      ; 100CE
        sub.w   g_ArthurY(a6),d0                ; 100D2
        addi.w  #$20,d0                         ; 100D6
        cmp.w   #$40,d0                         ; 100DA
        bhi.b   l_100EE                         ; 100DE
        move.b  #ST_ACTIVE,O_State(a5)          ; 100E0
        clr.b   O_Step(a5)                      ; 100E6
        clr.b   O_Step2(a5)                     ; 100EA
l_100EE:
        rts                                     ; 100EE

;---------------------------------------------------------------------------
; State 1. O_Step: 0 rise, 1 hop, 2 leap
;---------------------------------------------------------------------------
Skeleton_Active:
        move.b  O_Step(a5),d0                   ; 100F0
        add.w   d0,d0                           ; 100F4
        add.w   d0,d0                           ; 100F6
        jsr     Skeleton_Active_Jumps(pc,d0.w)  ; 100F8
        bra.w   CheckFarAway                    ; 100FC
Skeleton_Active_Jumps:
        bra.w   Skeleton_Rise                   ; 10100
        bra.w   Skeleton_Hop                    ; 10104
        bra.w   Skeleton_Leap                   ; 10108
Skeleton_Rise:
        move.b  O_Step2(a5),d0                  ; 1010C
        add.w   d0,d0                           ; 10110
        add.w   d0,d0                           ; 10112
        jmp     Skeleton_Rise_Jumps(pc,d0.w)    ; 10114
Skeleton_Rise_Jumps:
        bra.w   Skeleton_RiseStart              ; 10118
        bra.w   Skeleton_Rising1                ; 1011C
        bra.w   Skeleton_Rising2                ; 10120

;---------------------------------------------------------------------------
; Start rising at 3.5 px/frame
;---------------------------------------------------------------------------
Skeleton_RiseStart:
        lea.l   SkeletonMoveTable(pc),a0        ; 10124
        move.l  a0,O_MoveTable(a5)              ; 10128
        move.b  #$4,O_Dir(a5)                   ; 1012C
        move.b  #$2,O_Size(a5)                  ; 10132
        lea.l   Skeleton_AnimRise(pc),a0        ; 10138
        bsr.w   SetAnim                         ; 1013C  start animation
        move.l  #$38000,Skl_VelY(a5)            ; 10140
        addq.b  #$1,O_Step2(a5)                 ; 10148
        rts                                     ; 1014C
Skeleton_Rising1:
        bsr.b   Skeleton_RiseStep               ; 1014E
        tst.b   O_AnimTimer(a5)                 ; 10150
        bne.b   l_1015A                         ; 10154
        addq.b  #$1,O_Step2(a5)                 ; 10156
l_1015A:
        rts                                     ; 1015A

;---------------------------------------------------------------------------
; when the animation ends: size 3, start hopping
;---------------------------------------------------------------------------
Skeleton_Rising2:
        bsr.b   Skeleton_RiseStep               ; 1015C
        tst.b   O_AnimTimer(a5)                 ; 1015E
        bne.b   l_10174                         ; 10162
        move.b  #$3,O_Size(a5)                  ; 10164
        move.b  #$1,O_Step(a5)                  ; 1016A
        clr.b   O_Step2(a5)                     ; 10170
l_10174:
        rts                                     ; 10174

;---------------------------------------------------------------------------
; Y += speed, speed -= 0.16
;---------------------------------------------------------------------------
Skeleton_RiseStep:
        move.w  Skl_VelY(a5),d0                 ; 10176
        add.w   d0,O_Y(a5)                      ; 1017A
        subi.l  #$2985,Skl_VelY(a5)             ; 1017E
        bra.w   Animate                         ; 10186

;---------------------------------------------------------------------------
; O_Step2: 0 start, 1 take off, 2 rise, 3 fall, 4-5 pause and aim
;---------------------------------------------------------------------------
Skeleton_Hop:
        move.b  O_Step2(a5),d0                  ; 1018A
        add.w   d0,d0                           ; 1018E
        add.w   d0,d0                           ; 10190
        jmp     Skeleton_Hop_Jumps(pc,d0.w)     ; 10192
Skeleton_Hop_Jumps:
        bra.w   Skeleton_HopStart               ; 10196
        bra.w   Skeleton_TakeOff                ; 1019A
        bra.w   Skeleton_HopRise                ; 1019E
        bra.w   Skeleton_HopFall                ; 101A2
        bra.w   Skeleton_Land                   ; 101A6
        bra.w   Skeleton_LandPause              ; 101AA

;---------------------------------------------------------------------------
; 2 hops before the leap
;---------------------------------------------------------------------------
Skeleton_HopStart:
        lea.l   SkeletonMoveTable(pc),a0        ; 101AE
        move.l  a0,O_MoveTable(a5)              ; 101B2
        move.b  #$2,Skl_Hops(a5)                ; 101B6
        addq.b  #$1,O_Step2(a5)                 ; 101BC
        rts                                     ; 101C0

;---------------------------------------------------------------------------
; 3 px/frame upwards
;---------------------------------------------------------------------------
Skeleton_TakeOff:
        lea.l   Skeleton_AnimHop(pc),a0         ; 101C2
        bsr.w   SetAnim                         ; 101C6  start animation
        move.l  #$30000,Skl_VelY(a5)            ; 101CA
        addq.b  #$1,O_Step2(a5)                 ; 101D2

;---------------------------------------------------------------------------
; gravity 0.165 px/frame^2 until the top
;---------------------------------------------------------------------------
Skeleton_HopRise:
        bsr.w   Skeleton_HopMove                ; 101D6
        subi.l  #$2a16,Skl_VelY(a5)             ; 101DA
        tst.w   Skl_VelY(a5)                    ; 101E2
        bne.b   l_101EC                         ; 101E6
        addq.b  #$1,O_Step2(a5)                 ; 101E8
l_101EC:
        rts                                     ; 101EC

;---------------------------------------------------------------------------
; down to -3 px/frame until it lands
;---------------------------------------------------------------------------
Skeleton_HopFall:
        bsr.b   Skeleton_HopMove                ; 101EE
        cmpi.w  #$fffd,Skl_VelY(a5)             ; 101F0
        blt.b   l_10200                         ; 101F6
        subi.l  #$2a16,Skl_VelY(a5)             ; 101F8
l_10200:
        bsr.w   ObjectMapCollide                ; 10200  on the floor? (Z set = yes, Y snapped onto it)
        bne.b   l_1020A                         ; 10204
        addq.b  #$1,O_Step2(a5)                 ; 10206
l_1020A:
        rts                                     ; 1020A
Skeleton_Land:
        move.b  #$6,Skl_Pause(a5)               ; 1020C
        addq.b  #$1,O_Step2(a5)                 ; 10212

;---------------------------------------------------------------------------
; 6 frames, aim, then hop again or leap
;---------------------------------------------------------------------------
Skeleton_LandPause:
        subq.b  #$1,Skl_Pause(a5)               ; 10216
        bne.w   Animate                         ; 1021A
        bsr.b   Skeleton_Aim                    ; 1021E
        move.b  #$1,O_Step2(a5)                 ; 10220
        subq.b  #$1,Skl_Hops(a5)                ; 10226
        bne.b   l_10236                         ; 1022A
        move.b  #$2,O_Step(a5)                  ; 1022C
        clr.b   O_Step2(a5)                     ; 10232
l_10236:
        rts                                     ; 10236

;---------------------------------------------------------------------------
; Arthur 64+ px away: face him (O_Dir 1 right, 3 left); closer: keep going
;---------------------------------------------------------------------------
Skeleton_Aim:
        move.w  O_X(a5),d0                      ; 10238
        sub.w   g_ArthurX(a6),d0                ; 1023C
        addi.w  #$40,d0                         ; 10240
        cmp.w   #$80,d0                         ; 10244
        bcs.b   l_10260                         ; 10248
        move.b  #$3,O_Dir(a5)                   ; 1024A
        move.w  O_X(a5),d0                      ; 10250
        cmp.w   g_ArthurX(a6),d0                ; 10254
        bhi.b   l_10260                         ; 10258
        move.b  #$1,O_Dir(a5)                   ; 1025A
l_10260:
        rts                                     ; 10260

;---------------------------------------------------------------------------
; X += move table dx for O_Dir, Y += Skl_VelY
;---------------------------------------------------------------------------
Skeleton_HopMove:
        movea.l O_MoveTable(a5),a0              ; 10262
        clr.w   d0                              ; 10266
        move.b  O_Dir(a5),d0                    ; 10268
        add.w   d0,d0                           ; 1026C
        add.w   d0,d0                           ; 1026E
        adda.w  d0,a0                           ; 10270
        move.w  (a0),d0                         ; 10272
        ext.l   d0                              ; 10274
        asl.l   #$8,d0                          ; 10276
        add.l   d0,O_X(a5)                      ; 10278
        move.l  Skl_VelY(a5),d0                 ; 1027C
        add.l   d0,O_Y(a5)                      ; 10280
        bra.w   Animate                         ; 10284

;---------------------------------------------------------------------------
; O_Step2: 0 aim, 1 up, 2 down, 3-4 pause
;---------------------------------------------------------------------------
Skeleton_Leap:
        move.b  O_Step2(a5),d0                  ; 10288
        add.w   d0,d0                           ; 1028C
        add.w   d0,d0                           ; 1028E
        jmp     Skeleton_Leap_Jumps(pc,d0.w)    ; 10290
Skeleton_Leap_Jumps:
        bra.w   Skeleton_LeapStart              ; 10294
        bra.w   Skeleton_LeapUp                 ; 10298
        bra.w   Skeleton_LeapDown               ; 1029C
        bra.w   Skeleton_LeapLand               ; 102A0
        bra.w   Skeleton_LeapPause              ; 102A4

;---------------------------------------------------------------------------
; Skl_LeapDX = (Arthur X - X) / 42: lands on his spot after 42 frames
;---------------------------------------------------------------------------
Skeleton_LeapStart:
        lea.l   Skeleton_AnimLeap(pc),a0        ; 102A8
        bsr.w   SetAnim                         ; 102AC  start animation
        move.w  O_Y(a5),Skl_BaseY(a5)           ; 102B0
        clr.b   Skl_Phase(a5)                   ; 102B6
        move.w  g_ArthurX(a6),d0                ; 102BA
        sub.w   O_X(a5),d0                      ; 102BE
        ext.l   d0                              ; 102C2
        asl.l   #$8,d0                          ; 102C4
        divs.w  #$2a,d0                         ; 102C6
        ext.l   d0                              ; 102CA
        asl.l   #$8,d0                          ; 102CC
        move.l  d0,Skl_LeapDX(a5)               ; 102CE
        addq.b  #$1,O_Step2(a5)                 ; 102D2
        rts                                     ; 102D6

;---------------------------------------------------------------------------
; phase += 6 until the top
;---------------------------------------------------------------------------
Skeleton_LeapUp:
        addq.b  #$6,Skl_Phase(a5)               ; 102D8
        bmi.b   l_102EA                         ; 102DC
        bsr.b   Skeleton_LeapY                  ; 102DE
        move.l  Skl_LeapDX(a5),d0               ; 102E0
        add.l   d0,O_X(a5)                      ; 102E4
        rts                                     ; 102E8
l_102EA:
        addq.b  #$1,O_Step2(a5)                 ; 102EA
        rts                                     ; 102EE

;---------------------------------------------------------------------------
; until the phase wraps, or it lands (checked near the end)
;---------------------------------------------------------------------------
Skeleton_LeapDown:
        addq.b  #$6,Skl_Phase(a5)               ; 102F0
        bcs.b   l_10316                         ; 102F4
        cmpi.b  #$e0,Skl_Phase(a5)              ; 102F6
        bcs.b   l_10304                         ; 102FC
        bsr.w   ObjectMapCollide                ; 102FE  on the floor? (Z set = yes, Y snapped onto it)
        beq.b   l_10316                         ; 10302
l_10304:
        bsr.b   Skeleton_LeapY                  ; 10304
        move.l  Skl_LeapDX(a5),d0               ; 10306
        add.l   d0,O_X(a5)                      ; 1030A
        rts                                     ; 1030E
	dc.b	$3B,$6D,$00,$20,$00,$0A
l_10316:
        addq.b  #$1,O_Step2(a5)                 ; 10316
        rts                                     ; 1031A
Skeleton_LeapLand:
        move.b  #$6,Skl_Pause(a5)               ; 1031C
        addq.b  #$1,O_Step2(a5)                 ; 10322
Skeleton_LeapPause:
        subq.b  #$1,Skl_Pause(a5)               ; 10326
        bne.w   Animate                         ; 1032A
        bsr.w   Skeleton_Aim                    ; 1032E
        move.b  #$1,O_Step(a5)                  ; 10332
        clr.b   O_Step2(a5)                     ; 10338
        rts                                     ; 1033C

;---------------------------------------------------------------------------
; Y = Skl_BaseY + sin(phase) x 2 x 80 / 256
;---------------------------------------------------------------------------
Skeleton_LeapY:
        lea.l   SineTable(pc),a0                ; 1033E
        clr.w   d0                              ; 10342
        move.b  Skl_Phase(a5),d0                ; 10344
        move.b  (a0,d0.w),d0                    ; 10348
        add.w   d0,d0                           ; 1034C
        mulu.w  #$50,d0                         ; 1034E
        lsr.w   #$8,d0                          ; 10352
        add.w   Skl_BaseY(a5),d0                ; 10354
        move.w  d0,O_Y(a5)                      ; 10358
        rts                                     ; 1035C

;---------------------------------------------------------------------------
; State 2: sound 17, EnemyDieFacing
;---------------------------------------------------------------------------
Skeleton_Dying:
        cmpi.b  #$1,O_Step(a5)                  ; 1035E
        beq.b   l_10374                         ; 10364
        bcc.b   l_10378                         ; 10366
        moveq   #SFX_ENEMY_DIE,d0               ; 10368
        bsr.w   PlaySfx                         ; 1036A  sound effect 17 (enemy event)
        addq.b  #$1,O_Step(a5)                  ; 1036E  next step
        rts                                     ; 10372
l_10374:
        bra.w   EnemyDieFacing                  ; 10374
l_10378:
        move.b  #ST_REMOVE,O_State(a5)          ; 10378
        rts                                     ; 1037E

;---------------------------------------------------------------------------
; State 3: free the slot (no spawn quota given back)
;---------------------------------------------------------------------------
Skeleton_Free:
        clr.b   (a5)                            ; 10380  free this enemy slot
        rts                                     ; 10382

;---------------------------------------------------------------------------
; (dx, dy) 8.8: 0 still, 1 right 0.8, 2 down, 3 left 0.8, 4 up (only dx is used)
;---------------------------------------------------------------------------
SkeletonMoveTable:
	dc.b	$00,$00,$00,$00,$00,$CC,$00,$00,$00,$00,$FF,$34,$FF,$34,$00,$00
	dc.b	$00,$00,$00,$CC
Skeleton_AnimBones:
	AL	$00,3,Skeleton_AnimBones
Skeleton_AnimRise:
	AF	$01,1
	AL	$02,1,Skeleton_AnimRise
Skeleton_AnimHop:
	AF	$01,6
	AF	$02,6
	AF	$03,24
	AF	$02,3
	AL	$01,4,Skeleton_AnimHop
Skeleton_AnimLeap:
	AF	$01,6
	AF	$02,6
	AF	$03,24
	AF	$02,3
	AL	$01,3,Skeleton_AnimLeap

;---------------------------------------------------------------------------
; === Big Man (type 10, 500 pts, 10 hits) ===
; Ogre that walks and charges along the floor, pauses at random and throws projectiles.
; Dispatches on O_State: 0 main behaviour, 1 type-specific second phase, 2 killed (set by EnemyHitByShot after scoring), 3 remove.
;
; Behaviour, as coded:
;   * Walks at 0.53 px/frame, turning back at the edge of a floor, and pauses (70 or 100
;     frames, random) after each walk time in BigManWalkTimes, then picks a random direction.
;   * When Arthur is on its level (10 px below to 45 px above), it fights: paces to and
;     fro across him (turning 40 px past him), charges at 2 px/frame, and throws enemy
;     shot type 3 on BigManShotTimes (10-frame wind-up).
;   * When Arthur is directly below (within 10 px across) it crouches and throws down
;     every 30 frames.
;   * Each hit makes it flinch for 6 frames. Only acts while on screen.
;---------------------------------------------------------------------------
Enemy_BigMan:
        move.b  O_State(a5),d0                  ; 103BA
        add.w   d0,d0                           ; 103BE
        add.w   d0,d0                           ; 103C0
        jmp     Enemy_BigMan_Jumps(pc,d0.w)     ; 103C2
Enemy_BigMan_Jumps:
        bra.w   BigMan_Init                     ; 103C6
        bra.w   BigMan_Active                   ; 103CA
        bra.w   BigMan_Dying                    ; 103CE
        bra.w   BigMan_Free                     ; 103D2

;---------------------------------------------------------------------------
; State 0: 10 HP, size 3, face Arthur, start the scripts; wait until on screen
;---------------------------------------------------------------------------
BigMan_Init:
        tst.b   O_Step(a5)                      ; 103D6
        bne.b   BigMan_WaitVisible              ; 103DA
        move.b  O_Param(a5),BM_Crouched(a5)     ; 103DC
        clr.b   O_Param(a5)                     ; 103E2
        move.w  O_X(a5),d0                      ; 103E6
        cmp.w   g_ArthurX(a6),d0                ; 103EA
        slt.b   O_Dir(a5)                       ; 103EE
        addq.b  #$1,O_Dir(a5)                   ; 103F2
        move.b  #$3,O_Size(a5)                  ; 103F6
        lea.l   BigMan_AnimWalk(pc),a0          ; 103FC
        bsr.w   SetAnimIndexed                  ; 10400  start animation for current direction
        move.b  #$a,O_HP(a5)                    ; 10404
        clr.b   BM_Timer(a5)                    ; 1040A
        clr.b   BM_EdgeDir(a5)                  ; 1040E
        clr.b   BM_AtEdge(a5)                   ; 10412
        clr.b   BM_EdgeTurn(a5)                 ; 10416
        lea.l   BigManShotTimes(pc),a0          ; 1041A
        move.b  (a0)+,BM_ShotTime(a5)           ; 1041E
        move.l  a0,BM_ShotPtr(a5)               ; 10422
        lea.l   BigManWalkTimes(pc),a0          ; 10426
        move.b  (a0)+,BM_WalkTime(a5)           ; 1042A
        move.l  a0,BM_WalkPtr(a5)               ; 1042E
        lea.l   BigManMoveTable(pc),a0          ; 10432
        move.l  a0,O_MoveTable(a5)              ; 10436
        addq.b  #$1,O_Step(a5)                  ; 1043A  next step
        rts                                     ; 1043E
BigMan_WaitVisible:
        tst.b   O_OnScreen(a5)                  ; 10440
        beq.b   l_10452                         ; 10444
        addq.b  #ST_ACTIVE,O_State(a5)          ; 10446
        clr.b   O_Step(a5)                      ; 1044A
        clr.b   O_Step2(a5)                     ; 1044E
l_10452:
        rts                                     ; 10452
	dc.b	$00

;---------------------------------------------------------------------------
; frames between shots: 45, 35, 20, 20, 42, 60, 35, 50, 28 (bit 7 = loop)
;---------------------------------------------------------------------------
BigManShotTimes:
	dc.b	$2D,$23,$14,$14,$2A,$3C,$23,$32,$9C,$FF,$F7

;---------------------------------------------------------------------------
; frames of walking between pauses: 190, 100, 163, 230, 98, 156, 120, 160, 120
;---------------------------------------------------------------------------
BigManWalkTimes:
	dc.b	$BE,$64,$A3,$E6,$62,$9C,$78,$A0,$78,$00,$FF,$F6

;---------------------------------------------------------------------------
; O_Dir 0/1: +-0.53 walking; 2/3: +-2.0 charging
;---------------------------------------------------------------------------
BigManMoveTable:
	dc.b	$00,$88,$00,$00,$FF,$78,$00,$00,$02,$00,$00,$00,$FE,$00,$00,$00

;---------------------------------------------------------------------------
; State 1 (on screen only). O_Step: 0 walk, 1 fight, 2 shoot down, 3 flinch
;---------------------------------------------------------------------------
BigMan_Active:
        tst.b   O_OnScreen(a5)                  ; 1047C
        beq.b   l_104AA                         ; 10480
        move.b  O_Step(a5),d0                   ; 10482
        add.w   d0,d0                           ; 10486
        add.w   d0,d0                           ; 10488
        jsr     BigMan_Active_Jumps(pc,d0.w)    ; 1048A
        tst.b   O_Param(a5)                     ; 1048E
        beq.b   l_104AA                         ; 10492
        clr.b   O_Param(a5)                     ; 10494  hit (EnemyHitByShot set O_Param): flinch
        move.b  #$3,O_Step(a5)                  ; 10498
        clr.b   O_Step2(a5)                     ; 1049E
        lea.l   BigMan_AnimFlinch(pc),a0        ; 104A2
        bra.w   SetAnimIndexed                  ; 104A6
l_104AA:
        rts                                     ; 104AA
BigMan_Active_Jumps:
        bra.w   BigMan_Walk                     ; 104AC
        bra.w   BigMan_Fight                    ; 104B0
        bra.w   BigMan_ShootDown                ; 104B4
        bra.w   BigMan_Flinch                   ; 104B8

;---------------------------------------------------------------------------
; 6 frames after a hit, then walk
;---------------------------------------------------------------------------
BigMan_Flinch:
        tst.b   O_Step2(a5)                     ; 104BC
        bne.b   l_104CC                         ; 104C0
        move.b  #$6,BM_FlinchTime(a5)           ; 104C2
        addq.b  #$1,O_Step2(a5)                 ; 104C8
l_104CC:
        subq.b  #$1,BM_FlinchTime(a5)           ; 104CC
        bne.w   Animate                         ; 104D0
        clr.b   O_Step(a5)                      ; 104D4
        clr.b   O_Step2(a5)                     ; 104D8
        clr.b   O_Param(a5)                     ; 104DC
        rts                                     ; 104E0

;---------------------------------------------------------------------------
; O_Step2: 0 start, 1 walk, 2 pause, 3-4 crouch
;---------------------------------------------------------------------------
BigMan_Walk:
        clr.w   d0                              ; 104E2
        move.b  O_Step2(a5),d0                  ; 104E4
        add.w   d0,d0                           ; 104E8
        add.w   d0,d0                           ; 104EA
        jmp     BigMan_Walk_Jumps(pc,d0.w)      ; 104EC
BigMan_Walk_Jumps:
        bra.w   BigMan_WalkStart                ; 104F0
        bra.w   BigMan_Walking                  ; 104F4
        bra.w   BigMan_Pause                    ; 104F8
        bra.w   BigMan_CrouchWait               ; 104FC
        bra.w   BigMan_Crouching                ; 10500
BigMan_WalkStart:
        lea.l   BigMan_AnimWalk(pc),a0          ; 10504
        bsr.w   SetAnimIndexed                  ; 10508  start animation for current direction
        tst.b   BM_Crouched(a5)                 ; 1050C
        beq.b   l_10534                         ; 10510
        lea.l   BigMan_AnimCrouch(pc),a0        ; 10512
        bsr.w   SetAnimIndexed                  ; 10516  start animation for current direction
        bsr.w   Random                          ; 1051A  random number
        andi.w  #$3,d0                          ; 1051E
        move.b  BigManCrouchTimes(pc,d0.w),BM_CrouchTime(a5); 10522
        move.b  #$3,O_Step2(a5)                 ; 10528
        clr.b   BM_Crouched(a5)                 ; 1052E
        rts                                     ; 10532
l_10534:
        addq.b  #$1,O_Step2(a5)                 ; 10534
        rts                                     ; 10538

;---------------------------------------------------------------------------
; x 64 frames: 2, 3, 3, 2
;---------------------------------------------------------------------------
BigManCrouchTimes:
	dc.b	$02,$03,$03,$02

;---------------------------------------------------------------------------
; Arthur on its level: fight. Directly below it: shoot down. Otherwise walk,
; turn at floor edges, and pause when the walk time runs out.
;---------------------------------------------------------------------------
BigMan_Walking:
        move.w  g_ArthurY(a6),d0                ; 1053E
        sub.w   O_Y(a5),d0                      ; 10542  Arthur from 10 below to 45 above it: fight
        addi.w  #$a,d0                          ; 10546
        bmi.b   l_1055E                         ; 1054A
        cmp.w   #$37,d0                         ; 1054C
        bhi.b   l_1055E                         ; 10550
        move.b  #$1,O_Step(a5)                  ; 10552
        clr.b   O_Step2(a5)                     ; 10558
        rts                                     ; 1055C
l_1055E:
        move.w  O_X(a5),d0                      ; 1055E
        sub.w   g_ArthurX(a6),d0                ; 10562  Arthur within 10 px across and below: shoot down
        addi.w  #$a,d0                          ; 10566
        cmp.w   #$14,d0                         ; 1056A
        bhi.b   l_10586                         ; 1056E
        move.w  O_Y(a5),d0                      ; 10570
        cmp.w   g_ArthurY(a6),d0                ; 10574
        blt.b   l_10586                         ; 10578
        move.b  #$2,O_Step(a5)                  ; 1057A
        clr.b   O_Step2(a5)                     ; 10580
        rts                                     ; 10584
l_10586:
        move.w  g_GameFrame(a6),d0              ; 10586
        addq.w  #$1,d0                          ; 1058A
        andi.w  #$1f,d0                         ; 1058C
        bne.b   l_10594                         ; 10590
        moveq   #$c,d0                          ; 10592  d0 is not used by what follows. [1MB build: PlaySfx here, effect 9 (footstep); the call was removed in 512K]
l_10594:
        move.w  g_GameFrame(a6),d0              ; 10594
        addq.w  #$1,d0                          ; 10598
        andi.w  #$f,d0                          ; 1059A
        bne.b   l_105C4                         ; 1059E
        bsr.w   BigMan_CheckEdge                ; 105A0  every 16 frames: floor ahead?
        tst.b   BM_AtEdge(a5)                   ; 105A4
        beq.b   l_105C4                         ; 105A8
        move.b  O_Dir(a5),d0                    ; 105AA
        cmp.b   BM_EdgeDir(a5),d0               ; 105AE
        bne.b   l_105C4                         ; 105B2
        bchg    #$0,d0                          ; 105B4  at the edge and still facing it: turn round
        move.b  d0,O_Dir(a5)                    ; 105B8
        lea.l   BigMan_AnimWalk(pc),a0          ; 105BC
        bsr.w   SetAnimIndexed                  ; 105C0  start animation for current direction
l_105C4:
        bsr.w   ApplyMoveTable                  ; 105C4  move by the movement table
        bsr.w   Animate                         ; 105C8  animate
        subq.b  #$1,BM_WalkTime(a5)             ; 105CC
        bne.b   l_10612                         ; 105D0
        movea.l BM_WalkPtr(a5),a0               ; 105D2
        move.b  (a0)+,d0                        ; 105D6
        bne.b   l_105DE                         ; 105D8
        adda.w  (a0),a0                         ; 105DA
        move.b  (a0)+,d0                        ; 105DC
l_105DE:
        move.l  a0,BM_WalkPtr(a5)               ; 105DE
        move.b  d0,BM_WalkTime(a5)              ; 105E2
        bsr.w   Random                          ; 105E6  random number
        andi.w  #$1,d0                          ; 105EA
        bne.b   l_10600                         ; 105EE
        lea.l   BigMan_AnimPauseB(pc),a0        ; 105F0
        bsr.w   SetAnimIndexed                  ; 105F4  start animation for current direction
        move.b  #$64,BM_PauseTime(a5)           ; 105F8  pause 100 frames
        bra.b   l_1060E                         ; 105FE
l_10600:
        lea.l   BigMan_AnimPauseA(pc),a0        ; 10600
        bsr.w   SetAnimIndexed                  ; 10604  start animation for current direction
        move.b  #$46,BM_PauseTime(a5)           ; 10608  or 70
l_1060E:
        addq.b  #$1,O_Step2(a5)                 ; 1060E
l_10612:
        rts                                     ; 10612

;---------------------------------------------------------------------------
; then a random direction
;---------------------------------------------------------------------------
BigMan_Pause:
        subq.b  #$1,BM_PauseTime(a5)            ; 10614
        bne.w   Animate                         ; 10618
        bsr.w   Random                          ; 1061C  random number
        andi.b  #$1,d0                          ; 10620
        move.b  d0,O_Dir(a5)                    ; 10624
        clr.b   O_Step2(a5)                     ; 10628
        rts                                     ; 1062C

;---------------------------------------------------------------------------
; Waits until Arthur is within 16 px of it vertically (one unsigned compare:
; O_Y - Arthur Y + 16 <= 32), then counts BM_CrouchTime
;---------------------------------------------------------------------------
BigMan_CrouchWait:
        move.w  O_Y(a5),d0                      ; 1062E
        sub.w   g_ArthurY(a6),d0                ; 10632
        addi.w  #$10,d0                         ; 10636
        subi.w  #$20,d0                         ; 1063A
        bhi.b   l_10644                         ; 1063E
        addq.b  #$1,O_Step2(a5)                 ; 10640
l_10644:
        rts                                     ; 10644
BigMan_Crouching:
        moveq   #$3f,d0                         ; 10646
        and.w   g_GameFrame(a6),d0              ; 10648
        bne.b   l_1065A                         ; 1064C
        subq.b  #$1,BM_CrouchTime(a5)           ; 1064E
        bne.b   l_1065A                         ; 10652
        move.b  #$1,O_Step2(a5)                 ; 10654
l_1065A:
        rts                                     ; 1065A

;---------------------------------------------------------------------------
; Is there floor 2 px below? No: BM_AtEdge = 1 and remember the direction
;---------------------------------------------------------------------------
BigMan_CheckEdge:
        subq.w  #$2,O_Y(a5)                     ; 1065C
        bsr.w   ObjectMapCollide                ; 10660  on the floor? (Z set = yes, Y snapped onto it)
        beq.b   l_1067E                         ; 10664
        tst.b   BM_AtEdge(a5)                   ; 10666
        bne.b   l_10678                         ; 1066A
        move.b  O_Dir(a5),BM_EdgeDir(a5)        ; 1066C
        move.b  #$1,BM_AtEdge(a5)               ; 10672
l_10678:
        addq.w  #$2,O_Y(a5)                     ; 10678
        rts                                     ; 1067C
l_1067E:
        clr.b   BM_AtEdge(a5)                   ; 1067E
        clr.b   BM_EdgeTurn(a5)                 ; 10682
        rts                                     ; 10686

;---------------------------------------------------------------------------
; O_Step2: 0 face Arthur, 1 pace, 2 charge, 3 wind up, 4 throw
;---------------------------------------------------------------------------
BigMan_Fight:
        clr.w   d0                              ; 10688
        move.b  O_Step2(a5),d0                  ; 1068A
        add.w   d0,d0                           ; 1068E
        add.w   d0,d0                           ; 10690
        jmp     BigMan_Fight_Jumps(pc,d0.w)     ; 10692
BigMan_Fight_Jumps:
        bra.w   BigMan_FightStart               ; 10696
        bra.w   BigMan_Pace                     ; 1069A
        bra.w   BigMan_Charge                   ; 1069E
        bra.w   BigMan_WindUp                   ; 106A2
        bra.w   BigMan_Throw                    ; 106A6
BigMan_FightStart:
        bsr.b   BigMan_CheckEdge                ; 106AA
        move.w  O_X(a5),d0                      ; 106AC
        cmp.w   g_ArthurX(a6),d0                ; 106B0
        slt.b   O_Dir(a5)                       ; 106B4
        addq.b  #$1,O_Dir(a5)                   ; 106B8
        lea.l   BigMan_AnimWalk(pc),a0          ; 106BC
        bsr.w   SetAnimIndexed                  ; 106C0  start animation for current direction
        addq.b  #$1,O_Step2(a5)                 ; 106C4
        rts                                     ; 106C8

;---------------------------------------------------------------------------
; Arthur left its level: walk. Otherwise turn when 40 px past him.
;---------------------------------------------------------------------------
BigMan_Pace:
        move.w  g_ArthurY(a6),d0                ; 106CA
        sub.w   O_Y(a5),d0                      ; 106CE
        addi.w  #$a,d0                          ; 106D2
        bmi.b   l_10720                         ; 106D6
        cmp.w   #$37,d0                         ; 106D8
        bhi.b   l_10720                         ; 106DC
        tst.b   BM_AtEdge(a5)                   ; 106DE
        bne.b   l_1071A                         ; 106E2
        tst.b   O_Dir(a5)                       ; 106E4
        beq.b   l_106FE                         ; 106E8
        move.w  g_ArthurX(a6),d0                ; 106EA
        subi.w  #$28,d0                         ; 106EE
        cmp.w   O_X(a5),d0                      ; 106F2
        bcs.b   l_1071A                         ; 106F6
        clr.b   O_Dir(a5)                       ; 106F8
        bra.b   l_10712                         ; 106FC
l_106FE:
        move.w  g_ArthurX(a6),d0                ; 106FE
        addi.w  #$28,d0                         ; 10702
        cmp.w   O_X(a5),d0                      ; 10706
        bhi.b   l_1071A                         ; 1070A
        move.b  #$1,O_Dir(a5)                   ; 1070C
l_10712:
        lea.l   BigMan_AnimWalk(pc),a0          ; 10712
        bsr.w   SetAnimIndexed                  ; 10716  start animation for current direction
l_1071A:
        addq.b  #$1,O_Step2(a5)                 ; 1071A
        rts                                     ; 1071E
l_10720:
        clr.b   BM_EdgeTurn(a5)                 ; 10720
        clr.b   O_Step(a5)                      ; 10724
        clr.b   O_Step2(a5)                     ; 10728
        rts                                     ; 1072C

;---------------------------------------------------------------------------
; Run at 2 px/frame (not over the edge), and count down to the next shot
;---------------------------------------------------------------------------
BigMan_Charge:
        bsr.w   BigMan_CheckEdge                ; 1072E
        tst.b   BM_AtEdge(a5)                   ; 10732
        beq.b   l_10774                         ; 10736
        move.w  O_X(a5),d0                      ; 10738
        cmp.w   g_ArthurX(a6),d0                ; 1073C
        bhi.b   l_10756                         ; 10740
        move.b  BM_EdgeDir(a5),d0               ; 10742
        beq.b   l_10780                         ; 10746
        tst.b   BM_EdgeTurn(a5)                 ; 10748
        bne.b   l_10774                         ; 1074C
        move.b  d0,BM_EdgeTurn(a5)              ; 1074E
        clr.b   d0                              ; 10752
        bra.b   l_10768                         ; 10754
l_10756:
        tst.b   BM_EdgeDir(a5)                  ; 10756
        bne.b   l_10780                         ; 1075A
        tst.b   BM_EdgeTurn(a5)                 ; 1075C
