;---------------------------------------------------------------------------
; === Zombie (type 11, 200 pts) ===
; Spawned at run time near Arthur: rises out of the ground (size class changes as it emerges), shambles along the floor and sinks back. Sound effect 20.
; Dispatches on O_State: 0 main behaviour, 1 type-specific second phase, 2 killed (set by EnemyHitByShot after scoring), 3 remove.
;
; Behaviour, as coded: created hidden (shots pass through), drops onto the floor, waits a
; random 12-187 frames (parameter 1: no wait), then rises out of the ground, its size class
; growing with the animation. It shambles towards Arthur at 0.81 px/frame; once past him it
; walks on for 40-110 frames, then sinks back into the ground (also after 360 frames, or
; when the floor ends). Shots pass through it while it rises and sinks.
;---------------------------------------------------------------------------
Enemy_Zombie:
        move.b  O_State(a5),d0                  ; 109C4
        add.w   d0,d0                           ; 109C8
        add.w   d0,d0                           ; 109CA
        jmp     Enemy_Zombie_Jumps(pc,d0.w)     ; 109CC
Enemy_Zombie_Jumps:
        bra.w   Zombie_Init                     ; 109D0
        bra.w   Zombie_Active                   ; 109D4
        bra.w   Zombie_Dying                    ; 109D8
        bra.w   Zombie_Free                     ; 109DC
ZombieInitSteps:
        bra.w   Zombie_Hide                     ; 109E0
        bra.w   Zombie_Drop                     ; 109E4
        bra.w   Zombie_WaitRise                 ; 109E8
        bra.w   Zombie_StartRise                ; 109EC

;---------------------------------------------------------------------------
; State 0. O_Step 0: O_Step2 0 hide, 1 drop to the floor, 2 wait, 3 start rising;
; O_Step 1: rise
;---------------------------------------------------------------------------
Zombie_Init:
        tst.b   O_Step(a5)                      ; 109F0
        bne.w   Zombie_Rise                     ; 109F4
        clr.w   d0                              ; 109F8
        move.b  O_Step2(a5),d0                  ; 109FA
        add.w   d0,d0                           ; 109FE
        add.w   d0,d0                           ; 10A00
        jmp     ZombieInitSteps(pc,d0.w)        ; 10A02

;---------------------------------------------------------------------------
; shots pass through, size 0, invisible
;---------------------------------------------------------------------------
Zombie_Hide:
        move.b  #$2,(a5)                        ; 10A06
        clr.b   O_Size(a5)                      ; 10A0A
        clr.l   O_Anim(a5)                      ; 10A0E
        addq.b  #$1,O_Step2(a5)                 ; 10A12
l_10A16:
        rts                                     ; 10A16

;---------------------------------------------------------------------------
; Move down 2 px a frame until there is floor; parameter 1 starts at once
;---------------------------------------------------------------------------
Zombie_Drop:
        subq.w  #$2,O_Y(a5)                     ; 10A18
        bsr.w   ObjectMapCollide                ; 10A1C  on the floor? (Z set = yes, Y snapped onto it)
        bne.b   l_10A16                         ; 10A20
        tst.b   O_Param(a5)                     ; 10A22
        beq.b   l_10A38                         ; 10A26
        move.b  #ST_ACTIVE,O_State(a5)          ; 10A28
        clr.b   O_Step(a5)                      ; 10A2E
        clr.b   O_Step2(a5)                     ; 10A32
        rts                                     ; 10A36
l_10A38:
        lea.l   ZombieRiseDelays(pc),a0         ; 10A38
        move.w  d7,d0                           ; 10A3C
        add.w   g_GameFrame(a6),d0              ; 10A3E
        andi.w  #$f,d0                          ; 10A42
        adda.w  d0,a0                           ; 10A46
        move.b  (a0),Zmb_Timer(a5)              ; 10A48
        move.b  #$b4,Zmb_WalkTime(a5)           ; 10A4C  walk for 180 x 2 frames at most
        addq.b  #$1,O_Step2(a5)                 ; 10A52
        rts                                     ; 10A56
Zombie_WaitRise:
        subq.b  #$1,Zmb_Timer(a5)               ; 10A58
