        move.b  (a0)+,O_Size(a5)                ; 10AAC
        move.l  a0,Zmb_SizePtr(a5)              ; 10AB0
        move.b  #$7,Zmb_Steps(a5)               ; 10AB4
        addq.b  #$1,O_Step2(a5)                 ; 10ABA
        rts                                     ; 10ABE
l_10AC0:
