        bsr.w   SetBoxClass                     ; 10AD0  change size class
        subq.b  #$1,Zmb_Steps(a5)               ; 10AD4
        bne.b   l_10AEC                         ; 10AD8
        move.b  #ST_ACTIVE,O_State(a5)          ; 10ADA
        clr.b   O_Step(a5)                      ; 10AE0
        clr.b   O_Step2(a5)                     ; 10AE4
        move.b  #$1,(a5)                        ; 10AE8
l_10AEC:
        bsr.w   Animate                         ; 10AEC  animate
        rts                                     ; 10AF0
