        bsr.w   ObjectMapCollide                ; 10B68  on the floor? (Z set = yes, Y snapped onto it)
        bne.b   l_10B9C                         ; 10B6C
        tst.b   O_Dir(a5)                       ; 10B6E
        beq.b   l_10B80                         ; 10B72
        move.w  O_X(a5),d0                      ; 10B74
        cmp.w   g_ArthurX(a6),d0                ; 10B78
        bhi.b   l_10B8E                         ; 10B7C
        bra.b   l_10B8A                         ; 10B7E
l_10B80:
        move.w  O_X(a5),d0                      ; 10B80
        cmp.w   g_ArthurX(a6),d0                ; 10B84
        bls.b   l_10B8E                         ; 10B88
l_10B8A:
        addq.b  #$1,O_Step2(a5)                 ; 10B8A
l_10B8E:
        moveq   #$1,d0                          ; 10B8E
        and.w   g_GameFrame(a6),d0              ; 10B90
        beq.b   l_10BA6                         ; 10B94
        subq.b  #$1,Zmb_WalkTime(a5)            ; 10B96  every other frame
