;---------------------------------------------------------------------------
Zombie_Dying:
        cmpi.b  #$1,O_Step(a5)                  ; 10C14
        beq.b   l_10C2A                         ; 10C1A
        bcc.b   l_10C2E                         ; 10C1C
        moveq   #SFX_ENEMY_DIE2,d0              ; 10C1E
        bsr.w   PlaySfx                         ; 10C20  sound effect 20 (enemy event)
        addq.b  #$1,O_Step(a5)                  ; 10C24  next step
        rts                                     ; 10C28
l_10C2A:
        bra.w   EnemyDieFacing                  ; 10C2A
l_10C2E:
        move.b  #ST_REMOVE,O_State(a5)          ; 10C2E
        rts                                     ; 10C34

;---------------------------------------------------------------------------
