;---------------------------------------------------------------------------
; === Dragon (type 12, 200 pts per segment) ===
; Flying dragon boss of levels 2-3: a chain of segments led by the head (6 hits); the head aims and breathes fire at Arthur. Sound effects 12/20; awards 1000 extra on defeat.
; Dispatches on O_State: 0 main behaviour, 1 type-specific second phase, 2 killed (set by EnemyHitByShot after scoring), 3 remove.
;
; Behaviour, as coded:
;   * The placed head (parameter 0) builds the body: 7 segments (parameter 1) and a tail
;     (parameter 2) in free enemy slots, linked through Drg_Next / Drg_Prev.
;   * The head steers along path scripts of (frames, direction) pairs in 16 directions
;     at 2 px/frame. Each direction change is handed down the chain with a 6-frame
;     delay per segment (7 for the tail), which makes the body follow the head's path.
;   * Entrance: a short S-curve, then it waits frozen until it is on screen and Arthur
;     is no more than 32 px below it, for a further 2-5 x 16 frames, then attacks.
;   * Attack: when a path step ends it may (3 in 16) dive at Arthur if he is 24+ px in
;     front of it; otherwise it turns round once it is 94+ px past him (turn paths for the
;     upper and lower half of the screen), and climbs or descends towards his height.
;   * Every 32 frames, if Arthur is within 72 px vertically, it breathes fire (enemy shot
;     type 9) and opens its mouth for 10 frames.
;   * Hits: each hit on any segment scores 200. Hitting the tail kills it; hitting a body
;     segment kills the tail instead, so the dragon shortens from the tail. The head takes
;     6 hits; killing it kills every segment, scores a further 1000 and ends the boss.
;   * Off levels 2-3 it is removed when it gets far off screen.
;---------------------------------------------------------------------------
Enemy_Dragon:
        move.b  O_State(a5),d0                  ; 10CCE
        add.w   d0,d0                           ; 10CD2
        add.w   d0,d0                           ; 10CD4
        jmp     Enemy_Dragon_Jumps(pc,d0.w)     ; 10CD6
Enemy_Dragon_Jumps:
        bra.w   Dragon_Init                     ; 10CDA
        bra.w   Dragon_Active                   ; 10CDE
        bra.w   Dragon_Dying                    ; 10CE2
        bra.w   Dragon_Free                     ; 10CE6

;---------------------------------------------------------------------------
; State 0: by part (O_Param): head / body segment / tail
;---------------------------------------------------------------------------
Dragon_Init:
        move.b  O_Param(a5),d0                  ; 10CEA
        add.w   d0,d0                           ; 10CEE
        add.w   d0,d0                           ; 10CF0
        jmp     Dragon_Init_Jumps(pc,d0.w)      ; 10CF2
Dragon_Init_Jumps:
        bra.w   Dragon_InitHead                 ; 10CF6
        bra.w   Dragon_InitBody                 ; 10CFA
        bra.w   Dragon_InitTail                 ; 10CFE
Dragon_InitHead:
        move.b  O_Step(a5),d0                   ; 10D02
        add.w   d0,d0                           ; 10D06
        add.w   d0,d0                           ; 10D08
        jmp     Dragon_InitHead_Jumps(pc,d0.w)  ; 10D0A
Dragon_InitHead_Jumps:
        bra.w   Dragon_HeadSetup                ; 10D0E
        bra.w   Dragon_BuildBody                ; 10D12
        bra.w   Dragon_NumberChain              ; 10D16

;---------------------------------------------------------------------------
; Face Arthur, size 3, 6 HP, 16-way move table, start the entrance path
;---------------------------------------------------------------------------
Dragon_HeadSetup:
        clr.b   O_Dir(a5)                       ; 10D1A
        clr.b   Drg_Facing(a5)                  ; 10D1E
        clr.b   Drg_Part(a5)                    ; 10D22
        move.w  O_X(a5),d0                      ; 10D26
        cmp.w   g_ArthurX(a6),d0                ; 10D2A
        blt.b   l_10D3C                         ; 10D2E
        move.b  #$8,O_Dir(a5)                   ; 10D30  Arthur to the left: direction 8, facing left
        move.b  #$1,Drg_Facing(a5)              ; 10D36
l_10D3C:
        move.b  #$3,O_Size(a5)                  ; 10D3C
        lea.l   Dragon_AnimFly(pc),a0           ; 10D42
        clr.w   d0                              ; 10D46
        move.b  Drg_Facing(a5),d0               ; 10D48
        add.w   d0,d0                           ; 10D4C
        adda.w  d0,a0                           ; 10D4E
        adda.w  (a0),a0                         ; 10D50
        bsr.w   SetAnim                         ; 10D52  start animation
        lea.l   DragonMoveTable(pc),a0          ; 10D56
        move.l  a0,O_MoveTable(a5)              ; 10D5A
        lea.l   DragonEntrancePath(pc),a0       ; 10D5E
        move.b  (a0)+,Drg_PathTime(a5)          ; 10D62
        move.b  (a0)+,O_Dir(a5)                 ; 10D66
        move.l  a0,Drg_PathPtr(a5)              ; 10D6A
        move.b  #$2,Drg_Aggro(a5)               ; 10D6E  attack chance 3 in 16
        clr.b   Drg_Firing(a5)                  ; 10D74
        clr.b   Drg_Pending(a5)                 ; 10D78
        clr.b   Drg_Frozen(a5)                  ; 10D7C
        move.b  #$6,O_HP(a5)                    ; 10D80
        move.w  O_Y(a5),Drg_HomeY(a5)           ; 10D86
        addq.b  #$1,O_Step(a5)                  ; 10D8C  next step
        clr.b   O_Step2(a5)                     ; 10D90
        rts                                     ; 10D94

;---------------------------------------------------------------------------
; Allocate 7 body segments and the tail behind the head, each linked to the one
; before it (14 px apart, the first 20 px). Tries again next frame if the table is full.
;---------------------------------------------------------------------------
Dragon_BuildBody:
        moveq   #$7,d6                          ; 10D96
        clr.l   Drg_Prev(a5)                    ; 10D98
        movea.l a5,a3                           ; 10D9C
l_10D9E:
        lea.l   g_Enemies(a6),a4                ; 10D9E
        moveq   #$27,d5                         ; 10DA2
l_10DA4:
        tst.b   (a4)                            ; 10DA4
        beq.b   l_10DB4                         ; 10DA6
        lea.l   $3c(a4),a4                      ; 10DA8
        dbra    d5,l_10DA4                      ; 10DAC
        bra.w   Dragon_BuildExit                ; 10DB0
l_10DB4:
        move.l  a4,$24(a3)                      ; 10DB4
        cmp.b   #$7,d6                          ; 10DB8  first segment: 20 px behind the head, 3 px lower
        beq.b   l_10DD2                         ; 10DBC
        move.w  $6(a3),d0                       ; 10DBE
        addi.w  #$e,d0                          ; 10DC2
        move.w  d0,$6(a4)                       ; 10DC6
        move.w  $a(a3),$a(a4)                   ; 10DCA
        bra.b   l_10DE8                         ; 10DD0
l_10DD2:
        move.w  $6(a3),d0                       ; 10DD2
        addi.w  #$14,d0                         ; 10DD6
        move.w  d0,$6(a4)                       ; 10DDA
        move.w  $a(a3),d0                       ; 10DDE
        subq.w  #$3,d0                          ; 10DE2
        move.w  d0,$a(a4)                       ; 10DE4
l_10DE8:
        clr.b   $3(a4)                          ; 10DE8
        clr.b   $4(a4)                          ; 10DEC
        clr.b   $5(a4)                          ; 10DF0
        move.b  #$1,(a4)                        ; 10DF4
        clr.b   $1(a4)                          ; 10DF8
        move.b  O_Type(a5),$1a(a4)              ; 10DFC
        move.b  #$1,$2(a4)                      ; 10E02
        move.l  a3,$28(a4)                      ; 10E08  link back to the previous segment
        movea.l a4,a3                           ; 10E0C
        subq.w  #$1,d6                          ; 10E0E
        bne.b   l_10D9E                         ; 10E10
        lea.l   g_Enemies(a6),a4                ; 10E12
        moveq   #$27,d5                         ; 10E16
l_10E18:
        tst.b   (a4)                            ; 10E18
        beq.b   l_10E26                         ; 10E1A
        lea.l   $3c(a4),a4                      ; 10E1C
        dbra    d5,l_10E18                      ; 10E20
        bra.b   Dragon_BuildExit                ; 10E24
l_10E26:
        move.l  a4,$24(a3)                      ; 10E26
        move.l  a3,$28(a4)                      ; 10E2A
        clr.l   $24(a4)                         ; 10E2E
        move.b  O_Type(a5),$1a(a4)              ; 10E32
        move.b  #$2,$2(a4)                      ; 10E38
        clr.b   $3(a4)                          ; 10E3E
        clr.b   $4(a4)                          ; 10E42
        clr.b   $5(a4)                          ; 10E46
        move.b  #$1,(a4)                        ; 10E4A
        clr.b   $1(a4)                          ; 10E4E
        move.w  $6(a3),d0                       ; 10E52
        addi.w  #$c,d0                          ; 10E56
        move.w  d0,$6(a4)                       ; 10E5A
        move.w  $a(a3),d0                       ; 10E5E
        addq.w  #$2,d0                          ; 10E62
        move.w  d0,$a(a4)                       ; 10E64
        addq.b  #$1,O_Step(a5)                  ; 10E68  next step
Dragon_BuildExit:
        rts                                     ; 10E6C

;---------------------------------------------------------------------------
; Drg_Index: 8 for the head down to 0 for the tail
;---------------------------------------------------------------------------
Dragon_NumberChain:
        movea.l a5,a4                           ; 10E6E
        moveq   #$8,d0                          ; 10E70
        moveq   #$8,d6                          ; 10E72
l_10E74:
        move.b  d0,$37(a4)                      ; 10E74
        subq.b  #$1,d0                          ; 10E78
        movea.l $24(a4),a4                      ; 10E7A
        dbra    d6,l_10E74                      ; 10E7E
        move.b  #ST_ACTIVE,O_State(a5)          ; 10E82
        clr.b   O_Step(a5)                      ; 10E88
        clr.b   O_Step2(a5)                     ; 10E8C
