Dragon_InitBody:
        clr.b   O_Dir(a5)                       ; 10E92
        move.w  O_X(a5),d0                      ; 10E96
        sub.w   g_ArthurX(a6),d0                ; 10E9A
        blt.b   l_10EA6                         ; 10E9E
        move.b  #$8,O_Dir(a5)                   ; 10EA0
l_10EA6:
        move.b  #$1,O_Size(a5)                  ; 10EA6
        lea.l   Dragon_AnimBody(pc),a0          ; 10EAC
        bsr.w   SetAnim                         ; 10EB0  start animation
        lea.l   DragonMoveTable(pc),a0          ; 10EB4
        move.l  a0,O_MoveTable(a5)              ; 10EB8
        clr.b   Drg_NewDir(a5)                  ; 10EBC
        clr.b   Drg_Delay(a5)                   ; 10EC0
        clr.b   Drg_Pending(a5)                 ; 10EC4
        clr.b   Drg_Frozen(a5)                  ; 10EC8
        clr.b   Drg_Firing(a5)                  ; 10ECC
        move.b  #$1,O_HP(a5)                    ; 10ED0
        move.b  #$1,Drg_Part(a5)                ; 10ED6
        move.b  #ST_ACTIVE,O_State(a5)          ; 10EDC
        clr.b   O_Step(a5)                      ; 10EE2
        clr.b   O_Step2(a5)                     ; 10EE6
        rts                                     ; 10EEA

;---------------------------------------------------------------------------
; Tail: size 0, 1 HP, Drg_Part 2
