Dragon_InitTail:
        clr.b   O_Dir(a5)                       ; 10EEC
        move.w  O_X(a5),d0                      ; 10EF0
        sub.w   g_ArthurX(a6),d0                ; 10EF4
        blt.b   l_10F00                         ; 10EF8
        move.b  #$8,O_Dir(a5)                   ; 10EFA
l_10F00:
        move.b  #$0,O_Size(a5)                  ; 10F00
        lea.l   Dragon_AnimTail(pc),a0          ; 10F06
        bsr.w   SetAnim                         ; 10F0A  start animation
        lea.l   DragonMoveTable(pc),a0          ; 10F0E
        move.l  a0,O_MoveTable(a5)              ; 10F12
        clr.b   Drg_NewDir(a5)                  ; 10F16
        clr.b   Drg_Delay(a5)                   ; 10F1A
        clr.b   Drg_Pending(a5)                 ; 10F1E
        clr.b   Drg_Frozen(a5)                  ; 10F22
        clr.b   Drg_Firing(a5)                  ; 10F26
        move.b  #$1,O_HP(a5)                    ; 10F2A
        move.b  #$2,Drg_Part(a5)                ; 10F30
        move.b  #ST_ACTIVE,O_State(a5)          ; 10F36
        clr.b   O_Step(a5)                      ; 10F3C
        clr.b   O_Step2(a5)                     ; 10F40
        rts                                     ; 10F44

;---------------------------------------------------------------------------
; DragonEntrancePath - (frames, direction) steps flown on arrival (DSTEP; directions as
; DragonMoveTable: 0 right, 4 down, 8 left, 12 up), ended by a zero word. Then DragonPatrolPath.
;---------------------------------------------------------------------------
DragonEntrancePath:
	DSTEP	10,9	; WNW
	DSTEP	10,15	; ENE
	DSTEP	10,0	; E
	DSTEP	10,1	; ESE
	DSTEP	10,7	; WSW
	DSTEP	10,8	; W
	dc.w	0		; end

;---------------------------------------------------------------------------
; 16-way (dx, dy) at 2 px/frame (8.8), 0 = right, 4 = down
;---------------------------------------------------------------------------
DragonMoveTable:
	dc.b	$02,$00,$00,$00,$01,$D9,$FF,$3D,$01,$6A,$FE,$96,$00,$C3,$FE,$27
	dc.b	$00,$00,$FE,$00,$FF,$3D,$FE,$27,$FE,$96,$FE,$96,$FE,$27,$FF,$3D
	dc.b	$FE,$00,$00,$00,$FE,$27,$00,$C3,$FE,$96,$01,$6A,$FF,$3D,$01,$D9
	dc.b	$00,$00,$02,$00,$00,$C3,$01,$D9,$01,$6A,$01,$6A,$01,$D9,$00,$C3

;---------------------------------------------------------------------------
; State 1: head or segment; then remove it when far off screen (not on levels 2-3)
;---------------------------------------------------------------------------
Dragon_Active:
        tst.b   Drg_Part(a5)                    ; 10F94
        bne.b   l_10F9E                         ; 10F98
        bsr.b   Dragon_Head                     ; 10F9A
        bra.b   l_10FA2                         ; 10F9C
l_10F9E:
        bsr.w   Dragon_Segment                  ; 10F9E
l_10FA2:
        cmpi.w  #$2,g_Level(a6)                 ; 10FA2  levels 2 and 3: never removed
        beq.b   l_10FE4                         ; 10FA8
        cmpi.w  #$3,g_Level(a6)                 ; 10FAA
        beq.b   l_10FE4                         ; 10FB0
        move.w  O_X(a5),d0                      ; 10FB2
        sub.w   g_CameraX(a6),d0                ; 10FB6
        addi.w  #$180,d0                        ; 10FBA
        cmp.w   #$400,d0                        ; 10FBE
        bhi.b   l_10FD6                         ; 10FC2
        move.w  O_Y(a5),d0                      ; 10FC4
        sub.w   g_CameraY(a6),d0                ; 10FC8
        addi.w  #$180,d0                        ; 10FCC
        cmp.w   #$400,d0                        ; 10FD0
        bls.b   l_10FE4                         ; 10FD4
l_10FD6:
        move.b  #ST_REMOVE,O_State(a5)          ; 10FD6
        clr.b   O_Step(a5)                      ; 10FDC
        clr.b   O_Step2(a5)                     ; 10FE0
l_10FE4:
        rts                                     ; 10FE4

;---------------------------------------------------------------------------
; O_Step 0 = entrance (O_Step2 0 start, 1 path, 2 pick wait, 3 wait to be seen,
; 4 wait for Arthur), O_Step 1 = attack.
;---------------------------------------------------------------------------
Dragon_Head:
        tst.b   O_Step(a5)                      ; 10FE6
        bne.w   Dragon_Attack                   ; 10FEA
        move.b  O_Step2(a5),d0                  ; 10FEE
        add.w   d0,d0                           ; 10FF2
        add.w   d0,d0                           ; 10FF4
        jmp     Dragon_Head_Jumps(pc,d0.w)      ; 10FF6
Dragon_Head_Jumps:
        bra.w   Dragon_EntranceStart            ; 10FFA
        bra.w   Dragon_EntrancePath             ; 10FFE
        bra.w   Dragon_PickWait                 ; 11002
        bra.w   Dragon_WaitSeen                 ; 11006
        bra.w   Dragon_WaitArthur               ; 1100A
Dragon_EntranceStart:
        movea.l Drg_Next(a5),a4                 ; 1100E
        move.b  Drg_PathTime(a5),$39(a4)        ; 11012
        move.b  O_Dir(a5),$38(a4)               ; 11018
        move.b  #$1,$34(a4)                     ; 1101E
        addq.b  #$1,O_Step2(a5)                 ; 11024
        rts                                     ; 11028

;---------------------------------------------------------------------------
; Follow the entrance path, handing each new direction to the next segment.
; At its end: freeze every segment and load the patrol path.
;---------------------------------------------------------------------------
Dragon_EntrancePath:
        subq.b  #$1,Drg_PathTime(a5)            ; 1102A
        bne.b   l_11060                         ; 1102E
        movea.l Drg_PathPtr(a5),a0              ; 11030
        move.b  (a0)+,d0                        ; 11034
        move.b  (a0)+,d1                        ; 11036
        tst.w   -$2(a0)                         ; 11038
        beq.b   l_11062                         ; 1103C
        move.b  d0,Drg_PathTime(a5)             ; 1103E
        move.b  d1,O_Dir(a5)                    ; 11042
        move.l  a0,Drg_PathPtr(a5)              ; 11046
        movea.l Drg_Next(a5),a4                 ; 1104A
        move.b  d0,$39(a4)                      ; 1104E
        move.b  d1,$38(a4)                      ; 11052
        move.b  #$1,$34(a4)                     ; 11056
        bra.w   ApplyMoveTable                  ; 1105C
l_11060:
        rts                                     ; 11060
l_11062:
        moveq   #$8,d6                          ; 11062
        movea.l a5,a4                           ; 11064
l_11066:
        move.b  #$1,$35(a4)                     ; 11066
        movea.l $24(a4),a4                      ; 1106C
        dbra    d6,l_11066                      ; 11070
        lea.l   DragonPatrolPath(pc),a0         ; 11074  patrol path
        adda.w  (a0),a0                         ; 11078
        move.b  (a0)+,Drg_PathTime(a5)          ; 1107A
        move.b  (a0)+,O_Dir(a5)                 ; 1107E
        move.l  a0,Drg_PathPtr(a5)              ; 11082
        movea.l Drg_Next(a5),a4                 ; 11086
        move.b  Drg_PathTime(a5),$39(a4)        ; 1108A
        move.b  O_Dir(a5),$38(a4)               ; 11090
        move.b  #$1,$34(a4)                     ; 11096
        addq.b  #$1,O_Step2(a5)                 ; 1109C
        rts                                     ; 110A0

;---------------------------------------------------------------------------
; x 16 frames: 3, 2, 3, 2 (level 5: 5, 2, 5, 4)
;---------------------------------------------------------------------------
DragonWaitTimes:
	dc.b	$03,$02,$03,$02

;---------------------------------------------------------------------------
; Dragon wait times on level 5 (DragonWaitTimes elsewhere)
;---------------------------------------------------------------------------
DragonWaitTimesL5:
	dc.b	$05,$02,$05,$04
Dragon_PickWait:
        lea.l   DragonWaitTimesL5(pc),a0        ; 110AA
        cmpi.w  #$5,g_Level(a6)                 ; 110AE
        beq.b   l_110BA                         ; 110B4
        lea.l   DragonWaitTimes(pc),a0          ; 110B6
l_110BA:
        move.w  g_GameFrame(a6),d0              ; 110BA
        add.w   d7,d0                           ; 110BE
        andi.w  #$3,d0                          ; 110C0
        adda.w  d0,a0                           ; 110C4
        move.b  (a0),Drg_Wait(a5)               ; 110C6
        addq.b  #$1,O_Step2(a5)                 ; 110CA
        rts                                     ; 110CE
Dragon_WaitSeen:
        tst.b   O_OnScreen(a5)                  ; 110D0
        beq.b   l_110DA                         ; 110D4
        addq.b  #$1,O_Step2(a5)                 ; 110D6
l_110DA:
