;---------------------------------------------------------------------------
; Count down Drg_Wait (every 16 frames) while Arthur is no more than 32 px below;
; then unfreeze the chain and attack
;---------------------------------------------------------------------------
Dragon_WaitArthur:
        move.w  g_ArthurY(a6),d0                ; 110DC
        addi.w  #$20,d0                         ; 110E0
        sub.w   O_Y(a5),d0                      ; 110E4  Arthur more than 32 px below it: wait
        bmi.b   l_1111E                         ; 110E8
        move.w  g_GameFrame(a6),d0              ; 110EA
        addq.w  #$1,d0                          ; 110EE
        andi.w  #$f,d0                          ; 110F0
        bne.b   l_1111E                         ; 110F4
        subq.b  #$1,Drg_Wait(a5)                ; 110F6
        bne.b   l_1111E                         ; 110FA
        move.b  #$1,O_Step(a5)                  ; 110FC
        clr.b   O_Step2(a5)                     ; 11102
        addq.b  #$1,g_BigEnemyCount(a6)         ; 11106  one more big enemy engaged
        moveq   #$8,d6                          ; 1110A
        movea.l a5,a4                           ; 1110C
l_1110E:
        clr.b   $35(a4)                         ; 1110E
        move.l  $24(a4),d0                      ; 11112
        beq.b   l_1111E                         ; 11116
        movea.l d0,a4                           ; 11118
        dbra    d6,l_1110E                      ; 1111A
l_1111E:
        rts                                     ; 1111E

;---------------------------------------------------------------------------
; Flap every 128 frames, steer, breathe fire, move
;---------------------------------------------------------------------------
Dragon_Attack:
        move.w  g_GameFrame(a6),d0              ; 11120
        addq.w  #$1,d0                          ; 11124
        andi.w  #$7f,d0                         ; 11126
        bne.b   l_11144                         ; 1112A
        lea.l   Dragon_AnimFlap(pc),a0          ; 1112C
        tst.b   Drg_Facing(a5)                  ; 11130
        beq.b   l_11138                         ; 11134
        addq.l  #$2,a0                          ; 11136
l_11138:
        adda.w  (a0),a0                         ; 11138
        move.l  a0,O_Anim(a5)                   ; 1113A
        move.b  #$a,O_AnimTimer(a5)             ; 1113E
l_11144:
        bsr.w   Animate                         ; 11144  animate
        bsr.w   Random                          ; 11148  random number
        move.b  d0,d5                           ; 1114C
        bsr.b   Dragon_Steer                    ; 1114E
        bsr.w   Dragon_Breathe                  ; 11150
        bra.w   ApplyMoveTable                  ; 11154

;---------------------------------------------------------------------------
; When the path step ends: maybe dive at Arthur, turn round, or climb / descend
; towards his height (level 5: stay near Drg_HomeY)
;---------------------------------------------------------------------------
Dragon_Steer:
        subq.b  #$1,Drg_PathTime(a5)            ; 11158
        beq.b   l_11160                         ; 1115C
        rts                                     ; 1115E
l_11160:
        cmpi.w  #$5,g_Level(a6)                 ; 11160  level 5: never dives
        beq.b   Dragon_TurnCheck                ; 11166
        moveq   #$f,d0                          ; 11168  3 in 16 chance to dive
        and.b   d5,d0                           ; 1116A
        cmp.b   Drg_Aggro(a5),d0                ; 1116C
        bhi.b   Dragon_TurnCheck                ; 11170
        tst.b   Drg_Facing(a5)                  ; 11172
        beq.b   l_111B0                         ; 11176
        move.w  O_X(a5),d0                      ; 11178  facing left: Arthur must be 24+ px to the left
        sub.w   g_ArthurX(a6),d0                ; 1117C
        subi.w  #$18,d0                         ; 11180
        bmi.b   Dragon_TurnCheck                ; 11184

;---------------------------------------------------------------------------
; Head for Arthur (not straight down) for 40 frames, 18 if it is in the bottom 96 px of the screen
;---------------------------------------------------------------------------
Dragon_DiveAtArthur:
        bsr.w   DirectionToArthur               ; 11186  direction towards Arthur
        cmp.b   #$4,d0                          ; 1118A  not straight down
        beq.b   Dragon_TurnCheck                ; 1118E
        move.b  d0,d4                           ; 11190
        move.w  g_CameraY(a6),d3                ; 11192
        addi.w  #$60,d3                         ; 11196
        moveq   #$28,d0                         ; 1119A
        move.w  O_Y(a5),d1                      ; 1119C
        cmp.w   d3,d1                           ; 111A0
        bhi.b   l_111A6                         ; 111A2
        moveq   #$12,d0                         ; 111A4
l_111A6:
        move.b  d4,d1                           ; 111A6
        movea.l Drg_PathPtr(a5),a0              ; 111A8
        bra.w   Dragon_SetPathStep              ; 111AC
l_111B0:
        move.w  g_ArthurX(a6),d0                ; 111B0
        sub.w   O_X(a5),d0                      ; 111B4
        subi.w  #$18,d0                         ; 111B8
        bpl.b   Dragon_DiveAtArthur             ; 111BC
Dragon_TurnCheck:
        move.w  O_X(a5),d0                      ; 111BE
        cmp.w   g_ArthurX(a6),d0                ; 111C2
        bhi.b   l_111D2                         ; 111C6
        tst.b   Drg_Facing(a5)                  ; 111C8
        bne.b   l_111DA                         ; 111CC
        bra.w   Dragon_SeekHeight               ; 111CE
l_111D2:
        tst.b   Drg_Facing(a5)                  ; 111D2
        bne.w   Dragon_SeekHeight               ; 111D6
l_111DA:
        move.w  g_LevelWidth(a6),d0             ; 111DA  past the right end of the level, or 94+ px past Arthur: turn
        addi.w  #$100,d0                        ; 111DE
        cmp.w   O_X(a5),d0                      ; 111E2
        bls.b   Dragon_Turn                     ; 111E6
        move.w  O_X(a5),d0                      ; 111E8
        sub.w   g_ArthurX(a6),d0                ; 111EC
        addi.w  #$5e,d0                         ; 111F0
        cmp.w   #$bc,d0                         ; 111F4
        bcs.w   Dragon_SeekHeight               ; 111F8

;---------------------------------------------------------------------------
; Turn round: path for the upper or lower half of the screen, flip Drg_Facing
;---------------------------------------------------------------------------
Dragon_Turn:
        move.w  g_CameraY(a6),d3                ; 111FC
        addi.w  #$80,d3                         ; 11200
        moveq   #$0,d0                          ; 11204
        move.w  O_Y(a5),d1                      ; 11206
        cmp.w   d3,d1                           ; 1120A
        bcs.b   l_11210                         ; 1120C
        moveq   #$2,d0                          ; 1120E
l_11210:
        lea.l   DragonTurnRight(pc),a0          ; 11210
        clr.w   d1                              ; 11214
        move.b  Drg_Facing(a5),d1               ; 11216
        beq.b   l_11220                         ; 1121A
        lea.l   DragonTurnLeft(pc),a0           ; 1121C
l_11220:
        adda.w  d0,a0                           ; 11220
        adda.w  (a0),a0                         ; 11222
        move.l  a0,Drg_PathPtr(a5)              ; 11224
        eori.b  #$1,d1                          ; 11228
        move.b  d1,Drg_Facing(a5)               ; 1122C
        add.w   d1,d1                           ; 11230
        lea.l   Dragon_AnimFly(pc),a0           ; 11232
        adda.w  d1,a0                           ; 11236
        adda.w  (a0),a0                         ; 11238
        bsr.w   SetAnim                         ; 1123A  start animation

;---------------------------------------------------------------------------
; Next (frames, direction) pair; bit 7 = loop (offset follows)
;---------------------------------------------------------------------------
Dragon_NextPathStep:
        movea.l Drg_PathPtr(a5),a0              ; 1123E
        move.b  (a0)+,d0                        ; 11242
        move.b  (a0)+,d1                        ; 11244
        tst.b   d0                              ; 11246
        bpl.b   Dragon_SetPathStep              ; 11248
        andi.b  #$7f,d0                         ; 1124A
        adda.w  (a0),a0                         ; 1124E

;---------------------------------------------------------------------------
; Take a (frames, direction) step and hand the direction to the next segment
; (10-frame delay)
;---------------------------------------------------------------------------
Dragon_SetPathStep:
        move.b  d0,Drg_PathTime(a5)             ; 11250
        move.b  d1,O_Dir(a5)                    ; 11254
        move.l  a0,Drg_PathPtr(a5)              ; 11258
        move.l  Drg_Next(a5),d0                 ; 1125C
        beq.b   l_1127E                         ; 11260
        movea.l d0,a4                           ; 11262
        move.b  O_Dir(a5),d0                    ; 11264
        cmp.b   $12(a4),d0                      ; 11268
        beq.b   l_1127E                         ; 1126C
        move.b  d0,$38(a4)                      ; 1126E
        move.b  #$a,$39(a4)                     ; 11272
        move.b  #$1,$34(a4)                     ; 11278
l_1127E:
        rts                                     ; 1127E

;---------------------------------------------------------------------------
; 160+ px above Arthur: descend; below him: climb; else carry on (36-frame steps)
;---------------------------------------------------------------------------
Dragon_SeekHeight:
        cmpi.w  #$5,g_Level(a6)                 ; 11280
        beq.b   l_112B4                         ; 11286
        lea.l   DragonClimb(pc),a0              ; 11288
        move.w  O_Y(a5),d0                      ; 1128C
        sub.w   g_ArthurY(a6),d0                ; 11290
        bmi.b   l_112A0                         ; 11294
        cmp.w   #$a0,d0                         ; 11296  more than 160 px above him?
        bcs.b   Dragon_NextPathStep             ; 1129A
        lea.l   DragonDescend(pc),a0            ; 1129C
l_112A0:
        move.b  Drg_Facing(a5),d0               ; 112A0
        ext.w   d0                              ; 112A4
        add.w   d0,d0                           ; 112A6
        adda.w  d0,a0                           ; 112A8
        move.b  (a0)+,d0                        ; 112AA
        move.b  (a0)+,d1                        ; 112AC
        movea.l Drg_PathPtr(a5),a0              ; 112AE
        bra.b   Dragon_SetPathStep              ; 112B2
l_112B4:
        move.w  Drg_HomeY(a5),d0                ; 112B4  level 5: more than 256 px from its start height, or 94+ px from Arthur: head back
        sub.w   g_ArthurY(a6),d0                ; 112B8
        addi.w  #$100,d0                        ; 112BC
        cmp.w   #$200,d0                        ; 112C0
        bhi.b   l_112EE                         ; 112C4
        move.w  O_Y(a5),d0                      ; 112C6
        sub.w   g_ArthurY(a6),d0                ; 112CA
        addi.w  #$5e,d0                         ; 112CE
        cmp.w   #$bc,d0                         ; 112D2
        bcs.w   Dragon_NextPathStep             ; 112D6
        lea.l   DragonClimb(pc),a0              ; 112DA
        move.w  O_Y(a5),d0                      ; 112DE
        cmp.w   g_ArthurY(a6),d0                ; 112E2
        bcs.b   l_112EC                         ; 112E6
        lea.l   DragonDescend(pc),a0            ; 112E8
l_112EC:
        bra.b   l_112A0                         ; 112EC
l_112EE:
        lea.l   DragonClimb(pc),a0              ; 112EE
        move.w  O_Y(a5),d0                      ; 112F2
        cmp.w   g_ArthurY(a6),d0                ; 112F6
        bhi.b   l_11300                         ; 112FA
        lea.l   DragonDescend(pc),a0            ; 112FC
l_11300:
        bra.b   l_112A0                         ; 11300

;---------------------------------------------------------------------------
; DragonDescend / DragonClimb - one (frames, direction) step for each facing (right, left),
; used by Dragon_SeekHeight to move towards Arthur's height.
;---------------------------------------------------------------------------
DragonDescend:
	DSTEP	36,2	; facing right: SE
	DSTEP	36,6	; facing left: SW
DragonClimb:
	DSTEP	36,14	; facing right: NE
	DSTEP	36,10	; facing left: NW

;---------------------------------------------------------------------------
; Body / tail: unless frozen, take the pending direction and move
;---------------------------------------------------------------------------
Dragon_Segment:
        tst.b   Drg_Frozen(a5)                  ; 1130A
        bne.b   l_11350                         ; 1130E
        bsr.b   Dragon_PassDirection            ; 11310
        bra.w   ApplyMoveTable                  ; 11312

;---------------------------------------------------------------------------
; When Drg_Delay runs out take Drg_NewDir and hand it to the next segment
; (6 frames later, 7 for the tail)
;---------------------------------------------------------------------------
Dragon_PassDirection:
        tst.b   Drg_Pending(a5)                 ; 11316
        beq.b   l_11350                         ; 1131A
        subq.b  #$1,Drg_Delay(a5)               ; 1131C
        bne.b   l_11350                         ; 11320
        move.b  Drg_NewDir(a5),O_Dir(a5)        ; 11322
        clr.b   Drg_Pending(a5)                 ; 11328
        move.l  Drg_Next(a5),d0                 ; 1132C
        beq.b   l_11350                         ; 11330
        movea.l d0,a4                           ; 11332
        move.b  O_Dir(a5),$38(a4)               ; 11334
        moveq   #$6,d0                          ; 1133A
        cmpi.b  #$2,$36(a4)                     ; 1133C
        bne.b   l_11346                         ; 11342
        moveq   #$7,d0                          ; 11344
l_11346:
        move.b  d0,$39(a4)                      ; 11346
        move.b  #$1,$34(a4)                     ; 1134A
l_11350:
        rts                                     ; 11350

;---------------------------------------------------------------------------
; Every 32 frames, if Arthur is within 72 px vertically: fire (enemy shot type 9)
; from the mouth, mouth open for 10 frames
;---------------------------------------------------------------------------
Dragon_Breathe:
        tst.b   Drg_Firing(a5)                  ; 11352
        bne.w   l_113E6                         ; 11356
        move.w  O_Y(a5),d0                      ; 1135A
        sub.w   g_ArthurY(a6),d0                ; 1135E
        addi.w  #$48,d0                         ; 11362
        cmp.w   #$90,d0                         ; 11366
        bhi.w   l_11406                         ; 1136A
        move.w  g_GameFrame(a6),d0              ; 1136E
        addq.w  #$1,d0                          ; 11372
        andi.w  #$1f,d0                         ; 11374
        bne.w   l_11406                         ; 11378
        moveq   #$3,d0                          ; 1137C  d0 not used by FindFreeEnemyShot
        and.b   g_RandSeed+1(a6),d0             ; 1137E
        bsr.w   FindFreeEnemyShot               ; 11382  find a free enemy-projectile slot (fires a shot)
        bne.b   l_11406                         ; 11386
        lea.l   Dragon_AnimFire(pc),a0          ; 11388
        tst.b   Drg_Facing(a5)                  ; 1138C
        beq.b   l_11394                         ; 11390
        addq.l  #$2,a0                          ; 11392
l_11394:
        adda.w  (a0),a0                         ; 11394
        move.l  a0,O_Anim(a5)                   ; 11396
        bsr.w   SetAnim                         ; 1139A  start animation
        move.b  #$a,Drg_Pending(a5)             ; 1139E
        addq.b  #$1,Drg_Firing(a5)              ; 113A4
        move.b  Drg_Facing(a5),$12(a4)          ; 113A8  shot direction = facing
        beq.b   l_113BC                         ; 113AE
        moveq   #-10,d0                         ; 113B0
        add.w   O_X(a5),d0                      ; 113B2
        move.w  d0,$6(a4)                       ; 113B6
        bra.b   l_113C6                         ; 113BA
l_113BC:
        moveq   #$a,d0                          ; 113BC
        add.w   O_X(a5),d0                      ; 113BE
        move.w  d0,$6(a4)                       ; 113C2
l_113C6:
        moveq   #-5,d0                          ; 113C6
        add.w   O_Y(a5),d0                      ; 113C8
        move.w  d0,$a(a4)                       ; 113CC
        clr.b   $3(a4)                          ; 113D0
        clr.b   $4(a4)                          ; 113D4
        clr.b   $5(a4)                          ; 113D8
        move.b  #$1,(a4)                        ; 113DC
        move.b  #$9,$1a(a4)                     ; 113E0  enemy shot type 9 (dragon fire)
l_113E6:
        subq.b  #$1,Drg_Pending(a5)             ; 113E6
        bne.b   l_11406                         ; 113EA
        clr.b   Drg_Firing(a5)                  ; 113EC
        lea.l   Dragon_AnimFly(pc),a0           ; 113F0
        tst.b   Drg_Facing(a5)                  ; 113F4
        beq.b   l_113FC                         ; 113F8
        addq.l  #$2,a0                          ; 113FA
l_113FC:
        adda.w  (a0),a0                         ; 113FC
        move.l  a0,O_Anim(a5)                   ; 113FE
        bra.w   SetAnim                         ; 11402
l_11406:
        rts                                     ; 11406

;---------------------------------------------------------------------------
; DragonPatrolPath - an offset to the patrol taken after the entrance. Two endless patrols,
; (frames, direction) steps with a loop (DLOOP): DragonPatrolLeftward weaves to the left and
; DragonPatrolRightward to the right. The turn tables below (Dragon_Turn, by facing, then upper / lower half of the
; screen) curl round and then join the patrol in the new direction.
;---------------------------------------------------------------------------
DragonPatrolPath:
	dc.w	DragonPatrolLeftward-*
DragonPatrolLeftward:
	DSTEP	10,10	; NW
	DSTEP	10,11	; NNW
	DSTEP	10,10	; NW
	DSTEP	10,11	; NNW
	DSTEP	10,10	; NW
	DSTEP	10,9	; WNW
	DSTEP	10,8	; W
	DSTEP	10,7	; WSW
	DSTEP	10,6	; SW
	DSTEP	10,5	; SSW
	DSTEP	10,8	; W
	DSTEP	10,6	; SW
	DSTEP	10,10	; NW
	DSTEP	10,6	; SW
	DSTEP	10,10	; NW
	DSTEP	10,6	; SW
	DSTEP	10,10	; NW
	DSTEP	10,6	; SW
	DSTEP	10,6	; SW
	DSTEP	10,6	; SW
	DSTEP	10,9	; WNW
	DSTEP	10,10	; NW
	DSTEP	10,11	; NNW
	DSTEP	10,5	; SSW
	DSTEP	10,5	; SSW
	DSTEP	10,6	; SW
	DSTEP	10,6	; SW
	DSTEP	10,5	; SSW
	DSTEP	10,8	; W
	DSTEP	10,11	; NNW
	DSTEP	10,10	; NW
	DSTEP	10,10	; NW
	DSTEP	10,7	; WSW
	DSTEP	10,6	; SW
	DSTEP	10,5	; SSW
	DSTEP	10,7	; WSW
	DSTEP	10,11	; NNW
	DSTEP	10,8	; W
	DSTEP	10,6	; SW
	DSTEP	10,5	; SSW
	DLOOP	10,6,DragonPatrolLeftward	; SW, then loop
DragonPatrolRightward:
	DSTEP	10,0	; E
	DSTEP	10,13	; NNE
	DSTEP	10,14	; NE
	DSTEP	10,15	; ENE
	DSTEP	10,0	; E
	DSTEP	10,15	; ENE
	DSTEP	10,1	; ESE
	DSTEP	10,2	; SE
	DSTEP	10,2	; SE
	DSTEP	10,2	; SE
	DSTEP	10,3	; SSE
	DSTEP	10,0	; E
	DSTEP	10,13	; NNE
	DSTEP	10,14	; NE
	DSTEP	10,15	; ENE
	DSTEP	10,1	; ESE
	DSTEP	10,2	; SE
	DSTEP	10,1	; ESE
	DSTEP	10,2	; SE
	DSTEP	10,3	; SSE
	DSTEP	10,2	; SE
	DSTEP	10,1	; ESE
	DSTEP	10,13	; NNE
	DSTEP	10,15	; ENE
	DSTEP	10,14	; NE
	DSTEP	10,15	; ENE
	DSTEP	10,0	; E
	DSTEP	10,1	; ESE
	DSTEP	10,2	; SE
	DSTEP	10,3	; SSE
	DSTEP	10,2	; SE
	DSTEP	10,1	; ESE
	DSTEP	10,0	; E
	DSTEP	10,1	; ESE
	DSTEP	10,0	; E
	DSTEP	10,15	; ENE
	DSTEP	10,14	; NE
	DSTEP	10,13	; NNE
	DSTEP	10,15	; ENE
	DSTEP	10,13	; NNE
	DLOOP	10,2,DragonPatrolRightward	; SE, then loop

;---------------------------------------------------------------------------
; DragonTurnRight - turn paths when facing right: upper / lower half of the screen.
;---------------------------------------------------------------------------
DragonTurnRight:
	dc.w	DragonTurnRightUpper-*	; in the upper half of the screen
	dc.w	DragonTurnRightLower-*	; in the lower half of the screen
DragonTurnRightUpper:
	DSTEP	10,13	; NNE
	DSTEP	10,12	; N
	DSTEP	10,11	; NNW
	DSTEP	10,10	; NW
	DLOOP	10,9,DragonPatrolLeftward	; WNW, then loop
DragonTurnRightLower:
	DSTEP	10,3	; SSE
	DSTEP	10,4	; S
	DSTEP	10,5	; SSW
	DSTEP	10,6	; SW
	DSTEP	10,7	; WSW
	DLOOP	10,7,DragonPatrolLeftward	; WSW, then loop

;---------------------------------------------------------------------------
; DragonTurnLeft - turn paths when facing left: upper / lower half of the screen.
;---------------------------------------------------------------------------
DragonTurnLeft:
	dc.w	DragonTurnLeftUpper-*	; in the upper half of the screen
	dc.w	DragonTurnLeftLower-*	; in the lower half of the screen
DragonTurnLeftUpper:
	DSTEP	10,11	; NNW
	DSTEP	10,12	; N
	DSTEP	10,13	; NNE
	DSTEP	10,14	; NE
	DSTEP	10,15	; ENE
	DLOOP	10,0,DragonPatrolRightward	; E, then loop
DragonTurnLeftLower:
	DSTEP	10,5	; SSW
	DSTEP	10,4	; S
	DSTEP	10,3	; SSE
	DSTEP	10,2	; SE
	DLOOP	10,1,DragonPatrolRightward	; ESE, then loop

;---------------------------------------------------------------------------
; State 2. O_Step: 0 decide, 1 head: sound 12, 2 explode, 3 wait then +1000,
; 4 segment: sound 20, 5 explode, 6 wait
;---------------------------------------------------------------------------
Dragon_Dying:
        move.b  O_Step(a5),d0                   ; 114EE
        add.w   d0,d0                           ; 114F2
        add.w   d0,d0                           ; 114F4
        jmp     Dragon_Dying_Jumps(pc,d0.w)     ; 114F6
Dragon_Dying_Jumps:
        bra.w   Dragon_HitSegment               ; 114FA
        bra.w   Dragon_HeadDies                 ; 114FE
        bra.w   EnemyExplode                    ; 11502
        bra.w   Dragon_HeadWait                 ; 11506
        bra.w   Dragon_SegmentDies              ; 1150A
        bra.w   EnemyBurst                      ; 1150E
        bra.w   Dragon_SegmentWait              ; 11512

;---------------------------------------------------------------------------
; Head: every segment dies with it. Tail: unlink it. Body segment: it lives on and
; the tail dies instead.
;---------------------------------------------------------------------------
Dragon_HitSegment:
        movea.l a5,a4                           ; 11516
        move.b  $37(a4),d0                      ; 11518
        beq.b   l_1154A                         ; 1151C
        cmp.b   #$8,d0                          ; 1151E  the head?
        beq.b   l_1156C                         ; 11522
l_11524:
        movea.l $24(a4),a4                      ; 11524  a body segment: find the tail
        tst.b   $37(a4)                         ; 11528
        bne.b   l_11524                         ; 1152C
        addq.b  #$1,(a4)                        ; 1152E  kill the tail instead (O_Active 2)
        move.b  #ST_ACTIVE,O_State(a5)          ; 11530  and this segment carries on
        clr.b   O_Step(a5)                      ; 11536
        move.b  #$1,(a5)                        ; 1153A
        clr.b   O_HP(a5)                        ; 1153E
        move.l  a4,-(a7)                        ; 11542
        bsr.w   Dragon_Segment                  ; 11544
        movea.l (a7)+,a4                        ; 11548
l_1154A:
        movea.l $28(a4),a3                      ; 1154A  unlink the dying segment: the one before it becomes the tail
        cmpi.b  #$8,$37(a3)                     ; 1154E
        beq.b   l_1155A                         ; 11554
        clr.b   $37(a3)                         ; 11556
l_1155A:
        clr.l   $24(a3)                         ; 1155A
        move.b  #$2,$3(a4)                      ; 1155E  state 2, step 4: segment death
