;---------------------------------------------------------------------------
; === Astaroth (type 13, 10000 pts, 10 hits, cross only (final boss)) ===
; Seated final boss in the throne room: fires projectiles; can only be hurt by the cross, in a narrow band (see EnemyHitByShot); its last hit calls BossKilled -> Ending.
; Dispatches on O_State: 0 main behaviour, 1 type-specific second phase, 2 killed (set by EnemyHitByShot after scoring), 3 remove.
;
; Behaviour, as coded:
;   * Waits until on screen, then walks to and fro in a 128-pixel arena (camera X + 96
;     to + 224), at a random 0.18 or 0.41 px/frame, turning at the ends and after a
;     random 0-1023 frames, always facing Arthur.
;   * Fires enemy shot type 10 the way it faces, from a lower (Y-5) or upper (Y+12)
;     point, every 70-180 frames (AstarothShotGaps). While Arthur is within 80 px the shot
;     timer runs at a quarter of the speed and shots come from the lower point; further
;     away they come from whichever point was chosen last.
;   * A stand-and-fire phase (every 256-767 frames, faster shots from AstarothFastGaps)
;     is coded, but the branch that should keep it going is the wrong way round: the
;     phase ends in the same frame it starts.
;   * 10 hits, by the cross only (EnemyVulnerability).
;---------------------------------------------------------------------------
Enemy_Astaroth:
        move.b  O_State(a5),d0                  ; 11640
        add.w   d0,d0                           ; 11644
        add.w   d0,d0                           ; 11646
        jmp     Enemy_Astaroth_Jumps(pc,d0.w)   ; 11648
Enemy_Astaroth_Jumps:
        bra.w   Astaroth_Init                   ; 1164C
        bra.w   Astaroth_Active                 ; 11650
        bra.w   Astaroth_Dying                  ; 11654
        bra.w   Astaroth_Free                   ; 11658

;---------------------------------------------------------------------------
; State 0: size 6, 10 HP, then wait to be on screen and fix the arena
;---------------------------------------------------------------------------
Astaroth_Init:
        tst.b   O_Step(a5)                      ; 1165C
        bne.b   Astaroth_Wake                   ; 11660
        move.b  #$6,O_Size(a5)                  ; 11662
        move.b  #$1,O_Dir(a5)                   ; 11668
        move.b  #$1,Ast_Facing(a5)              ; 1166E
        clr.b   Ast_Turning(a5)                 ; 11674
        clr.b   Ast_Standing(a5)                ; 11678
        clr.b   Ast_HighShot(a5)                ; 1167C
        lea.l   AstarothMoveTables(pc),a0       ; 11680
        move.l  a0,O_MoveTable(a5)              ; 11684
        move.b  #$a,O_HP(a5)                    ; 11688
        bsr.w   Astaroth_NextStand              ; 1168E
        bsr.w   Astaroth_NextShotTime           ; 11692
        addq.b  #$1,O_Step(a5)                  ; 11696  next step
        rts                                     ; 1169A
Astaroth_Wake:
        tst.b   O_OnScreen(a5)                  ; 1169C
        beq.b   l_116C2                         ; 116A0
        move.w  g_CameraX(a6),d0                ; 116A2  arena: camera X + 96 ... + 224
        addi.w  #$60,d0                         ; 116A6
        move.w  d0,Ast_ArenaL(a5)               ; 116AA
        addi.w  #$80,d0                         ; 116AE
        move.w  d0,Ast_ArenaR(a5)               ; 116B2
        addq.b  #ST_ACTIVE,O_State(a5)          ; 116B6
        clr.b   O_Step(a5)                      ; 116BA
        clr.b   O_Step2(a5)                     ; 116BE
l_116C2:
        rts                                     ; 116C2

;---------------------------------------------------------------------------
; Walk with its move table; stop and turn at the arena ends
;---------------------------------------------------------------------------
Astaroth_Walk:
        move.w  d7,d0                           ; 116C4
        add.w   g_GameFrame(a6),d0              ; 116C6
        andi.w  #$1f,d0                         ; 116CA
        bne.b   l_116D2                         ; 116CE
        moveq   #$c,d0                          ; 116D0  d0 is not used by what follows. [1MB build: PlaySfx here, effect 9 (footstep); the call was removed in 512K]
l_116D2:
        bsr.w   ApplyMoveTable                  ; 116D2  move by the movement table
        move.w  O_X(a5),d0                      ; 116D6
        cmp.w   Ast_ArenaL(a5),d0               ; 116DA
        bhi.b   l_116EC                         ; 116DE
        move.w  Ast_ArenaL(a5),O_X(a5)          ; 116E0
        clr.b   O_Dir(a5)                       ; 116E6
        rts                                     ; 116EA
l_116EC:
        cmp.w   Ast_ArenaR(a5),d0               ; 116EC
        bcs.b   l_116FE                         ; 116F0
        move.w  Ast_ArenaR(a5),O_X(a5)          ; 116F2
        move.b  #$1,O_Dir(a5)                   ; 116F8
l_116FE:
        rts                                     ; 116FE

;---------------------------------------------------------------------------
; State 1. O_Step 0 start a walk, 1 walk, 2 turn
;---------------------------------------------------------------------------
Astaroth_Active:
        move.b  O_Step(a5),d0                   ; 11700
        add.w   d0,d0                           ; 11704
        add.w   d0,d0                           ; 11706
        jmp     Astaroth_Active_Jumps(pc,d0.w)  ; 11708
