        andi.b  #$3,d0                          ; 1171C
        move.b  d0,Ast_WalkTime(a5)             ; 11720
        bsr.w   Random                          ; 11724  random number
        move.b  d0,Ast_WalkTimeLo(a5)           ; 11728
        clr.b   Ast_Turning(a5)                 ; 1172C
        bsr.w   Astaroth_SetAnim                ; 11730
        addq.b  #$1,O_Step(a5)                  ; 11734  next step
Astaroth_Walking:
        subq.w  #$1,Ast_WalkTime(a5)            ; 11738
        beq.b   l_11752                         ; 1173C
        bsr.b   Astaroth_Think                  ; 1173E
        tst.b   Ast_Standing(a5)                ; 11740
        bne.b   l_1174E                         ; 11744
        bsr.w   Astaroth_Walk                   ; 11746
        bsr.w   Animate                         ; 1174A  animate
l_1174E:
