        andi.b  #$2f,d0                         ; 11756  143-190 frames
        addi.b  #$8f,d0                         ; 1175A
        move.b  d0,Ast_TurnWait(a5)             ; 1175E
        move.b  #$1,Ast_Turning(a5)             ; 11762
        bsr.w   Astaroth_SetAnim                ; 11768
        addq.b  #$1,O_Step(a5)                  ; 1176C  next step
        rts                                     ; 11770

;---------------------------------------------------------------------------
