;---------------------------------------------------------------------------
Astaroth_Turn:
        subq.b  #$1,Ast_TurnWait(a5)            ; 11772
        beq.b   Astaroth_Think                  ; 11776
        bsr.b   Astaroth_RandomSpeed            ; 11778
        bchg    #$0,O_Dir(a5)                   ; 1177A  turn round
