        cmp.w   g_ArthurX(a6),d0                ; 118AC
        scs.b   d0                              ; 118B0
        addq.b  #$1,d0                          ; 118B2
        cmp.b   Ast_Facing(a5),d0               ; 118B4
        beq.b   l_118C2                         ; 118B8
        bchg    #$0,Ast_Facing(a5)              ; 118BA
        bra.b   Astaroth_SetAnim                ; 118C0
l_118C2:
        rts                                     ; 118C2

