        move.b  Ast_Facing(a5),d0               ; 118C8
        ext.w   d0                              ; 118CC
        add.w   d0,d0                           ; 118CE
        adda.w  d0,a0                           ; 118D0
        adda.w  (a0),a0                         ; 118D2
        tst.b   Ast_Standing(a5)                ; 118D4
        beq.b   l_118DC                         ; 118D8
        addq.l  #$4,a0                          ; 118DA
l_118DC:
        adda.w  (a0),a0                         ; 118DC
        bra.w   SetAnim                         ; 118DE

