        move.b  O_State(a5),d0                  ; 11CDA
        add.w   d0,d0                           ; 11CDE
        add.w   d0,d0                           ; 11CE0
        jmp     Enemy_FirePillar_Jumps(pc,d0.w) ; 11CE2
Enemy_FirePillar_Jumps:
        bra.w   FirePillar_Init                 ; 11CE6
        bra.w   FirePillar_Active               ; 11CEA
        bra.w   FirePillar_Dying                ; 11CEE
        bra.w   FirePillar_Free                 ; 11CF2

