        add.w   g_GameFrame(a6),d0              ; 11D20
        andi.w  #$3,d0                          ; 11D24
        move.b  (a0,d0.w),Pil_LowWait(a5)       ; 11D28
        move.l  a0,Pil_LowPtr(a5)               ; 11D2E
        move.b  $1(a0,d0.w),Pil_HighWait(a5)    ; 11D32
